/// An empty state drawn alone in a column of a chosen width, the way the forwards
/// dialog and the host list hold it.
struct EmptyStateHarness {
    width: f32,
    zoom: Zoom,
    body: &'static str,
}

impl Render for EmptyStateHarness {
    fn render(
        &mut self,
        _window: &mut gpui::Window,
        _cx: &mut gpui::Context<Self>,
    ) -> impl IntoElement {
        let metrics = Metrics::new(self.zoom);
        div().size_full().child(
            div()
                .w(px(self.width))
                .flex()
                .flex_col()
                .child(crate::app::components::empty_state(
                    crate::app::icons::Icon::Forward,
                    "Nothing yet",
                    Some(self.body.into()),
                    Some(
                        crate::app::components::button(
                            "New",
                            crate::app::components::Variant::Primary,
                            metrics,
                        )
                        .into_any_element(),
                    ),
                    metrics,
                )),
        )
    }
}

/// How tall `text` is once wrapped at `width`, at the size the empty state's line is
/// drawn at: the height its painted lines take, whatever box layout gave it.
fn wrapped_height(
    cx: &mut VisualTestContext,
    text: &str,
    font_size: Pixels,
    width: Pixels,
) -> Pixels {
    cx.update(|window, _app| {
        let style = window.text_style();
        // The height a wrapped text measures itself with: unrounded, unlike the one
        // `line_height_in_pixels` gives.
        let line_height = style
            .line_height
            .to_pixels(font_size.into(), window.rem_size());
        let run = style.to_run(text.len());
        window
            .text_system()
            .shape_text(text.to_owned().into(), font_size, &[run], Some(width), None)
            .expect("the line is shaped")
            .iter()
            .map(|line| line.size(line_height).height)
            .fold(px(0.0), |total, height| total + height)
    })
}

/// The empty state's title, its line and its button, measured top to bottom: each
/// starts below where the one before it is painted to, and each text's box is as tall
/// as the lines it is painted in at the width it was given (R1).
fn assert_empty_state_stacks(
    cx: &mut VisualTestContext,
    title: &str,
    body: Option<&str>,
    zoom: Zoom,
    what: &str,
) {
    let metrics = Metrics::new(zoom);
    let heading = bounds_of(cx, "empty.state.title");
    let action = bounds_of(cx, "empty.state.action");
    let mut end =
        heading.origin.y + wrapped_height(cx, title, metrics.title_size(), heading.size.width);
    assert!(
        heading.origin.y + heading.size.height + px(1.0) >= end,
        "{what}: the title is painted to {end:?} but its box is {heading:?}"
    );
    if let Some(body) = body {
        let line = bounds_of(cx, "empty.state.body");
        let painted = wrapped_height(cx, body, metrics.body_size(), line.size.width);
        assert!(
            line.size.height + px(1.0) >= painted,
            "{what}: the line is painted {painted:?} tall but its box is {line:?}, so its \
             last line runs into what follows"
        );
        assert!(
            end <= line.origin.y + px(0.5),
            "{what}: the title, painted to {end:?}, overlaps the line {line:?}"
        );
        end = line.origin.y + painted;
    }
    assert!(
        end <= action.origin.y + px(0.5),
        "{what}: the text is painted to {end:?}, below the top of the button {action:?}"
    );
}

/// Puts the window at `window`, the text at `zoom` and the copy in `locale`.
fn set_look(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    window: Size<Pixels>,
    zoom: Zoom,
    locale: Locale,
) {
    cx.simulate_resize(window);
    cx.run_until_parked();
    for _ in 0..Zoom::ALL.len() {
        if cx.update(|_window, app| view.read(app).workspace().zoom()) == zoom {
            break;
        }
        go(cx, CycleTextSize);
    }
    if cx.update(|_window, app| view.read(app).workspace().locale()) != locale {
        go(cx, ToggleLanguage);
    }
    assert_eq!(
        cx.update(|_window, app| {
            let workspace = view.read(app).workspace();
            (workspace.zoom(), workspace.locale())
        }),
        (zoom, locale)
    );
}

/// The two sizes a wrapping line has to survive, in both languages (R1).
fn empty_state_looks() -> [(Size<Pixels>, Zoom, Locale); 4] {
    [
        (narrow_window(), Zoom::Comfortable, Locale::English),
        (narrow_window(), Zoom::Comfortable, Locale::Chinese),
        (design_window(), Zoom::Regular, Locale::English),
        (design_window(), Zoom::Regular, Locale::Chinese),
    ]
}

#[gpui::test]
async fn the_forwards_and_host_list_empty_states_keep_their_button_below_the_words(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("empty-states");
    seed(
        &dir.store(),
        vec![stored_host("web", "10.0.0.5", 22, "deploy", None)],
    );
    let (view, cx) = hosts_view(cx, dir.store());
    focus_root(&view, cx);

    // The forwards dialog with a host to tunnel through: the line and its button.
    go(cx, GoToForwards);
    for (window, zoom, locale) in empty_state_looks() {
        set_look(&view, cx, window, zoom, locale);
        let what = format!("forwards.empty at {window:?} {zoom:?} {locale:?}");
        assert!(cx.debug_bounds("forwards.empty").is_some(), "{what}");
        let ux = copy::ux_for(locale);
        assert_empty_state_stacks(cx, ux.fwd_empty_title, Some(ux.fwd_empty_body), zoom, &what);
    }
    set_look(&view, cx, design_window(), Zoom::Regular, Locale::English);
    click(cx, "forwards.dialog.close");

    // The recent view before anything was connected: a title and its button.
    click(cx, "hosts.view.recent");
    for (window, zoom, locale) in empty_state_looks() {
        set_look(&view, cx, window, zoom, locale);
        let what = format!("hosts.recent.empty at {window:?} {zoom:?} {locale:?}");
        assert!(cx.debug_bounds("hosts.recent.empty").is_some(), "{what}");
        let strings: &Strings = if locale == Locale::Chinese {
            &CHINESE
        } else {
            &ENGLISH
        };
        assert_empty_state_stacks(cx, strings.hosts_recent_empty, None, zoom, &what);
    }
    set_look(&view, cx, design_window(), Zoom::Regular, Locale::English);

    // A search that matches nothing: the reason, the hint and the way out.
    click(cx, "hosts.view.all");
    type_into(cx, "hosts.search", "zzz");
    for (window, zoom, locale) in empty_state_looks() {
        set_look(&view, cx, window, zoom, locale);
        let what = format!("hosts.nomatch at {window:?} {zoom:?} {locale:?}");
        assert!(cx.debug_bounds("hosts.nomatch").is_some(), "{what}");
        let strings: &Strings = if locale == Locale::Chinese {
            &CHINESE
        } else {
            &ENGLISH
        };
        let ux = copy::ux_for(locale);
        assert_empty_state_stacks(
            cx,
            strings.hosts_no_match,
            Some(ux.hosts_no_match_hint),
            zoom,
            &what,
        );
    }
}

#[gpui::test]
async fn an_empty_states_line_wraps_above_its_button_at_any_width(cx: &mut TestAppContext) {
    // Long enough to fit on one line across the whole column but not inside the
    // line's own cap: the width the column offers and the width the line is drawn at
    // disagree, which is when the box used to keep one line and paint two.
    const BODY: &str = "A tunnel carries one port through a host, so it is used on the other side.";
    for (width, zoom) in [
        (630.0, Zoom::Regular),
        (560.0, Zoom::Regular),
        (480.0, Zoom::Regular),
        (1200.0, Zoom::Comfortable),
        (900.0, Zoom::Comfortable),
        (590.0, Zoom::Comfortable),
        (360.0, Zoom::Comfortable),
    ] {
        let (_view, cx) = cx.add_window_view(move |_window, _cx| EmptyStateHarness {
            width,
            zoom,
            body: BODY,
        });
        cx.simulate_resize(size(px(1400.0), px(1200.0)));
        cx.run_until_parked();
        assert_empty_state_stacks(
            cx,
            "Nothing yet",
            Some(BODY),
            zoom,
            &format!("{width}px at {zoom:?}"),
        );
    }
}

/// A section's state card drawn alone in a column of a chosen width, with a row under
/// it, the way a page holds its empty, loading or failed section.
struct StateCardHarness {
    width: f32,
    zoom: Zoom,
    body: &'static str,
}

impl Render for StateCardHarness {
    fn render(
        &mut self,
        _window: &mut gpui::Window,
        _cx: &mut gpui::Context<Self>,
    ) -> impl IntoElement {
        let metrics = Metrics::new(self.zoom);
        div().size_full().child(
            div()
                .w(px(self.width))
                .flex()
                .flex_col()
                .child(crate::app::components::state_card_with_icon(
                    Tone::Neutral,
                    Some(crate::app::icons::Icon::Terminal),
                    "No sessions yet",
                    self.body,
                    Some("Press + to open one.".into()),
                    metrics,
                ))
                .child(
                    div()
                        .h(px(20.0))
                        .debug_selector(|| "state.card.after".to_owned()),
                ),
        )
    }
}

#[gpui::test]
async fn a_state_cards_words_wrap_inside_their_own_boxes_at_any_width(cx: &mut TestAppContext) {
    // R1, R5: the same measuring trap as the empty state. The words are long enough to
    // fit on one line across the whole card but not inside the card's cap, which is
    // when a box measured at one width and painted at another kept one line and
    // painted two over the next step.
    const BODY: &str =
        "A session is a shell on this computer or a host; it keeps running in its tab.";
    for (width, zoom) in [
        (900.0, Zoom::Regular),
        (760.0, Zoom::Regular),
        (620.0, Zoom::Regular),
        (420.0, Zoom::Regular),
        (1600.0, Zoom::Comfortable),
        (1200.0, Zoom::Comfortable),
        (720.0, Zoom::Comfortable),
        (420.0, Zoom::Comfortable),
    ] {
        let (_view, cx) = cx.add_window_view(move |_window, _cx| StateCardHarness {
            width,
            zoom,
            body: BODY,
        });
        cx.simulate_resize(size(px(1800.0), px(1400.0)));
        cx.run_until_parked();
        let what = format!("{width}px at {zoom:?}");
        let metrics = Metrics::new(zoom);
        let title = bounds_of(cx, "state.card.title");
        let body = bounds_of(cx, "state.card.body");
        let step = bounds_of(cx, "state.card.step");
        let card = bounds_of(cx, "state.card");
        let after = bounds_of(cx, "state.card.after");
        let title_end = title.origin.y
            + wrapped_height(
                cx,
                "No sessions yet",
                metrics.title_size() + px(1.0),
                title.size.width,
            );
        assert!(
            title_end <= body.origin.y + px(0.5),
            "{what}: the title, painted to {title_end:?}, overlaps the line {body:?}"
        );
        let painted = wrapped_height(cx, BODY, metrics.body_size(), body.size.width);
        assert!(
            body.size.height + px(1.0) >= painted,
            "{what}: the line is painted {painted:?} tall but its box is {body:?}, so its last \
             line runs into what follows"
        );
        let body_end = body.origin.y + painted;
        assert!(
            body_end <= step.origin.y + px(0.5),
            "{what}: the line, painted to {body_end:?}, overlaps the next step {step:?}"
        );
        // The card is as tall as the words it paints: its bottom padding is whole
        // under the next step, so nothing is painted into the padding or past the card.
        let card_end = card.origin.y + card.size.height;
        let step_end = step.origin.y + step.size.height;
        assert!(
            step_end + metrics.scale(theme::spacing::LOOSE + 16.0) <= card_end + px(0.5),
            "{what}: the card was measured shorter than its words paint: the step ends at \
             {step_end:?}, the card at {card_end:?}"
        );
        assert!(
            card_end <= after.origin.y + px(0.5),
            "{what}: the card ends before what follows it: {card:?}, then {after:?}"
        );
        assert!(
            body.size.width <= metrics.scale(480.0) + px(0.5),
            "{what}: the line keeps to its cap: {body:?}"
        );
    }
}

#[gpui::test]
async fn every_empty_loading_and_failed_state_renders_a_state_card(cx: &mut TestAppContext) {
    // No capability of this build is "planned" any more, so the states a section can
    // really be in are loading, failed and empty; all three go through one state card.
    let cases = [
        (
            "loading",
            Destination::Transfers,
            Workspace::with_sections(
                Section::<Session>::ready(Vec::new()),
                Section::<HostConfig>::ready(Vec::new()),
                Section::<Transfer>::loading(),
            ),
            SectionState::Loading,
        ),
        (
            "failed",
            Destination::Transfers,
            Workspace::with_sections(
                Section::<Session>::ready(Vec::new()),
                Section::<HostConfig>::ready(Vec::new()),
                Section::<Transfer>::failed(Failure::new(
                    "the transfer list could not be read",
                    Recovery::Retry,
                )),
            ),
            SectionState::Failed,
        ),
        (
            "empty",
            Destination::Hosts,
            Workspace::with_sections(
                Section::<Session>::ready(Vec::new()),
                Section::<HostConfig>::ready(Vec::new()),
                Section::<Transfer>::ready(Vec::new()),
            ),
            SectionState::Empty,
        ),
    ];

    for (name, destination, mut workspace, expected) in cases {
        workspace.select(destination);
        let (view, cx) =
            cx.add_window_view(move |_window, cx| ShelluneView::with_workspace(cx, workspace));
        cx.simulate_resize(design_window());
        cx.run_until_parked();
        if destination == Destination::Transfers {
            go(cx, GoToTransfers);
        }

        let viewport = cx.update(|window, _app| window.viewport_size());
        assert_eq!(
            cx.update(|_window, app| view.read(app).workspace().state(destination)),
            expected,
            "the {name} fixture did not keep its state"
        );
        // An empty host list is the home page's first-run card, which says what a
        // host is and offers the ways to add one.
        let card = if destination == Destination::Hosts && expected == SectionState::Empty {
            "hosts.empty"
        } else {
            "state.card"
        };
        assert_fits_inside(bounds_of(cx, card), viewport, name);
        assert!(
            cx.debug_bounds("row.0").is_none(),
            "the {name} state must not render list rows"
        );
    }
}

#[gpui::test]
async fn a_host_file_that_cannot_be_read_stays_failed_when_it_is_retried(cx: &mut TestAppContext) {
    // A data directory that is a file cannot hold a host file. Retrying reads the
    // same impossible path, so the failure has to survive the retry instead of
    // turning into an empty host list.
    let dir = TempDir::new("unreadable");
    let root = dir.path().join("data");
    std::fs::write(&root, "not a directory").expect("the sentinel file is written");

    let mut workspace = Workspace::new();
    workspace.select(Destination::Hosts);
    let store = HostStore::at(&root);
    let (view, cx) =
        cx.add_window_view(move |_window, cx| ShelluneView::with_store(cx, workspace, store));
    cx.simulate_resize(design_window());
    cx.run_until_parked();

    cx.update(|_window, app| {
        assert_eq!(
            view.read(app).workspace().state(Destination::Hosts),
            SectionState::Failed
        );
    });
    assert!(
        cx.debug_bounds("state.card").is_some(),
        "the failure has to be visible where the hosts would be"
    );

    new_default_shell(cx);
    cx.run_until_parked();

    cx.update(|_window, app| {
        let workspace = view.read(app).workspace();
        assert_eq!(workspace.state(Destination::Hosts), SectionState::Failed);
        assert_eq!(workspace.item_count(Destination::Hosts), 0);
        let reason = workspace
            .failure(Destination::Hosts)
            .map(Failure::reason)
            .unwrap_or_default()
            .to_owned();
        assert!(
            reason.contains("hosts.json"),
            "the reason names the file it could not read: {reason}"
        );
    });
}

