/// The surfaces a label or a mark is drawn on: the five layers, and the chosen fill (a
/// veil) on each of them.
fn label_surfaces() -> Vec<(String, theme::Token)> {
    let layers = [
        ("canvas", palette::CANVAS),
        ("chrome", palette::CHROME),
        ("surface", palette::SURFACE),
        ("raised", palette::RAISED),
        ("overlay", palette::OVERLAY),
    ];
    layers
        .iter()
        .map(|(name, token)| ((*name).to_owned(), *token))
        .chain(layers.iter().map(|(name, token)| {
            (
                format!("selected on {name}"),
                palette::SURFACE_SELECTED.over(*token),
            )
        }))
        .collect()
}

#[test]
fn body_text_reaches_the_contrast_floor_on_every_surface() {
    let text = [
        ("primary", palette::TEXT_PRIMARY),
        ("secondary", palette::TEXT_SECONDARY),
        ("muted", palette::TEXT_MUTED),
        ("accent", palette::ACCENT),
    ];

    for (surface_name, surface) in label_surfaces() {
        for (text_name, token) in text {
            let (dark, light) = theme::contrast::both(token, surface);
            assert!(
                dark >= BODY_CONTRAST_FLOOR && light >= BODY_CONTRAST_FLOOR,
                "{text_name} on {surface_name} is {dark:.2}:1 dark and {light:.2}:1 light, \
                 below {BODY_CONTRAST_FLOOR}"
            );
        }
    }
}

#[test]
fn host_avatar_initials_are_readable_on_their_tint() {
    // The tile is the selected veil over whatever the row stands on, its letters in the
    // secondary ink; a picked row's tile is the accent tint with the accent's ink.
    for (layer_name, layer) in [
        ("surface", palette::SURFACE),
        ("raised", palette::RAISED),
        ("overlay", palette::OVERLAY),
        (
            "hovered raised",
            palette::SURFACE_HOVER.over(palette::RAISED),
        ),
    ] {
        let tile = palette::SURFACE_SELECTED.over(layer);
        for ink in palette::HOST_INKS {
            let ratio = theme::contrast::worst(ink, tile);
            assert!(
                ratio >= BODY_CONTRAST_FLOOR,
                "the avatar's mark {ink:x} on {layer_name} is {ratio:.2}:1"
            );
        }
    }
    let picked = theme::contrast::worst(palette::ACCENT_ON_TINT, palette::ACCENT_TINT);
    assert!(
        picked >= BODY_CONTRAST_FLOOR,
        "a picked avatar is {picked:.2}:1"
    );
}

