#[gpui::test]
async fn the_two_switches_take_their_keys_only_while_the_bar_holds_them(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("needle", cx);
    click(cx, "terminal.search");
    cx.simulate_input("needle");
    cx.simulate_keystrokes("alt-c");
    let held = search_state_of(&pane, cx);
    assert!(
        held.case_sensitive,
        "Alt+C is the bar's while it has the keys"
    );
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().to_vec()),
        Vec::<u8>::new(),
        "a bar key never reaches the shell"
    );

    cx.simulate_keystrokes("escape");
    assert!(!search_state_of(&pane, cx).open, "Escape closed the bar");

    // With the bar closed the same combinations belong to the program again: these
    // are the bytes a shell reads as Alt+C and Alt+R, not a shortcut.
    cx.simulate_keystrokes("alt-c");
    cx.simulate_keystrokes("alt-r");
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().to_vec()),
        b"\x1bc\x1br".to_vec(),
        "closing the bar hands Alt+C and Alt+R back to the terminal"
    );
    assert!(
        !search_state_of(&pane, cx).open,
        "a program key does not reopen the bar"
    );
}

#[gpui::test]
async fn the_bar_says_which_of_the_two_has_the_keys(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("needle\r\nneedle", cx);
    click(cx, "terminal.search");
    cx.simulate_input("needle");
    cx.run_until_parked();

    let held = search_state_of(&pane, cx);
    assert!(held.focused, "the bar holds the keyboard: {held:?}");
    assert!(
        cx.debug_bounds("terminal.search.keyboard.bar").is_some(),
        "the query field is drawn as the one with the keyboard"
    );
    assert!(
        cx.debug_bounds("terminal.search.keys.terminal").is_none(),
        "nothing claims the terminal has the keys while the bar does"
    );
    assert_eq!(
        held.note,
        SearchNote::Position {
            position: 1,
            total: 2
        }
    );

    // The line naming the keys and the switches themselves stay inside the smallest
    // window, where the bar has the least room.
    cx.simulate_resize(narrow_window());
    cx.run_until_parked();
    let small = cx.update(|window, _app| window.viewport_size());
    assert_fits_inside(
        bounds_of(cx, "terminal.search.keys"),
        small,
        "the find bar's key hint",
    );
    assert_fits_inside(
        bounds_of(cx, "terminal.search.case"),
        small,
        "the case switch",
    );
    cx.simulate_resize(design_window());
    cx.run_until_parked();

    // Clicking the grid hands the keys back to the shell and leaves the bar open: the
    // reader has to be able to tell the two states apart, so the field turns neutral
    // and the bar says where the keys go.
    click(cx, "terminal.viewport");
    let back = search_state_of(&pane, cx);
    assert!(!back.focused, "the terminal has the keys again: {back:?}");
    assert_eq!(back.query, "needle", "the query is still on the bar");
    assert!(
        cx.debug_bounds("terminal.search.keyboard.terminal")
            .is_some(),
        "the query field is drawn as the one without the keyboard"
    );
    assert!(
        cx.debug_bounds("terminal.search.keys.terminal").is_some(),
        "the bar says the keys go to the terminal"
    );
    assert_eq!(
        back.note,
        SearchNote::Position {
            position: 1,
            total: 2
        },
        "the count keeps showing while the terminal has the keys"
    );
    // And the keys are the shell's now, exactly as the line above says: the bar's
    // switches do not change behind the reader's back.
    cx.simulate_keystrokes("alt-c");
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().to_vec()),
        b"\x1bc".to_vec(),
        "with the terminal holding the keys, Alt+C reaches the program"
    );
    assert!(
        !search_state_of(&pane, cx).case_sensitive,
        "the case switch did not turn over while the keys were the shell's"
    );
}

#[gpui::test]
async fn a_resize_recounts_the_matches_on_the_new_wrap(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("", cx);
    // The narrow width comes first, so the text is written at the width it is wrapped
    // at and the match below straddles a break rather than having to find one.
    cx.simulate_resize(narrow_window());
    cx.run_until_parked();
    let narrow = cx.update(|_window, app| pane.read(app).grid());
    assert!(narrow.cols > 8, "the narrow grid still has columns");
    let mut line = "x".repeat(narrow.cols - 3);
    line.push_str("needle");
    cx.update(|_window, app| {
        pane.update(app, |pane, cx| pane.feed_for_test(line.as_bytes(), cx));
    });
    cx.run_until_parked();

    click(cx, "terminal.search");
    cx.simulate_input("needle");
    cx.run_until_parked();
    assert_eq!(
        search_state_of(&pane, cx).note,
        SearchNote::Empty,
        "at this width the word is split by the wrap, so nothing matches: {:?}",
        search_state_of(&pane, cx)
    );

    // A wider grid joins the two rows again. The count and the places it steps
    // through follow the new layout instead of the numbers from before it.
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    let wide = cx.update(|_window, app| pane.read(app).grid());
    assert!(wide.cols > narrow.cols, "the window really got wider");
    assert_eq!(
        search_state_of(&pane, cx).note,
        SearchNote::Position {
            position: 1,
            total: 1
        },
        "the match the narrower grid split is counted again: {:?}",
        search_state_of(&pane, cx)
    );
    assert!(
        cx.debug_bounds("terminal.search.position").is_some(),
        "the reopened count is drawn"
    );
    // Stepping still lands on a line of the new layout, and there is one place, so it
    // wraps to itself.
    cx.simulate_keystrokes("enter");
    assert_eq!(
        search_state_of(&pane, cx).note,
        SearchNote::Position {
            position: 1,
            total: 1
        },
        "stepping through the recounted places works after the resize"
    );
}

/// The measured parts of the find bar, plus the bar itself.
///
/// Each is a box the walkthrough would have to reach with a pointer: the query and the
/// count are read, the switches and the two arrows are pressed, and the last one closes
/// the bar (R1, R4).
const FIND_BAR_PARTS: [&str; 8] = [
    "terminal.search.query",
    "terminal.search.keys",
    "terminal.search.previous",
    "terminal.search.next",
    "terminal.search.case",
    "terminal.search.regex",
    "terminal.search.close",
    "terminal.search.bar",
];

/// The find bar at the size the walkthrough measures it: the minimum window in the
/// largest text, with the session drawn inside the window rather than the pane alone.
///
/// The bar hangs over the grid at the bottom of the pane, so every part of it has to be
/// inside the window and inside the panel it belongs to. A part drawn past either edge
/// is drawn past the window where neither the pointer nor a scroll can bring it back
/// (R4); this test reads the boxes instead of the drawing, so a squeezed part still has
/// to be inside them.
#[gpui::test]
async fn the_find_bar_stays_inside_the_window_at_the_large_text(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let pane = cx
        .update(|_window, app| view.read(app).pane_of(id).cloned())
        .expect("the session has a terminal");
    cx.simulate_resize(narrow_window());
    focus_root(&view, cx);
    cx.dispatch_action(CycleTextSize);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|window, _app| window.viewport_size()),
        narrow_window(),
        "the bar is not being measured at the minimum window"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().zoom()),
        Zoom::Comfortable
    );

    click(cx, "terminal.search");
    cx.run_until_parked();
    let query = bounds_of(cx, "terminal.search.query");
    // The find bar uses the terminal metrics, which stay at the regular size.
    let placeholder = px("Search this terminal".chars().count() as f32
        * (Metrics::new(Zoom::Regular).caption_size() / px(1.0))
        * shellune_terminal::MONOSPACE_ADVANCE_RATIO);
    assert!(
        query.size.width + px(1.0) >= placeholder,
        "the empty search field cuts the placeholder through a word: {query:?} needs {placeholder:?}"
    );
    cx.simulate_input("ready");
    cx.run_until_parked();
    assert_eq!(
        search_state_of(&pane, cx).note,
        SearchNote::Position {
            position: 1,
            total: 1
        },
        "the bar has something to count at this size"
    );

    // Both languages: the words on the bar are the widest thing in it, and the count and
    // the switches have to share whatever the Chinese labels leave them.
    for locale in [Locale::English, Locale::Chinese] {
        if locale == Locale::Chinese {
            cx.dispatch_action(ToggleLanguage);
            cx.run_until_parked();
            assert_eq!(
                cx.update(|_window, app| view.read(app).workspace().locale()),
                Locale::Chinese
            );
        }
        let viewport = cx.update(|window, _app| window.viewport_size());
        let panel = bounds_of(cx, "content");
        assert!(
            cx.debug_bounds("terminal.search.position").is_some(),
            "the count is drawn in {locale:?}"
        );
        for selector in FIND_BAR_PARTS {
            let bounds = bounds_of(cx, selector);
            assert_fits_inside(bounds, viewport, selector);
            assert_inside_box(bounds, panel, selector);
        }
    }

    // And it is still a bar, not just a drawing of one: its close button answers at this
    // size and hands the keys back to the terminal.
    click(cx, "terminal.search.close");
    cx.run_until_parked();
    let closed = search_state_of(&pane, cx);
    assert!(!closed.open, "the close button closed the bar: {closed:?}");
    assert!(!closed.focused, "the terminal has the keys again");
}

/// The bar in one pane of a sideways split of the minimum window.
///
/// At that size the sidebar is an icon strip and the two panes share the 720 px: each
/// pane is 354 px wide with the 12 px divider between them, so the bar inside one is
/// 336 px wide. The line naming the keys is wider than that on its own, so it takes a
/// line of its own and wraps there instead of running past the pane's right edge, where
/// the rest of it — including the key that closes the bar — would be unreadable (R4).
/// The size is the measured pane box, not a guess; the split test below measures the
/// same bar inside a real split.
#[gpui::test]
async fn the_find_bar_narrows_with_the_pane_instead_of_leaving_it(cx: &mut TestAppContext) {
    let (_pane, cx) = pane_with("needle line\r\nother", cx);
    cx.simulate_resize(size(px(354.0), px(392.0)));
    cx.run_until_parked();
    click(cx, "terminal.search");
    cx.simulate_input("needle");
    cx.run_until_parked();

    let viewport = cx.update(|window, _app| window.viewport_size());
    let bar = bounds_of(cx, "terminal.search.bar");
    let query = bounds_of(cx, "terminal.search.query");
    let hint = bounds_of(cx, "terminal.search.keys");
    assert!(
        hint.size.width <= bar.size.width + px(0.5),
        "the key hint is drawn past the bar: {hint:?} vs {bar:?}"
    );
    assert!(
        hint.size.height > query.size.height,
        "the hint kept one line where there is no room for one: {hint:?} vs {query:?}"
    );
    for selector in FIND_BAR_PARTS {
        assert_fits_inside(bounds_of(cx, selector), viewport, selector);
    }
    assert!(
        cx.debug_bounds("terminal.search.position").is_some(),
        "the count is drawn in the narrow pane too"
    );
}

/// The reason under a broken expression, in a pane as narrow as one half of the
/// minimum window.
///
/// A sideways split of 720 px gives each pane 354 px (the divider takes 12). The
/// engine's reason for `a{2,1}` — the start of a repetition is past its end — is a
/// sentence wider than that pane. The count, the empty result and that reason are
/// the three notes beside the query; a note that cannot shrink is drawn past the
/// pane's right edge, and the pane clips it, so the end of the reason cannot be
/// read (R4). This measures the same width as
/// [the_find_bar_narrows_with_the_pane_instead_of_leaving_it], which is the width a
/// real split pane has. The boxes are the test window's `debug_bounds`, not a
/// Windows, macOS or Linux walkthrough.
#[gpui::test]
async fn a_broken_expression_reason_wraps_inside_the_narrow_pane(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("needle\r\nother", cx);
    cx.simulate_resize(size(px(354.0), px(392.0)));
    cx.run_until_parked();
    click(cx, "terminal.search");
    cx.simulate_keystrokes("alt-r");
    cx.simulate_input("a{2,1}");
    cx.run_until_parked();

    let note = search_state_of(&pane, cx).note;
    let SearchNote::Invalid(reason) = &note else {
        panic!(
            "a repetition whose start is past its end is an invalid expression, not a count: {note:?}"
        );
    };
    assert!(
        reason.contains("the start must be <= the end"),
        "the bar is showing the engine's reason, whose tail is what a narrow pane used to clip: {reason}"
    );
    let before = cx.update(|_window, app| pane.read(app).visible_text());
    assert!(
        before.iter().any(|line| line.contains("needle")),
        "a broken expression must not clear the grid: {before:?}"
    );

    let viewport = cx.update(|window, _app| window.viewport_size());
    let bar = bounds_of(cx, "terminal.search.bar");
    let query = bounds_of(cx, "terminal.search.query");
    let error = bounds_of(cx, "terminal.search.error");
    assert_fits_inside(bar, viewport, "terminal.search.bar");
    assert_fits_inside(error, viewport, "terminal.search.error");
    assert_inside_box(error, bar, "the invalid-expression reason");
    assert!(
        error.size.width <= bar.size.width + px(0.5),
        "the reason is drawn past the bar: {error:?} vs {bar:?}"
    );
    assert!(
        error.size.height > query.size.height,
        "the reason stayed on one line and ran past the pane: {error:?} vs {query:?}"
    );
    for selector in [
        "terminal.search.close",
        "terminal.search.case",
        "terminal.search.regex",
        "terminal.search.previous",
        "terminal.search.next",
    ] {
        assert_fits_inside(bounds_of(cx, selector), viewport, selector);
        assert_inside_box(bounds_of(cx, selector), bar, selector);
    }
}

/// The same bar inside a real sideways split of the minimum window.
///
/// [the_find_bar_narrows_with_the_pane_instead_of_leaving_it] measures the width a split
/// pane has; this one takes it from the window, so the two sizes cannot drift apart: the
/// bar and every part of it stays inside the pane it belongs to and inside the window.
#[gpui::test]
async fn a_find_bar_in_a_split_pane_stays_inside_its_pane(cx: &mut TestAppContext) {
    let Some((view, cx, _left, right)) = split_tab(cx) else {
        // No shell to start: nothing is measured here, and a skip is not a pass.
        return;
    };
    let pane = cx
        .update(|_window, app| view.read(app).pane_of(right).cloned())
        .expect("the split has two terminals");
    cx.simulate_resize(narrow_window());
    cx.run_until_parked();
    feed_session(cx, &view, right, b"needle line\r\n");

    cx.dispatch_action(crate::app::actions::TerminalSearch);
    cx.run_until_parked();
    assert!(
        search_state_of(&pane, cx).open,
        "the keys opened the bar in the pane they were typed in"
    );
    cx.simulate_input("needle");
    cx.run_until_parked();
    assert_eq!(
        search_state_of(&pane, cx).note,
        SearchNote::Position {
            position: 1,
            total: 1
        }
    );

    let viewport = cx.update(|window, _app| window.viewport_size());
    let frame = bounds_of(cx, "pane.active");
    assert!(
        frame.size.width < px(400.0),
        "the split really shares the window: {frame:?}"
    );
    for selector in FIND_BAR_PARTS {
        let bounds = bounds_of(cx, selector);
        assert_fits_inside(bounds, viewport, selector);
        assert_inside_box(bounds, frame, selector);
    }
}

#[gpui::test]
async fn chinese_text_is_sent_as_utf8_and_composition_is_not_sent_early(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("", cx);

    cx.simulate_input("你好");
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().to_vec()),
        "你好".as_bytes().to_vec(),
        "committed Chinese text must reach the shell as UTF-8"
    );

    // A composition that has not been committed yet stays out of the byte stream:
    // it is shown next to the caret until the input method commits it.
    let sent_before = cx.update(|_window, app| pane.read(app).sent().len());
    let marked = cx.update(|window, app| {
        use gpui::EntityInputHandler;
        pane.update(app, |pane, cx| {
            pane.replace_and_mark_text_in_range(None, "nihao", None, window, cx);
            pane.marked_text_range(window, cx)
        })
    });
    assert!(marked.is_some(), "the composition must be tracked");
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().len()),
        sent_before,
        "an uncommitted composition must not be sent to the shell"
    );
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("terminal.composition").is_some(),
        "the composition must be visible while it is being typed"
    );

    // Committing replaces the composition with its final text and sends it once.
    cx.update(|window, app| {
        use gpui::EntityInputHandler;
        pane.update(app, |pane, cx| {
            pane.replace_text_in_range(None, "你好", window, cx);
        });
    });
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().to_vec()),
        "你好你好".as_bytes().to_vec(),
        "the committed text is sent and not repeated"
    );
}

#[gpui::test]
async fn a_mouse_selection_is_copied_when_it_is_released(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world", cx);
    let viewport = bounds_of(cx, "terminal.viewport");
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    let origin = viewport.origin;
    let y = origin.y + px(cell.height * 0.5);
    // From the left half of the first cell to the right half of the fifth: the
    // edges of a selection are the halves of cells the pointer was in (R4).
    let first = point(origin.x + px(cell.width * 0.25), y);
    let fifth = point(origin.x + px(cell.width * 4.75), y);

    cx.simulate_mouse_down(first, MouseButton::Left, Modifiers::default());
    cx.simulate_mouse_move(fifth, Some(MouseButton::Left), Modifiers::default());
    cx.simulate_mouse_up(fifth, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();

    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        Some("hello".to_owned()),
        "selecting with the mouse must put the text on the clipboard"
    );
    let clipboard =
        cx.update(|_window, app| app.read_from_clipboard().and_then(|item| item.text()));
    assert_eq!(clipboard, Some("hello".to_owned()));
}

/// Window pixels of a place inside the grid, in cells: `column` 3.25 is the left
/// quarter of the fourth cell, 3.75 its right quarter.
fn grid_point_at(
    cx: &mut VisualTestContext,
    pane: &Entity<TerminalPane>,
    row: f32,
    column: f32,
) -> gpui::Point<Pixels> {
    let viewport = bounds_of(cx, "terminal.viewport");
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    point(
        viewport.origin.x + px(cell.width * column),
        viewport.origin.y + px(cell.height * row),
    )
}

/// Presses at `from`, moves to `to` with the button held and releases there, all
/// with the same modifiers; returns what the release copied.
fn drag_in_grid(
    cx: &mut VisualTestContext,
    pane: &Entity<TerminalPane>,
    from: gpui::Point<Pixels>,
    to: gpui::Point<Pixels>,
    modifiers: Modifiers,
) -> Option<String> {
    cx.simulate_mouse_down(from, MouseButton::Left, modifiers);
    cx.simulate_mouse_move(to, Some(MouseButton::Left), modifiers);
    cx.simulate_mouse_up(to, MouseButton::Left, modifiers);
    cx.run_until_parked();
    cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned))
}

/// The case from the report: dragging leftwards from just after
/// `test-c9685ba2` to the left half of its `t` dropped the `t` (R4). The edge of a
/// selection is the half of a cell the pointer is in, as in other terminals, so a
/// drag that starts or ends on the left half of a character includes it.
#[gpui::test]
async fn a_drag_from_the_left_half_of_a_character_includes_it(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("cd test-c9685ba2 now", cx);

    // Leftwards: from the left half of the space after `2` to the left half of `t`.
    let after = grid_point_at(cx, &pane, 0.5, 16.25);
    let t = grid_point_at(cx, &pane, 0.5, 3.25);
    assert_eq!(
        drag_in_grid(cx, &pane, after, t, Modifiers::default()),
        Some("test-c9685ba2".to_owned()),
        "a leftward drag ending on the left half of `t` includes the `t`"
    );

    // Rightwards: from the left half of `t` to the right half of `2`.
    let two = grid_point_at(cx, &pane, 0.5, 15.75);
    assert_eq!(
        drag_in_grid(cx, &pane, t, two, Modifiers::default()),
        Some("test-c9685ba2".to_owned()),
        "a rightward drag from the left half of `t` includes the `t`"
    );
}

/// A drag that starts on the right half of a character leaves it out, in either
/// direction, and a drag that runs left of the grid reaches the first column (R4).
#[gpui::test]
async fn the_half_of_a_cell_decides_whether_it_is_selected(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world", cx);

    // From the right half of `h` to the right half of `o`: `h` is left out.
    let h_right = grid_point_at(cx, &pane, 0.5, 0.75);
    let o_right = grid_point_at(cx, &pane, 0.5, 4.75);
    assert_eq!(
        drag_in_grid(cx, &pane, h_right, o_right, Modifiers::default()),
        Some("ello".to_owned()),
        "a drag starting on the right half of a character does not take it"
    );

    // Leftwards from the right half of `o` to the right half of `e`: `e` is left out
    // and `o` is kept.
    let e_right = grid_point_at(cx, &pane, 0.5, 1.75);
    assert_eq!(
        drag_in_grid(cx, &pane, o_right, e_right, Modifiers::default()),
        Some("llo".to_owned()),
        "a leftward drag keeps the pressed character and drops the one it ends right of"
    );

    // Leftwards past the start of the line: the pointer is left of the grid, which
    // is the first column's left half, so the first character is taken.
    let viewport = bounds_of(cx, "terminal.viewport");
    let left_of_grid = point(viewport.origin.x - px(20.0), o_right.y);
    assert_eq!(
        drag_in_grid(cx, &pane, o_right, left_of_grid, Modifiers::default()),
        Some("hello".to_owned()),
        "a drag past the start of the line selects through its first character"
    );
}

/// A press becomes a selection only after the pointer moved more than 3 px or into
/// another cell; a shaky click selects nothing and copies nothing (R4).
#[gpui::test]
async fn a_press_becomes_a_selection_past_the_drag_threshold(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world", cx);
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    assert!(
        cell.width > 2.0 * SELECTION_DRAG_THRESHOLD && cell.width < 20.0,
        "the cases below need a cell wider than twice the threshold and under 20 px"
    );
    let start = grid_point_at(cx, &pane, 0.5, 0.1);

    // 2 px inside the first cell: still a click.
    let near = point(start.x + px(2.0), start.y);
    cx.simulate_mouse_down(start, MouseButton::Left, Modifiers::default());
    cx.simulate_mouse_move(near, Some(MouseButton::Left), Modifiers::default());
    assert_eq!(
        cx.update(|_window, app| pane.read(app).selection_kind()),
        None,
        "a move under the threshold inside the pressed cell does not begin a selection"
    );
    cx.simulate_mouse_up(near, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        None,
        "a click that shook by 2 px copies nothing"
    );

    // Crossing into the next cell begins a selection even under 3 px.
    let edge = grid_point_at(cx, &pane, 0.5, 0.9);
    let across = point(edge.x + px(2.0), edge.y);
    cx.simulate_mouse_down(edge, MouseButton::Left, Modifiers::default());
    cx.simulate_mouse_move(across, Some(MouseButton::Left), Modifiers::default());
    assert_eq!(
        cx.update(|_window, app| pane.read(app).selection_kind()),
        Some(shellune_terminal::SelectionType::Simple),
        "crossing into another cell begins the selection"
    );
    cx.simulate_mouse_up(across, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();

    // More than 3 px inside one cell, into its right half, selects that character.
    let far = point(
        start.x + px((cell.width * 0.6).max(SELECTION_DRAG_THRESHOLD + 1.0)),
        start.y,
    );
    assert_eq!(
        drag_in_grid(cx, &pane, start, far, Modifiers::default()),
        Some("h".to_owned()),
        "a move past the threshold begins the selection"
    );
}

/// Shift+click moves the end of the selection to the click; with nothing selected
/// it selects from the cursor to the click (R4).
#[gpui::test]
async fn shift_click_extends_the_selection(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world", cx);
    let h = grid_point_at(cx, &pane, 0.5, 0.25);
    let o = grid_point_at(cx, &pane, 0.5, 4.75);
    assert_eq!(
        drag_in_grid(cx, &pane, h, o, Modifiers::default()),
        Some("hello".to_owned())
    );

    let d = grid_point_at(cx, &pane, 0.5, 10.75);
    cx.simulate_mouse_down(d, MouseButton::Left, Modifiers::shift());
    cx.simulate_mouse_up(d, MouseButton::Left, Modifiers::shift());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        Some("hello world".to_owned()),
        "Shift+click moves the end of the selection to the click"
    );

    // A plain click clears the selection; Shift+click then selects from the cursor,
    // which is after `world`, back to the click.
    cx.simulate_mouse_down(h, MouseButton::Left, Modifiers::default());
    cx.simulate_mouse_up(h, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).selection_kind()),
        None
    );
    let w = grid_point_at(cx, &pane, 0.5, 6.25);
    cx.simulate_mouse_down(w, MouseButton::Left, Modifiers::shift());
    cx.simulate_mouse_up(w, MouseButton::Left, Modifiers::shift());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        Some("world".to_owned()),
        "with nothing selected, Shift+click selects from the cursor to the click"
    );
}

/// Alt (Option on macOS) drags a block: the same columns from every row (R4).
#[gpui::test]
async fn alt_drag_selects_a_block(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("abcd\r\nefgh\r\nijkl", cx);
    let from = grid_point_at(cx, &pane, 0.5, 1.25);
    let to = grid_point_at(cx, &pane, 2.5, 2.75);
    assert_eq!(
        drag_in_grid(cx, &pane, from, to, Modifiers::alt()),
        Some("bc\nfg\njk".to_owned()),
        "an Alt drag takes columns 2-3 of every row it spans"
    );
    assert_eq!(
        cx.update(|_window, app| pane.read(app).selection_kind()),
        Some(shellune_terminal::SelectionType::Block)
    );

    // Without Alt the same drag runs through the text.
    assert_eq!(
        drag_in_grid(cx, &pane, from, to, Modifiers::default()),
        Some("bcd\nefgh\nijk".to_owned())
    );
}

/// A drag keeps following the pointer after it leaves the grid, and the release
/// outside the grid still ends it (R4).
#[gpui::test]
async fn a_drag_that_leaves_the_grid_keeps_selecting(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world\r\nsecond line", cx);
    let viewport = bounds_of(cx, "terminal.viewport");
    let h = grid_point_at(cx, &pane, 0.5, 0.25);

    // Right of the grid and of the window, on the first row.
    let outside = point(viewport.right() + px(400.0), h.y);
    cx.simulate_mouse_down(h, MouseButton::Left, Modifiers::default());
    cx.simulate_mouse_move(outside, Some(MouseButton::Left), Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).selected_text()),
        Some("hello world".to_owned()),
        "a pointer right of the grid selects to the end of its row"
    );

    // Down onto the second row, still outside, then released there.
    let lower = grid_point_at(cx, &pane, 1.5, 0.0);
    let outside_lower = point(viewport.right() + px(400.0), lower.y);
    cx.simulate_mouse_move(outside_lower, Some(MouseButton::Left), Modifiers::default());
    cx.simulate_mouse_up(outside_lower, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        Some("hello world\nsecond line".to_owned()),
        "a release outside the grid ends the drag and copies it"
    );

    // The drag is over: moving the pointer afterwards changes nothing.
    let elsewhere = grid_point_at(cx, &pane, 0.5, 2.0);
    cx.simulate_mouse_move(elsewhere, None, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).selected_text()),
        Some("hello world\nsecond line".to_owned())
    );
}

/// A drag held past the top edge scrolls the history every 50 ms, one line per
/// row height past the edge and at most 5 lines a step, and extends the selection
/// with it (R4).
#[gpui::test]
async fn a_drag_past_the_edge_scrolls_the_history(cx: &mut TestAppContext) {
    let mut content = String::new();
    for line in 0..200 {
        content.push_str(&format!("line {line}\r\n"));
    }
    let (pane, cx) = pane_with(&content, cx);
    let rows = cx.update(|_window, app| pane.read(app).grid().rows);
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    let viewport = bounds_of(cx, "terminal.viewport");
    assert_eq!(cx.update(|_window, app| pane.read(app).display_offset()), 0);

    let press = grid_point_at(cx, &pane, 2.5, 0.25);
    cx.simulate_mouse_down(press, MouseButton::Left, Modifiers::default());
    // One and a half rows above the grid: two lines a step.
    let above = point(press.x, viewport.origin.y - px(cell.height * 1.5));
    cx.simulate_mouse_move(above, Some(MouseButton::Left), Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).display_offset()),
        0,
        "nothing scrolls before the first step"
    );
    cx.executor()
        .advance_clock(crate::app::terminal::SELECTION_AUTOSCROLL_INTERVAL);
    cx.run_until_parked();
    assert_eq!(cx.update(|_window, app| pane.read(app).display_offset()), 2);

    // Far above: the step is capped at five lines.
    let far = point(press.x, viewport.origin.y - px(cell.height * 20.0));
    cx.simulate_mouse_move(far, Some(MouseButton::Left), Modifiers::default());
    cx.executor()
        .advance_clock(crate::app::terminal::SELECTION_AUTOSCROLL_INTERVAL);
    cx.run_until_parked();
    assert_eq!(cx.update(|_window, app| pane.read(app).display_offset()), 7);

    // Back inside the grid the scrolling stops.
    let inside = grid_point_at(cx, &pane, 0.5, 0.25);
    cx.simulate_mouse_move(inside, Some(MouseButton::Left), Modifiers::default());
    cx.executor()
        .advance_clock(crate::app::terminal::SELECTION_AUTOSCROLL_INTERVAL * 4);
    cx.run_until_parked();
    assert_eq!(cx.update(|_window, app| pane.read(app).display_offset()), 7);

    cx.simulate_mouse_up(inside, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();
    // The grid holds `line 0` .. `line 199` and the empty line the cursor is on. The
    // press was on row 2 with the view at the bottom; the release on row 0 with the
    // view 7 lines back.
    let first = 201 - rows - 7;
    let last = 201 - rows + 2;
    let expected = (first..last)
        .map(|line| format!("line {line}"))
        .collect::<Vec<_>>()
        .join("\n");
    let copied = cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned));
    assert_eq!(
        copied.as_deref().map(str::trim_end),
        Some(expected.as_str()),
        "the selection runs from the row scrolled into view to where the drag began"
    );
}

/// In a program that took the mouse, Shift keeps the pointer for the terminal: a
/// Shift+drag selects and copies locally and nothing is reported (R4).
#[gpui::test]
async fn shift_drag_selects_locally_while_a_program_has_the_mouse(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world\x1b[?1000h\x1b[?1006h", cx);
    let h = grid_point_at(cx, &pane, 0.5, 0.25);
    let o = grid_point_at(cx, &pane, 0.5, 4.75);
    let sent_before = cx.update(|_window, app| pane.read(app).sent().len());
    assert_eq!(
        drag_in_grid(cx, &pane, h, o, Modifiers::shift()),
        Some("hello".to_owned()),
        "Shift+drag selects even while the program takes the mouse"
    );
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().len()),
        sent_before,
        "a Shift+drag is not reported to the program"
    );

    // Without Shift the drag is the program's: it is reported and nothing is copied.
    let w = grid_point_at(cx, &pane, 0.5, 6.25);
    let d = grid_point_at(cx, &pane, 0.5, 10.75);
    cx.simulate_mouse_down(w, MouseButton::Left, Modifiers::default());
    cx.simulate_mouse_move(d, Some(MouseButton::Left), Modifiers::default());
    cx.simulate_mouse_up(d, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();
    let sent = cx.update(|_window, app| pane.read(app).sent()[sent_before..].to_vec());
    assert!(
        String::from_utf8_lossy(&sent).contains("\x1b[<0;"),
        "a plain drag is reported to the program: {sent:?}"
    );
    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        Some("hello".to_owned()),
        "a reported drag copies nothing"
    );
}

/// A double click still selects a word and a triple click the line (R4).
#[gpui::test]
async fn double_and_triple_clicks_select_a_word_and_a_line(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world", cx);
    let w = grid_point_at(cx, &pane, 0.5, 7.5);
    for (count, expected) in [(2, "world"), (3, "hello world")] {
        cx.simulate_event(gpui::MouseDownEvent {
            position: w,
            button: MouseButton::Left,
            modifiers: Modifiers::default(),
            click_count: count,
            first_mouse: false,
        });
        cx.simulate_event(gpui::MouseUpEvent {
            position: w,
            button: MouseButton::Left,
            modifiers: Modifiers::default(),
            click_count: count,
        });
        cx.run_until_parked();
        // A line selection carries its line break, as it did before.
        let copied = cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned));
        assert_eq!(
            copied.as_deref().map(str::trim_end),
            Some(expected),
            "a click {count} times selects and copies {expected:?}"
        );
    }
}

#[gpui::test]
async fn a_click_in_the_terminal_leaves_the_clipboard_untouched(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("hello world", cx);

    // What the user copied elsewhere, before clicking into the terminal to paste it.
    cx.update(|_window, app| {
        app.write_to_clipboard(ClipboardItem::new_string("copied elsewhere".to_owned()));
    });

    let viewport = bounds_of(cx, "terminal.viewport");
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    // Pressing and releasing on the same cell: moving the caret, not selecting text.
    let target = point(
        viewport.origin.x + px(cell.width * 0.5),
        viewport.origin.y + px(cell.height * 0.5),
    );
    cx.simulate_mouse_down(target, MouseButton::Left, Modifiers::default());
    cx.simulate_mouse_up(target, MouseButton::Left, Modifiers::default());
    cx.run_until_parked();

    assert_eq!(
        cx.update(|_window, app| app.read_from_clipboard().and_then(|item| item.text())),
        Some("copied elsewhere".to_owned()),
        "a click must not replace the clipboard with the one cell under the pointer"
    );
    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        None,
        "a click selects nothing, so there is nothing to copy"
    );
}

