/// One shell, split sideways, so one tab holds two panes at once (R4, R7).
///
/// Returns the sessions of the two panes in tree order and the one that receives input,
/// or `None` when the machine has no shell to start.
fn split_tab(
    cx: &mut TestAppContext,
) -> Option<(
    Entity<ShelluneView>,
    &mut VisualTestContext,
    SessionId,
    SessionId,
)> {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    if cx.update(|_window, app| view.read(app).workspace().shells().is_empty()) {
        return None;
    }
    new_default_shell(cx);
    cx.update(|window, app| {
        view.update(app, |view, cx| {
            view.split_active_for_test(SplitAxis::LeftRight, window, cx);
        });
    });
    cx.run_until_parked();
    let sessions: Vec<SessionId> = cx
        .update(|_window, app| view.read(app).active_leaf_sessions_for_test())
        .into_iter()
        .flatten()
        .collect();
    assert_eq!(sessions.len(), 2, "the tab holds two started panes");
    assert_eq!(
        cx.update(|_window, app| view.read(app).open_tabs().len()),
        1,
        "the split is still one tab"
    );
    let (left, right) = (sessions[0], sessions[1]);
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(right),
        "the newest pane is the one that receives input"
    );
    Some((view, cx, left, right))
}

#[gpui::test]
async fn a_bell_or_a_reported_end_in_a_split_pane_on_screen_marks_nothing(cx: &mut TestAppContext) {
    let Some((view, cx, unfocused, focused)) = split_tab(cx) else {
        return;
    };

    // The unfocused pane is on screen beside the one being typed into, so its bell is
    // news the user is already looking at: it marks nothing, on this tab or any other.
    feed_session(cx, &view, unfocused, b"\x07");
    assert!(
        unread_of(cx, &view, unfocused).is_empty(),
        "a bell in the visible pane of the tab on screen is not a background notice"
    );
    assert!(unread_of(cx, &view, focused).is_empty());
    assert!(
        cx.debug_bounds("session.tab.mark.bell.0").is_none(),
        "the tab on screen carries no bell mark"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(focused),
        "the bell moved no focus"
    );

    // The same holds for a command end the shell itself reported there.
    feed_session(cx, &view, unfocused, REPORTED_COMMAND);
    assert!(
        unread_of(cx, &view, unfocused).is_empty(),
        "a reported end in the visible pane marks nothing either"
    );
    assert!(
        cx.debug_bounds("session.tab.mark.finished.0").is_none(),
        "the tab on screen carries no command-end mark"
    );
    // The block is still recorded: the reminder is what is absent, not the record.
    let blocks = cx.update(|_window, app| {
        view.read(app)
            .pane_of(unfocused)
            .map(|pane| pane.read(app).command_block_count_for_test())
    });
    assert_eq!(blocks, Some(1), "the shell's command block is still kept");

    // A bell in the pane that has the keyboard is not a reminder at all.
    feed_session(cx, &view, focused, b"\x07");
    feed_session(cx, &view, focused, REPORTED_COMMAND);
    assert!(
        unread_of(cx, &view, focused).is_empty(),
        "the pane being typed into never marks its own tab"
    );
    assert!(
        cx.debug_bounds("session.tab.mark.bell.0").is_none()
            && cx.debug_bounds("session.tab.mark.finished.0").is_none(),
        "a split tab on screen stays unmarked"
    );
}

#[gpui::test]
async fn a_marked_split_tab_is_cleared_when_it_is_looked_at(cx: &mut TestAppContext) {
    let Some((view, cx, unfocused, focused)) = split_tab(cx) else {
        return;
    };
    // A second tab takes the screen, so the first one is now in the background.
    new_default_shell(cx);
    let other = cx
        .update(|_window, app| view.read(app).active_session())
        .filter(|id| *id != unfocused && *id != focused)
        .expect("the new shell is the tab on screen");

    // Both panes of the background tab are in that background tab, so each kind of news
    // from either of them marks that tab and only that tab (R7).
    feed_session(cx, &view, unfocused, b"\x07");
    feed_session(cx, &view, focused, REPORTED_COMMAND);
    assert!(
        unread_of(cx, &view, unfocused).bell,
        "the bell marks the tab it happened in"
    );
    assert!(
        unread_of(cx, &view, focused).finished,
        "and the reported end marks the same tab, whichever pane it came from"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(other),
        "a background mark takes no focus and switches no tab"
    );
    assert!(
        unread_of(cx, &view, other).is_empty(),
        "the tab on screen is not marked for another tab's news"
    );
    assert!(
        cx.debug_bounds("session.tab.mark.bell.0").is_some()
            && cx.debug_bounds("session.tab.mark.finished.0").is_some(),
        "the strip says what the background tab is carrying"
    );
    assert!(
        cx.debug_bounds("session.tab.mark.bell.1").is_none(),
        "the tab on screen stays unmarked"
    );

    // Looking at the marked tab clears both marks, and the pane with the keyboard in it
    // is the one the layout calls active, whether or not it was the pane that rang.
    click(cx, "session.tab.0");
    assert!(
        unread_of(cx, &view, unfocused).is_empty() && unread_of(cx, &view, focused).is_empty(),
        "viewing the tab cleared what it was carrying"
    );

    // Moving focus to the other pane of the same tab keeps it clear: the tab is being
    // looked at as a whole, and switching panes inside it is not new news.
    cx.update(|window, app| {
        view.update(app, |view, cx| {
            view.focus_direction_for_test(Direction::Left, window, cx);
        });
    });
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(unfocused),
        "the keyboard moved to the other pane"
    );
    assert!(
        unread_of(cx, &view, unfocused).is_empty() && unread_of(cx, &view, focused).is_empty(),
        "a focus change inside the tab leaves no mark behind"
    );
    feed_session(cx, &view, focused, b"\x07");
    feed_session(cx, &view, focused, REPORTED_COMMAND);
    assert!(
        unread_of(cx, &view, focused).is_empty(),
        "the panes beside the focused one are seen, so they still mark nothing"
    );
}

/// Asserts a measured box stays inside another box, on both axes.
///
/// A tab draws its marks and its close button inside its own box; anything measured
/// outside it would be drawn over the neighbouring tab, and a pointer landing there
/// would act on that neighbour instead (R4, R7).
fn assert_stays_inside_box(inner: gpui::Bounds<Pixels>, outer: gpui::Bounds<Pixels>, what: &str) {
    assert!(
        inner.size.width > px(0.0) && inner.size.height > px(0.0),
        "{what} was measured with an empty box: {inner:?}"
    );
    assert!(
        inner.origin.x >= outer.origin.x - px(0.5)
            && inner.origin.x + inner.size.width <= outer.origin.x + outer.size.width + px(0.5),
        "{what} leaves its box sideways: {inner:?} in {outer:?}"
    );
    assert!(
        inner.origin.y >= outer.origin.y - px(0.5)
            && inner.origin.y + inner.size.height <= outer.origin.y + outer.size.height + px(0.5),
        "{what} leaves its box vertically: {inner:?} in {outer:?}"
    );
}

#[gpui::test]
async fn a_marked_tab_keeps_its_marks_and_close_button_inside_itself(cx: &mut TestAppContext) {
    let Some((view, cx)) = two_shells(cx) else {
        return;
    };
    // Enough tabs that the strip cannot give any of them more than its minimum: the
    // state in which a tab's own content used to be squeezed outward.
    for _ in 0..6 {
        new_default_shell(cx);
    }
    let tabs = cx.update(|_window, app| view.read(app).open_tabs());
    assert_eq!(
        tabs.len(),
        8,
        "the strip is crowded enough to shrink every tab"
    );
    let marked = tabs[1];
    feed_session(cx, &view, marked, b"\x07");
    feed_session(cx, &view, marked, REPORTED_COMMAND);
    assert!(
        unread_of(cx, &view, marked).bell && unread_of(cx, &view, marked).finished,
        "the background tab carries both marks"
    );
    // The newest tab is the current one, so the strip has scrolled to it; the marked
    // tab is reached the way a user reaches it, with the strip's own scroll button.
    scroll_tab_strip_to_start(cx, &view);

    // The marked tab is wider than a bare one, because its two words need the room;
    // they are not squeezed into a title's width.
    let tab = bounds_of(cx, "session.tab.1");
    let bare = bounds_of(cx, "session.tab.2");
    assert!(
        tab.size.width > bare.size.width,
        "the marked tab reserves room for its words: {tab:?} against {bare:?}"
    );

    // Every part of the tab stays inside the tab, so nothing is drawn over the next
    // tab, and the close button is the one the pointer finds inside this tab.
    for selector in [
        "session.tab.mark.bell.1",
        "session.tab.mark.finished.1",
        "session.tab.close.1",
    ] {
        assert_stays_inside_box(bounds_of(cx, selector), tab, selector);
    }
    assert_pointer_target(cx, "session.tab.close.1");
    assert!(
        bare.origin.x >= tab.origin.x + tab.size.width - px(0.5),
        "the next tab starts after the marked one: {tab:?} then {bare:?}"
    );

    // Choosing the close button of the marked tab closes that tab and only it.
    click(cx, "session.tab.close.1");
    let mut expected = tabs;
    expected.remove(1);
    assert_eq!(
        cx.update(|_window, app| view.read(app).open_tabs()),
        expected,
        "the close button belongs to the tab it is drawn in, not to its neighbour"
    );
}

/// Clicks the strip's left scroll button until no tab is hidden past its left end.
///
/// Whether one is hidden is read from the strip's scroll state: a scroll button that
/// went away keeps its last debug bounds, so its bounds cannot say it is gone.
fn scroll_tab_strip_to_start(cx: &mut VisualTestContext, view: &Entity<ShelluneView>) {
    for _ in 0..40 {
        if !cx.update(|_window, app| view.read(app).tab_strip_ends_for_test().0) {
            return;
        }
        click(cx, "session.tabs.scroll.start");
    }
    panic!("the strip never reached its first tab");
}

/// Asserts a tab is wholly inside the visible part of the strip.
fn assert_tab_in_view(cx: &mut VisualTestContext, selector: &'static str) {
    let strip = bounds_of(cx, "session.tabs");
    assert_inside_horizontally(bounds_of(cx, selector), strip, selector);
}

/// Asserts every part of the strip's tab at `index` stays inside that tab, and that the
/// tab keeps the strip's width range (R2, R4): from the narrowest the row as drawn
/// allows (`min`) to the widest a tab grows.
fn assert_tab_holds_its_parts(
    cx: &mut VisualTestContext,
    index: usize,
    min: Pixels,
    metrics: Metrics,
) {
    let tab: &'static str = Box::leak(format!("session.tab.{index}").into_boxed_str());
    let bounds = bounds_of(cx, tab);
    for part in ["dot", "title", "close"] {
        let selector: &'static str =
            Box::leak(format!("session.tab.{part}.{index}").into_boxed_str());
        assert_stays_inside_box(bounds_of(cx, selector), bounds, selector);
    }
    assert!(
        bounds.size.width >= min - px(0.5)
            && bounds.size.width <= metrics.tab_max_width() + px(0.5),
        "{tab} keeps the strip's width range: {bounds:?}"
    );
    assert_pointer_target(
        cx,
        Box::leak(format!("session.tab.close.{index}").into_boxed_str()),
    );
}

/// Asserts the pinned hosts tab is drawn whole: inside the window, before the strip,
/// and with its word inside it when it shows one (R2).
fn assert_hosts_tab_whole(cx: &mut VisualTestContext, viewport: Size<Pixels>) {
    let hosts = bounds_of(cx, "nav.hosts");
    assert_fits_inside(hosts, viewport, "the hosts tab");
    let strip = bounds_of(cx, "session.tabs");
    assert!(
        hosts.origin.x + hosts.size.width <= strip.origin.x + px(0.5),
        "the hosts tab ends where the strip starts: {hosts:?} then {strip:?}"
    );
    assert_pointer_target(cx, "nav.hosts");
}

#[gpui::test]
async fn a_tab_keeps_its_dot_title_and_close_inside_itself_at_any_width(cx: &mut TestAppContext) {
    let Some((view, cx)) = two_shells(cx) else {
        return;
    };
    let tabs = cx.update(|_window, app| view.read(app).open_tabs());
    let (long, connecting) = (tabs[0], tabs[1]);
    let long_name = "production-database-primary-eu-west-1 replica and log watcher";
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            let workspace = view.workspace_mut_for_test();
            let tab = workspace
                .tab_of_session(long)
                .expect("the first session has a tab");
            assert!(workspace.rename_tab(tab, Some(long_name.to_owned())));
            // The second session is connecting again, the state whose word used to
            // widen the tab past the strip's room.
            assert!(workspace.session_failed(connecting, SessionFailure::ConnectionLost));
            assert!(workspace.session_reconnecting(connecting));
            cx.notify();
        });
    });
    cx.run_until_parked();
    wait_for_loading_card(cx);
    assert_eq!(
        session_state(cx, &view, connecting),
        Some(SessionState::Connecting),
        "the second tab is connecting"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).tab_label_for_test(long)),
        long_name,
        "the whole name is the tab's title; the strip only cuts what it draws"
    );

    // In a narrow window at 115% text the full row does not always fit, so the row
    // draws its compact form: the hosts tab as its icon and the current session tab
    // alone, whole, with the list of every tab beside it to reach the other one.
    for (viewport, zoom) in [
        (design_window(), Zoom::Regular),
        (narrow_window(), Zoom::Regular),
        (design_window(), Zoom::Comfortable),
        (compact_window(), Zoom::Comfortable),
    ] {
        cx.update(|_window, app| {
            view.update(app, |view, cx| {
                view.workspace_mut_for_test().set_zoom(zoom);
                cx.notify();
            });
        });
        cx.simulate_resize(viewport);
        cx.run_until_parked();
        let metrics = Metrics::new(zoom);
        let compact = cx.update(|_window, app| view.read(app).header_compact_for_test());
        assert_eq!(
            compact,
            viewport == compact_window() && zoom == Zoom::Comfortable,
            "only a window narrower than the full row needs the compact form ({viewport:?}, {zoom:?})"
        );
        let min = cx.update(|_window, app| view.read(app).tab_min_width_for_test());
        assert_hosts_tab_whole(cx, viewport);
        // The pinned hosts tab is its icon alone at every width; its name is in the
        // tooltip, and the sidebar of the page it opens names the list.
        assert!(
            cx.debug_bounds("nav.hosts.title").is_none(),
            "the hosts tab draws no word ({viewport:?}, {zoom:?})"
        );
        // The list of every tab is there exactly when a tab is out of sight (R2).
        let listed = cx.update(|_window, app| view.read(app).tab_list_control_shown_for_test());
        let overflows = cx.update(|_window, app| view.read(app).tab_strip_overflows_for_test());
        assert_eq!(
            listed,
            compact || overflows,
            "the list control follows the strip ({viewport:?}, {zoom:?})"
        );
        // Nothing beside the strip is pushed out of the window.
        let mut beside = vec!["header.primary", "palette.open", "nav.settings"];
        if listed {
            beside.push("tabs.list.open");
        }
        for selector in beside {
            assert_fits_inside(bounds_of(cx, selector), viewport, selector);
            assert_pointer_target(cx, selector);
        }
        if Platform::current() == Platform::Windows {
            for selector in ["window.minimize", "window.maximize", "window.close"] {
                assert_fits_inside(bounds_of(cx, selector), viewport, selector);
                assert_pointer_target(cx, selector);
            }
        }
        // The current tab is in view, connecting and whole.
        assert_tab_in_view(cx, "session.tab.1");
        assert_tab_holds_its_parts(cx, 1, min, metrics);
        // The connecting tab breathes when motion is allowed and is still otherwise.
        let breathing = cx.debug_bounds("session.tab.dot.1.pulse").is_some();
        assert_eq!(
            breathing,
            cx.update(|_window, _app| theme::motion_allowed()),
            "the connecting tab's dot breathes exactly when motion is allowed"
        );
        // The other one is reached with the strip's own scroll button when the window
        // is too narrow for both, and from the list of every tab in a compact row.
        if compact {
            click(cx, "tabs.list.open");
            click(cx, "tabs.list.row.0");
            assert_eq!(
                cx.update(|_window, app| view.read(app).active_session()),
                Some(long),
                "the list reaches the tab the compact row does not show"
            );
        } else {
            scroll_tab_strip_to_start(cx, &view);
        }
        assert_tab_in_view(cx, "session.tab.0");
        assert_tab_holds_its_parts(cx, 0, min, metrics);
        // The long name is cut inside its own tab: the title ends before the close
        // button starts. In a compact row the close floats over the end of the title
        // and shows under the pointer, so the title has that room (T9); both still
        // stay inside the tab.
        let title = bounds_of(cx, "session.tab.title.0");
        let close = bounds_of(cx, "session.tab.close.0");
        if compact {
            let tab = bounds_of(cx, "session.tab.0");
            assert!(
                title.right() <= tab.right() + px(0.5) && close.right() <= tab.right() + px(0.5),
                "the title and the close stay inside the tab at {zoom:?}: {title:?} {close:?} in {tab:?}"
            );
        } else {
            assert!(
                title.origin.x + title.size.width <= close.origin.x + px(0.5),
                "the long title stops before its close button at {zoom:?}: {title:?} then {close:?}"
            );
        }
        assert!(
            cx.debug_bounds("session.tab.dot.0.pulse").is_none(),
            "a live tab's dot is still"
        );
    }
}

/// Asserts the current tab of the strip, the second one, is drawn whole in the top row
/// whatever the row says beside it, and that nothing the row holds after the strip is
/// pushed out of the window (R2, R9).
fn assert_current_tab_whole_beside_notices(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    viewport: Size<Pixels>,
    zoom: Zoom,
    form: &str,
) {
    let metrics = Metrics::new(zoom);
    let min = cx.update(|_window, app| view.read(app).tab_min_width_for_test());
    assert_tab_in_view(cx, "session.tab.1");
    assert_tab_holds_its_parts(cx, 1, min, metrics);
    // The strip clips what it cannot hold, so its own box is not enough: the tab and
    // its close button end before the first control after the strip begins - the list
    // of every tab while a tab is out of sight, the "+" otherwise (R2).
    let listed = cx.update(|_window, app| view.read(app).tab_list_control_shown_for_test());
    let next: &'static str = if listed {
        "tabs.list.open"
    } else {
        "header.primary"
    };
    let after = bounds_of(cx, next);
    for selector in ["session.tab.1", "session.tab.close.1"] {
        let bounds = bounds_of(cx, selector);
        assert!(
            bounds.origin.x + bounds.size.width <= after.origin.x + px(0.5),
            "{selector} ends before {next} at {viewport:?} {zoom:?} ({form}): \
             {bounds:?} then {after:?}"
        );
    }
    for selector in [next, "palette.open", "nav.settings"] {
        assert_fits_inside(bounds_of(cx, selector), viewport, selector);
        assert_pointer_target(cx, selector);
    }
    if Platform::current() == Platform::Windows {
        for selector in ["window.minimize", "window.maximize", "window.close"] {
            assert_fits_inside(bounds_of(cx, selector), viewport, selector);
            assert_pointer_target(cx, selector);
        }
    }
}

#[gpui::test]
async fn the_top_rows_notices_never_cut_the_current_tab(cx: &mut TestAppContext) {
    let Some((view, cx)) = two_shells(cx) else {
        return;
    };
    let tall = |width: f32| size(px(width), px(720.0));
    // The widths around the row's thresholds: below the full row's width, where the
    // row is compact and folds its notices; the narrow window at both text sizes, where
    // a notice is an icon; the width just past the full row's own threshold, where one
    // notice used to cut the current tab; the design window; and room for the words.
    let cases = [
        (tall(520.0), Zoom::Comfortable),
        (tall(680.0), Zoom::Comfortable),
        (narrow_window(), Zoom::Regular),
        (narrow_window(), Zoom::Comfortable),
        (tall(1080.0), Zoom::Comfortable),
        (tall(1140.0), Zoom::Comfortable),
        (design_window(), Zoom::Comfortable),
        (tall(1200.0), Zoom::Comfortable),
        (tall(1920.0), Zoom::Comfortable),
    ];

    // A newer release alone, then with a failed sync beside it: each notice the row
    // shows takes its room from the caption and the row's form, never from the tab.
    for phase in ["update", "update+sync"] {
        cx.update(|_window, app| {
            view.update(app, |view, cx| {
                view.offer_update_for_test(cx);
                if phase == "update+sync" {
                    view.fail_sync_for_test(cx);
                }
            });
        });
        let notices: &[&'static str] = if phase == "update" {
            &["topbar.update"]
        } else {
            &["topbar.update", "topbar.sync"]
        };
        let mut forms = Vec::new();
        for (viewport, zoom) in cases {
            cx.update(|_window, app| {
                view.update(app, |view, cx| {
                    view.workspace_mut_for_test().set_zoom(zoom);
                    cx.notify();
                });
            });
            cx.simulate_resize(viewport);
            cx.run_until_parked();
            let form = cx.update(|_window, app| view.read(app).topbar_notice_form_for_test());
            let compact = cx.update(|_window, app| view.read(app).header_compact_for_test());
            assert_eq!(
                form == "folded",
                compact,
                "a compact row and only it folds the notices ({viewport:?}, {zoom:?})"
            );
            // One notice at the narrow window still leaves the full row: its words do
            // not fit, so it is an icon. Two fold it into the controls instead.
            if viewport == narrow_window() && zoom == Zoom::Comfortable && !compact {
                assert_eq!(
                    form, "icon",
                    "the full row shows a notice as an icon when its words do not fit"
                );
            }
            forms.push(form);
            assert_current_tab_whole_beside_notices(cx, &view, viewport, zoom, form);

            let metrics = Metrics::new(zoom);
            let settings = bounds_of(cx, "nav.settings");
            for &notice in notices {
                let bounds = bounds_of(cx, notice);
                assert_fits_inside(bounds, viewport, notice);
                match form {
                    // Folded into the settings button: its mark is the button's own.
                    "folded" => assert_stays_inside_box(bounds, settings, notice),
                    "icon" => {
                        assert_pointer_target(cx, notice);
                        assert!(
                            bounds.size.width <= metrics.scale(30.0) + px(0.5),
                            "{notice} is an icon of the row's buttons: {bounds:?}"
                        );
                    }
                    _ => assert!(
                        bounds.size.width <= metrics.scale(200.0) + px(0.5),
                        "{notice} keeps to its room as words: {bounds:?}"
                    ),
                }
            }
        }
        for form in ["folded", "icon", "words"] {
            assert!(
                forms.contains(&form),
                "the widths reach every form of the notices ({phase}): {forms:?}"
            );
        }

        // In the compact row the settings button leads where the folded notice did: the
        // sync settings for a failed sync, else the update card.
        cx.update(|_window, app| {
            view.update(app, |view, cx| {
                view.workspace_mut_for_test().set_zoom(Zoom::Comfortable);
                cx.notify();
            });
        });
        cx.simulate_resize(tall(520.0));
        cx.run_until_parked();
        assert!(cx.update(|_window, app| view.read(app).header_compact_for_test()));
        click(cx, "nav.settings");
        assert_eq!(
            cx.update(|_window, app| view.read(app).workspace().destination()),
            Destination::Settings
        );
        let page = cx.update(|_window, app| view.read(app).settings_page_id());
        if phase == "update" {
            assert_eq!(page, ("about", "update"), "the release leads to its card");
        } else {
            assert_eq!(page.0, "sync", "the failed sync leads to the sync settings");
        }
        cx.update(|window, app| view.update(app, |view, cx| view.select_tab(1, window, cx)));
        cx.run_until_parked();
        assert_current_tab_whole_beside_notices(
            cx,
            &view,
            narrow_window(),
            Zoom::Comfortable,
            "folded",
        );
    }
}

#[gpui::test]
async fn twenty_tabs_scroll_and_leave_the_window_buttons_reachable(cx: &mut TestAppContext) {
    let Some((view, cx)) = two_shells(cx) else {
        return;
    };
    for _ in 0..18 {
        new_default_shell(cx);
    }
    let tabs = cx.update(|_window, app| view.read(app).open_tabs());
    assert_eq!(tabs.len(), 20, "twenty tabs are open");

    for viewport in [design_window(), narrow_window()] {
        cx.simulate_resize(viewport);
        cx.run_until_parked();
        // The newest tab is the current one and the strip has brought it into view; the
        // first ones are hidden past the left end, which says so.
        assert_tab_in_view(cx, "session.tab.19");
        assert_eq!(
            cx.update(|_window, app| view.read(app).tab_strip_ends_for_test()),
            (true, false),
            "tabs run on past the left end only"
        );
        assert_pointer_target(cx, "session.tabs.scroll.start");
        assert_inside_horizontally(
            bounds_of(cx, "session.tabs.scroll.start"),
            bounds_of(cx, "session.tabs"),
            "the left scroll button",
        );

        assert!(
            cx.update(|_window, app| view.read(app).tab_list_control_shown_for_test()),
            "twenty tabs run on, so the list of every tab is beside the strip"
        );
        // Nothing the row holds beside the strip is pushed out of the window, and the
        // strip ends before the controls after it begin.
        let strip = bounds_of(cx, "session.tabs");
        for selector in [
            "tabs.list.open",
            "header.primary",
            "palette.open",
            "nav.settings",
        ] {
            let bounds = bounds_of(cx, selector);
            assert_fits_inside(bounds, viewport, selector);
            assert_pointer_target(cx, selector);
            assert!(
                bounds.origin.x >= strip.origin.x + strip.size.width - px(0.5),
                "{selector} sits after the strip: {bounds:?} after {strip:?}"
            );
        }
        if Platform::current() == Platform::Windows {
            for selector in ["window.minimize", "window.maximize", "window.close"] {
                assert_fits_inside(bounds_of(cx, selector), viewport, selector);
                assert_pointer_target(cx, selector);
            }
        }
    }

    // At 520 wide and 115% text the compact row shows the current tab alone and whole,
    // and every control beside it - the list of the other nineteen among them - and the
    // window buttons stay inside the window and take the pointer.
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.workspace_mut_for_test().set_zoom(Zoom::Comfortable);
            cx.notify();
        });
    });
    cx.simulate_resize(compact_window());
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).header_compact_for_test()));
    assert!(cx.update(|_window, app| view.read(app).tab_list_control_shown_for_test()));
    assert_tab_in_view(cx, "session.tab.19");
    assert_eq!(
        cx.update(|_window, app| view.read(app).tab_strip_ends_for_test()),
        (false, false),
        "the compact strip hides nothing past its ends: it shows one tab"
    );
    assert_hosts_tab_whole(cx, compact_window());
    for selector in [
        "tabs.list.open",
        "header.primary",
        "palette.open",
        "nav.settings",
    ] {
        assert_fits_inside(bounds_of(cx, selector), compact_window(), selector);
        assert_pointer_target(cx, selector);
    }
    if Platform::current() == Platform::Windows {
        for selector in ["window.minimize", "window.maximize", "window.close"] {
            assert_fits_inside(bounds_of(cx, selector), narrow_window(), selector);
            assert_pointer_target(cx, selector);
        }
    }
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.workspace_mut_for_test().set_zoom(Zoom::Regular);
            cx.notify();
        });
    });

    // The strip scrolls back to its first tab with its own button, and then says that
    // the tabs run on past the right end instead.
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    scroll_tab_strip_to_start(cx, &view);
    assert_tab_in_view(cx, "session.tab.0");
    assert_eq!(
        cx.update(|_window, app| view.read(app).tab_strip_ends_for_test()),
        (false, true),
        "after scrolling back, the tabs run on past the right end only"
    );

    // Choosing a tab that is out of view - here from the list of every tab - brings it
    // into the strip's view: another tab, and the current one after it was scrolled
    // away.
    click(cx, "tabs.list.open");
    click(cx, "tabs.list.row.12");
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(tabs[12]),
        "the chosen tab is the current one"
    );
    assert_tab_in_view(cx, "session.tab.12");
    scroll_tab_strip_to_start(cx, &view);
    // The last row is below the list's fold, so it is chosen the way the list and the
    // tab shortcuts choose a tab.
    cx.update(|window, app| view.update(app, |view, cx| view.select_tab(19, window, cx)));
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(tabs[19]),
        "the last tab is the current one again"
    );
    assert_tab_in_view(cx, "session.tab.19");
    // The current tab scrolled away and chosen again comes back into view as well.
    scroll_tab_strip_to_start(cx, &view);
    cx.update(|window, app| view.update(app, |view, cx| view.select_tab(19, window, cx)));
    cx.run_until_parked();
    assert_tab_in_view(cx, "session.tab.19");
    // The tabs the strip shows are still the ones a click lands on.
    click(cx, "session.tab.19");
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(tabs[19])
    );
}

#[gpui::test]
async fn the_tab_list_keeps_the_marks_readable_in_the_smallest_window_at_large_text(
    cx: &mut TestAppContext,
) {
    let Some((view, cx)) = two_shells(cx) else {
        return;
    };
    let background = cx.update(|_window, app| view.read(app).open_tabs())[0];
    let viewport = compact_window();
    // The marks are first read on the strip of the design window, the narrowest that
    // still draws every tab at this size.
    cx.simulate_resize(design_window());
    focus_root(&view, cx);
    for _ in 0..Zoom::ALL.len() {
        if cx.update(|_window, app| view.read(app).workspace().zoom()) == Zoom::Comfortable {
            break;
        }
        cx.dispatch_action(CycleTextSize);
        cx.run_until_parked();
    }
    feed_session(cx, &view, background, b"\x07");
    feed_session(cx, &view, background, REPORTED_COMMAND);

    // The marks stay inside the tab's own box rather than sliding over the
    // neighbouring tab.
    let tab = bounds_of(cx, "session.tab.0");
    for selector in [
        "session.tab.mark.bell.0",
        "session.tab.mark.finished.0",
        "session.tab.close.0",
    ] {
        assert_stays_inside_box(bounds_of(cx, selector), tab, selector);
    }
    assert_pointer_target(cx, "session.tab.close.0");

    // The same holds in Chinese, where the two words are two full-width characters.
    cx.dispatch_action(ToggleLanguage);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().locale()),
        Locale::Chinese,
        "the marks are measured in Chinese too"
    );
    let tab = bounds_of(cx, "session.tab.0");
    for selector in [
        "session.tab.mark.bell.0",
        "session.tab.mark.finished.0",
        "session.tab.close.0",
    ] {
        assert_stays_inside_box(bounds_of(cx, selector), tab, selector);
    }

    // In the smallest window the compact row shows the current tab alone, so the list
    // of every tab is the way to read the marks there: it fits the window and writes
    // each mark out in full.
    cx.simulate_resize(viewport);
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).header_compact_for_test()));
    assert_fits_inside(
        bounds_of(cx, "tabs.list.open"),
        viewport,
        "the all-tabs control",
    );
    assert_pointer_target(cx, "tabs.list.open");
    click(cx, "tabs.list.open");
    assert_fits_inside(bounds_of(cx, "tabs.list.dialog"), viewport, "the tab list");
    let row = bounds_of(cx, "tabs.list.row.0");
    assert_fits_inside(row, viewport, "the row of the marked tab");
    for selector in ["tabs.list.mark.bell.0", "tabs.list.mark.finished.0"] {
        assert_stays_inside_box(bounds_of(cx, selector), row, selector);
        assert_fits_inside(bounds_of(cx, selector), viewport, selector);
    }
    assert_pointer_target(cx, "tabs.list.rename.0");

    // Choosing the row shows that tab and clears what it was carrying (R7).
    click(cx, "tabs.list.row.0");
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(background)
    );
    assert!(
        unread_of(cx, &view, background).is_empty(),
        "looking at the tab cleared the marks the list showed"
    );
}

// ---------------------------------------------------------------------------
// Saved shortcut commands (R6)
// ---------------------------------------------------------------------------

/// Mounts the shell on a directory of its own, so a test's saved commands are its own too.
fn snippet_view<'a>(
    cx: &'a mut TestAppContext,
    dir: &TempDir,
) -> (Entity<ShelluneView>, &'a mut VisualTestContext) {
    let workspace = Workspace::new();
    let store = dir.store();
    let trust = TrustStore::at(dir.path());
    let (view, cx) = cx.add_window_view(move |_window, cx| {
        ShelluneView::with_store_and_trust(cx, workspace, store, trust)
    });
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(tall_window());
    cx.run_until_parked();
    (view, cx)
}

/// A library file a previous run would have left, with one command in it.
fn seed_snippet(dir: &TempDir, name: &str, body: &str) -> shellune_core::SnippetId {
    let mut book = shellune_core::SnippetBook::new();
    let id = book.create(name, body).expect("a valid command");
    shellune_storage::SnippetStore::at(dir.path())
        .save(&book)
        .expect("the library saves");
    id
}

fn snippet_sent(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    session: SessionId,
) -> Vec<u8> {
    cx.update(|_window, app| {
        view.read(app)
            .pane_of(session)
            .map(|pane| pane.read(app).sent().to_vec())
            .unwrap_or_default()
    })
}

#[gpui::test]
async fn a_shortcut_command_is_saved_found_in_the_palette_and_read_back_after_a_restart(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("snippet-save");
    let (view, vcx) = snippet_view(cx, &dir);

    // Through the manager the palette offers: a name, a command, save.
    vcx.update(|_window, app| {
        view.update(app, |view, cx| view.open_snippets(true, cx));
    });
    vcx.run_until_parked();
    assert!(
        vcx.debug_bounds("snippet.editor").is_some(),
        "the editor is drawn when it is opened"
    );
    type_into(vcx, "snippet.editor.name", "deploy");
    type_into(vcx, "snippet.editor.body", "make deploy");
    click(vcx, "snippet.editor.save");
    assert_eq!(
        vcx.update(|_window, app| view.read(app).snippets().snippets().len()),
        1,
        "the command is in the library"
    );
    assert!(
        !vcx.update(|_window, app| view.read(app).snippet_panel().is_editing()),
        "the editor closes once the command is saved"
    );
    assert!(
        vcx.debug_bounds("snippet.row.0").is_some(),
        "the saved command is listed"
    );

    // The palette offers the two actions, named after the command.
    vcx.simulate_keystrokes(palette_keystroke());
    vcx.run_until_parked();
    vcx.simulate_input("deploy");
    vcx.run_until_parked();
    let titles = vcx.update(|_window, app| view.read(app).palette_titles());
    let insert = copy::fill(
        copy::ENGLISH_UX.snippet_insert_action,
        &[("name", "deploy")],
    );
    let run = copy::fill(copy::ENGLISH_UX.snippet_run_action, &[("name", "deploy")]);
    assert!(
        titles.iter().any(|title| title == &insert),
        "the palette can type the command: {titles:?}"
    );
    assert!(
        titles.iter().any(|title| title == &run),
        "the palette can run the command: {titles:?}"
    );
    vcx.simulate_keystrokes("escape");
    vcx.run_until_parked();

    // A restart is a second window on the same directory.
    let (restarted, vcx) = snippet_view(cx, &dir);
    vcx.run_until_parked();
    let read: Vec<(String, String)> = vcx.update(|_window, app| {
        restarted
            .read(app)
            .snippets()
            .snippets()
            .iter()
            .map(|snippet| (snippet.name().to_owned(), snippet.body().to_owned()))
            .collect()
    });
    assert_eq!(
        read,
        vec![("deploy".to_owned(), "make deploy".to_owned())],
        "the next run reads the command the last one saved"
    );
}

