#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_saved_desktop_row_only_says_connected_once_a_session_really_runs(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("desktop-row-state");
    let record = desktop_record("office");
    seed_connections(&dir.store(), vec![record.clone()]);
    let (view, cx) = hosts_view_with_trust(cx, &dir);

    // Saving a record is not starting one. The row states no session, and it does not
    // invent an "offline" either: idle is not a state a saved record has (R2).
    assert!(
        cx.debug_bounds("hosts.connection.state.0").is_none(),
        "a record that was never started is not drawn as connected"
    );

    // One real session in this window, mounted through the same registration the start
    // path uses; only the link is scripted, and nothing here is evidence about a server.
    let desktop = (64u32, 48u32);
    let (link, _log) = ScriptedLink::new(vec![
        LinkEvent::State {
            state: LinkState::Connected,
            failure: LinkFailure::None,
            detail: 0,
            reason: String::new(),
        },
        LinkEvent::Frame(solid(0, 0, 64, 48, desktop, [16, 32, 48, 255])),
    ]);
    mount_scripted_desktop(&view, cx, &record, link);

    // Back on the list: the row now says what the session says, because it reads the
    // sessions this window holds rather than the saved file.
    cx.dispatch_action(GoToHosts);
    cx.run_until_parked();
    assert_eq!(destination_of(&view, cx), Destination::Hosts);
    assert!(
        cx.debug_bounds("hosts.connection.state.0").is_some(),
        "the row of a record with a running session says it is connected"
    );
    assert!(
        cx.debug_bounds("hosts.connection.0").is_some(),
        "and it is still the same row, with the same actions"
    );
}

#[gpui::test]
async fn the_settings_page_scrolls_through_every_category_and_the_navigation_follows(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    cx.dispatch_action(crate::app::actions::GoToSettings);
    cx.run_until_parked();

    // One page: every category's section is drawn, not only the chosen one.
    for section in [
        "settings.section.appearance",
        "settings.section.terminal",
        "settings.section.connection",
        "settings.section.about",
    ] {
        assert!(
            cx.debug_bounds(section).is_some(),
            "{section} is on the page"
        );
    }
    let first = cx.update(|_window, app| view.read(app).settings_category_in_view_id());

    // Scrolling the page moves the mark in the navigation with it.
    let center = bounds_of(cx, "settings.scroll").center();
    for _ in 0..12 {
        cx.simulate_event(ScrollWheelEvent {
            position: point(center.x, center.y),
            delta: ScrollDelta::Pixels(point(px(0.0), px(-120.0))),
            ..Default::default()
        });
        cx.run_until_parked();
    }
    let after = cx.update(|_window, app| view.read(app).settings_category_in_view_id());
    assert_ne!(first, after, "the navigation followed the page down");

    // A press in the navigation scrolls the page to that category.
    click(cx, "settings.category.about");
    cx.run_until_parked();
    let about = bounds_of(cx, "settings.section.about");
    let area = bounds_of(cx, "settings.scroll");
    assert!(
        about.origin.y < area.origin.y + area.size.height,
        "the chosen category is scrolled into view: {about:?} in {area:?}"
    );

    // After a press in the navigation the wheel still scrolls the page: the reveal
    // lets go instead of pulling the page back to the chosen heading every frame.
    click(cx, "settings.category.terminal");
    cx.run_until_parked();
    let revealed = bounds_of(cx, "settings.section.terminal").origin.y;
    for _ in 0..3 {
        cx.simulate_event(ScrollWheelEvent {
            position: point(center.x, center.y),
            delta: ScrollDelta::Pixels(point(px(0.0), px(-120.0))),
            ..Default::default()
        });
        cx.run_until_parked();
    }
    let scrolled = bounds_of(cx, "settings.section.terminal").origin.y;
    assert!(
        scrolled < revealed - px(200.0),
        "the wheel moved the page on from the revealed heading: {revealed:?} -> {scrolled:?}"
    );
}

/// Asks the window to close the way Windows and Linux do - for real.
///
/// On macOS the window's own close button only hides it (R13), so a test about the
/// question a real close asks drives that path directly instead of through the
/// platform's close, which would hide the window on a Mac runner.
fn request_real_close(cx: &mut VisualTestContext, view: &Entity<ShelluneView>) -> bool {
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.on_window_should_close(Platform::Windows, cx)
        })
    })
}

// ---------------------------------------------------------------------------
// Remote desktops in the workspace (R8, R10, R17-R20, R23)
// ---------------------------------------------------------------------------

use crate::app::desktop::scripted::{ScriptedLink, solid};
use crate::app::desktop::{Buttons, DesktopInput, LinkEvent, LinkFailure, LinkState};

/// A saved RDP connection, for the desktop tests.
fn desktop_record(name: &str) -> shellune_core::ConnectionRecord {
    shellune_core::ConnectionRecord::Rdp(
        shellune_core::RdpConfig::new(name, "rdp.example.com", Some("desk"))
            .expect("a valid RDP record"),
    )
}

/// Mounts a scripted desktop surface and drains what its link already holds.
///
/// The polling task waits on the window's timer, which a test cannot advance, so
/// the same call it would make is made here: everything else - the session
/// record, the placement, the tab - goes through the path the application takes.
fn mount_scripted_desktop(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    record: &shellune_core::ConnectionRecord,
    link: ScriptedLink,
) -> SessionId {
    let id = cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            view.attach_scripted_desktop(record, Box::new(link), cx)
        })
    });
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            if let Some(pane) = view.desktop_of(id).cloned() {
                pane.update(cx, |pane, cx| {
                    pane.pump_once(cx);
                });
            }
        })
    });
    cx.run_until_parked();
    id
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_fast_remote_desktop_never_draws_its_loading_card(cx: &mut TestAppContext) {
    for record in [desktop_record("rdp"), vnc_record_sharing("vnc", false)] {
        let (view, window) = cx.add_window_view(|_, cx| ShelluneView::new(cx));
        let (link, _) = ScriptedLink::new(Vec::new());
        let feed = link.feed();
        let id = mount_scripted_desktop(&view, window, &record, link);
        assert!(window.debug_bounds("desktop.status").is_none());
        feed.feed(live_desktop_events());
        pump_desktop(&view, window, id);
        assert!(window.debug_bounds("desktop.picture").is_some());
        wait_for_loading_card(window);
        assert!(window.debug_bounds("desktop.status").is_none());
    }
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_desktop_tab_applies_every_region_in_the_order_it_arrived(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let desktop = (320u32, 200u32);
    let (link, _log) = ScriptedLink::new(vec![
        LinkEvent::State {
            state: LinkState::Connected,
            failure: LinkFailure::None,
            detail: 0,
            reason: String::new(),
        },
        LinkEvent::Frame(solid(0, 0, 320, 200, desktop, [16, 32, 48, 255])),
        LinkEvent::Frame(solid(8, 8, 16, 16, desktop, [200, 100, 50, 255])),
    ]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);

    let (size, applied, corner, inner, live, state) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        let surface = pane.surface();
        let inner = (8 * 320 + 8) * 4;
        (
            surface.size(),
            surface.applied(),
            surface.pixels()[0..4].to_vec(),
            surface.pixels()[inner..inner + 4].to_vec(),
            pane.is_live(),
            view.workspace()
                .session(id)
                .map(|session| session.state().clone()),
        )
    });
    assert_eq!(size, desktop, "the first frame fixes the desktop size");
    assert_eq!(
        applied, 2,
        "both regions were applied: a diff is never dropped in favour of a newer one"
    );
    assert_eq!(
        corner,
        vec![16, 32, 48, 255],
        "the background region is drawn"
    );
    assert_eq!(
        inner,
        vec![200, 100, 50, 255],
        "the later region is on top of the earlier one, in arrival order"
    );
    assert!(live, "a first frame is what makes the surface live");
    assert_eq!(
        state,
        Some(SessionState::Connected),
        "the record states what the surface reports"
    );

    // The picture really is drawn inside the tab: the element that carries the
    // image was measured with a box of its own.
    let picture = bounds_of(cx, "desktop.surface");
    assert!(
        picture.size.width > px(0.0) && picture.size.height > px(0.0),
        "the frame is presented in the application tab: {picture:?}"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_press_on_a_desktop_is_mapped_and_a_close_releases_it(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let desktop = (1600u32, 900u32);
    let (link, log) = ScriptedLink::new(vec![LinkEvent::Frame(solid(
        0,
        0,
        1600,
        900,
        desktop,
        [1, 2, 3, 255],
    ))]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);

    let surface = bounds_of(cx, "desktop.surface");
    let centre = surface.center();
    let expected = crate::app::desktop::to_remote(surface, desktop, centre)
        .expect("the centre of the picture is on the desktop");
    cx.simulate_mouse_down(centre, MouseButton::Left, Modifiers::default());
    let sent = log.lock().expect("the log is not poisoned").inputs.clone();
    match sent.last() {
        Some(DesktopInput::Pointer { x, y, buttons }) => {
            assert_eq!(
                (*x, *y),
                expected,
                "the press names the remote pixel under the pointer, not the offset in the pane"
            );
            assert!(buttons.contains(Buttons::LEFT), "the left button is held");
        }
        other => panic!("a pointer press was not sent: {other:?}"),
    }

    cx.simulate_mouse_up(centre, MouseButton::Left, Modifiers::default());
    cx.update(|_window, cx| view.update(cx, |view, cx| view.close_session(id, cx)));
    let log = log.lock().expect("the log is not poisoned").clone();
    assert_eq!(
        log.shutdowns, 1,
        "closing the tab stops the protocol worker exactly once"
    );
    assert!(
        matches!(log.inputs.last(), Some(DesktopInput::Pointer { buttons, .. }) if !buttons.any_button()),
        "the button that was held is released before the session ends: {:?}",
        log.inputs.last()
    );
    let open = cx.update(|_window, app| view.read(app).open_sessions());
    assert!(!open.contains(&id), "the closed surface left the workspace");
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_desktop_that_was_refused_states_one_reason_and_forgets_its_disclosure(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let mut events = live_desktop_events();
    events.push(LinkEvent::State {
        state: LinkState::Failed(LinkFailure::Authentication),
        failure: LinkFailure::Authentication,
        detail: 0,
        reason: "the server rejected the logon".to_owned(),
    });
    let (link, _log) = ScriptedLink::new(events);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);

    let (state, headline, shown) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            view.workspace()
                .session(id)
                .map(|session| session.state().clone()),
            view.workspace()
                .status(id)
                .map(|status| status.headline(view.workspace().locale())),
            view.workspace()
                .status(id)
                .and_then(|status| status.diagnostic().map(str::to_owned)),
        )
    });
    assert_eq!(
        state,
        Some(SessionState::Failed(SessionFailure::AuthenticationFailed)),
        "a refused credential is the credential problem, not a transport one"
    );
    assert_eq!(headline.as_deref(), Some("Failed"));
    assert!(
        shown.is_some_and(|reason| reason.contains("credentials")),
        "the record states the fact it knows, without inventing a detail"
    );
    let layer = cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .layer_reason()
            .map(str::to_owned)
    });
    assert!(
        layer
            .as_ref()
            .is_some_and(|reason| reason.contains("logon")),
        "the sentence the protocol layer gave is kept beside it: {layer:?}"
    );

    // The disclosure is a view fact about one session: opening it and then closing
    // the session must not leave it behind for an id that a later session takes.
    let details = bounds_of(cx, "terminal.failure.details");
    cx.simulate_click(details.center(), Modifiers::default());
    assert!(
        cx.update(|_window, app| view.read(app).diagnostics_open(id)),
        "the disclosure opened"
    );
    cx.update(|_window, cx| view.update(cx, |view, cx| view.close_session(id, cx)));
    assert!(
        !cx.update(|_window, app| view.read(app).diagnostics_open(id)),
        "the disclosure is forgotten with the session it belonged to"
    );
}

/// A remote desktop that ended before any frame uses its own status card alone (no duplicate
/// banner on top); once a picture has been shown, an ended session preserves that last picture
/// and states the reason once in the banner above it (R5 / ADR-5).
#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn an_ended_desktop_states_itself_in_the_banner_above_its_own_card(cx: &mut TestAppContext) {
    // Without a first frame: only desktop.status is shown, no duplicate terminal.failure banner.
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.simulate_resize(design_window());
    let (link, _log) = ScriptedLink::new(vec![LinkEvent::State {
        state: LinkState::Failed(LinkFailure::Authentication),
        failure: LinkFailure::Authentication,
        detail: 0,
        reason: "the server rejected the logon".to_owned(),
    }]);
    let record = desktop_record("desk");
    let no_frame_id = mount_scripted_desktop(&view, cx, &record, link);
    redraw(cx);
    assert!(
        cx.debug_bounds("desktop.status").is_some(),
        "a desktop that failed before its first frame renders its status card"
    );
    assert!(
        cx.debug_bounds("terminal.failure").is_none(),
        "a desktop without a first frame must not stack a duplicate banner above desktop.status"
    );
    cx.update(|_window, app| view.update(app, |view, cx| view.close_session(no_frame_id, cx)));
    cx.run_until_parked();

    // After a live frame: last picture stays visible and a single banner states the reason.
    let mut events = live_desktop_events();
    events.push(LinkEvent::State {
        state: LinkState::Failed(LinkFailure::Authentication),
        failure: LinkFailure::Authentication,
        detail: 0,
        reason: "the server rejected the logon".to_owned(),
    });
    let (link, _log) = ScriptedLink::new(events);
    let id = mount_scripted_desktop(&view, cx, &record, link);
    redraw(cx);

    let metrics = Metrics::default();
    let banner = bounds_of(cx, "terminal.failure");
    assert!(
        banner.size.height <= metrics.large_control_height() + px(1.0),
        "the failure is one banner line, not a card: {banner:?}"
    );
    assert!(
        cx.debug_bounds("desktop.picture").is_some(),
        "the last picture remains visible under the banner"
    );
    assert!(
        cx.debug_bounds("terminal.failure.next").is_some(),
        "the banner offers the next step"
    );

    click(cx, "terminal.failure.dismiss");
    redraw(cx);
    assert!(
        !cx.update(|_window, app| view.read(app).banner_shown_for_test(id, app)),
        "the banner closed"
    );
    assert!(
        cx.debug_bounds("desktop.picture").is_some(),
        "dismissing the banner leaves the last picture visible"
    );
}

/// The banner above an ended desktop (after a picture was shown) is reached from the keyboard
/// the way a terminal's is: the banner does not take the keyboard, Tab from the desktop reaches
/// its first control, Tab past the last one goes back to the desktop, and Enter presses the step
/// (ADR-6, ADR-7). A live desktop keeps Tab for the remote side.
#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn tab_reaches_the_banner_above_an_ended_desktop_and_enter_reconnects(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.simulate_resize(design_window());
    let mut events = live_desktop_events();
    events.push(LinkEvent::State {
        state: LinkState::Failed(LinkFailure::Connect),
        failure: LinkFailure::Connect,
        detail: 0,
        reason: "the address could not be reached".to_owned(),
    });
    let (link, _log) = ScriptedLink::new(events);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    redraw(cx);
    let pane = cx
        .update(|_window, app| view.read(app).desktop_of(id).cloned())
        .expect("the surface is mounted");
    cx.update(|window, app| window.focus(pane.read(app).focus_handle()));
    redraw(cx);
    let focused = |cx: &mut VisualTestContext| {
        cx.update(|window, app| view.read(app).banner_focus_for_test(window))
    };
    let desktop_focused = |cx: &mut VisualTestContext| {
        cx.update(|window, app| pane.read(app).focus_handle().is_focused(window))
    };
    assert!(
        cx.debug_bounds("terminal.failure.next").is_some(),
        "the banner offers the reconnect"
    );
    assert_eq!(focused(cx), None, "the banner does not take the keyboard");
    assert!(desktop_focused(cx), "the desktop holds the keyboard");

    cx.simulate_keystrokes("tab");
    cx.run_until_parked();
    assert_eq!(focused(cx), Some(0), "Tab reaches the next step first");
    cx.simulate_keystrokes("shift-tab");
    cx.run_until_parked();
    assert_eq!(focused(cx), None);
    assert!(
        desktop_focused(cx),
        "Shift+Tab before the first control gives the keyboard back to the desktop"
    );

    cx.simulate_keystrokes("tab");
    cx.run_until_parked();
    assert_eq!(focused(cx), Some(0));
    let before = session_state(cx, &view, id);
    assert!(
        matches!(
            before,
            Some(SessionState::Failed(_) | SessionState::Disconnected(_))
        ),
        "the session ended: {before:?}"
    );
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    let replaced = cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .is_none_or(|now| now.entity_id() != pane.entity_id())
    });
    assert!(
        replaced,
        "Enter on the step reconnects: the ended surface is released"
    );
}

/// Escape closes the banner above an ended desktop, as it does above a terminal, and
/// the keyboard is on the desktop afterwards whether it was on the banner or not
/// (ADR-6, ADR-7).
#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn escape_closes_the_banner_above_an_ended_desktop(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.simulate_resize(design_window());
    let mut events = live_desktop_events();
    events.push(LinkEvent::State {
        state: LinkState::Failed(LinkFailure::Connect),
        failure: LinkFailure::Connect,
        detail: 0,
        reason: "the address could not be reached".to_owned(),
    });
    let (link, _log) = ScriptedLink::new(events);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    redraw(cx);
    let pane = cx
        .update(|_window, app| view.read(app).desktop_of(id).cloned())
        .expect("the surface is mounted");
    cx.update(|window, app| window.focus(pane.read(app).focus_handle()));
    redraw(cx);
    assert!(cx.update(|_window, app| view.read(app).banner_shown_for_test(id, app)));

    // From a banner control: the banner closes and the desktop has the keyboard.
    cx.simulate_keystrokes("tab");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|window, app| view.read(app).banner_focus_for_test(window)),
        Some(0)
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).banner_shown_for_test(id, app)),
        "Escape closes the banner"
    );
    assert!(
        cx.update(|window, app| pane.read(app).focus_handle().is_focused(window)),
        "the keyboard goes back to the desktop"
    );
    assert!(
        cx.update(|_window, app| view.read(app).desktop_of(id).is_some()),
        "closing the banner leaves the session's place"
    );
}

#[test]
fn a_stale_session_allows_no_capability_at_all() {
    let workspace = Workspace::new();
    let capabilities = workspace.capabilities(SessionId::new());
    assert!(
        capabilities.is_empty(),
        "a session the shell no longer has allows nothing"
    );
    for capability in Capability::ALL {
        assert!(
            !capabilities.allows(capability),
            "{capability:?} was allowed for an id no session has"
        );
    }
}

#[test]
#[ignore = "opt-in RDP/VNC test"]
fn a_desktop_record_can_be_registered_without_opening_anything() {
    let mut workspace = Workspace::new();
    let record = desktop_record("desk");
    let session = workspace.register_session_not_started(
        SessionKind::Rdp { host: record.id() },
        record.name(),
        PaneTarget::rdp(record.id()),
    );
    assert_eq!(
        workspace.session(session.id()).map(|s| s.state().clone()),
        Some(SessionState::Idle),
        "placing a pane dials nothing"
    );
    assert!(
        workspace.session_starting(session.id()),
        "starting the pane is the step that moves the record"
    );
    assert_eq!(
        workspace.session(session.id()).map(|s| s.state().clone()),
        Some(SessionState::Connecting)
    );
    assert!(
        !workspace.session_starting(session.id()),
        "a second start does not restart a session that is already connecting"
    );
}

#[test]
fn a_clean_exit_is_called_the_same_thing_on_the_tab_and_in_the_notice() {
    let ended = SessionState::Disconnected(SessionFailure::ProcessExited { code: Some(0) });
    for locale in Locale::ALL {
        assert_eq!(
            copy::session_state_label(&ended, locale),
            locale.strings().terminal_exited,
            "a clean exit is not called a disconnect in {locale:?}"
        );
    }
    let failed = SessionState::Disconnected(SessionFailure::ProcessExited { code: Some(1) });
    assert_ne!(
        copy::session_state_label(&failed, Locale::English),
        ENGLISH.terminal_exited,
        "an exit that failed keeps the wording of a failed connection"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_desktop_that_cannot_be_reached_reports_what_the_backend_said(cx: &mut TestAppContext) {
    let backend_built = shellune_desktop::backend_info(shellune_desktop::Protocol::Vnc).is_ok();
    // A port nothing is listening on: the pane really creates a handle in the
    // native backend, really dials, and reports the failure it is given. The
    // endpoint matrix in tests/rdp_vnc.rs is what proves a real server; this proves
    // the pane's own path to the backend is wired.
    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("a probe port");
    let port = listener.local_addr().expect("the probe address").port();
    drop(listener);
    let mut config =
        shellune_core::VncConfig::new("unreachable", "127.0.0.1").expect("a valid record");
    config.set_port(u32::from(port)).expect("a valid port");
    let record = shellune_core::ConnectionRecord::Vnc(config);
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let id = cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            view.start_desktop_with_record_for_test(&record, cx)
        })
    });

    // The protocol worker is a native thread, so the test polls the pane the way
    // the window's timer would, until the attempt has ended.
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    let mut ended = false;
    while std::time::Instant::now() < deadline {
        let phase_ended = cx.update(|_window, cx| {
            view.update(cx, |view, cx| {
                let Some(pane) = view.desktop_of(id).cloned() else {
                    return false;
                };
                pane.update(cx, |pane, cx| {
                    pane.pump_once(cx);
                    pane.phase().failure().is_some()
                })
            })
        });
        if phase_ended {
            ended = true;
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
    assert!(ended, "the attempt ended instead of hanging");

    let (state, reason) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            view.workspace()
                .session(id)
                .map(|session| session.state().clone()),
            view.desktop_of(id)
                .map(|pane| pane.read(app).layer_reason().map(str::to_owned))
                .unwrap_or_default(),
        )
    });
    match (backend_built, state) {
        (true, Some(SessionState::Failed(SessionFailure::ConnectionFailed { reason }))) => {
            assert!(
                reason.contains("127.0.0.1") || reason.contains("connect"),
                "the reason names what the transport said: {reason}"
            );
        }
        (
            false,
            Some(SessionState::Failed(
                SessionFailure::ReconnectUnavailable { reason }
                | SessionFailure::ConnectionFailed { reason },
            )),
        ) => {
            assert!(
                !reason.trim().is_empty(),
                "even without a compiled native backend, synchronous failure updates the session state: {reason}"
            );
        }
        (_, other) => panic!("an unreachable endpoint is a start failure, not {other:?}"),
    }
    if backend_built {
        assert!(
            reason.is_some(),
            "the backend's own sentence is kept beside the session's state"
        );
    }
}

// ---------------------------------------------------------------------------
// A desktop pane in the whole window, at a zoom step, and at every step of its
// connection (R18-R20)
// ---------------------------------------------------------------------------

/// The saved record of an RDP host that refuses any certificate it cannot trust.
fn desktop_record_rejecting_certificates(name: &str) -> shellune_core::ConnectionRecord {
    let mut config = shellune_core::RdpConfig::new(name, "rdp.example.com", Some("desk"))
        .expect("a valid RDP record");
    config.set_certificate(shellune_core::RdpCertificatePolicy::Reject);
    shellune_core::ConnectionRecord::Rdp(config)
}

/// Applies whatever the scripted link has queued, the way the poll does.
fn pump_desktop(view: &Entity<ShelluneView>, cx: &mut VisualTestContext, id: SessionId) {
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            if let Some(pane) = view.desktop_of(id).cloned() {
                pane.update(cx, |pane, cx| {
                    pane.pump_once(cx);
                });
            }
        });
    });
    cx.run_until_parked();
}

/// A copy of the canvas, so a test can prove a picture survived a change.
fn desktop_canvas(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    id: SessionId,
) -> Vec<u8> {
    cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .surface()
            .pixels()
            .to_vec()
    })
}

/// Gives the desktop pane the keyboard without clicking it.
fn focus_desktop(view: &Entity<ShelluneView>, cx: &mut VisualTestContext, id: SessionId) {
    let handle = cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .focus_handle()
            .clone()
    });
    cx.update(|window, _app| window.focus(&handle));
    cx.run_until_parked();
}

/// Keep this attempt pending while the test clock also drives transport polling.
fn hold_reconnect(view: &Entity<ShelluneView>, cx: &mut VisualTestContext, id: SessionId) {
    cx.update(|_, app| {
        view.update(app, |view, cx| {
            view.install_scripted_session(id, shellune_ssh::ScriptedSession::new(), cx)
        })
    });
}

fn wait_for_loading_card(cx: &mut VisualTestContext) {
    cx.run_until_parked();
    cx.executor().advance_clock(crate::app::CONNECT_STATE_FLOOR);
    cx.run_until_parked();
}

/// Draws the window once, the way the next frame will.
///
/// A change made from a key or a click is drawn on the frame after the event that
/// caused it, so a test that reads measured bounds has to ask for that frame.
fn redraw(cx: &mut VisualTestContext) {
    cx.update(|window, cx| {
        let _ = window.draw(cx);
    });
}

/// The pointer state the pane sent last.
fn last_pointer(
    log: &std::sync::Arc<std::sync::Mutex<crate::app::desktop::scripted::Log>>,
) -> (u16, u16, Buttons) {
    let log = log.lock().expect("the log is not poisoned").clone();
    match log.inputs.last() {
        Some(DesktopInput::Pointer { x, y, buttons }) => (*x, *y, *buttons),
        other => panic!("a pointer state was not sent: {other:?}"),
    }
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_desktop_pane_takes_the_whole_window_and_gives_it_back(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let desktop = (1600u32, 900u32);
    let (link, log) = ScriptedLink::new(vec![
        LinkEvent::State {
            state: LinkState::Connected,
            failure: LinkFailure::None,
            detail: 0,
            reason: String::new(),
        },
        LinkEvent::Frame(solid(0, 0, 1600, 900, desktop, [12, 34, 56, 255])),
    ]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    let picture = bounds_of(cx, "desktop.surface");
    let canvas = desktop_canvas(&view, cx, id);
    let tag = cx.update(|_window, app| {
        view.read(app)
            .workspace()
            .session(id)
            .map(|session| session.tag())
    });
    assert!(
        cx.debug_bounds("session.header").is_some(),
        "the tab strip is drawn while the desktop shares the window"
    );

    // F11 in the pane is the way in (R18).
    focus_desktop(&view, cx, id);
    cx.simulate_keystrokes("f11");
    cx.run_until_parked();
    redraw(cx);

    assert!(
        cx.update(|window, _app| window.is_fullscreen()),
        "the pane asked the window for the whole screen"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_fullscreen()),
        Some(id),
        "the pane that asked is the one the window is showing"
    );
    let fullscreen = bounds_of(cx, "desktop.surface");
    let scale = cx.update(|window, _| window.scale_factor());
    let layout_for = |bounds: gpui::Bounds<Pixels>| {
        (
            (f32::from(bounds.size.width) * scale).floor() as u32 & !1,
            (f32::from(bounds.size.height) * scale).floor() as u32,
            (scale * 100.).round() as u32,
        )
    };
    assert_eq!(
        log.lock().unwrap().resizes.last(),
        Some(&layout_for(fullscreen))
    );
    assert!(
        fullscreen.size.height > picture.size.height,
        "the picture is drawn in the space the tab strip gave back: {fullscreen:?} was {picture:?}"
    );
    assert_eq!(
        fullscreen.origin.y,
        px(0.0),
        "nothing is drawn above a full-screen desktop: {fullscreen:?}"
    );
    // Nothing was rebuilt to do it: the link is the same one, the picture is the
    // same pixels, and the tab is the same tab (R18).
    assert_eq!(
        desktop_canvas(&view, cx, id),
        canvas,
        "the frame that was on screen before full screen is still there"
    );
    assert!(cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .is_live()
    }));
    assert_eq!(
        cx.update(|_window, app| view
            .read(app)
            .workspace()
            .session(id)
            .map(|session| session.tag())),
        tag,
        "the tab identity is the one it had before"
    );

    // The pointer is mapped through the space the picture is drawn in, which is a
    // different rectangle now: the same inverse still names the drawn pixel.
    let centre = fullscreen.center();
    cx.simulate_mouse_down(centre, MouseButton::Left, Modifiers::default());
    let expected = crate::app::desktop::to_remote(fullscreen, desktop, centre)
        .expect("the centre of the picture is on the desktop");
    let (x, y, _buttons) = last_pointer(&log);
    assert_eq!(
        (x, y),
        expected,
        "a click in full screen names the remote pixel it is over"
    );
    cx.simulate_mouse_up(centre, MouseButton::Left, Modifiers::default());

    // F11 again is the way out, and it puts everything back.
    cx.simulate_keystrokes("f11");
    cx.run_until_parked();
    redraw(cx);

    assert!(
        !cx.update(|window, _app| window.is_fullscreen()),
        "the window is a window again"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_fullscreen()),
        None
    );
    let restored = bounds_of(cx, "desktop.surface");
    assert_eq!(
        log.lock().unwrap().resizes.last(),
        Some(&layout_for(restored))
    );
    assert!(
        (f32::from(restored.size.height) - f32::from(picture.size.height)).abs() < 1.0
            && (f32::from(restored.size.width) - f32::from(picture.size.width)).abs() < 1.0,
        "the pane is back in the space it had: {restored:?} was {picture:?}"
    );
    assert_eq!(
        restored.origin.y, picture.origin.y,
        "the tab strip is back with the space it took: {restored:?} was {picture:?}"
    );
    assert_eq!(
        desktop_canvas(&view, cx, id),
        canvas,
        "the round trip did not lose the picture"
    );
    assert_eq!(
        cx.update(|_window, app| view
            .read(app)
            .workspace()
            .session(id)
            .map(|session| session.tag())),
        tag,
        "the tab is where it was"
    );
    let log = log.lock().expect("the log is not poisoned").clone();
    assert_eq!(
        log.shutdowns, 0,
        "going in and out of full screen does not rebuild the connection"
    );
}

/// Mounts one live scripted desktop and puts it in full screen, for the tests that
/// check what takes the window back (R18).
fn desktop_in_full_screen(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> SessionId {
    let (link, _log) = ScriptedLink::new(vec![
        LinkEvent::State {
            state: LinkState::Connected,
            failure: LinkFailure::None,
            detail: 0,
            reason: String::new(),
        },
        LinkEvent::Frame(solid(0, 0, 1600, 900, (1600, 900), [9, 9, 9, 255])),
    ]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(view, cx, &record, link);
    // The keys reach a pane the frame has drawn: the surface is measured here, as the
    // full-screen test above measures it before it presses F11.
    let _ = bounds_of(cx, "desktop.surface");
    focus_desktop(view, cx, id);
    cx.simulate_keystrokes("f11");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        cx.update(|window, _app| window.is_fullscreen()),
        "the pane asked for the window"
    );
    id
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn full_screen_gives_the_window_back_when_another_page_is_chosen(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let id = desktop_in_full_screen(&view, cx);

    cx.dispatch_action(crate::app::actions::GoToHosts);
    cx.run_until_parked();
    redraw(cx);

    assert!(
        !cx.update(|window, _app| window.is_fullscreen()),
        "the window is a window again the moment its head would be needed"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_fullscreen()),
        None,
        "the full-screen state does not outlive the page it belonged to"
    );
    assert!(
        cx.debug_bounds("session.header").is_some(),
        "the page that took over has its head back"
    );
    // The session itself is untouched: it is still live behind the page.
    assert!(cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is still mounted")
            .read(app)
            .is_live()
    }));
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn full_screen_gives_the_window_back_when_the_desktop_tab_is_split(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    desktop_in_full_screen(&view, cx);

    cx.dispatch_action(crate::app::actions::SplitPaneRight);
    cx.run_until_parked();
    redraw(cx);

    assert!(
        !cx.update(|window, _app| window.is_fullscreen()),
        "a split desktop needs the head the full screen hid"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_fullscreen()),
        None
    );
    assert!(
        cx.debug_bounds("session.header").is_some(),
        "the tab strip is back, so the split pane can be found"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn the_send_warning_is_drawn_once_before_the_first_frame(cx: &mut TestAppContext) {
    // A send that fails before the picture arrives: the status card already carries
    // the sentence, so the strip that sits over a picture must not repeat it (R18).
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(Vec::new());
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    let reason = crate::app::desktop::LinkError::State.reason();
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            if let Some(pane) = view.desktop_of(id).cloned() {
                pane.update(cx, |pane, cx| pane.show_send_problem(&reason, cx));
            }
        });
    });
    cx.run_until_parked();
    redraw(cx);

    wait_for_loading_card(cx);
    assert!(
        cx.debug_bounds("desktop.status").is_some(),
        "the card explains the session before any picture"
    );
    assert!(
        cx.debug_bounds("desktop.notice").is_none(),
        "the same sentence is not drawn twice while there is no picture"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn the_zoom_control_scales_the_picture_and_the_pointer_follows_it(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let desktop = (1600u32, 900u32);
    let (link, log) = ScriptedLink::new(vec![
        LinkEvent::State {
            state: LinkState::Connected,
            failure: LinkFailure::None,
            detail: 0,
            reason: String::new(),
        },
        LinkEvent::Frame(solid(0, 0, 1600, 900, desktop, [7, 7, 7, 255])),
    ]);
    let record = desktop_record("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);
    // The fit step places the picture at the contain rectangle of the pane: a placed
    // rectangle, but one that holds the whole picture and nothing outside the pane.
    let fitted = bounds_of(cx, "desktop.picture");
    let full = bounds_of(cx, "desktop.surface");
    let expected = crate::app::desktop::content_rect(full, desktop);
    assert!(
        (f32::from(fitted.size.width) - f32::from(expected.size.width)).abs() < 1.0
            && (f32::from(fitted.size.height) - f32::from(expected.size.height)).abs() < 1.0,
        "the fit step draws the whole picture at the contain rectangle: {fitted:?} was {expected:?}"
    );

    let larger = bounds_of(cx, "desktop.zoom.in").center();
    cx.simulate_click(larger, Modifiers::default());
    cx.run_until_parked();

    let (zoom, pan) = cx.update(|_window, app| {
        let pane = view
            .read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        (pane.zoom(), pane.pan())
    });
    assert_eq!(
        zoom,
        crate::app::desktop::DesktopZoom::Percent(200),
        "the larger control is one step in on the ladder"
    );
    let surface = bounds_of(cx, "desktop.surface");
    let drawn = bounds_of(cx, "desktop.picture");
    let expected = crate::app::desktop::content_rect_in(
        surface,
        desktop,
        crate::app::desktop::DesktopZoom::Percent(200),
        pan,
    );
    assert!(
        (f32::from(drawn.size.width) - f32::from(expected.size.width)).abs() < 1.0
            && (f32::from(drawn.size.height) - f32::from(expected.size.height)).abs() < 1.0,
        "the picture is drawn in the rectangle the pointer is mapped through: {drawn:?} was {expected:?}"
    );
    assert!(
        drawn.size.width > surface.size.width,
        "a zoom step larger than the pane is cropped by it rather than shrunk back"
    );

    // The centre of the space is the centre of the remote desktop at any zoom.
    let centre = surface.center();
    cx.simulate_mouse_down(centre, MouseButton::Left, Modifiers::default());
    let (x, y, _buttons) = last_pointer(&log);
    assert_eq!(
        (x, y),
        (800, 450),
        "a click at the centre of a zoomed picture is the centre of the desktop"
    );
    cx.simulate_mouse_up(centre, MouseButton::Left, Modifiers::default());

    // Pixel-sized touchpad deltas combine into one remote wheel step.
    for phase in [gpui::TouchPhase::Started, gpui::TouchPhase::Ended].repeat(2) {
        cx.simulate_event(ScrollWheelEvent {
            position: centre,
            touch_phase: phase,
            delta: ScrollDelta::Pixels(point(px(0.0), px(-10.0))),
            ..Default::default()
        });
    }
    let wheel_presses = log
        .lock()
        .unwrap()
        .inputs
        .iter()
        .filter(|input| {
            matches!(input,
                DesktopInput::Pointer { buttons, .. } if buttons.contains(Buttons::WHEEL_DOWN)
            )
        })
        .count();
    assert_eq!(wheel_presses, 1);
    for (delta, expected) in [
        (point(0.0, 1.0), Buttons::WHEEL_UP),
        (point(-1.0, 0.0), Buttons::WHEEL_RIGHT),
        (point(1.0, 0.0), Buttons::WHEEL_LEFT),
    ] {
        let start = log.lock().unwrap().inputs.len();
        cx.simulate_event(ScrollWheelEvent {
            position: centre,
            delta: ScrollDelta::Lines(delta),
            ..Default::default()
        });
        assert!(matches!(&log.lock().unwrap().inputs[start..],
            [DesktopInput::Pointer { buttons, x: 800, y: 450 }, DesktopInput::Pointer { buttons: released, .. }]
            if *buttons == expected && *released == Buttons::none()));
    }

    // A panned picture must still put the reported pixel directly under the pointer.
    cx.simulate_event(ScrollWheelEvent {
        position: centre,
        delta: ScrollDelta::Pixels(point(px(0.0), px(-80.0))),
        modifiers: Modifiers {
            shift: true,
            ..Default::default()
        },
        ..Default::default()
    });
    cx.run_until_parked();
    let panned = bounds_of(cx, "desktop.picture");
    assert!((panned.origin.y - drawn.origin.y - px(80.0)).abs() < px(1.0));
    cx.simulate_mouse_down(centre, MouseButton::Left, Modifiers::default());
    let (x, y, _) = last_pointer(&log);
    assert_eq!((x, y), (800, 410));
    cx.simulate_mouse_up(centre, MouseButton::Left, Modifiers::default());

    // Smaller steps back to the fit, and the fit is the whole desktop again.
    let smaller = bounds_of(cx, "desktop.zoom.out").center();
    for _ in 0..crate::app::desktop::DesktopZoom::LADDER.len() {
        cx.simulate_click(smaller, Modifiers::default());
        cx.run_until_parked();
    }
    let zoom = cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .zoom()
    });
    assert_eq!(
        zoom,
        crate::app::desktop::DesktopZoom::Fit,
        "a fit picture is where zooming out ends"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_certificate_that_may_not_be_trusted_is_refused_at_once_and_releases_the_worker(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(vec![LinkEvent::Certificate {
        request_id: 9,
        host: "rdp.example.com".to_owned(),
        subject: "CN=rdp".to_owned(),
        issuer: "CN=ca".to_owned(),
        fingerprint: "AA:BB".to_owned(),
        flags: 1,
    }]);
    let record = desktop_record_rejecting_certificates("desk");
    let id = mount_scripted_desktop(&view, cx, &record, link);

    let log = log.lock().expect("the log is not poisoned").clone();
    assert_eq!(
        log.answers,
        vec![(9, false)],
        "the refusal reached the server, with the request id it asked about"
    );
    assert_eq!(
        log.shutdowns, 1,
        "the worker is stopped instead of being held while the server waits"
    );
    let (state, phase, stage) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        (
            view.workspace()
                .session(id)
                .map(|session| session.state().clone()),
            pane.phase().clone(),
            pane.failed_stage(),
        )
    });
    assert_eq!(
        state,
        Some(SessionState::Failed(SessionFailure::HostKeyRejected)),
        "the record says the certificate was refused"
    );
    assert!(
        matches!(phase, crate::app::view::DesktopPhase::Ended(_)),
        "the pane ended instead of staying in a connecting step"
    );
    assert_eq!(
        stage,
        Some(crate::app::view::DesktopStage::VerifyingCertificate),
        "the step it stopped on is the one it was on"
    );
}

/// Show a precise local target while waiting for the VNC cursor.
#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn vnc_uses_a_visible_local_pointer_until_a_shape_arrives(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(live_desktop_events());
    let feed = link.feed();
    let record = vnc_record_sharing("desk", true);
    let id = mount_scripted_desktop(&view, cx, &record, link);

    let (live, cursor) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        (pane.is_live(), pane.surface_cursor_for_test())
    });
    assert!(live, "the frame put the session in its live step");
    assert_eq!(
        cursor,
        gpui::CursorStyle::Crosshair,
        "motion is visible before the server supplies a shape"
    );
    let picture = cx
        .debug_bounds("desktop.surface")
        .expect("the remote picture is drawn");
    cx.simulate_mouse_move(
        point(
            picture.origin.x + picture.size.width / 2.0,
            picture.origin.y + picture.size.height / 2.0,
        ),
        None,
        Modifiers::default(),
    );
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("desktop.controls").is_some(),
        "the bar over the picture is drawn while the pointer is on the pane"
    );

    feed.feed(vec![LinkEvent::State {
        state: LinkState::Closed,
        failure: LinkFailure::None,
        detail: 0,
        reason: String::new(),
    }]);
    pump_desktop(&view, cx, id);

    let (ended, cursor) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app);
        (
            matches!(pane.phase(), crate::app::view::DesktopPhase::Ended(_)),
            pane.surface_cursor_for_test(),
        )
    });
    assert!(ended, "the closed state ended the session");
    assert_eq!(
        cursor,
        gpui::CursorStyle::Arrow,
        "an ended session is not a picture and keeps the ordinary pointer"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn reconnecting_desktop_freezes_the_old_picture_and_discards_input(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(vec![LinkEvent::Frame(solid(
        0,
        0,
        2,
        2,
        (2, 2),
        [7, 8, 9, 255],
    ))]);
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &vnc_record_sharing("desk", true), link);
    let point = bounds_of(cx, "desktop.picture").center();
    cx.simulate_mouse_down(point, MouseButton::Left, Modifiers::default());
    let count = log.lock().unwrap().inputs.len();
    feed.feed(vec![LinkEvent::State {
        state: LinkState::Connecting,
        failure: LinkFailure::None,
        reason: "reconnecting".into(),
        detail: 0,
    }]);
    pump_desktop(&view, cx, id);
    assert_eq!(&desktop_canvas(&view, cx, id)[..4], &[7, 8, 9, 255]);
    cx.simulate_mouse_up(point, MouseButton::Left, Modifiers::default());
    cx.simulate_click(point, Modifiers::default());
    assert_eq!(log.lock().unwrap().inputs.len(), count);
    feed.feed(vec![LinkEvent::Frame(solid(
        0,
        0,
        1,
        1,
        (2, 2),
        [3, 4, 5, 255],
    ))]);
    pump_desktop(&view, cx, id);
    let pixels = desktop_canvas(&view, cx, id);
    assert_eq!(&pixels[..4], &[3, 4, 5, 255]);
    assert!(pixels[4..].iter().all(|&p| p == 0));
    cx.simulate_click(point, Modifiers::default());
    assert!(log.lock().unwrap().inputs.len() > count);
}

/// Local motion must remain visible while the link sends no new frames.
#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn desktop_pointer_follows_local_motion_without_another_frame(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _) = ScriptedLink::new(vec![
        LinkEvent::Frame(solid(0, 0, 1, 1, (800, 600), [3, 3, 3, 255])),
        LinkEvent::Pointer(shellune_desktop::PointerShape::Bitmap {
            width: 4,
            height: 4,
            hotspot: (1, 2),
            pixels: vec![255; 64].into(),
        }),
    ]);
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    let picture = bounds_of(cx, "desktop.picture");
    let scale = f32::from(picture.size.width) / 800.0;
    for offset in [0.0, 40.0, -27.0] {
        let point = picture.center() + point(px(offset), px(offset));
        cx.simulate_mouse_move(point, None, Modifiers::default());
        cx.run_until_parked();
        let cursor = bounds_of(cx, "desktop.pointer");
        assert!((f32::from(cursor.origin.x - point.x) + scale).abs() < 1.1);
        assert!((f32::from(cursor.origin.y - point.y) + 2.0 * scale).abs() < 1.1);
    }
    assert_eq!(
        cx.update(|_, app| view
            .read(app)
            .desktop_of(id)
            .unwrap()
            .read(app)
            .surface_cursor_for_test()),
        gpui::CursorStyle::None
    );
    for shape in [
        shellune_desktop::PointerShape::Hidden,
        shellune_desktop::PointerShape::Bitmap {
            width: 1,
            height: 1,
            hotspot: (0, 0),
            pixels: vec![0; 4].into(),
        },
    ] {
        feed.feed(vec![LinkEvent::Pointer(shape)]);
        pump_desktop(&view, cx, id);
        assert_eq!(
            cx.update(|_, app| view
                .read(app)
                .desktop_of(id)
                .unwrap()
                .read(app)
                .surface_cursor_for_test()),
            gpui::CursorStyle::None
        );
    }
    feed.feed(vec![LinkEvent::Pointer(
        shellune_desktop::PointerShape::Default,
    )]);
    pump_desktop(&view, cx, id);
    assert_eq!(
        cx.update(|_, app| view
            .read(app)
            .desktop_of(id)
            .unwrap()
            .read(app)
            .surface_cursor_for_test()),
        gpui::CursorStyle::None
    );
}

