#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn each_notice_is_shown_once_per_session_and_a_ready_clipboard_withdraws_the_refusal(
    cx: &mut TestAppContext,
) {
    use crate::app::desktop::{ClipboardKind, DriveProblem, Notice};
    use crate::app::view::DesktopNotice;

    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(live_desktop_events());
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    assert!(desktop_notices(&view, cx, id).is_empty());

    feed.feed(vec![
        LinkEvent::Notice(Notice::DriveUnavailable(DriveProblem::Missing)),
        LinkEvent::Notice(Notice::ClipboardRefused),
        LinkEvent::Notice(Notice::ClipboardRefused),
        LinkEvent::Notice(Notice::Unknown(99)),
    ]);
    pump_desktop(&view, cx, id);
    redraw(cx);
    assert_eq!(
        desktop_notices(&view, cx, id),
        vec![
            DesktopNotice::DriveUnavailable,
            DesktopNotice::ClipboardRefused
        ],
        "a repeated notice is said once, and one this build does not know is not said"
    );
    let strip = bounds_of(cx, "desktop.notice");
    assert!(
        strip.size.width > px(0.0) && strip.size.height > px(0.0),
        "the notices are drawn over the picture"
    );
    assert!(
        cx.debug_bounds("desktop.notice.drive_unavailable")
            .is_some()
    );
    assert!(
        cx.debug_bounds("desktop.notice.clipboard_refused")
            .is_some()
    );
    let reason = ENGLISH
        .desktop_notice_drive_unavailable
        .replace("{reason}", ENGLISH.desktop_drive_missing);
    assert!(
        reason.contains("does not exist"),
        "the folder notice names its reason: {reason}"
    );

    // The clipboard becoming ready takes the refusal back.
    feed.feed(vec![LinkEvent::Notice(Notice::ClipboardReady)]);
    pump_desktop(&view, cx, id);
    assert_eq!(
        desktop_notices(&view, cx, id),
        vec![DesktopNotice::DriveUnavailable]
    );

    // Dismissed notices stay away, and a kind already shown is not shown again.
    click(cx, "desktop.notice.dismiss");
    assert!(desktop_notices(&view, cx, id).is_empty());
    feed.feed(vec![
        LinkEvent::Notice(Notice::DriveUnavailable(DriveProblem::NoAccess)),
        LinkEvent::Notice(Notice::ClipboardTooLarge(ClipboardKind::Text)),
        LinkEvent::Notice(Notice::ClipboardTooLarge(ClipboardKind::Png)),
        LinkEvent::Notice(Notice::ClipboardTooLarge(ClipboardKind::Dib)),
        LinkEvent::Notice(Notice::ClipboardLatin1Only),
        // A refused drive is a notice of its own, beside an unavailable one, and
        // either way the server refused it is the same notice.
        LinkEvent::Notice(Notice::DriveRefused(
            shellune_desktop::DriveRefusal::Declined(0xC000_0022),
        )),
        LinkEvent::Notice(Notice::DriveRefused(
            shellune_desktop::DriveRefusal::NotOpened,
        )),
    ]);
    pump_desktop(&view, cx, id);
    redraw(cx);
    assert_eq!(
        desktop_notices(&view, cx, id),
        vec![
            DesktopNotice::TextTooLarge,
            DesktopNotice::ImageTooLarge,
            DesktopNotice::ClipboardLatin1,
            DesktopNotice::DriveRefused,
        ],
        "text cut and image left out are two notices; each image form is the same one"
    );
    for selector in [
        "desktop.notice.text_too_large",
        "desktop.notice.image_too_large",
        "desktop.notice.clipboard_latin1",
        "desktop.notice.drive_refused",
    ] {
        assert!(cx.debug_bounds(selector).is_some(), "{selector} is drawn");
    }
    assert!(cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the surface is mounted")
            .read(app)
            .is_live()
    }));
}

#[test]
#[ignore = "opt-in RDP/VNC test"]
fn a_desktop_target_carries_the_clipboard_switch_and_the_folder_to_map() {
    let mut config = shellune_core::RdpConfig::new("desk", "rdp.example.com", Some("desk"))
        .expect("a valid RDP record");
    let target = crate::app::desktop::DesktopTarget::of_record(
        &shellune_core::ConnectionRecord::Rdp(config.clone()),
    )
    .expect("a target");
    assert!(target.clipboard(), "the clipboard is shared by default");
    assert_eq!(target.drive_folder(), None, "nothing is mapped by default");

    config.set_clipboard(false);
    config
        .set_drive_folder(Some(r"D:\Exchange"))
        .expect("a folder path");
    let target = crate::app::desktop::DesktopTarget::of_record(
        &shellune_core::ConnectionRecord::Rdp(config),
    )
    .expect("a target");
    assert!(!target.clipboard());
    assert_eq!(target.drive_folder(), Some(r"D:\Exchange"));

    let target = crate::app::desktop::DesktopTarget::of_record(&vnc_record_sharing("vnc", false))
        .expect("a target");
    assert!(!target.clipboard());
    assert_eq!(target.drive_folder(), None, "VNC has no drive to map");
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn the_rdp_form_saves_the_clipboard_switch_and_the_folder_and_vnc_has_only_the_switch(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("desktop-sharing-form");
    let (view, cx) = hosts_view(cx, dir.store());
    cx.simulate_resize(size(px(1400.0), px(1300.0)));
    cx.run_until_parked();

    click(cx, "hosts.new");
    click(cx, "connection.protocol.rdp");
    assert!(cx.update(|_window, app| {
        view.read(app)
            .hosts_state()
            .protocol_draft()
            .is_some_and(|draft| draft.clipboard())
    }));
    type_into(cx, "connection.field.address", "10.0.0.9");
    click(cx, "connection.field.clipboard");
    type_into(cx, "connection.field.drive_folder", r"C:\Exchange");
    assert!(
        cx.debug_bounds("connection.drive_folder.note").is_some(),
        "the folder says what the remote side sees"
    );
    click(cx, "connection.save");

    let saved = cx.update(|_window, app| view.read(app).book().connections().to_vec());
    let rdp = saved
        .iter()
        .find_map(|record| match record {
            shellune_core::ConnectionRecord::Rdp(config) => Some(config.clone()),
            _ => None,
        })
        .expect("the RDP connection was saved");
    assert!(!rdp.clipboard(), "the switch was turned off and saved off");
    assert_eq!(rdp.drive_folder(), Some(r"C:\Exchange"));

    // Opening it again shows both choices as they were saved.
    let id = rdp.id();
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.edit_connection_for_test(id, cx));
    });
    cx.run_until_parked();
    let draft = cx.update(|_window, app| view.read(app).hosts_state().protocol_draft().cloned());
    let draft = draft.expect("the form is open");
    assert!(!draft.clipboard());
    assert_eq!(
        draft.text(crate::app::hosts::ConnectionFormField::DriveFolder),
        r"C:\Exchange"
    );
    click(cx, "connection.cancel");

    // A VNC form has the switch and no folder.
    click(cx, "hosts.new");
    click(cx, "connection.protocol.vnc");
    redraw(cx);
    let fields = cx.update(|_window, app| {
        view.read(app)
            .hosts_state()
            .protocol_draft()
            .map(|draft| draft.fields().to_vec())
    });
    let fields = fields.expect("the VNC form is open");
    assert!(fields.contains(&crate::app::hosts::ConnectionFormField::Clipboard));
    assert!(!fields.contains(&crate::app::hosts::ConnectionFormField::DriveFolder));
    type_into(cx, "connection.field.address", "10.0.0.41");
    click(cx, "connection.field.clipboard");
    click(cx, "connection.save");
    let vnc = cx.update(|_window, app| {
        view.read(app)
            .book()
            .connections()
            .iter()
            .find_map(|record| match record {
                shellune_core::ConnectionRecord::Vnc(config) => Some(config.clone()),
                _ => None,
            })
    });
    assert!(
        !vnc.expect("the VNC connection was saved").clipboard(),
        "a VNC connection keeps its switch too"
    );
}

/// Saves an RDP connection on a closed port, with the password typed in the form.
fn save_desktop_password_form(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    protocol: &'static str,
    password: &str,
    remember: bool,
) -> shellune_core::HostId {
    click(cx, "hosts.new");
    click(cx, protocol);
    type_into(cx, "connection.field.address", "127.0.0.1");
    clear_field(cx, "connection.field.port", 4);
    type_into(cx, "connection.field.port", "1");
    type_into(cx, "connection.field.secret", password);
    let current_remember = cx.update(|_window, app| {
        view.read(app)
            .hosts_state()
            .protocol_draft()
            .is_some_and(|draft| draft.remember())
    });
    if current_remember != remember {
        click(cx, "connection.field.remember");
    }
    click(cx, "connection.save");
    cx.update(|_window, app| {
        view.read(app)
            .book()
            .connections()
            .last()
            .map(shellune_core::ConnectionRecord::id)
    })
    .expect("the connection was saved")
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn the_desktop_form_asks_for_a_password_and_hides_it(cx: &mut TestAppContext) {
    let dir = TempDir::new("desktop-secret-form");
    let (view, cx) = hosts_view(cx, dir.store());
    cx.simulate_resize(size(px(1400.0), px(1300.0)));
    cx.run_until_parked();

    click(cx, "hosts.new");
    click(cx, "connection.protocol.rdp");
    assert!(
        cx.debug_bounds("connection.field.secret").is_some(),
        "a RDP server asks for a password, so the form does"
    );
    assert!(
        cx.debug_bounds("connection.field.remember").is_some(),
        "the password can be kept, the way a host's can"
    );
    type_into(cx, "connection.field.secret", "rdp-pass");
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .hosts_state()
                .protocol_draft()
                .map(|draft| draft.text(ConnectionFormField::Secret).to_owned())
        }),
        Some("rdp-pass".to_owned()),
        "every typed character lands once, in the draft the record is built from"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).connection_secret_masked_for_test(app)),
        Some(true),
        "the password is not drawn as it is typed"
    );

    // VNC asks for one too; a serial port has nothing to sign in to.
    click(cx, "connection.protocol.vnc");
    let vnc = cx
        .update(|_window, app| view.read(app).hosts_state().protocol_draft().cloned())
        .expect("the VNC form is open");
    assert!(vnc.fields().contains(&ConnectionFormField::Secret));
    assert_eq!(
        vnc.text(ConnectionFormField::Secret),
        "",
        "a password typed for RDP is not carried into the VNC form"
    );

    click(cx, "connection.protocol.serial");
    let serial = cx
        .update(|_window, app| view.read(app).hosts_state().protocol_draft().cloned())
        .expect("the serial form is open");
    assert!(
        !serial.fields().contains(&ConnectionFormField::Secret),
        "a serial port has no password"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn switching_protocols_does_not_carry_a_password_between_forms(cx: &mut TestAppContext) {
    let dir = TempDir::new("desktop-secret-switch");
    let (view, cx) = hosts_view(cx, dir.store());
    cx.simulate_resize(size(px(1400.0), px(1300.0)));
    cx.run_until_parked();

    let secret_text = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| {
            view.read(app)
                .hosts_state()
                .protocol_draft()
                .map(|draft| draft.text(ConnectionFormField::Secret).to_owned())
        })
    };

    click(cx, "hosts.new");
    click(cx, "connection.protocol.rdp");
    type_into(cx, "connection.field.secret", "rdp-secret");

    // A VNC form is a new one: the RDP password is not in it.
    click(cx, "connection.protocol.vnc");
    assert_eq!(secret_text(cx), Some(String::new()));
    type_into(cx, "connection.field.secret", "vnc-secret");

    // The SSH form is the host form, and it starts with nothing typed either.
    click(cx, "connection.protocol.ssh");
    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().protocol_draft().is_none()),
        "the SSH form is the host form"
    );
    let ssh_secret = cx.update(|_window, app| {
        view.read(app)
            .hosts_state()
            .draft()
            .map(|draft| draft.text(crate::app::hosts::HostField::Secret).to_owned())
    });
    assert_eq!(ssh_secret, Some(String::new()));
    type_into(cx, "hosts.field.secret", "ssh-secret");

    // And back: the SSH password stays in the form it was typed into.
    click(cx, "connection.protocol.rdp");
    assert_eq!(
        secret_text(cx),
        Some(String::new()),
        "a password typed for SSH is not carried into a desktop form"
    );
    assert!(cx.update(|_window, app| { view.read(app).hosts_state().draft().is_none() }));
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn one_press_on_a_saved_desktop_opens_one_attempt(cx: &mut TestAppContext) {
    let dir = TempDir::new("desktop-one-attempt");
    let record = desktop_record("office");
    seed_connections(&dir.store(), vec![record.clone()]);
    let (view, cx) = hosts_view_with_trust(cx, &dir);

    click(cx, "hosts.connection.connect.0");
    cx.run_until_parked();

    let (attempts, sessions) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            view.desktop_start_count_for_test(),
            view.open_sessions().len(),
        )
    });
    assert_eq!(attempts, 1, "one press starts one attempt, not two");
    assert_eq!(sessions, 1, "one press opens one session");
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_pane_count_for_test()),
        1,
        "one connection paints one picture: a second surface would show the desktop twice"
    );

    // The pane itself was asked to start once, and it dialled once.
    let session = cx
        .update(|_window, app| view.read(app).open_sessions().first().copied())
        .expect("the session exists");
    let starts = cx.update(|_window, app| {
        view.read(app)
            .desktop_of(session)
            .map(|pane| pane.read(app).starts())
    });
    assert_eq!(starts, Some(1), "the surface is started once");

    // The attempt fails at once - nothing listens on the record's address - and a
    // session that ended is not quietly started again: another attempt is the user's
    // decision, made from the tab or the list.
    pump_desktop(&view, cx, session);
    pump_desktop(&view, cx, session);
    let after = cx.update(|_window, app| {
        (
            view.read(app).desktop_start_count_for_test(),
            view.read(app).open_sessions().len(),
        )
    });
    assert_eq!(
        after,
        (1, 1),
        "one press stays one attempt, however the attempt ends"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn every_keystroke_reaches_a_desktop_once(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    focus_desktop_drawn(&view, cx, id);

    let before = sent(&log).len();
    cx.simulate_keystrokes("a");
    release_key(cx, "a");
    let a = crate::app::desktop::key_codes("a").expect("a is a key");
    assert_eq!(
        sent(&log)[before..],
        [
            DesktopInput::Key {
                codes: a,
                down: true
            },
            DesktopInput::Key {
                codes: a,
                down: false
            },
        ],
        "one press and one release, so a character cannot arrive twice"
    );
}

/// The pane's zoom step, read the way the controls draw it.
fn desktop_zoom(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    id: SessionId,
) -> crate::app::desktop::DesktopZoom {
    cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("the desktop surface is mounted")
            .read(app)
            .zoom()
    })
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn the_zoom_readout_switches_between_fit_and_one_hundred(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Fit,
        "a session starts by fitting the window"
    );

    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Percent(100),
        "pressing the readout asks for the actual size"
    );
    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Fit,
        "pressing it again fits the window"
    );

    // The steps on either side keep their own ladder; the readout is not a third
    // way of stepping through it.
    click(cx, "desktop.zoom.in");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Percent(200),
        "the + button still jumps to the largest step from Fit"
    );
    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Fit,
        "from a zoomed picture the readout fits the window again"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn the_controls_stay_clickable_over_a_notice_and_a_certificate(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let mut events = live_desktop_events();
    events.push(LinkEvent::Notice(
        crate::app::desktop::Notice::ClipboardTooLarge(crate::app::desktop::ClipboardKind::Text),
    ));
    let (link, _log) = ScriptedLink::new(events);
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    assert!(
        cx.debug_bounds("desktop.notice").is_some(),
        "the warning strip is over the picture"
    );

    // A press on a control still reaches it with the strip on screen: the strip is
    // at the picture's foot and the bar is drawn after it.
    click(cx, "desktop.zoom.in");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Percent(200),
        "the zoom button works with the warning strip up"
    );

    // With a certificate card up, the certificate question takes priority above the toolbar
    // so it is never obscured or blocked by non-essential controls (R2).
    feed.feed(vec![LinkEvent::Certificate {
        request_id: 3,
        host: "rdp.example.com".to_owned(),
        subject: "CN=rdp".to_owned(),
        issuer: "CN=ca".to_owned(),
        fingerprint: "AA:BB".to_owned(),
        flags: 0,
    }]);
    pump_desktop(&view, cx, id);
    redraw(cx);
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("desktop.certificate").is_some(),
        "the certificate question is immediately visible above the toolbar"
    );
    assert!(
        cx.debug_bounds("desktop.certificate.reject").is_some(),
        "the certificate decision remains reachable without unfolding the toolbar"
    );
    click(cx, "desktop.certificate.reject");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| {
            view.read(app)
                .desktop_of(id)
                .expect("desktop mounted")
                .read(app)
                .phase()
                .failure()
                .is_some()
        }),
        "refusing the certificate card acts directly on the certificate"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_dropped_desktop_reconnects_only_when_the_user_asks(cx: &mut TestAppContext) {
    // The record is in the book: the reconnect opens the saved connection again, and
    // a record that is only mounted on a scripted link has nothing to open.
    let dir = TempDir::new("desktop-drop-reconnect");
    let record = desktop_record("desk");
    seed_connections(&dir.store(), vec![record.clone()]);
    let (view, cx) = hosts_view_with_trust(cx, &dir);
    let (link, _log) = ScriptedLink::new(live_desktop_events());
    let feed = link.feed();
    let id = mount_scripted_desktop(&view, cx, &record, link);

    // The server closes the session. The client reports it and stops: it does not
    // dial again on its own, which on xrdp would log the same user in twice and take
    // the display over from the first connection.
    feed.feed(vec![LinkEvent::State {
        state: LinkState::Failed(LinkFailure::RemoteClosed),
        failure: LinkFailure::RemoteClosed,
        detail: 0,
        reason: "the server closed the connection".to_owned(),
    }]);
    pump_desktop(&view, cx, id);
    assert!(
        matches!(
            session_state(cx, &view, id),
            Some(SessionState::Disconnected(_))
        ),
        "the drop ends the session: {:?}",
        session_state(cx, &view, id)
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_start_count_for_test()),
        0,
        "nothing dials again by itself"
    );

    // The reconnect the user asks for is a new attempt, in the same tab.
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.reconnect_session(id, cx));
    });
    cx.run_until_parked();
    let (attempts, tabs) = cx.update(|_window, app| {
        (
            view.read(app).desktop_start_count_for_test(),
            view.read(app).open_tabs(),
        )
    });
    assert_eq!(
        attempts,
        1,
        "the explicit reconnect starts one new attempt (state {:?})",
        session_state(cx, &view, id)
    );
    assert_eq!(tabs, vec![id], "and it stays in the session's own tab");
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn a_folded_bar_stays_folded_until_the_handle_is_pressed(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);
    let collapsed = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| {
            view.read(app)
                .desktop_of(id)
                .expect("the desktop surface is mounted")
                .read(app)
                .controls_collapsed_for_test()
        })
    };
    let drawn = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| {
            view.read(app)
                .desktop_of(id)
                .expect("the desktop surface is mounted")
                .read(app)
                .controls_frames_for_test()
        })
    };
    let revealed = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| {
            view.read(app)
                .desktop_of(id)
                .expect("the desktop surface is mounted")
                .read(app)
                .controls_revealed_for_test()
        })
    };

    hover(cx, "desktop.body");
    cx.run_until_parked();
    assert!(revealed(cx), "the bar follows the pointer");
    assert!(
        cx.debug_bounds("desktop.controls").is_some(),
        "the bar is over the picture while the pointer is on it"
    );

    click(cx, "desktop.controls.collapse");
    cx.run_until_parked();
    assert!(collapsed(cx), "the fold is the pane's own state");

    // The test window keeps the debug bounds of an element that is gone, so absence
    // is read two ways: no frame draws the bar any more, and a press where the
    // readout was does nothing.
    let frames = drawn(cx);
    for _ in 0..3 {
        redraw(cx);
        cx.run_until_parked();
    }
    assert_eq!(drawn(cx), frames, "no frame after the fold drew the bar");
    let fitted = desktop_zoom(&view, cx, id);
    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        fitted,
        "a folded bar does not answer a press where its readout was"
    );

    // No residual expand handle exists while collapsed (R2: zero residual hit area).
    assert!(
        cx.debug_bounds("desktop.controls.expand").is_none(),
        "no residual expand handle is drawn when collapsed"
    );

    // Moving away and back over the middle of the picture keeps the bar folded.
    cx.simulate_mouse_move(point(px(2.0), px(2.0)), None, Modifiers::default());
    cx.run_until_parked();
    assert!(
        !revealed(cx),
        "away from the picture nothing is drawn over it"
    );
    hover(cx, "desktop.body");
    cx.run_until_parked();
    assert!(
        collapsed(cx),
        "moving to the middle of the picture keeps the bar folded"
    );
    assert_eq!(drawn(cx), frames, "still no frame drew the bar");

    // Moving the pointer into the top-center reveal zone unfolds the bar cleanly.
    let body = bounds_of(cx, "desktop.body");
    let reveal_point = point((body.left() + body.right()) / 2.0, body.top() + px(4.0));
    cx.simulate_mouse_move(reveal_point, None, Modifiers::default());
    cx.run_until_parked();
    assert!(
        !collapsed(cx),
        "entering the top-center reveal zone unfolds the bar"
    );
    assert!(
        cx.debug_bounds("desktop.controls").is_some(),
        "the bar is drawn again"
    );
    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Percent(100),
        "the readout works again once the bar is back"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn the_zoom_readout_works_after_folding_and_unfolding(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, _log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);

    click(cx, "desktop.controls.collapse");
    cx.run_until_parked();
    let folded = desktop_zoom(&view, cx, id);
    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        folded,
        "the readout is not there while the bar is folded, so the press changes nothing"
    );

    let body = bounds_of(cx, "desktop.body");
    let reveal_point = point((body.left() + body.right()) / 2.0, body.top() + px(4.0));
    cx.simulate_mouse_move(reveal_point, None, Modifiers::default());
    cx.run_until_parked();
    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Percent(100),
        "the readout still switches once the bar is back"
    );
    click(cx, "desktop.zoom.fit");
    assert_eq!(
        desktop_zoom(&view, cx, id),
        crate::app::desktop::DesktopZoom::Fit
    );
}
