#[gpui::test]
async fn a_closed_serial_tab_still_says_which_frames_never_left(cx: &mut TestAppContext) {
    // A driver that takes the first frame and then holds it: the second frame is still in
    // the queue when the tab closes, which is the case a person has to be told about.
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device) = scripted_serial_port(
        "COM3",
        shellune_serial::testing::FakeSpec::new().holding_writes(),
        std::time::Duration::from_secs(2),
    );
    let id = mount_scripted_serial(&view, cx, "console", "COM3", false, link);
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            let pane = view.pane_of(id).expect("the pane is mounted").clone();
            pane.update(cx, |pane, cx| {
                pane.type_text("first", cx);
                pane.type_text("second", cx);
            });
        });
    });
    // Let the writer take the first frame, so the second is really queued at the close.
    std::thread::sleep(std::time::Duration::from_millis(60));
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.close_session(id, cx));
    });
    cx.run_until_parked();

    let (gone, titles, entries, queued) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            pane_gone(app, view, id),
            view.toast_titles(),
            view.toast_entries(),
            view.workspace()
                .session(id)
                .map(|session| session.title().to_owned()),
        )
    });
    assert!(gone, "the tab is closed");
    assert!(
        queued.is_some(),
        "the session record survives the pane, so the tab it named is accounted for"
    );
    let note = titles
        .iter()
        .find(|title| title.contains("never sent"))
        .unwrap_or_else(|| panic!("the corner says what was left behind: {titles:?}"));
    let count: usize = note
        .chars()
        .take_while(char::is_ascii_digit)
        .collect::<String>()
        .parse()
        .expect("the sentence starts with how many frames were left");
    assert!(
        count >= 1,
        "the number of frames that never left is stated: {note}"
    );
    assert!(
        note.contains("bytes)"),
        "and so is how much of them there was: {note}"
    );
    assert!(
        entries
            .iter()
            .any(|(tone, title)| *tone == Tone::Warning && title.contains("never sent")),
        "a close that lost bytes is not reported as a success: {entries:?}"
    );
    assert!(
        !titles.iter().any(|title| title.contains("still held")),
        "a port that was really released is not called held: {titles:?}"
    );
    assert!(
        device.written().is_empty(),
        "the frame the driver was inside never reached the wire either: {:?}",
        device.written()
    );
}

#[gpui::test]
async fn a_close_the_driver_never_answers_is_reported_after_the_tab_is_gone(
    cx: &mut TestAppContext,
) {
    // A driver that ignores the cancellation request: the close waits, gives up and says
    // the port is still held. The wait is shortened so the test does not sit for two
    // seconds; the sequence is the application's.
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device) = scripted_serial_port(
        "COM4",
        shellune_serial::testing::FakeSpec::new().ignoring_interrupt(),
        std::time::Duration::from_millis(60),
    );
    let id = mount_scripted_serial(&view, cx, "console", "COM4", false, link);
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.close_session(id, cx));
    });
    cx.run_until_parked();
    let strings = Locale::English.strings();
    let titles = cx.update(|_window, app| {
        let view = view.read(app);
        assert!(
            pane_gone(app, view, id),
            "the tab keeps closing even when the port does not"
        );
        view.toast_titles()
    });
    let note = titles
        .iter()
        .find(|title| title.contains(strings.serial_still_held))
        .unwrap_or_else(|| panic!("the corner says the port is still held: {titles:?}"));
    assert!(
        note.contains("did not stop within"),
        "the sentence says what the driver did instead of stopping: {note}"
    );
    assert!(
        !device.is_released(),
        "and the port really was still held, so the sentence is true"
    );
    // Let the blocked read finish so the thread does not outlive the test.
    device.release_driver();
}

#[gpui::test]
async fn a_serial_session_that_lost_its_device_stops_driving_it(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    let (link, device) = unplugged_serial("COM3");
    let id = mount_scripted_serial(&view, cx, "console", "COM3", false, link);

    // The device goes away: the reader reports it and the session ends. The tab stays -
    // it names the device and the reason - but the line must stop being driven.
    pump_serial_until(&view, cx, id, |pane| !pane.state().accepts_input());
    cx.run_until_parked();
    let state = session_state(cx, &view, id);
    assert!(
        matches!(state, Some(SessionState::Disconnected(_))),
        "the session states the loss instead of looking live: {state:?}"
    );
    let (holds, still_open, note, titles) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view.pane_of(id).expect("the pane is still there");
        let pane = pane.read(app);
        (
            pane.holds_source(),
            view.open_sessions().contains(&id),
            pane.serial_note().map(str::to_owned),
            view.toast_titles(),
        )
    });
    assert!(
        !holds,
        "the pane let go of the device when the session ended, so the writer thread and the send queue do not outlive it"
    );
    assert!(
        still_open,
        "the tab stays: it is what tells the user which device went away"
    );
    assert!(
        device.is_released(),
        "the port is back with the system, so the device can be opened again"
    );
    assert!(
        note.is_none()
            || titles
                .iter()
                .any(|title| note.as_deref() == Some(title.as_str())),
        "a note about the close is shown in the corner as well as on the strip: {note:?} / {titles:?}"
    );
    // Running the release twice is harmless: the session is over either way.
    let again = cx.update(|_window, app| {
        let pane = view
            .read(app)
            .pane_of(id)
            .expect("the pane is there")
            .clone();
        pane.update(app, |pane, cx| pane.release_serial(cx))
    });
    assert!(again.is_none(), "a second release has nothing left to say");
}

/// Whether a session has no pane any more, for a test.
fn pane_gone(_app: &gpui::App, view: &ShelluneView, id: SessionId) -> bool {
    view.pane_of(id).is_none() && !view.open_sessions().contains(&id)
}

#[gpui::test]
async fn a_serial_session_reconnects_in_its_own_tab_without_replaying_the_old_queue(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("serial-reconnect");
    // The record is really saved, because the reconnect reads it back from the book the
    // way the application does: a session that is reopened is the one the user saved.
    let record = serial_record("console", "COM3");
    let mut book = HostBook::new();
    book.insert_connection(record.clone())
        .expect("the serial record is saved");
    let store = dir.store();
    store.save(&book).expect("the book saves");
    let (view, cx) = cx
        .add_window_view(move |_window, cx| ShelluneView::with_store(cx, Workspace::new(), store));
    cx.run_until_parked();

    let (old_link, old_device) = unplugged_serial("COM3");
    let id = cx.update(|_window, cx| {
        view.update(cx, |view, cx| {
            view.attach_scripted_serial_for_test(
                &record,
                old_link,
                "COM3",
                "115200 8N1, none flow control",
                false,
                cx,
            )
        })
    });
    cx.run_until_parked();
    // The device goes away, which is what the reconnect entry answers.
    pump_serial_until(&view, cx, id, |pane| !pane.state().accepts_input());
    cx.run_until_parked();
    assert!(
        matches!(
            session_state(cx, &view, id),
            Some(SessionState::Disconnected(_))
        ),
        "the session ended before it is reopened"
    );
    let (old_pane, old_tag, name, kind, tabs) = cx.update(|_window, app| {
        let view = view.read(app);
        let pane = view.pane_of(id).expect("the pane is there").clone();
        let session = view.workspace().session(id).expect("the session is listed");
        (
            pane.clone(),
            pane.read(app).tag(),
            session.title().to_owned(),
            session.kind().clone(),
            view.open_sessions(),
        )
    });
    assert_eq!(tabs, vec![id], "one tab was open before the reconnect");

    // The device the record names is the in-memory pair here; the port of the previous
    // attempt is gone, and the queue it still held went with it.
    let (new_link, new_device, _new_peer) = scripted_serial();
    cx.update(|_window, cx| {
        view.update(cx, |view, _cx| {
            view.queue_scripted_serial_for_test("COM3", new_link);
        });
    });
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.reconnect_session(id, cx));
    });
    cx.run_until_parked();

    let (new_pane, state, generation, device, tabs, kind_after, name_after) =
        cx.update(|_window, app| {
            let view = view.read(app);
            let pane = view
                .pane_of(id)
                .expect("the reconnected pane is there")
                .clone();
            let session = view.workspace().session(id).expect("the session is listed");
            let device = pane
                .read(app)
                .serial()
                .map(|serial| serial.device().to_owned());
            (
                pane.clone(),
                session.state().clone(),
                session.generation(),
                device,
                view.open_sessions(),
                session.kind().clone(),
                session.title().to_owned(),
            )
        });
    assert_ne!(
        new_pane.entity_id(),
        old_pane.entity_id(),
        "a reconnect is a new pane, not the old one restarted"
    );
    assert_eq!(tabs, vec![id], "the tab, its identity and its place stay");
    assert_eq!(
        (&kind_after, name_after.as_str()),
        (&kind, name.as_str()),
        "the session is still the same serial connection, named the same"
    );
    assert_eq!(
        state,
        SessionState::Connected,
        "the new attempt really opened a device"
    );
    assert_eq!(
        generation, 1,
        "the reconnect is another generation, so a late event can be told apart"
    );
    assert_eq!(
        device.as_deref(),
        Some("COM3"),
        "the device is the one the record names, never a similar port that happens to be attached"
    );
    assert!(
        old_device.written().is_empty(),
        "the port of the previous attempt received nothing that could be replayed: {:?}",
        old_device.written()
    );
    assert!(
        new_device.written().is_empty()
            && cx.update(|_window, app| new_pane.read(app).sent().is_empty()),
        "nothing typed into the lost session is sent again: {:?}",
        new_device.written()
    );

    // An event that still carries the previous generation is refused instead of being
    // drawn into the terminal that replaced it.
    let accepted = cx.update(|_window, app| {
        new_pane.update(app, |pane, cx| {
            pane.adopt_events(
                old_tag,
                vec![SourceEvent::Data(b"stale-from-the-old-port\r\n".to_vec())],
                cx,
            )
        })
    });
    assert!(
        !accepted,
        "an event of the previous attempt must be refused"
    );
    let screen = cx.update(|_window, app| new_pane.read(app).visible_text().join("\n"));
    assert!(
        !screen.contains("stale-from-the-old-port"),
        "the old port's output reached the new terminal: {screen:?}"
    );

    // The reconnected device really is the one driving the tab.
    new_device.push_from_device(b"alive\r\n");
    pump_serial_until(&view, cx, id, |pane| {
        pane.visible_text().iter().any(|row| row.contains("alive"))
    });
    let screen = cx.update(|_window, app| new_pane.read(app).visible_text().join("\n"));
    assert!(
        screen.contains("alive"),
        "the reconnected device reaches the tab: {screen:?}"
    );
}

// ---------------------------------------------------------------------------
// Following the shell's directory (R15)
// ---------------------------------------------------------------------------

/// One OSC 7 report, as a shell with directory reporting writes it.
fn directory_report(path: &str) -> Vec<u8> {
    format!("\u{1b}]7;file://web{path}\u{7}").into_bytes()
}

/// Opens the file view of one session with a scripted connection.
fn open_files_for(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
    answers: &FileAnswers,
) {
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_files_for_test(
                id,
                "web",
                "deploy@10.0.0.5:22",
                Box::new(answers.clone()),
                cx,
            );
        });
    });
    cx.run_until_parked();
    click(cx, "session.files");
}

/// The remote path one session's file view shows.
fn remote_path(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
) -> Option<String> {
    cx.update(|_window, app| {
        view.read(app)
            .files_browser(id)
            .and_then(|browser| browser.path().map(str::to_owned))
    })
}

#[gpui::test]
async fn the_file_view_follows_the_directory_the_shell_reports(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/home/deploy"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::NoReport),
        "following waits for a report instead of pretending the login directory was one"
    );

    // The user runs cd /var/log, and the shell says so with OSC 7.
    feed_session(cx, &view, id, &directory_report("/var/log"));
    let request = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(path, "/var/log", "the reported directory is listed");
            request
        }
        other => panic!("following asks for the reported directory, got {other:?}"),
    };
    answers.reply(
        request,
        "/var/log",
        &[("syslog", shellune_core::FileKind::File)],
    );
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/var/log"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Following {
            path: "/var/log".to_owned()
        })
    );
    assert!(
        cx.debug_bounds("files.follow").is_some(),
        "the switch that says the view follows is on screen"
    );
    // R4: the switch is a small icon in the column's header, right after its refresh,
    // and nothing about following takes a row of its own under the path.
    let follow = bounds_of(cx, "files.follow");
    let refresh = bounds_of(cx, "files.refresh");
    let header = bounds_of(cx, "files.header");
    assert!(
        (follow.top() - refresh.top()).abs() <= px(0.5)
            && follow.left() >= refresh.right() - px(0.5)
            && follow.left() - refresh.right() <= px(8.0),
        "the switch sits beside the refresh: follow {follow:?}, refresh {refresh:?}"
    );
    assert!(
        follow.top() >= header.top() - px(0.5) && follow.bottom() <= header.bottom() + px(0.5),
        "the switch is part of the column's header: follow {follow:?}, header {header:?}"
    );
    assert!(
        follow.size.width <= px(32.0) && follow.size.height <= px(32.0),
        "the switch is an icon, not a labelled segment: {follow:?}"
    );
    assert!(
        cx.debug_bounds("files.follow.row").is_none()
            && cx.debug_bounds("files.follow.note").is_none(),
        "no follow row and no note sit under the path"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_tooltip_for_test(id)),
        crate::app::copy::Locale::English.strings().files_follow_on,
        "while it follows, the tooltip says only that it is on"
    );

    // The report was a report: it is not part of what the terminal shows.
    let screen = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .map(|pane| pane.read(app).visible_text().join("\n"))
            .unwrap_or_default()
    });
    assert!(
        !screen.contains("file://") && !screen.contains("7;"),
        "the sequence is not drawn as text: {screen:?}"
    );
}

#[gpui::test]
async fn a_step_up_the_root_cannot_take_keeps_following_on(cx: &mut TestAppContext) {
    // R15: only a directory the user really moved to is browsing by hand. At the root
    // there is no parent, so the switch must not quietly turn itself off.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    let channel = files.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_files_for_test(id, "web", "deploy@10.0.0.5:22", Box::new(channel), cx);
        });
    });
    cx.run_until_parked();
    feed_session(cx, &view, id, &directory_report("/"));
    click(cx, "session.files");
    files.reply(1, "/", &[("etc", shellune_core::FileKind::Directory)]);
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/"));
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
    let sent = files.requests().len();
    press_key(cx, "left");
    assert!(
        cx.update(|_window, app| view.read(app).files_follows(id)),
        "the step the column cannot take does not turn following off"
    );
    assert_eq!(
        files.requests().len(),
        sent,
        "nothing is asked for a directory that has no parent"
    );
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/"));
}
#[gpui::test]
async fn following_opens_on_the_reported_directory_and_survives_the_background(
    cx: &mut TestAppContext,
) {
    // Three edges R15 has to hold: the report that arrived before the view opened is the
    // directory it opens on, a step up the column cannot take is not the user browsing,
    // and a report that arrives while another session is in front waits for its own.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();

    // 1. A report before the view exists is the directory the first listing asks for,
    //    and the note says so instead of "no directory reported yet".
    let channel = files.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_files_for_test(id, "web", "deploy@10.0.0.5:22", Box::new(channel), cx);
        });
    });
    cx.run_until_parked();
    feed_session(cx, &view, id, &directory_report("/var/log"));
    click(cx, "session.files");
    let first = files.requests().first().cloned();
    assert!(
        matches!(&first, Some(shellune_core::BrowseRequest::List { path, .. }) if path == "/var/log"),
        "the first listing is the reported directory, not the login one: {first:?}"
    );
    files.reply(1, "/var/log", &[("syslog", shellune_core::FileKind::File)]);
    pump_files(cx, &view);
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Following {
            path: "/var/log".to_owned()
        }),
        "the column says it follows the directory it was asked for"
    );

    // 2. A report that arrives while another session is in front moves nothing until
    //    this session is the one on screen again.
    let _second = live_remote_second(cx, &view, id);
    feed_session(cx, &view, id, &directory_report("/etc"));
    assert_eq!(
        remote_path(cx, &view, id).as_deref(),
        Some("/var/log"),
        "the listing of a background session is left where it is"
    );
    show_remote_terminal(cx, &view, id);
    pump_files(cx, &view);
    let request = match files.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(
                path, "/etc",
                "the report is followed once this session is in front"
            );
            request
        }
        other => panic!("coming back asks for the reported directory, got {other:?}"),
    };
    files.reply(request, "/etc", &[("hosts", shellune_core::FileKind::File)]);
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/etc"));
}
#[gpui::test]
async fn browsing_by_hand_stops_the_following_and_the_switch_takes_it_back(
    cx: &mut TestAppContext,
) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);
    feed_session(cx, &view, id, &directory_report("/var/log"));
    let request = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { request, .. }) => request,
        other => panic!("following asks for the reported directory, got {other:?}"),
    };
    answers.reply(
        request,
        "/var/log",
        &[("syslog", shellune_core::FileKind::File)],
    );
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/var/log"));

    // The user clicks an ancestor breadcrumb: that is browsing, not following.
    click(cx, "files.crumb.0");
    assert!(
        !cx.update(|_window, app| view.read(app).files_follows(id)),
        "browsing by hand turns following off"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Manual)
    );

    // A later cd must not take the path the user chose.
    let before = answers.requests().len();
    feed_session(cx, &view, id, &directory_report("/etc"));
    assert_eq!(
        answers.requests().len(),
        before,
        "a manual path is not replaced by the next directory the shell reports"
    );

    // The switch returns to where the shell is now.
    click(cx, "files.follow");
    match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(
                path, "/etc",
                "the switch goes to the last reported directory"
            );
            answers.reply(request, "/etc", &[("hosts", shellune_core::FileKind::File)]);
        }
        other => panic!("following asks for the reported directory, got {other:?}"),
    }
    pump_files(cx, &view);
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/etc"));
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
}

#[gpui::test]
async fn a_directory_that_cannot_be_read_keeps_the_last_readable_one_and_says_why(
    cx: &mut TestAppContext,
) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);

    feed_session(cx, &view, id, &directory_report("/root/private"));
    let refused = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(path, "/root/private");
            request
        }
        other => panic!("the reported directory is asked for, got {other:?}"),
    };
    answers.fail(
        refused,
        shellune_core::BrowseFailure::PermissionDenied {
            path: "/root/private".to_owned(),
        },
    );
    pump_files(cx, &view);
    // The window returns to the directory the server really listed.
    let back = match answers.requests().last().cloned() {
        Some(shellune_core::BrowseRequest::List { path, request }) => {
            assert_eq!(path, "/home/deploy");
            request
        }
        other => panic!("the last readable directory is listed again, got {other:?}"),
    };
    answers.reply(
        back,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);

    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/home/deploy"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).files_follow_note(id)),
        Some(crate::app::files::FollowNote::Unreadable {
            path: "/root/private".to_owned()
        }),
        "the refusal is stated together with the last readable path"
    );
    // R4: the reason is in the switch's tooltip, after its state, and not in a warning
    // line under the path.
    assert!(
        cx.debug_bounds("files.follow.note").is_none(),
        "the remote column draws no follow note under its path"
    );
    let tooltip = cx.update(|_window, app| view.read(app).files_follow_tooltip_for_test(id));
    let strings = crate::app::copy::Locale::English.strings();
    assert!(
        tooltip.starts_with(strings.files_follow_on)
            && tooltip.contains(strings.files_follow_unreadable)
            && tooltip.contains("/root/private"),
        "the tooltip states the switch and why the column is not where the shell is: {tooltip:?}"
    );
}

#[gpui::test]
async fn the_follow_switch_is_a_keyboard_stop_and_answers_enter(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let answers = FileAnswers::accepting();
    open_files_for(cx, &view, id, &answers);
    answers.reply(
        1,
        "/home/deploy",
        &[("docs", shellune_core::FileKind::Directory)],
    );
    pump_files(cx, &view);

    // The keyboard lands in the server column, which is where a session's files are
    // browsed from.
    cx.update(|window, app| view.read(app).focus_remote_files_for_test(window));
    cx.run_until_parked();
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Body))
    );

    // Tab walks the file view's controls until the switch has the ring.
    let mut reached = false;
    for _ in 0..8 {
        press_key(cx, "tab");
        if files_stop(cx, &view) == Some((FileSource::Remote, FilesStop::Follow)) {
            reached = true;
            break;
        }
    }
    assert!(reached, "the follow switch is reachable with the keyboard");

    // Enter presses it, exactly as a click does.
    press_key(cx, "enter");
    assert!(
        !cx.update(|_window, app| view.read(app).files_follows(id)),
        "Enter turns following off"
    );
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Follow)),
        "the ring stays on the switch it just pressed"
    );
    press_key(cx, "enter");
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
    // Space answers as Enter does.
    press_key(cx, "space");
    assert!(
        !cx.update(|_window, app| view.read(app).files_follows(id)),
        "Space turns following off"
    );
    press_key(cx, "space");
    assert!(cx.update(|_window, app| view.read(app).files_follows(id)));
}

/// The names one column shows, in the order it shows them (R14).
fn column_rows(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
    source: FileSource,
) -> Vec<String> {
    cx.update(|_window, app| view.read(app).files_rows_for_test(id, source))
}

/// The entries one column has marked (R14).
fn column_marked(
    cx: &mut VisualTestContext,
    view: &Entity<ShelluneView>,
    id: SessionId,
    source: FileSource,
) -> Vec<String> {
    cx.update(|_window, app| view.read(app).files_marked_for_test(id, source))
}

/// Every deletion the scripted connection was asked for, in the order it was asked (R14).
fn deleted_paths(answers: &FileAnswers) -> Vec<String> {
    answers
        .requests()
        .into_iter()
        .filter_map(|request| match request {
            shellune_core::BrowseRequest::Delete { path, .. } => Some(path),
            _ => None,
        })
        .collect()
}

/// The names as the columns report them, which is what an assertion compares.
fn names(list: &[&str]) -> Vec<String> {
    list.iter().map(|name| (*name).to_owned()).collect()
}

#[gpui::test]
async fn each_column_sorts_and_filters_its_own_listing(cx: &mut TestAppContext) {
    // R14 wants sorting and filtering to belong to one column: narrowing the server's
    // side must leave this computer's side alone, and neither may reorder the other.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (remote, _local) = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[
            ("b.txt", shellune_core::FileKind::File),
            ("a.txt", shellune_core::FileKind::File),
            ("logs", shellune_core::FileKind::Directory),
        ],
    );
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Local),
        names(&["logs", "a.txt", "b.txt"]),
        "a folder stays first and the names run A to Z"
    );
    // The same key pressed again reverses the order, and the folder still leads.
    click(cx, "files.local.sort.name");
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Local),
        names(&["logs", "b.txt", "a.txt"])
    );
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "the server's column keeps its own order"
    );

    // A filter is read from the column it was typed into, and costs no request.
    let sent = remote.requests().len();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.files_filter_set_for_test(id, FileSource::Remote, "note", cx);
        });
    });
    cx.run_until_parked();
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Remote),
        names(&["notes.txt"])
    );
    assert_eq!(
        cx.update(|_window, app| { view.read(app).files_counts_for_test(id, FileSource::Remote) }),
        Some((1, 2)),
        "the column says how many names the filter lets through"
    );
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Local),
        names(&["logs", "b.txt", "a.txt"]),
        "the other column is not filtered"
    );
    assert_eq!(
        remote.requests().len(),
        sent,
        "filtering a listing asks the server for nothing"
    );
}

#[gpui::test]
async fn marking_rows_with_the_pointer_uploads_every_marked_file(cx: &mut TestAppContext) {
    // R14 asks for a batch to be reachable with the pointer as well as the keyboard, and
    // R16 for every file to become its own task: one transfer carries one path.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (remote, _local) = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[
            ("a.txt", shellune_core::FileKind::File),
            ("b.txt", shellune_core::FileKind::File),
        ],
    );
    let transfers = TransferAnswers::accepting();
    let channel = transfers.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_transfers_for_test(id, Box::new(channel), cx);
        });
    });
    cx.run_until_parked();

    // The box on each row is a target of its own.
    click(cx, "files.local.mark.0");
    click(cx, "files.local.mark.1");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Local),
        names(&["a.txt", "b.txt"])
    );
    click(cx, "files.local.mark.upload");
    let starts = transfers.starts();
    assert_eq!(starts.len(), 2, "one task per marked file: {starts:?}");
    let expected_first = if cfg!(windows) {
        "C:\\work\\a.txt"
    } else {
        "/C:/work/a.txt"
    };
    assert_eq!(
        starts[0].source.as_str(),
        expected_first,
        "the first task is the first marked row"
    );
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Local),
        Vec::<String>::new(),
        "the batch is done, so nothing is left marked"
    );
    let _ = remote;
}

#[gpui::test]
async fn the_keyboard_marks_rows_and_a_batch_delete_names_every_entry(cx: &mut TestAppContext) {
    // R14: a batch is built with the keyboard (Space marks the row under the cursor and
    // moves on, Ctrl+A marks the column) and the question names every entry it covers,
    // while the requests go out one at a time.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Body)),
        "the listing holds the keys"
    );
    press_key(cx, "down");
    press_key(cx, "space");
    press_key(cx, "space");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "Space marks the row it is on and moves to the next"
    );

    click(cx, "files.mark.delete");
    assert_eq!(
        cx.update(|_window, app| { view.read(app).files_delete_question_for_test() }),
        Some(names(&["docs", "notes.txt"])),
        "the question names every entry it would delete"
    );
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.submit_files_change_for_test(cx));
    });
    cx.run_until_parked();
    assert_eq!(
        deleted_paths(&files),
        names(&["/home/deploy/docs"]),
        "only the first deletion has been asked for"
    );
    files.changed(
        2,
        shellune_core::MutationOutcome::new(
            shellune_core::MutationAction::Delete {
                path: "/home/deploy/docs".to_owned(),
                kind: shellune_core::FileKind::Directory,
            },
            vec![shellune_core::MutationStep::done(
                "/home/deploy/docs",
                Some(shellune_core::FileKind::Directory),
            )],
        ),
    );
    pump_files(cx, &view);
    files.reply(
        3,
        "/home/deploy",
        &[("notes.txt", shellune_core::FileKind::File)],
    );
    pump_files(cx, &view);
    assert_eq!(
        deleted_paths(&files),
        names(&["/home/deploy/docs", "/home/deploy/notes.txt"]),
        "the second deletion follows once the first answer and its listing arrived"
    );
}

#[gpui::test]
async fn a_wide_window_docks_the_files_beside_the_terminal_and_keeps_both(cx: &mut TestAppContext) {
    // R14 asks a wide window to show the terminal and the files at once, and asks a
    // layout switch to change neither the terminal nor either column's path.
    let (view, cx) = remote_view(cx);
    cx.simulate_resize(size(px(1680.0), px(940.0)));
    cx.run_until_parked();
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);
    assert!(
        cx.update(|_window, app| view.read(app).files_docked_for_test()),
        "a window this wide docks the files beside the terminal"
    );
    let split = bounds_of(cx, "files.split");
    assert!(
        split.size.height > px(0.0),
        "the two share one row: {split:?}"
    );
    let screen = cx.update(|_window, app| {
        view.read(app)
            .pane_of(id)
            .map(|pane| pane.read(app).visible_text().join("\n"))
            .unwrap_or_default()
    });
    assert!(
        screen.contains("remote ready"),
        "the terminal is still drawn beside the files: {screen:?}"
    );

    // The focus switch gives the files the whole width; the terminal and the paths stay.
    let docked_width = bounds_of(cx, "files.panel").size.width;
    click(cx, "files.mode.focus");
    assert!(!cx.update(|_window, app| view.read(app).files_docked_for_test()));
    // Focused, the file view has the whole client area rather than half of it. The
    // selector of the docked row is not asked about here: a removed selector keeps the
    // bounds of the frame that drew it.
    let focused_width = bounds_of(cx, "files.panel").size.width;
    assert!(
        focused_width > docked_width,
        "the files take the terminal's width too: {focused_width:?} against {docked_width:?}"
    );
    assert_eq!(
        remote_path(cx, &view, id).as_deref(),
        Some("/home/deploy"),
        "the path survives the layout switch"
    );
    click(cx, "files.mode.dock");
    assert!(cx.update(|_window, app| view.read(app).files_docked_for_test()));
    assert!(cx.debug_bounds("files.split").is_some());
    let docked_again = bounds_of(cx, "files.panel").size.width;
    assert!(
        docked_again < focused_width,
        "the terminal has its half back: {docked_again:?}"
    );
    assert_eq!(remote_path(cx, &view, id).as_deref(), Some("/home/deploy"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        Some(id),
        "the terminal is the same session in every arrangement"
    );
}
#[gpui::test]
async fn the_focus_switch_is_only_offered_where_the_window_can_dock(cx: &mut TestAppContext) {
    // R14 asks for a switch between the docked and the focused layout. A window narrower
    // than DOCK_MIN_WIDTH has no docked layout to leave, so the switch used to be drawn
    // anyway and did nothing but relabel itself: the files already had the terminal's
    // place. It is offered only where the press changes the arrangement.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);

    // The default 1120-pixel window: the files take the terminal's place, and the bar
    // does not offer a second arrangement that would render identically.
    assert!(
        !cx.update(|_window, app| view.read(app).files_docked_for_test()),
        "a window this narrow does not dock the files"
    );
    assert!(
        cx.debug_bounds("files.layout.dual").is_some(),
        "the two columns share the whole width instead"
    );
    assert!(
        cx.debug_bounds("files.mode.focus").is_none(),
        "no layout switch is drawn where both modes render the same"
    );
    assert!(
        cx.debug_bounds("files.mode.dock").is_none(),
        "and the other label of that switch is not drawn either"
    );

    // A window that really can dock gets the switch, and the press changes the layout.
    cx.simulate_resize(size(px(1680.0), px(940.0)));
    cx.run_until_parked();
    let switch = bounds_of(cx, "files.mode.focus");
    assert!(
        switch.size.width > px(0.0),
        "a dockable window offers the focus switch: {switch:?}"
    );
    let docked_width = bounds_of(cx, "files.panel").size.width;
    click(cx, "files.mode.focus");
    assert!(!cx.update(|_window, app| view.read(app).files_docked_for_test()));
    let focused_width = bounds_of(cx, "files.panel").size.width;
    assert!(
        focused_width > docked_width,
        "the focused mode gives the files the terminal's half: {focused_width:?} against {docked_width:?}"
    );
    click(cx, "files.mode.dock");
    assert!(cx.update(|_window, app| view.read(app).files_docked_for_test()));
    assert!(
        bounds_of(cx, "files.panel").size.width < focused_width,
        "the terminal comes back on the same press"
    );
}

#[gpui::test]
async fn the_delete_key_covers_the_batch_the_menu_deletes(cx: &mut TestAppContext) {
    // R14: one marked state has one answer. The menu on a marked row says "Delete the
    // selection" and deletes the marks; the Delete key used to delete only the row under
    // the cursor, so the two entry points disagreed about the same selection.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("docs", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Body)),
        "the listing holds the keys"
    );
    press_key(cx, "down");
    press_key(cx, "space");
    press_key(cx, "space");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "two rows are marked"
    );

    let handled = cx.update(|window, app| {
        view.update(app, |view, cx| {
            view.files_key_for_test(id, FileSource::Remote, "delete", false, window, cx)
        })
    });
    assert!(handled, "Delete belongs to the column");
    let by_key = cx.update(|_window, app| view.read(app).files_delete_question_for_test());
    assert_eq!(
        by_key,
        Some(names(&["docs", "notes.txt"])),
        "the key asks about every marked entry, not only the row it sits on"
    );
    press_key(cx, "escape");
    assert!(
        !cx.update(|_window, app| view.read(app).files_question_open()),
        "the question closes again"
    );

    // The menu on one of those marked rows covers exactly the same entries.
    right_click(cx, "files.entry.1");
    click(cx, "files.menu.delete");
    let by_menu = cx.update(|_window, app| view.read(app).files_delete_question_for_test());
    assert_eq!(
        by_menu, by_key,
        "the menu and the key delete the same entries for one selection"
    );
}

#[gpui::test]
async fn typing_letters_in_a_file_listing_jumps_to_the_row_they_start(cx: &mut TestAppContext) {
    // R14: a listing answers letters the way a file manager does, so a long folder is
    // crossed by name instead of by holding an arrow key.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let files = FileAnswers::accepting();
    open_files_for(cx, &view, id, &files);
    files.reply(
        1,
        "/home/deploy",
        &[
            ("bin", shellune_core::FileKind::Directory),
            ("Desktop", shellune_core::FileKind::Directory),
            ("docs", shellune_core::FileKind::Directory),
            ("downloads", shellune_core::FileKind::Directory),
            ("notes.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);
    assert_eq!(
        files_stop(cx, &view),
        Some((FileSource::Remote, FilesStop::Body)),
        "the listing holds the keys"
    );
    let selected = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| {
            view.read(app)
                .files_selected_for_test(id, FileSource::Remote)
        })
    };

    let pause = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| {
            view.update(app, |view, _cx| view.files_type_ahead_pause_for_test());
        });
    };

    press_key(cx, "n");
    assert_eq!(selected(cx).as_deref(), Some("notes.txt"));
    pause(cx);
    // One letter pressed again walks through every row it starts, in any case.
    press_key(cx, "d");
    assert_eq!(selected(cx).as_deref(), Some("Desktop"));
    press_key(cx, "d");
    assert_eq!(selected(cx).as_deref(), Some("docs"));
    pause(cx);
    // A quick word narrows the jump: "dow" passes docs and lands on downloads.
    press_key(cx, "d o w");
    assert_eq!(
        selected(cx).as_deref(),
        Some("downloads"),
        "the whole word is matched"
    );
    press_key(cx, "shift-b");
    assert_eq!(
        selected(cx).as_deref(),
        Some("downloads"),
        "a word nothing starts with leaves the row where it was"
    );
    assert!(
        column_marked(cx, &view, id, FileSource::Remote).is_empty(),
        "letters only move the row, they mark nothing"
    );
}

#[gpui::test]
async fn a_batch_counts_the_tasks_it_started_and_says_what_it_left_out(cx: &mut TestAppContext) {
    // R14: a batch reports what really happened. A folder among the marks is not a task -
    // a batch copies one path per task and never expands a folder into a tree behind the
    // user's back - so the count leaves it out and the strip says how many were skipped,
    // instead of announcing an upload that never started.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (remote, local) = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[
            ("logs", shellune_core::FileKind::Directory),
            ("a.txt", shellune_core::FileKind::File),
            ("b.txt", shellune_core::FileKind::File),
        ],
    );
    let transfers = TransferAnswers::accepting();
    let channel = transfers.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_transfers_for_test(id, Box::new(channel), cx);
        });
    });
    cx.run_until_parked();
    let _ = local;

    // The whole local listing is marked: one folder and two files.
    click(cx, "files.local.mark.0");
    click(cx, "files.local.mark.1");
    click(cx, "files.local.mark.2");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Local).len(),
        3,
        "three entries are marked"
    );
    click(cx, "files.local.mark.upload");
    let starts = transfers.starts();
    assert_eq!(
        starts.len(),
        2,
        "one task per marked file and none for the folder: {starts:?}"
    );
    let strings = Locale::default().strings();
    assert_eq!(
        cx.update(|_window, app| view.read(app).toast_titles()),
        vec![copy::fill(
            strings.files_uploaded_selected,
            &[("count", "2")]
        )],
        "the toast counts the tasks that exist, not the marks that were made"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).transfer_skipped_folders_for_test(id)),
        Some(copy::fill(
            strings.files_batch_folders_skipped,
            &[("count", "1")]
        )),
        "the folder that was left out is stated once, with its own reason"
    );
    assert!(
        cx.debug_bounds("transfers.skipped").is_some(),
        "the line is on screen beside the transfer list"
    );
    let _ = (remote, local);
}

#[gpui::test]
async fn a_download_batch_states_the_folder_it_left_out(cx: &mut TestAppContext) {
    // The same rule on the other side: a marked remote folder is not a task either, so
    // the count is the files that started and the line names the folder that did not.
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (remote, _local) = open_both_sources(
        cx,
        &view,
        id,
        "/C:/work",
        &[("a.txt", shellune_core::FileKind::File)],
    );
    let transfers = TransferAnswers::accepting();
    let channel = transfers.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.attach_transfers_for_test(id, Box::new(channel), cx);
        });
    });
    cx.run_until_parked();
    assert_eq!(
        column_rows(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "the server's listing holds one folder and one file"
    );
    click(cx, "files.mark.0");
    click(cx, "files.mark.1");
    assert_eq!(
        column_marked(cx, &view, id, FileSource::Remote),
        names(&["docs", "notes.txt"]),
        "both are marked, though only one of them can become a task"
    );
    click(cx, "files.mark.download");
    let starts = transfers.starts();
    assert_eq!(starts.len(), 1, "only the file became a task: {starts:?}");
    let strings = Locale::default().strings();
    assert_eq!(
        cx.update(|_window, app| view.read(app).toast_titles()),
        vec![copy::fill(
            strings.files_downloaded_selected,
            &[("count", "1")]
        )],
        "the download count is one task, not two marks"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).transfer_skipped_folders_for_test(id)),
        Some(copy::fill(
            strings.files_batch_folders_skipped,
            &[("count", "1")]
        )),
        "the remote folder is stated the same way"
    );
    assert!(
        cx.debug_bounds("transfers.skipped").is_some(),
        "the line is on screen beside the transfer list"
    );
    let _ = remote;
}

