#[gpui::test]
async fn terminal_scrollback_jump_pill_select_all_and_font_reset_work_end_to_end(
    cx: &mut TestAppContext,
) {
    let mut initial = String::new();
    for line in 0..45 {
        initial.push_str(&format!("history-line-{line}\r\n"));
    }
    initial.push_str("live-bottom-prompt");
    let (pane, cx) = pane_with(&initial, cx);

    assert_eq!(cx.update(|_window, app| pane.read(app).display_offset()), 0);
    assert!(
        cx.debug_bounds("terminal.scroll_bottom").is_none(),
        "pinned at the live bottom, no jump-to-bottom pill is drawn"
    );

    let center = bounds_of(cx, "terminal.row.0").center();
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    cx.simulate_event(ScrollWheelEvent {
        position: center,
        delta: ScrollDelta::Pixels(point(px(0.0), px(5.0 * cell.height))),
        touch_phase: gpui::TouchPhase::Started,
        ..Default::default()
    });
    cx.run_until_parked();

    assert!(cx.update(|_window, app| pane.read(app).display_offset()) > 0);
    assert!(
        cx.debug_bounds("terminal.scrollbar.thumb").is_some(),
        "scrolling into history shows the scrollbar position thumb"
    );
    let pill = bounds_of(cx, "terminal.scroll_bottom");
    assert!(
        pill.size.height >= px(24.0),
        "jump-to-bottom pill meets the 24px minimum hit target: {pill:?}"
    );

    click(cx, "terminal.scroll_bottom");
    assert_eq!(
        cx.update(|_window, app| pane.read(app).display_offset()),
        0,
        "clicking the pill jumps back to the live bottom"
    );

    // Select All from the terminal context menu covers scrollback + visible rows.
    right_click(cx, "terminal.row.0");
    assert!(cx.debug_bounds("terminal.menu.select_all").is_some());
    click(cx, "terminal.menu.select_all");
    right_click(cx, "terminal.row.0");
    click(cx, "terminal.menu.copy");
    let copied = cx
        .read_from_clipboard()
        .and_then(|item| item.text())
        .unwrap_or_default();
    assert!(
        copied.contains("history-line-0") && copied.contains("live-bottom-prompt"),
        "Select All copies both scrollback and live screen: {copied:?}"
    );

    // The menu's reset puts the font size back to DEFAULT_FONT_SIZE.
    click(cx, "terminal.more");
    click(cx, "terminal.more.font.increase");
    click(cx, "terminal.more.font.increase");
    assert!(
        cx.update(|_window, app| pane.read(app).font_size()) > shellune_terminal::DEFAULT_FONT_SIZE
    );
    click(cx, "terminal.more.font.reset");
    assert_eq!(
        cx.update(|_window, app| pane.read(app).font_size()),
        shellune_terminal::DEFAULT_FONT_SIZE,
        "clicking the font readout resets the terminal font size to default"
    );
}

#[gpui::test]
async fn narrow_window_at_comfortable_text_keeps_hosts_row_and_actions_within_bounds(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("regular-window-hosts");
    seed(
        &dir.store(),
        vec![stored_host(
            "prod-gateway",
            "10.240.12.8",
            22,
            "deploy",
            Some("Production"),
        )],
    );
    let store = dir.store();
    let trust = TrustStore::at(dir.path());
    let mut workspace = Workspace::new();
    workspace.select(Destination::Settings);
    let (view, cx) = cx.add_window_view(move |_window, cx| {
        ShelluneView::with_store_and_trust(cx, workspace, store, trust)
    });
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(narrow_window());
    focus_root(&view, cx);
    cx.dispatch_action(ToggleLanguage);
    // One step from the default is 115%. The row is measured at that size, not at
    // 90%: a second step would hide and show different columns.
    cx.dispatch_action(CycleTextSize);
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().zoom()),
        Zoom::Comfortable
    );
    click(cx, "nav.hosts");
    cx.simulate_resize(narrow_window());
    cx.run_until_parked();

    let viewport = cx.update(|window, _app| window.viewport_size());
    let row = bounds_of(cx, "hosts.row.0");
    let connect = bounds_of(cx, "hosts.connect.0");
    let more = bounds_of(cx, "hosts.more.0");
    assert_within_width(row, viewport, "hosts.row.0 at 720x480 @ 115%");
    assert_within_width(connect, viewport, "hosts.connect.0 at 720x480 @ 115%");
    assert_within_width(more, viewport, "hosts.more.0 at 720x480 @ 115%");
    // 720 is narrower than the 760 (scaled to 874 at 115%) the row needs for its
    // duplicate tool, so the tool is left out rather than pushing the actions out.
    assert!(
        cx.debug_bounds("hosts.duplicate.0").is_none(),
        "a narrow window at 115% hides the inline duplicate icon so the primary actions fit"
    );
}

// ---------------------------------------------------------------------------
// The home page: sidebar, toolbar and one list (ADR-3)
// ---------------------------------------------------------------------------

/// Four hosts in two top-level groups and one without: three reached at different
/// times, and the last one marked as a favourite.
fn seed_dashboard(dir: &TempDir) -> Vec<HostId> {
    let store = dir.store();
    let mut book = seed(
        &store,
        vec![
            stored_host("alpha", "10.0.0.1", 22, "deploy", Some("Prod")),
            stored_host("beta", "10.0.0.2", 22, "deploy", Some("Prod")),
            stored_host("gamma", "10.0.0.3", 22, "deploy", Some("Staging")),
            stored_host("delta", "10.0.0.4", 22, "deploy", None),
        ],
    );
    let ids: Vec<HostId> = book.hosts().iter().map(HostConfig::id).collect();
    book.record_connection(ids[0], 1_000).expect("a saved host");
    book.record_connection(ids[2], 3_000).expect("a saved host");
    book.record_connection(ids[1], 2_000).expect("a saved host");
    book.set_favorite(ids[3], true).expect("a saved host");
    store.save(&book).expect("the book saves");
    ids
}

/// The name of the host whose connection form is open.
fn open_form_name(cx: &mut VisualTestContext, view: &Entity<ShelluneView>) -> Option<String> {
    cx.update(|_window, app| {
        view.read(app)
            .remote_state()
            .map(|panel| panel.host().name().to_owned())
    })
}

/// The platform's command key with one letter: Ctrl on Windows and Linux, Cmd on macOS.
fn command_key(letter: &str) -> String {
    format!("{}-{letter}", Platform::current().keystroke_modifier())
}

#[gpui::test]
async fn the_home_is_a_sidebar_a_toolbar_and_one_list(cx: &mut TestAppContext) {
    let dir = TempDir::new("home-shape");
    seed_dashboard(&dir);
    let (_view, cx) = hosts_view_with_trust(cx, &dir);

    // The sidebar: the places, the groups and the local terminal at its foot.
    let sidebar = bounds_of(cx, "home.sidebar");
    assert!(
        (sidebar.size.width - Metrics::default().scale(220.0)).abs() < px(1.0),
        "the sidebar is 220 wide on a wide window: {sidebar:?}"
    );
    for entry in [
        "hosts.view.all",
        "hosts.view.favorites",
        "hosts.view.recent",
        "hosts.group.new",
        "hosts.tree.0",
        "hosts.tree.1",
        "home.local",
    ] {
        let bounds = bounds_of(cx, entry);
        assert!(
            sidebar.contains(&bounds.center()),
            "{entry} is in the sidebar: {bounds:?} {sidebar:?}"
        );
    }
    assert!(
        bounds_of(cx, "home.local").top() > bounds_of(cx, "hosts.tree.1").bottom(),
        "the local terminal sits under the groups"
    );

    // The toolbar: the sidebar's switch, the one search, the two menus and the one
    // primary action.
    let toolbar = bounds_of(cx, "hosts.toolbar");
    for part in [
        "home.sidebar.toggle",
        "hosts.search",
        "hosts.filter",
        "hosts.more",
        "hosts.new",
    ] {
        assert!(
            toolbar.contains(&bounds_of(cx, part).center()),
            "{part} is in the toolbar"
        );
    }
    assert!(toolbar.left() >= sidebar.right() - px(0.5));
    // The place and its count head the content under the toolbar, once.
    for part in ["header.title", "header.count"] {
        let bounds = bounds_of(cx, part);
        assert!(
            bounds.top() >= toolbar.bottom() - px(0.5) && bounds.left() >= sidebar.right(),
            "{part} heads the content under the toolbar: {bounds:?} {toolbar:?}"
        );
    }
    assert!(
        bounds_of(cx, "header.title").bottom() <= bounds_of(cx, "hosts.row.0").top() + px(0.5),
        "the heading is above the list"
    );

    // One list of four, each row with its address, tag, time and state.
    assert!(cx.debug_bounds("hosts.list.4").is_some());
    let row = bounds_of(cx, "hosts.row.0");
    for part in [
        "hosts.tag.0",
        "hosts.last.0",
        "hosts.connect.0",
        "hosts.edit.0",
        "hosts.more.0",
    ] {
        assert!(
            row.contains(&bounds_of(cx, part).center()),
            "{part} is on the first row"
        );
    }
    assert!(
        cx.debug_bounds("hosts.last.3").is_none(),
        "delta was never reached, so its row says no time"
    );

    // What the page no longer has: a second search, the cards, the segments and the
    // quick-connect button.
    for gone in [
        "home.quick",
        "home.dashboard",
        "home.recent",
        "home.groups",
        "welcome.quick",
        "hosts.view.groups",
        "hosts.count",
        "hosts.statuses",
    ] {
        assert!(cx.debug_bounds(gone).is_none(), "{gone} is not drawn");
    }
}

