#[gpui::test]
async fn another_machine_s_host_arrives_at_start_and_on_the_next_check(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let machine_a = TempDir::new("sync-a");
    seed(
        &machine_a.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let a = other_machine(&machine_a, &server);
    assert!(matches!(
        a.sync().expect("A uploads"),
        shellune_sync::SyncOutcome::Uploaded(_)
    ));

    // B starts with nothing and pulls what A wrote.
    let machine_b = TempDir::new("sync-b");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&machine_b, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &machine_b, &secrets, Destination::Hosts);
    assert_eq!(host_names(&view, cx), vec!["alpha"], "pulled at start");

    // A adds a host; B's next check brings it in without a restart.
    seed(
        &machine_a.store(),
        vec![
            stored_host("alpha", "10.0.0.1", 22, "root", None),
            stored_host("beta", "10.0.0.2", 22, "root", None),
        ],
    );
    let _ = a.sync().expect("A uploads again");
    after_poll(cx);
    assert_eq!(host_names(&view, cx), vec!["alpha", "beta"]);
    assert_eq!(
        machine_b.store().load().expect("reads").hosts().len(),
        2,
        "and it is saved on B"
    );
    // Applying the pull did not send it back.
    let puts = put_count(&server);
    after_debounce(cx);
    assert_eq!(put_count(&server), puts, "a pull is not uploaded again");
}

/// Sets up a conflict: A and B synced once, then both changed, and A uploaded first.
fn conflicting_machines<'a>(
    cx: &'a mut TestAppContext,
    server: &shellune_sync::testing::WebDavServer,
    machine_a: &TempDir,
    machine_b: &TempDir,
) -> (
    Entity<ShelluneView>,
    &'a mut VisualTestContext,
    shellune_sync::SyncService,
) {
    seed(
        &machine_a.store(),
        vec![stored_host("alpha", "10.0.0.1", 22, "root", None)],
    );
    let a = other_machine(machine_a, server);
    let _ = a.sync().expect("A uploads");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(machine_b, &secrets, server, true);
    let (view, cx) = sync_window(cx, machine_b, &secrets, Destination::Settings);
    assert_eq!(host_names(&view, cx), vec!["alpha"]);

    // Both sides change the same field of one host - a real conflict; A also
    // adds a host and B marks a favourite, which alone would merge.
    let mut book = machine_a.store().load().expect("A's hosts read");
    let mut alpha_a = book.hosts()[0].clone();
    alpha_a.set_address("10.0.0.9").expect("a valid address");
    book.update(alpha_a.clone(), alpha_a.id())
        .expect("A's alpha changes");
    book.apply(&HostEdit::create(stored_host(
        "from-a", "10.0.0.7", 22, "root", None,
    )))
    .expect("A adds a host");
    machine_a.store().save(&book).expect("A saves");
    let _ = a.sync().expect("A uploads its change");
    let alpha = first_host_id(&view, cx);
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.edit_connection_for_test(alpha, cx));
    });
    cx.run_until_parked();
    clear_field(cx, "hosts.field.address", "10.0.0.1".len());
    type_into(cx, "hosts.field.address", "10.0.0.8");
    click(cx, "hosts.save");
    cx.run_until_parked();
    toggle_favorite(&view, cx, alpha);
    after_debounce(cx);
    (view, cx, a)
}

#[gpui::test]
async fn a_conflict_asks_and_cancel_keeps_both_sides(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("conflict-a"), TempDir::new("conflict-b"));
    let (view, cx, _a) = conflicting_machines(cx, &server, &machine_a, &machine_b);
    assert!(
        sync_conflict_open(&view, cx),
        "both sides changed, so the window asks"
    );
    assert!(cx.debug_bounds("sync.conflict.dialog").is_some());
    assert_eq!(cloud_host_names(&server), vec!["alpha", "from-a"]);

    click(cx, "sync.conflict.cancel");
    assert!(!sync_conflict_open(&view, cx));
    assert_eq!(
        host_names(&view, cx),
        vec!["alpha"],
        "nothing local was replaced"
    );
    assert_eq!(
        cloud_host_names(&server),
        vec!["alpha", "from-a"],
        "nothing in the cloud was replaced"
    );
    assert_eq!(sync_marker(&view, cx), Some("conflict"));
    assert!(cx.debug_bounds("topbar.sync").is_some());

    // An automatic check does not ask again while the conflict is put away...
    after_poll(cx);
    assert!(!sync_conflict_open(&view, cx));
    // ...and the settings page asks again on request.
    click(cx, "settings.category.sync");
    click(cx, "settings.sync.conflict");
    assert!(sync_conflict_open(&view, cx));
    // Escape is the same as cancel.
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!sync_conflict_open(&view, cx));
    assert_eq!(host_names(&view, cx), vec!["alpha"]);
    assert_eq!(cloud_host_names(&server), vec!["alpha", "from-a"]);
}

#[gpui::test]
async fn only_connecting_here_merges_with_the_cloud_without_asking(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("merge-a"), TempDir::new("merge-b"));
    seed(
        &machine_a.store(),
        vec![
            stored_host("alpha", "10.0.0.1", 22, "root", None),
            stored_host("beta", "10.0.0.2", 22, "root", None),
        ],
    );
    let a = other_machine(&machine_a, &server);
    let _ = a.sync().expect("A uploads");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(&machine_b, &secrets, &server, true);
    let (view, cx) = sync_window(cx, &machine_b, &secrets, Destination::Hosts);
    assert_eq!(host_names(&view, cx), vec!["alpha", "beta"]);

    // A adds a host and uploads; B meanwhile only connects to alpha.
    let store_a = machine_a.store();
    let mut book_a = store_a.load().expect("A's hosts read");
    book_a
        .insert(stored_host("from-a", "10.0.0.7", 22, "root", None))
        .expect("inserted");
    store_a.save(&book_a).expect("saved");
    let _ = a.sync().expect("A uploads its change");
    let alpha = first_host_id(&view, cx);
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            assert!(view.record_host_connection(alpha, 1_800_000_000, cx));
        });
    });
    cx.run_until_parked();
    after_debounce(cx);

    assert!(
        !sync_conflict_open(&view, cx),
        "only connecting here is no conflict"
    );
    assert_eq!(sync_marker(&view, cx), None);
    assert_eq!(
        host_names(&view, cx),
        vec!["alpha", "beta", "from-a"],
        "A's host is listed without a restart"
    );
    let recent = |book: &HostBook| {
        book.recent_of(alpha)
            .map(shellune_storage::RecentConnection::last_connected_unix)
    };
    assert_eq!(
        cx.update(|_window, app| recent(view.read(app).book())),
        Some(1_800_000_000),
        "B's connection is still listed"
    );
    assert_eq!(
        recent(&machine_b.store().load().expect("B's hosts read")),
        Some(1_800_000_000)
    );
    assert_eq!(
        recent(cloud_document(&server).shared().hosts()),
        Some(1_800_000_000),
        "and it reached the cloud"
    );
    assert!(
        shellune_storage::SnapshotStore::at(machine_b.path())
            .list()
            .iter()
            .any(|snapshot| snapshot.reason().starts_with("sync-merge")),
        "the data replaced here was copied aside first"
    );
    // A takes B's connection on its next sync, and nothing is sent back again.
    assert!(matches!(
        a.sync().expect("A syncs"),
        shellune_sync::SyncOutcome::Pulled(_)
    ));
    assert_eq!(
        recent(&machine_a.store().load().expect("A's hosts read")),
        Some(1_800_000_000)
    );
    let puts = put_count(&server);
    after_poll(cx);
    assert_eq!(put_count(&server), puts);
    assert_eq!(sync_progress(&view, cx).2, None);
}

