/// The one tab of a compact row - 720x480 at 115% text - shows at least four letters of
/// its name: its close button gives the title its room and shows under the pointer
/// (T9, R2).
#[gpui::test]
async fn the_one_compact_tab_shows_four_letters_of_its_name(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.workspace_mut_for_test().set_zoom(Zoom::Comfortable);
            cx.notify();
        });
    });
    cx.simulate_resize(compact_window());
    cx.run_until_parked();
    redraw(cx);
    assert!(cx.update(|_window, app| view.read(app).header_compact_for_test()));
    let title = cx.update(|_window, app| view.read(app).tab_title_for_test(id));
    let index = cx
        .update(|_window, app| view.read(app).open_tabs())
        .iter()
        .position(|open| *open == id)
        .expect("the session has a tab");
    assert_eq!(index, 0, "the session's tab is the first");
    let four: String = title.chars().take(4).chain(['\u{2026}']).collect();
    let need = cx.update(|window, app| {
        let metrics = view.read(app).workspace().metrics();
        crate::app::view::tab_title_width(window, &four, metrics)
    });
    let label = bounds_of(cx, "session.tab.title.0");
    let tab = bounds_of(cx, "session.tab.0");
    assert!(
        label.size.width + px(2.0) >= need,
        "the title {title:?} shows less than {four:?} ({need:?}): {label:?} in {tab:?}"
    );
    assert!(
        label.right() <= tab.right() + px(0.5),
        "the title stays inside its tab"
    );
    // The close is still the tab's own target under the pointer.
    let close = bounds_of(cx, "session.tab.close.0");
    assert!(
        close.left() >= tab.left() && close.right() <= tab.right() + px(0.5),
        "{close:?} in {tab:?}"
    );
    assert!(close.size.width >= px(theme::HIT_TARGET) - px(0.5));
}

/// A reason as long as the ones a shell or a jump host really reports: one unbroken
/// path, then a sentence.
const LONG_LOSS: &str = concat!(
    r"C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe exited because the pipe ",
    r"C:\Users\someone\AppData\Local\Temp\shellune-pty-0123456789abcdef was closed"
);

/// Ends the terminal of `id` with `reason`, the way a shell that stopped or a
/// connection that dropped reaches its pane.
fn lose_pane_with(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    id: SessionId,
    reason: &str,
) {
    let pane = cx
        .update(|_window, app| view.read(app).pane_of(id).cloned())
        .expect("the session has a terminal");
    let tag = cx.update(|_window, app| pane.read(app).tag());
    cx.update(|_window, app| {
        pane.update(app, |pane, cx| {
            pane.adopt_events(tag, vec![SourceEvent::Lost(reason.to_owned())], cx);
        });
    });
    cx.run_until_parked();
    assert!(matches!(
        session_state(cx, view, id),
        Some(SessionState::Disconnected(_))
    ));
}

/// Whether a control of the session bar is on the bar's one line, beside where the
/// session is, rather than wrapped onto the hidden line under it.
fn on_the_line(control: gpui::Bounds<Pixels>, context: gpui::Bounds<Pixels>) -> bool {
    let centre = control.center().y;
    centre >= context.origin.y && centre <= context.origin.y + context.size.height
}

/// Whether `inner` lies wholly inside `outer`, to half a pixel.
fn wholly_inside(inner: gpui::Bounds<Pixels>, outer: gpui::Bounds<Pixels>) -> bool {
    inner.size.width > px(0.0)
        && inner.size.height > px(0.0)
        && inner.origin.x >= outer.origin.x - px(0.5)
        && inner.origin.y >= outer.origin.y - px(0.5)
        && inner.origin.x + inner.size.width <= outer.origin.x + outer.size.width + px(0.5)
        && inner.origin.y + inner.size.height <= outer.origin.y + outer.size.height + px(0.5)
}

/// A local shell that ended - its target a full path, the default session of the app -
/// states it in a banner above its terminal in `split`, at the design size and at
/// 720x480 and 115%; the banner's Reconnect restarts it in place (ADR-6, R8, R9).
fn an_ended_shell_card_reaches_its_step(cx: &mut TestAppContext, split: Option<SplitAxis>) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    if cx.update(|_window, app| view.read(app).workspace().shells().is_empty()) {
        return;
    }
    while cx.update(|_window, app| view.read(app).workspace().motion()) != Motion::Reduced {
        cx.update(|_window, app| view.update(app, |view, cx| view.cycle_motion(cx)));
        cx.run_until_parked();
    }
    new_default_shell(cx);
    if let Some(axis) = split {
        cx.update(|window, app| {
            view.update(app, |view, cx| view.split_active_for_test(axis, window, cx));
        });
        cx.run_until_parked();
    }
    let id = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("a shell is on screen");
    let tabs = cx.update(|_window, app| view.read(app).open_tabs().len());
    let others: Vec<SessionId> = cx
        .update(|_window, app| view.read(app).active_leaf_sessions_for_test())
        .into_iter()
        .flatten()
        .filter(|other| *other != id)
        .collect();
    lose_pane_with(&view, cx, id, LONG_LOSS);

    let layout = format!("{split:?}");
    for (what, small) in [("at the design size", false), ("at 720x480 and 115%", true)] {
        if small {
            cx.simulate_resize(narrow_window());
            largest_text_size(&view, cx);
            cx.run_until_parked();
        }
        let viewport = cx.update(|window, _app| window.viewport_size());
        let banner = bounds_of(cx, "terminal.failure");
        let grid = bounds_of(cx, "terminal.viewport");
        let bar = bounds_of(cx, "terminal.bar");
        assert!(
            banner.bottom() <= grid.top() + px(0.5) && grid.bottom() <= bar.top() + px(0.5),
            "{layout} {what}: banner, grid and bar stand one under the other: {banner:?} {grid:?} {bar:?}"
        );
        for selector in ["terminal.failure", "terminal.bar", "session.more"] {
            assert_fits_inside(bounds_of(cx, selector), viewport, selector);
        }
        let next = bounds_of(cx, "terminal.failure.next");
        // A stacked pane at 720x480 and 115% is too short for the whole line and the
        // bar: the line gives way and the bar, with its Reconnect and its menu, stays.
        let short = small && split == Some(SplitAxis::TopBottom);
        assert!(
            wholly_inside(next, banner) || short,
            "{layout} {what}: the step is whole on the banner: {next:?} in {banner:?}"
        );
        // The raw reason, unfolded, wraps at the banner's width and is no taller than
        // its box.
        if short {
            continue;
        }
        click(cx, "terminal.failure.details");
        let detail = bounds_of(cx, "terminal.failure.detail");
        let cap = crate::app::view::banner::DIAGNOSTIC_MAX_HEIGHT * if small { 2.0 } else { 1.0 };
        assert!(
            detail.size.width <= banner.size.width + px(0.5)
                && detail.size.height <= px(cap) + px(0.5),
            "{layout} {what}: the unfolded reason stays in its box: {detail:?}"
        );
        click(cx, "terminal.failure.details");
    }
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    click(cx, "terminal.failure.next");
    assert!(
        !matches!(
            session_state(cx, &view, id),
            Some(SessionState::Disconnected(_) | SessionState::Failed(_))
        ),
        "{layout}: pressing Reconnect starts the shell again"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).open_tabs().len()),
        tabs,
        "{layout}: the reconnect happens in the tab it was pressed in"
    );
    for other in others {
        assert_eq!(
            session_state(cx, &view, other),
            Some(SessionState::Connected),
            "{layout}: the other pane is left alone"
        );
    }
}

