/// A local shell split `axis`, at the design size with reduced motion, so bounds are
/// read where the cards stand. `None` on a machine with no local shell.
fn split_local_shell(
    cx: &mut TestAppContext,
    axis: SplitAxis,
) -> Option<(Entity<ShelluneView>, &mut VisualTestContext)> {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    if cx.update(|_window, app| view.read(app).workspace().shells().is_empty()) {
        return None;
    }
    while cx.update(|_window, app| view.read(app).workspace().motion()) != Motion::Reduced {
        cx.update(|_window, app| view.update(app, |view, cx| view.cycle_motion(cx)));
        cx.run_until_parked();
    }
    new_default_shell(cx);
    cx.update(|window, app| {
        view.update(app, |view, cx| view.split_active_for_test(axis, window, cx));
    });
    cx.run_until_parked();
    Some((view, cx))
}

/// The menu entry that stands in for a bar control the bar had no room for.
fn bar_entry_selector(control: &'static str) -> &'static str {
    match control {
        "session.reconnect" => "session.more.reconnect",
        "files.close" | "session.files" => "session.more.files",
        "pane.split.right" => "session.more.split_right",
        "pane.split.down" => "session.more.split_down",
        other => panic!("no menu entry is known for {other}"),
    }
}

/// In a side-by-side split of a narrow window at the largest text, the session's menu
/// stays on the bar's line, and every control of the session that the bar had no room
/// for is in that menu, where it still does what it does on the bar (R3, R9).
#[gpui::test]
async fn a_narrow_split_bar_keeps_the_session_menu_and_offers_what_it_hides_there(
    cx: &mut TestAppContext,
) {
    let Some((view, cx)) = split_local_shell(cx, SplitAxis::LeftRight) else {
        return;
    };
    let id = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("a shell is on screen");
    let pane = cx
        .update(|_window, app| view.read(app).pane_of(id).cloned())
        .expect("the active pane has a terminal");
    let hidden =
        |cx: &mut VisualTestContext| cx.update(|_window, app| pane.read(app).bar_hidden_controls());

    // With room, nothing is hidden and the menu holds only its own entries.
    assert_eq!(
        hidden(cx),
        0,
        "the design window has room for every control"
    );
    click(cx, "session.more");
    assert!(cx.debug_bounds("session.more.menu").is_some());
    for entry in [
        "session.more.split_right",
        "session.more.split_down",
        "session.more.reconnect",
    ] {
        assert!(
            cx.debug_bounds(entry).is_none(),
            "{entry} is on the bar, so the menu does not repeat it"
        );
    }
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).session_more_open()));

    // The window can be dragged narrower than the old 720 minimum, and the split keeps
    // half of it: 440 wide is where the pane's bar still has controls it cannot fit.
    cx.simulate_resize(tiny_window());
    largest_text_size(&view, cx);
    cx.run_until_parked();
    redraw(cx);
    cx.run_until_parked();

    let viewport = cx.update(|window, _app| window.viewport_size());
    let window = gpui::Bounds::new(point(px(0.0), px(0.0)), viewport);
    let context = bounds_of(cx, "session.context");
    let menu_button = bounds_of(cx, "session.more");
    let bar = bounds_of(cx, "terminal.bar");
    assert!(
        wholly_inside(menu_button, window)
            && wholly_inside(menu_button, bar)
            && on_the_line(menu_button, context),
        "the session's menu stays whole on the bar's line: {menu_button:?} in {bar:?}"
    );
    assert_pointer_target(cx, "session.more");

    // The controls that give way are the last ones; those still on the bar are whole
    // on its line.
    let left_out = cx.update(|_window, app| view.read(app).session_bar_hidden_for_test(id, app));
    assert_eq!(
        left_out.len(),
        hidden(cx),
        "the window and the pane agree on what the bar left out"
    );
    assert!(
        !left_out.is_empty(),
        "a narrow side-by-side pane has no room for every control"
    );
    assert!(
        left_out.contains(&"pane.split.down"),
        "the last control is the first to give way: {left_out:?}"
    );
    for selector in ["pane.split.right", "pane.split.down"] {
        if left_out.contains(&selector) {
            continue;
        }
        let bounds = bounds_of(cx, selector);
        assert!(
            wholly_inside(bounds, bar) && on_the_line(bounds, context),
            "{selector} is left on the bar, so it is whole on its line: {bounds:?} in {bar:?}"
        );
    }

    // Every one of them is in the menu, and the entry does what the control does.
    click(cx, "session.more");
    let menu = bounds_of(cx, "session.more.menu");
    assert_fits_inside(menu, viewport, "session.more.menu");
    for selector in &left_out {
        let entry = bar_entry_selector(selector);
        assert!(
            cx.debug_bounds(entry).is_some(),
            "{selector} is off the bar, so the menu offers {entry}"
        );
        assert_fits_inside(bounds_of(cx, entry), viewport, entry);
    }
    let leaves = cx.update(|_window, app| view.read(app).leaf_ids_for_test().len());
    click(cx, "session.more.split_down");
    assert!(
        !cx.update(|_window, app| view.read(app).session_more_open()),
        "a command closes the menu"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).leaf_ids_for_test().len()),
        leaves + 1,
        "the menu's split splits the active pane"
    );
}

/// The part of `inner` that lies inside `outer`.
fn overlap(inner: gpui::Bounds<Pixels>, outer: gpui::Bounds<Pixels>) -> gpui::Bounds<Pixels> {
    let left = inner.origin.x.max(outer.origin.x);
    let top = inner.origin.y.max(outer.origin.y);
    let right = (inner.origin.x + inner.size.width).min(outer.origin.x + outer.size.width);
    let bottom = (inner.origin.y + inner.size.height).min(outer.origin.y + outer.size.height);
    gpui::Bounds::new(
        point(left, top),
        size((right - left).max(px(0.0)), (bottom - top).max(px(0.0))),
    )
}

/// Turns the wheel over the part of the card that shows in its box, and returns where
/// the card was and where it is afterwards.
fn wheel_over_card(
    cx: &mut VisualTestContext,
    card_selector: &'static str,
    scroll_selector: &'static str,
) -> (gpui::Bounds<Pixels>, gpui::Bounds<Pixels>) {
    let card = bounds_of(cx, card_selector);
    let scroll = bounds_of(cx, scroll_selector);
    let shown = overlap(card, scroll);
    assert!(
        shown.size.height > px(8.0) && shown.size.width > px(8.0),
        "part of the card shows in its box: {card:?} in {scroll:?}"
    );
    cx.simulate_event(ScrollWheelEvent {
        position: shown.center(),
        delta: ScrollDelta::Pixels(point(px(0.0), px(-40.0))),
        ..Default::default()
    });
    cx.run_until_parked();
    (card, bounds_of(cx, card_selector))
}

/// A session with no terminal in a short pane - a stacked split at 720x480 and 115% -
/// shows its card from the top, inside the pane, and the wheel over the card scrolls
/// the rest into view (R3, R9).
#[gpui::test]
async fn a_state_card_in_a_short_pane_starts_at_its_top_and_scrolls_under_the_wheel(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("state-card-short-pane");
    let (view, cx, left, remember) = connected_remote_tab(cx, &dir, X11Forwarding::Off, Vec::new());
    while cx.update(|_window, app| view.read(app).workspace().motion()) != Motion::Reduced {
        cx.update(|_window, app| view.update(app, |view, cx| view.cycle_motion(cx)));
        cx.run_until_parked();
    }
    cx.update(|window, app| {
        view.update(app, |view, cx| {
            view.split_active_for_test(SplitAxis::TopBottom, window, cx);
        });
    });
    cx.run_until_parked();
    let waiting = cx
        .update(|_window, app| {
            let view = view.read(app);
            view.leaf_ids_for_test().into_iter().find(|pane| {
                view.leaf_snapshot_for_test(*pane)
                    .is_some_and(|(pending, _, _)| pending)
            })
        })
        .expect("the split made a waiting pane");
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.connect_leaf_for_test(waiting, cx));
    });
    cx.run_until_parked();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.script_remote_attempt(
                vec![
                    shellune_ssh::RemoteEvent::Connected,
                    shellune_ssh::RemoteEvent::Data(b"lower process\r\n$ ".to_vec()),
                ],
                cx,
            );
            view.pump_remote_once(cx);
        });
    });
    cx.run_until_parked();
    let lower = cx
        .update(|_window, app| view.read(app).leaf_snapshot_for_test(waiting))
        .and_then(|(_, _, session)| session)
        .expect("the waiting pane adopted its session");

    // The upper pane loses its server and dials again; while it dials it has no
    // terminal, so its pane shows the session's card. The lower pane is the active one.
    lose_remote_session(&view, cx, left);
    remember();
    cx.update(|_window, app| view.update(app, |view, cx| view.activate(left, cx)));
    cx.run_until_parked();
    cx.simulate_keystrokes(&reconnect_keystroke());
    cx.run_until_parked();
    assert_eq!(
        session_state(cx, &view, left),
        Some(SessionState::Connecting)
    );
    assert!(cx.update(|_window, app| view.read(app).pane_of(left).is_none()));
    hold_reconnect(&view, cx, left);
    // The kept last screen would stand in the card's place (ADR-6); this test is about
    // the card of a session that has nothing to show.
    cx.update(|_window, app| {
        view.update(app, |view, _cx| view.forget_reconnect_screen_for_test(left))
    });
    cx.update(|_window, app| view.update(app, |view, cx| view.activate(lower, cx)));
    cx.run_until_parked();

    // Shorter than the compact window: the pane the card is drawn in has to be
    // shorter than the card for the card to be read by turning.
    cx.simulate_resize(size(px(520.0), px(340.0)));
    largest_text_size(&view, cx);
    cx.run_until_parked();

    // A start that comes up inside the floor draws no card; this one is still
    // connecting a moment later, so the card appears once the floor has passed.
    assert!(
        cx.debug_bounds("session.state.card").is_none(),
        "a just-started connection draws no state card"
    );
    wait_for_loading_card(cx);

    let viewport = cx.update(|window, _app| window.viewport_size());
    let window = gpui::Bounds::new(point(px(0.0), px(0.0)), viewport);
    let floor = bounds_of(cx, "pane.state");
    let scroll = bounds_of(cx, "pane.state.scroll");
    let card = bounds_of(cx, "session.state.card");
    let headline = bounds_of(cx, "session.state.headline");
    assert!(
        wholly_inside(scroll, floor) && wholly_inside(floor, window),
        "the card's box is held inside its pane: {scroll:?} in {floor:?}"
    );
    assert!(
        card.size.height > scroll.size.height,
        "the card is taller than the short pane: {card:?} in {scroll:?}"
    );
    assert!(
        card.origin.y >= scroll.origin.y - px(0.5) && wholly_inside(headline, scroll),
        "the card opens on its headline, nothing of it above the pane: {headline:?} in {scroll:?}"
    );
    let (before, after) = wheel_over_card(cx, "session.state.card", "pane.state.scroll");
    assert!(
        after.origin.y < before.origin.y - px(1.0),
        "the wheel over the card scrolls the card: {before:?} then {after:?}"
    );
}

#[gpui::test]
async fn the_host_dialog_is_the_shared_dialog_and_keeps_its_actions_in_the_narrow_window(
    cx: &mut TestAppContext,
) {
    let (view, cx, _dir) = dialog_view(cx, Vec::new());
    click(cx, "hosts.new");
    cx.simulate_resize(narrow_window());
    largest_text_size(&view, cx);
    let viewport = cx.update(|window, _app| window.viewport_size());

    // The form is drawn in the shared dialog: a dimmed page, a fixed header, a body
    // that scrolls and a fixed row of actions (R5).
    assert!(
        cx.debug_bounds("hosts.editor.backdrop").is_some(),
        "the host form dims the page behind it"
    );
    assert!(cx.debug_bounds("hosts.editor.body").is_some());
    let dialog = bounds_of(cx, "hosts.editor");
    assert_within_width(dialog, viewport, "the host dialog");
    assert!(
        dialog.origin.y >= px(-0.5)
            && dialog.origin.y + dialog.size.height <= viewport.height + px(0.5),
        "the host dialog leaves the window vertically: {dialog:?} in {viewport:?}"
    );
    for action in ["hosts.cancel", "hosts.save", "hosts.save_connect"] {
        let bounds = bounds_of(cx, action);
        assert_inside_box(bounds, dialog, action);
        assert!(
            bounds.origin.y + bounds.size.height <= dialog.origin.y + dialog.size.height + px(0.5),
            "{action} is drawn below the dialog: {bounds:?} in {dialog:?}"
        );
    }
    let cancel = bounds_of(cx, "hosts.cancel");
    let connect = bounds_of(cx, "hosts.save_connect");
    assert!(
        connect.origin.x > cancel.origin.x || connect.origin.y > cancel.origin.y,
        "the primary action is the last one: cancel {cancel:?}, connect {connect:?}"
    );

    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).hosts_state().is_editing()),
        "Escape still closes the dialog without saving"
    );
    assert!(cx.update(|_window, app| view.read(app).book().hosts().is_empty()));
}

#[gpui::test]
async fn a_settings_switch_is_one_pointer_target_that_flips_its_setting(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    show_settings_at_the_minimum_window_in_large_text(&view, cx);
    click(cx, "settings.category.notices");
    click(cx, "settings.item.bell-notice");
    scroll_fully_into_view(cx, "settings.scroll", "settings.notice.bell");

    // One switch, with its state written beside it, and a target a finger can hit at the
    // largest text (R5, R9).
    let switch = bounds_of(cx, "settings.notice.bell");
    assert!(
        switch.size.width >= px(24.0) && switch.size.height >= px(24.0),
        "the switch is smaller than a 24px pointer target: {switch:?}"
    );
    assert!(
        cx.debug_bounds("settings.notice.bell.state").is_some(),
        "the switch says its state in words as well"
    );
    let bell = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| view.read(app).workspace().attention_settings().bell)
    };
    let before = bell(cx);
    click(cx, "settings.notice.bell");
    assert_eq!(bell(cx), !before, "a press flips the setting");
    click(cx, "settings.notice.bell");
    assert_eq!(bell(cx), before, "and a second press flips it back");
}

#[gpui::test]
async fn the_shortcut_capture_is_the_shared_dialog_and_a_press_outside_cancels_it(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(tall_window());
    cx.run_until_parked();
    click(cx, "nav.settings");
    click(cx, "settings.category.keys");
    click(cx, "settings.keys.change.nav.settings");

    // The capture is drawn in the shared dialog, over a dimmed window (R5).
    assert!(cx.debug_bounds("keys.capture").is_some());
    assert!(
        cx.debug_bounds("keys.capture.dialog.backdrop").is_some(),
        "the capture dims the window behind it"
    );
    let dialog = bounds_of(cx, "keys.capture.dialog");
    assert_inside_box(
        bounds_of(cx, "keys.capture.cancel"),
        dialog,
        "keys.capture.cancel",
    );

    // Nothing typed can be lost here, so a press on the dimmed window outside the
    // dialog is a way out, as it was before, and the binding is untouched.
    let corner = point(
        dialog.origin.x / 2.0,
        dialog.origin.y + dialog.size.height / 2.0,
    );
    cx.simulate_click(corner, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).capturing_for()),
        None,
        "a press outside the dialog cancels the capture"
    );
    assert_eq!(
        cx.update(|_window, app| view
            .read(app)
            .keymap()
            .keystroke("nav.settings")
            .map(str::to_owned)),
        Keymap::defaults(Platform::current())
            .keystroke("nav.settings")
            .map(str::to_owned),
        "cancelling leaves the binding as it was"
    );
}

/// Sets the window's motion preference to `motion`, by the same step the settings use.
fn motion_to(view: &Entity<ShelluneView>, cx: &mut VisualTestContext, motion: Motion) {
    while cx.update(|_window, app| view.read(app).workspace().motion()) != motion {
        cx.update(|_window, app| view.update(app, |view, cx| view.cycle_motion(cx)));
        cx.run_until_parked();
    }
}

#[gpui::test]
async fn closing_a_dialog_clears_the_scrim_before_the_next_action(cx: &mut TestAppContext) {
    use crate::app::theme::ThemeChoice;

    let dir = TempDir::new("dialog-scrim");
    let store = dir.store();
    seed(
        &store,
        vec![stored_host("web", "10.0.0.5", 22, "deploy", None)],
    );
    let (view, cx) = hosts_view(cx, store);
    for (choice, motion) in [
        (ThemeChoice::Light, Motion::Full),
        (ThemeChoice::Dark, Motion::Full),
        (ThemeChoice::Dark, Motion::Reduced),
    ] {
        while cx.update(|_, app| view.read(app).theme_choice()) != choice {
            cx.update(|_, app| view.update(app, |view, cx| view.cycle_theme(cx)));
        }
        motion_to(&view, cx, motion);
        for open in ["hosts.delete.0", "hosts.new"] {
            click(cx, open);
            let viewport = cx.update(|window, _| window.viewport_size());
            assert_eq!(bounds_of(cx, "modal.scrim").size, viewport);
            crate::app::view::take_frame_marks();
            cx.simulate_keystrokes("escape");
            cx.run_until_parked();
            let frames = crate::app::view::take_frame_marks();
            assert!(!frames.is_empty());
            assert!(frames.iter().all(|frame| !frame.dimmed));
            assert!(cx.debug_bounds("modal.scrim.exit").is_none());
        }
    }
    motion_to(&view, cx, Motion::Full);
}

#[gpui::test]
async fn a_delete_question_keeps_every_key_but_escape(cx: &mut TestAppContext) {
    let dir = TempDir::new("question-keys");
    seed(
        &dir.store(),
        vec![
            stored_host("web", "10.0.0.5", 22, "deploy", None),
            stored_host("db", "10.0.0.9", 22, "postgres", None),
        ],
    );
    let (view, cx) = hosts_view_with_trust(cx, &dir);
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    // The language shortcut this platform binds: Ctrl+L on Windows and Linux, Cmd+L on
    // macOS, where Ctrl+L is no shortcut at all and the last step could not pass.
    let language = Keymap::defaults(Platform::current())
        .keystroke("language.toggle")
        .expect("the language has a default shortcut")
        .to_owned();
    type_into(cx, "hosts.search", "db");
    let search = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| view.read(app).hosts_state().search().to_owned())
    };
    assert_eq!(search(cx), "db");

    // The question is asked while the search field still holds the keyboard.
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            let id = view.book().hosts()[1].id();
            view.request_delete_host_for_test(id, cx);
        });
    });
    cx.run_until_parked();
    assert!(cx.debug_bounds("hosts.confirm").is_some());

    // Enter behind the question would connect the match the user cannot see; typed
    // text would change the search under it; a shortcut would act behind it. All of
    // them are spent on the question, which stays open (R5).
    cx.simulate_keystrokes("enter");
    cx.simulate_keystrokes("x");
    cx.simulate_keystrokes(&language);
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).remote_state().is_none()),
        "Enter behind the question connects nothing"
    );
    assert_eq!(
        search(cx),
        "db",
        "typed text does not reach the field behind"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().locale()),
        Locale::English,
        "no shortcut runs behind the question"
    );
    assert!(
        cx.update(|_window, app| view.read(app).question_open()),
        "only an answer closes the question"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).book().hosts().len()),
        2,
        "no key deletes anything"
    );

    // Escape is the way out, and the keys belong to the page again after it.
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).question_open()));
    assert_eq!(
        cx.update(|_window, app| view.read(app).book().hosts().len()),
        2
    );
    cx.simulate_keystrokes(&language);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().locale()),
        Locale::Chinese,
        "shortcuts run again once the question is answered"
    );
}

