/// The host dialog's form is a two-column grid that becomes one column when the
/// dialog is narrow: the address and its port side by side in a wide window, under
/// each other in a narrow one, and neither field squeezed below its floor (ADR-7).
#[gpui::test]
async fn the_host_form_is_two_columns_wide_and_one_column_narrow(cx: &mut TestAppContext) {
    let (view, cx, _dir) = dialog_view(cx, Vec::new());
    click(cx, "hosts.new");
    let address = bounds_of(cx, "hosts.field.address");
    let port = bounds_of(cx, "hosts.field.port");
    assert!(
        (address.top() - port.top()).abs() <= px(0.5) && port.left() > address.right(),
        "the port sits beside the address in a wide dialog: {address:?} {port:?}"
    );
    assert!(
        address.size.width > port.size.width,
        "the address takes the larger share"
    );
    let name = bounds_of(cx, "hosts.field.name");
    let group = bounds_of(cx, "hosts.field.group");
    assert!(
        (name.top() - group.top()).abs() <= px(0.5),
        "the name and the group share a row"
    );

    // Narrower than a window at which two columns still fit the dialog.
    cx.simulate_resize(tiny_window());
    largest_text_size(&view, cx);
    let dialog = bounds_of(cx, "hosts.editor");
    let address = bounds_of(cx, "hosts.field.address");
    let port = bounds_of(cx, "hosts.field.port");
    assert!(
        port.top() >= address.bottom() - px(0.5),
        "the port moves under the address in a narrow dialog: {address:?} {port:?}"
    );
    for (field, bounds) in [("address", address), ("port", port)] {
        assert!(
            bounds.left() >= dialog.left() - px(0.5) && bounds.right() <= dialog.right() + px(0.5),
            "the {field} field stays inside the dialog: {bounds:?} in {dialog:?}"
        );
    }
    // The folded part stays folded: one line under the form, its body not drawn.
    assert!(cx.debug_bounds("hosts.advanced").is_some());
    assert!(cx.debug_bounds("hosts.advanced.body").is_none());
}

/// The host form is titled groups, one under the other: where and who, then how to
/// sign in, then the folded advanced part, which opens as one group per subject -
/// the route, the startup command, transfers, X11 and keepalive - each holding its
/// own fields (ADR-7, T8).
#[gpui::test]
async fn the_host_form_is_titled_groups_and_advanced_opens_one_group_per_subject(
    cx: &mut TestAppContext,
) {
    let (_view, cx, _dir) = dialog_view(cx, Vec::new());
    click(cx, "hosts.new");
    let inside = |outer: gpui::Bounds<Pixels>, inner: gpui::Bounds<Pixels>| {
        inner.left() >= outer.left() - px(0.5)
            && inner.right() <= outer.right() + px(0.5)
            && inner.top() >= outer.top() - px(0.5)
            && inner.bottom() <= outer.bottom() + px(0.5)
    };
    let basic = bounds_of(cx, "hosts.group.basic");
    for field in [
        "hosts.field.address",
        "hosts.field.port",
        "hosts.field.user",
        "hosts.field.name",
        "hosts.field.group",
    ] {
        assert!(
            inside(basic, bounds_of(cx, field)),
            "{field} is a basic field"
        );
    }
    let auth = bounds_of(cx, "hosts.group.auth");
    assert!(auth.top() >= basic.bottom(), "sign-in follows the basics");
    assert!(inside(auth, bounds_of(cx, "hosts.auth")));
    let toggle = bounds_of(cx, "hosts.advanced");
    assert!(
        toggle.top() >= auth.bottom(),
        "the advanced line follows sign-in"
    );
    assert!(
        cx.debug_bounds("hosts.group.route").is_none(),
        "the advanced groups are folded away at first"
    );

    scroll_into_view(cx, "hosts.editor.body", "hosts.advanced");
    click(cx, "hosts.advanced");
    let mut above = bounds_of(cx, "hosts.advanced");
    for (group, holds) in [
        ("hosts.group.route", "hosts.jump"),
        ("hosts.group.startup", "hosts.field.startup"),
        ("hosts.group.transfer", "hosts.editor.protocol"),
        ("hosts.group.x11", "hosts.editor.x11"),
        ("hosts.group.keepalive", "hosts.editor.connection"),
    ] {
        let bounds = bounds_of(cx, group);
        assert!(
            bounds.top() >= above.bottom(),
            "{group} is under the one before it"
        );
        assert!(
            inside(bounds, bounds_of(cx, holds)),
            "{group} holds {holds}"
        );
        above = bounds;
    }
}

/// The settings navigation is a column of navigation entries a control high, the
/// chosen one ringed only for the keyboard, and the page heading is the heading size
/// (ADR-7).
#[gpui::test]
async fn the_settings_navigation_is_a_column_of_entries_beside_the_cards(cx: &mut TestAppContext) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    click(cx, "nav.settings");
    let metrics = cx.update(|_window, app| view.read(app).workspace().metrics());
    let nav = bounds_of(cx, "settings.nav");
    let mut above: Option<gpui::Bounds<Pixels>> = None;
    for category in [
        "settings.category.appearance",
        "settings.category.terminal",
        "settings.category.connection",
        "settings.category.keys",
        "settings.category.about",
    ] {
        let bounds = bounds_of(cx, category);
        assert!(
            bounds.size.height + px(0.5) >= metrics.control_height(),
            "{category} is a control high"
        );
        assert!(bounds.left() >= nav.left() && bounds.right() <= nav.right() + px(0.5));
        if let Some(above) = above {
            assert!(
                bounds.top() >= above.top(),
                "{category} is under the one before it"
            );
        }
        above = Some(bounds);
    }
    // The page of the chosen category is beside the column, not under it.
    let card = bounds_of(cx, "settings.card.theme");
    assert!(
        card.left() > nav.right(),
        "the cards stand beside the navigation"
    );
    // The pages of the open category are listed under it, indented to its words.
    let category = bounds_of(cx, "settings.category.appearance");
    let item = bounds_of(cx, "settings.item.language");
    assert!(item.top() >= category.bottom() - px(0.5));
}

/// A batch dialog's actions stay at its right edge, the primary one last, when its
/// note takes the room beside them and they move to a line of their own (ADR-7).
#[gpui::test]
async fn the_batch_actions_stay_on_the_right_of_their_footer(cx: &mut TestAppContext) {
    let dir = TempDir::new("batch-footer");
    seed(&dir.store(), batch_hosts());
    let (view, cx) = hosts_view(cx, dir.store());
    preview_batch(cx, &view, 2);
    write_commands(cx, &["uptime"]);
    let dialog = bounds_of(cx, "batch.dialog");
    let confirm = bounds_of(cx, "batch.preview.confirm");
    let cancel = bounds_of(cx, "batch.preview.cancel");
    let note = bounds_of(cx, "batch.footer.note");
    let metrics = cx.update(|_window, app| view.read(app).workspace().metrics());
    let pad = metrics.scale(theme::spacing::LOOSE);
    assert!(
        (dialog.right() - pad - confirm.right()).abs() <= px(1.0),
        "the primary action is at the right edge: {confirm:?} in {dialog:?}"
    );
    assert!(
        cancel.right() <= confirm.left(),
        "cancel is left of the primary action"
    );
    assert!(note.left() < cancel.left(), "the note is at the left");

    // In the smallest window at the largest text the actions wrap under the note and
    // still end at the right edge.
    cx.simulate_resize(narrow_window());
    largest_text_size(&view, cx);
    let dialog = bounds_of(cx, "batch.dialog");
    let confirm = bounds_of(cx, "batch.preview.confirm");
    let pad = cx
        .update(|_window, app| view.read(app).workspace().metrics())
        .scale(theme::spacing::LOOSE);
    assert!(
        (dialog.right() - pad - confirm.right()).abs() <= px(1.0),
        "the primary action stays at the right edge when the footer wraps: {confirm:?} in {dialog:?}"
    );
}

/// One dialog, whichever protocol it asks for (R7).
///
/// The dialog's entrance is a fade with an eight-pixel settle, keyed by the modal's id.
/// With one id per protocol the entrance replayed on every switch between SSH and
/// another protocol: the dialog went transparent and jumped, which over a window-sized
/// dialog is the whole window flashing. This measures both halves instead of
/// photographing them - a frame log for "no frame without the dialog", and the
/// dialog's own place for "no replay" - and the name, group, list and keyboard that a
/// switch must carry over.
#[gpui::test]
async fn switching_protocols_keeps_the_open_dialog_in_place(cx: &mut TestAppContext) {
    let (view, cx, _dir) = dialog_view(
        cx,
        vec![stored_host("edge", "10.0.0.7", 22, "deploy", Some("Prod"))],
    );
    click(cx, "hosts.new");
    cx.run_until_parked();
    type_into(cx, "hosts.field.name", "kept name");
    type_into(cx, "hosts.field.group", "Prod");
    let settle = |cx: &mut VisualTestContext| {
        cx.executor()
            .advance_clock(std::time::Duration::from_secs(1));
        redraw(cx);
        cx.run_until_parked();
    };
    settle(cx);
    // What the switch must leave alone: the page under the dialog.
    let row = bounds_of(cx, "hosts.row.0");
    let search = bounds_of(cx, "hosts.search");
    crate::app::view::take_frame_marks();

    for (protocol, selector) in [
        ("rdp", "connection.protocol.rdp"),
        ("vnc", "connection.protocol.vnc"),
        ("ssh", "connection.protocol.ssh"),
    ] {
        click(cx, selector);
        let first = open_form_bounds(cx);
        assert!(
            form_backdrop_drawn(cx),
            "the dimming stays with the dialog through the switch to {protocol}"
        );
        assert_eq!(
            bounds_of(cx, "hosts.row.0"),
            row,
            "the host list under the dialog does not move when the form becomes {protocol}"
        );
        assert_eq!(
            bounds_of(cx, "hosts.search"),
            search,
            "the page above the list does not move when the form becomes {protocol}"
        );
        assert_frames_of_a_switch(&crate::app::view::take_frame_marks(), protocol);

        // What a switch keeps: the name and group already typed.
        assert_eq!(
            typed_form_text(&view, cx),
            ("kept name".to_owned(), "Prod".to_owned())
        );

        // What a switch must not do: replay the entrance. A replayed fade starts the
        // dialog eight pixels above where it settles and wholly transparent.
        settle(cx);
        let settled = open_form_bounds(cx);
        assert!(
            (first.origin.y - settled.origin.y).abs() <= px(0.5),
            "the dialog replays its entrance on the switch to {protocol}: {first:?} then {settled:?}"
        );
    }

    // The keyboard follows the form: after a switch, typing reaches the new form's first
    // field rather than a field of the form that is gone.
    click(cx, "connection.protocol.rdp");
    settle(cx);
    cx.simulate_keystrokes("1");
    cx.simulate_keystrokes("0");
    cx.run_until_parked();
    assert_eq!(
        addressed_text(&view, cx),
        "10",
        "the keyboard is in the address of the form that is open"
    );

    // The entrance is still played when the form opens: what was wrong was replaying it
    // on a switch, not the dialog arriving.
    click(cx, "connection.cancel");
    click(cx, "connection.discard.ok");
    settle(cx);
    click(cx, "hosts.new");
    let arriving = open_form_bounds(cx);
    settle(cx);
    let arrived = open_form_bounds(cx);
    assert!(
        arriving.origin.y < arrived.origin.y,
        "the dialog still settles into place when it opens: {arriving:?} then {arrived:?}"
    );
}

/// Every frame a protocol switch drew that had a form open drew exactly that form's
/// dialog and its dimming, and the switch ended on the form it asked for (R7).
fn assert_frames_of_a_switch(marks: &[crate::app::view::FrameMarks], protocol: &str) {
    let mut seen = 0;
    for mark in marks {
        if !mark.form_open {
            continue;
        }
        seen += 1;
        assert!(
            mark.dimmed,
            "a frame with the form open was drawn without its dimming: {mark:?}"
        );
        assert_eq!(
            u8::from(mark.host_dialog) + u8::from(mark.connection_dialog),
            1,
            "a frame with the form open drew the wrong number of dialogs: {mark:?}"
        );
        match mark.form_protocol {
            Some("ssh") => assert!(
                mark.host_dialog,
                "the SSH form is drawn in its dialog: {mark:?}"
            ),
            Some(_) => assert!(
                mark.connection_dialog,
                "another protocol's form is drawn in the same dialog: {mark:?}"
            ),
            None => panic!("a frame drew a dialog with no form open: {mark:?}"),
        }
    }
    assert!(seen > 0, "the switch drew no frame with the form open");
    let last = marks
        .iter()
        .rev()
        .find(|mark| mark.form_open)
        .expect("a frame with the form open");
    assert_eq!(
        last.form_protocol,
        Some(protocol),
        "the switch ends on the form it asked for"
    );
}

/// The bounds of the open host form's dialog, whichever modal it is drawn in.
fn open_form_bounds(cx: &mut VisualTestContext) -> gpui::Bounds<Pixels> {
    cx.debug_bounds("hosts.editor")
        .or_else(|| cx.debug_bounds("connection.editor"))
        .expect("the host form is drawn")
}

/// Whether the dialog's dimming was drawn with it.
fn form_backdrop_drawn(cx: &mut VisualTestContext) -> bool {
    cx.debug_bounds("hosts.editor.backdrop").is_some()
        || cx.debug_bounds("connection.editor.backdrop").is_some()
}

/// The name and group the open form holds, whichever protocol it is for.
fn typed_form_text(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> (String, String) {
    cx.update(|_window, app| {
        let state = view.read(app).hosts_state();
        match (state.draft(), state.protocol_draft()) {
            (Some(draft), _) => (
                draft.text(crate::app::hosts::HostField::Name).to_owned(),
                draft.text(crate::app::hosts::HostField::Group).to_owned(),
            ),
            (_, Some(draft)) => (
                draft
                    .text(crate::app::hosts::ConnectionFormField::Name)
                    .to_owned(),
                draft
                    .text(crate::app::hosts::ConnectionFormField::Group)
                    .to_owned(),
            ),
            (None, None) => panic!("no form is open"),
        }
    })
}

/// The address the open protocol form holds.
fn addressed_text(view: &Entity<ShelluneView>, cx: &mut VisualTestContext) -> String {
    cx.update(|_window, app| {
        view.read(app)
            .hosts_state()
            .protocol_draft()
            .map(|draft| {
                draft
                    .text(crate::app::hosts::ConnectionFormField::Address)
                    .to_owned()
            })
            .expect("a protocol form is open")
    })
}

#[gpui::test]
async fn non_ssh_dialog_save_and_connect_order_and_validation_failure(cx: &mut TestAppContext) {
    let dir = TempDir::new("non-ssh-save-connect-validation");
    let (view, cx) = hosts_view(cx, dir.store());
    cx.simulate_resize(size(px(1400.0), px(1000.0)));
    cx.run_until_parked();

    click(cx, "hosts.new");
    for protocol in [
        "connection.protocol.rdp",
        "connection.protocol.vnc",
        "connection.protocol.serial",
    ] {
        click(cx, protocol);
        redraw(cx);
        let dialog = bounds_of(cx, "hosts.editor");
        let cancel = bounds_of(cx, "connection.cancel");
        let save = bounds_of(cx, "connection.save");
        let save_connect = bounds_of(cx, "connection.save_connect");
        for (name, bounds) in [
            ("connection.cancel", cancel),
            ("connection.save", save),
            ("connection.save_connect", save_connect),
        ] {
            assert_inside_box(bounds, dialog, name);
        }
        assert!(
            cancel.origin.x < save.origin.x && save.origin.x < save_connect.origin.x,
            "{protocol} actions must be ordered cancel -> save -> save_connect: {cancel:?} {save:?} {save_connect:?}"
        );
    }

    // Switch back to RDP, fill only the name (missing address), and press Save & Connect.
    click(cx, "connection.protocol.rdp");
    type_into(cx, "connection.field.name", "lab-rdp");
    click(cx, "connection.save_connect");
    redraw(cx);

    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().protocol_draft().is_some()),
        "validation failure must keep the non-SSH dialog open"
    );
    assert!(
        cx.debug_bounds("connection.field.address.problem")
            .is_some(),
        "validation failure must show the inline field problem"
    );
    assert!(
        cx.debug_bounds("connection.message").is_some(),
        "validation failure must show the footer refusal banner"
    );
    assert_eq!(
        typed_form_text(&view, cx).0,
        "lab-rdp",
        "validation failure must preserve already-typed form text"
    );
    assert!(
        cx.update(|_window, app| view.read(app).book().connections().is_empty()),
        "validation failure must not save the connection"
    );
    assert!(
        cx.update(|_window, app| view.read(app).workspace().sessions().items().is_empty()),
        "validation failure must not start any session"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn non_ssh_dialog_save_and_connect_starts_rdp_vnc_and_serial_sessions(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("non-ssh-save-connect-flow");
    let (view, cx) = hosts_view(cx, dir.store());
    cx.simulate_resize(size(px(1400.0), px(1000.0)));
    cx.run_until_parked();

    // 1. New RDP: Save & Connect saves and opens an RDP session.
    click(cx, "hosts.new");
    click(cx, "connection.protocol.rdp");
    type_into(cx, "connection.field.address", "127.0.0.1");
    clear_field(cx, "connection.field.port", 4);
    type_into(cx, "connection.field.port", "1");
    type_into(cx, "connection.field.name", "rdp-direct");
    click(cx, "connection.save_connect");
    cx.run_until_parked();

    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().protocol_draft().is_none()),
        "successful save & connect closes the RDP dialog"
    );
    let rdp_id = cx
        .update(|_window, app| {
            view.read(app)
                .book()
                .connections()
                .iter()
                .find(|record| record.name() == "rdp-direct")
                .map(shellune_core::ConnectionRecord::id)
        })
        .expect("RDP connection saved");
    assert!(
        cx.update(|_window, app| {
            view.read(app)
                .workspace()
                .sessions()
                .items()
                .iter()
                .any(|session| {
                    matches!(session.kind(), shellune_core::SessionKind::Rdp { host } if *host == rdp_id)
                })
        }),
        "RDP save & connect must start an RDP session for the saved record"
    );

    // 2. Edit existing RDP: Save & Connect is present, updates record, and starts another session.
    let sessions_before_edit =
        cx.update(|_window, app| view.read(app).workspace().sessions().items().len());
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.edit_connection_for_test(rdp_id, cx));
    });
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("connection.save_connect").is_some(),
        "edit dialog must also expose connection.save_connect"
    );
    type_into(cx, "connection.field.name", "-v2");
    click(cx, "connection.save_connect");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .book()
                .connection(rdp_id)
                .map(|record| record.name().to_owned())
        }),
        Some("rdp-direct-v2".to_owned()),
        "editing via save & connect must persist the updated record"
    );
    assert!(
        cx.update(|_window, app| view.read(app).workspace().sessions().items().len())
            > sessions_before_edit,
        "editing via save & connect must start a new session"
    );

    // 3. New VNC: Save & Connect saves and opens a VNC session.
    click(cx, "nav.hosts");
    click(cx, "hosts.new");
    click(cx, "connection.protocol.vnc");
    type_into(cx, "connection.field.address", "127.0.0.1");
    clear_field(cx, "connection.field.port", 4);
    type_into(cx, "connection.field.port", "1");
    type_into(cx, "connection.field.name", "vnc-direct");
    click(cx, "connection.save_connect");
    cx.run_until_parked();

    let vnc_id = cx
        .update(|_window, app| {
            view.read(app)
                .book()
                .connections()
                .iter()
                .find(|record| record.name() == "vnc-direct")
                .map(shellune_core::ConnectionRecord::id)
        })
        .expect("VNC connection saved");
    assert!(
        cx.update(|_window, app| {
            view.read(app)
                .workspace()
                .sessions()
                .items()
                .iter()
                .any(|session| {
                    matches!(session.kind(), shellune_core::SessionKind::Vnc { host } if *host == vnc_id)
                })
        }),
        "VNC save & connect must start a VNC session for the saved record"
    );

    // 4. New Serial: Save & Connect saves and opens a Serial session.
    click(cx, "nav.hosts");
    click(cx, "hosts.new");
    click(cx, "connection.protocol.serial");
    type_into(
        cx,
        "connection.field.device",
        "/dev/shellune-nonexistent-tty0",
    );
    type_into(cx, "connection.field.name", "serial-direct");
    click(cx, "connection.save_connect");
    cx.run_until_parked();

    let serial_id = cx
        .update(|_window, app| {
            view.read(app)
                .book()
                .connections()
                .iter()
                .find(|record| record.name() == "serial-direct")
                .map(shellune_core::ConnectionRecord::id)
        })
        .expect("Serial connection saved");
    assert!(
        cx.update(|_window, app| {
            view.read(app)
                .workspace()
                .sessions()
                .items()
                .iter()
                .any(|session| {
                    matches!(session.kind(), shellune_core::SessionKind::Serial { host } if *host == serial_id)
                })
        }),
        "Serial save & connect must start a Serial session for the saved record"
    );
}

#[test]
fn home_row_connect_buttons_are_quiet_row_actions_while_new_host_is_primary() {
    let source = include_str!("view/home.rs");
    let new_pos = source
        .find(".id(\"hosts.new\")")
        .expect("hosts.new button in home.rs");
    let new_window = &source[new_pos.saturating_sub(240)..new_pos];
    assert!(
        new_window.contains("Variant::Primary"),
        "hosts.new must remain Variant::Primary"
    );

    // A row's Connect is the shared row action: hidden at rest, the accent's soft tint
    // on the pointed or keyboard row, and never the page's one primary button.
    for (selector, reach) in [
        ("format!(\"hosts.connect.{number}\")", 200),
        ("\"hosts.connection.connect.{number}\"", 220),
    ] {
        let pos = source
            .find(selector)
            .unwrap_or_else(|| panic!("{selector} button in home.rs"));
        let window = &source[pos.saturating_sub(reach)..pos];
        assert!(
            window.contains("components::row_action_button("),
            "{selector} must be drawn with components::row_action_button"
        );
        assert!(
            !window.contains("Variant::Primary"),
            "{selector} must not use Variant::Primary"
        );
    }
    let components = include_str!("components.rs");
    let action = components
        .find("pub fn row_action_button(")
        .expect("row_action_button in components.rs");
    let body = &components[action..action + 1400];
    assert!(
        body.contains("palette::ACCENT_TINT") && body.contains("Variant::Ghost"),
        "row_action_button rests as a ghost and wears the accent's soft tint when shown"
    );
    // The solid accent is only what the button turns into under the pointer.
    assert!(body.contains("hover(hover_style(solid))"));
}

#[gpui::test]
async fn narrow_split_bar_marks_session_more_overflow_and_inactive_pane_closes_directly(
    cx: &mut TestAppContext,
) {
    let Some((view, cx)) = split_local_shell(cx, SplitAxis::LeftRight) else {
        return;
    };
    let id = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("a shell is on screen");
    let pane = cx
        .update(|_window, app| view.read(app).pane_of(id).cloned())
        .expect("the active pane has a terminal");

    // In a wide window, no controls are hidden and session.more shows no overflow dot.
    assert_eq!(
        cx.update(|_window, app| pane.read(app).bar_hidden_controls()),
        0
    );
    assert!(
        cx.debug_bounds("session.more.overflow").is_none(),
        "no overflow indicator when all bar controls fit"
    );

    // Narrow the window so controls fold into session.more, and verify the visual indicator.
    cx.simulate_resize(tiny_window());
    largest_text_size(&view, cx);
    cx.run_until_parked();
    redraw(cx);
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| pane.read(app).bar_hidden_controls()) > 0,
        "narrow split bar should fold trailing controls into session.more"
    );
    let overflow = bounds_of(cx, "session.more.overflow");
    let more = bounds_of(cx, "session.more");
    assert!(
        wholly_inside(overflow, more),
        "overflow dot {overflow:?} must sit inside session.more {more:?}"
    );

    // Restore width and verify the inactive pane offers its own direct close button.
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    let (active_pane, idle_pane) = cx.update(|_window, app| {
        let layout = view.read(app).workspace().layout();
        let active = layout.active_pane().expect("active pane");
        let idle = layout
            .leaves()
            .into_iter()
            .map(|leaf| leaf.id())
            .find(|pane_id| *pane_id != active)
            .expect("idle pane");
        (active, idle)
    });
    assert!(cx.debug_bounds("pane.active.mark").is_some());
    assert!(cx.debug_bounds("pane.close").is_some());
    let idle_close: &'static str = Box::leak(format!("pane.close.{idle_pane}").into_boxed_str());
    let active_close: &'static str =
        Box::leak(format!("pane.close.{active_pane}").into_boxed_str());
    assert!(
        cx.debug_bounds(idle_close).is_some(),
        "inactive pane {idle_pane} must offer direct close button {idle_close}"
    );
    assert!(
        cx.debug_bounds(active_close).is_none(),
        "active pane keeps the shared pane.close selector"
    );

    click(cx, idle_close);
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_leaf_sessions_for_test())
            .len(),
        1,
        "clicking inactive pane's close button closes it directly"
    );
}

#[gpui::test]
async fn split_pane_terminal_receives_escape_ctrl_c_and_ctrl_l(cx: &mut TestAppContext) {
    let Some((view, cx)) = split_local_shell(cx, SplitAxis::LeftRight) else {
        return;
    };
    let id = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("a shell is on screen");
    let pane = cx
        .update(|_window, app| view.read(app).pane_of(id).cloned())
        .expect("the active pane has a terminal");

    // Focus the active terminal pane and verify Esc, Ctrl+C, and Ctrl+L are not intercepted.
    cx.update(|window, app| {
        window.focus(pane.read(app).focus_handle());
    });
    cx.run_until_parked();
    let before = cx.update(|_window, app| pane.read(app).sent().len());
    cx.simulate_keystrokes("escape ctrl-c ctrl-l");
    cx.run_until_parked();
    let sent = cx.update(|_window, app| pane.read(app).sent()[before..].to_vec());
    assert_eq!(
        sent,
        vec![0x1b, 0x03, 0x0c],
        "split pane chrome must not intercept Esc, Ctrl+C, or Ctrl+L"
    );
}

#[gpui::test]
#[ignore = "opt-in RDP/VNC test"]
async fn desktop_controls_dock_top_center_keep_expand_handle_visible_and_block_passthrough(
    cx: &mut TestAppContext,
) {
    let (view, cx) = cx.add_window_view(|_window, cx| ShelluneView::new(cx));
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    let (link, log) = ScriptedLink::new(live_desktop_events());
    let id = mount_scripted_desktop(&view, cx, &desktop_record("desk"), link);

    hover(cx, "desktop.body");
    cx.run_until_parked();
    let body = bounds_of(cx, "desktop.body");
    let controls = bounds_of(cx, "desktop.controls");
    let body_center_x = (body.left() + body.right()) / 2.0;
    let controls_center_x = (controls.left() + controls.right()) / 2.0;
    assert!(
        (controls_center_x - body_center_x).abs() <= px(2.0),
        "desktop.controls must be horizontally centered: controls={controls:?}, body={body:?}"
    );
    assert!(
        controls.top() >= body.top() && controls.top() <= body.top() + px(32.0),
        "desktop.controls must dock near the top edge: controls={controls:?}, body={body:?}"
    );
    assert!(
        controls.right() < body.right() - px(40.0),
        "desktop.controls must stay clear of the remote top-right corner: controls={controls:?}, body={body:?}"
    );

    // Clicking a bar button must not leak a left-button press to the remote picture.
    let before_inputs = log.lock().expect("log lock").inputs.len();
    click(cx, "desktop.zoom.in");
    let leaked_press = log.lock().expect("log lock").inputs[before_inputs..]
        .iter()
        .any(|input| matches!(input, DesktopInput::Pointer { buttons, .. } if buttons.contains(Buttons::LEFT)));
    assert!(
        !leaked_press,
        "clicking desktop.zoom.in must not pass through to the remote surface"
    );

    // Collapse the bar and move the pointer off the picture: a minimal top-center
    // restore handle stays visible, and moving into the top-center reveal zone
    // restores the bar without sending any pointer press to the remote surface.
    click(cx, "desktop.controls.collapse");
    cx.simulate_mouse_move(point(px(2.0), px(2.0)), None, Modifiers::default());
    cx.run_until_parked();
    redraw(cx);
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("desktop.controls.handle").is_some(),
        "a minimal top-center restore handle is drawn after collapsing desktop.controls"
    );
    let before_expand = log.lock().expect("log lock").inputs.len();
    cx.simulate_mouse_move(
        point(body_center_x, body.top() + px(4.0)),
        None,
        Modifiers::default(),
    );
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| {
            view.read(app)
                .desktop_of(id)
                .expect("desktop mounted")
                .read(app)
                .controls_collapsed_for_test()
        }),
        "moving to the top-center reveal zone must unfold the bar"
    );
    let leaked_expand = log.lock().expect("log lock").inputs[before_expand..]
        .iter()
        .any(|input| matches!(input, DesktopInput::Pointer { buttons, .. } if buttons.contains(Buttons::LEFT)));
    assert!(
        !leaked_expand,
        "revealing desktop.controls must not send a click to the remote surface"
    );

    // Fullscreen entry and automatic exit guard when closing the session.
    hover(cx, "desktop.body");
    click(cx, "desktop.fullscreen");
    cx.run_until_parked();
    assert!(cx.update(|_window, app| {
        view.read(app)
            .desktop_of(id)
            .expect("desktop mounted")
            .read(app)
            .is_fullscreen()
    }));
    cx.update(|_window, app| view.update(app, |view, cx| view.close_session(id, cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|window, _app| window.is_fullscreen()),
        "closing a fullscreen desktop session must exit window fullscreen"
    );
}

#[gpui::test]
async fn toast_stack_clears_session_bar_and_resets_hover_when_dismissed(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    show_remote_terminal(cx, &view, id);
    cx.simulate_resize(design_window());
    cx.run_until_parked();
    let search = bounds_of(cx, "terminal.search");
    let more = bounds_of(cx, "session.more");

    // Emit a toast via copy_text and verify the toast stack sits strictly above
    // terminal.search and session.more in the bottom-right corner.
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.copy_text("copied-for-clearance-check".to_owned(), cx);
        });
    });
    cx.run_until_parked();
    redraw(cx);
    cx.run_until_parked();

    let toasts = bounds_of(cx, "toasts");
    assert!(
        toasts.bottom() <= search.top() + px(0.5),
        "toast stack must sit above terminal.search: toasts={toasts:?}, search={search:?}"
    );
    assert!(
        toasts.bottom() <= more.top() + px(0.5),
        "toast stack must sit above session.more: toasts={toasts:?}, more={more:?}"
    );

    // Hover the toast stack, then dismiss the only toast; hover state must reset to false.
    hover(cx, "toasts");
    redraw(cx);
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).toasts_hovered()),
        "hovering the toast stack sets toasts_hovered"
    );
    click(cx, "toast.close.0");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).toast_titles().is_empty()),
        "clicking close removes the toast"
    );
    assert!(
        !cx.update(|_window, app| view.read(app).toasts_hovered()),
        "clearing the last toast must reset toasts_hovered"
    );
}

#[gpui::test]
async fn palette_host_detail_localizes_jumps_and_proxy_command(cx: &mut TestAppContext) {
    let dir = TempDir::new("palette-host-detail-i18n");
    let store = HostStore::at(dir.path());
    let bastion = HostConfig::new("bastion", "bastion.example.com", 22, "ops").expect("valid host");
    let mut via_jump = HostConfig::new("via-jump", "app.internal", 22, "ops").expect("valid host");
    via_jump.set_jumps([bastion.id()]);
    let mut via_proxy =
        HostConfig::new("via-proxy", "proxy.internal", 22, "ops").expect("valid host");
    via_proxy.set_proxy_command(Some("nc %h %p"));
    let mut book = HostBook::new();
    book.insert(bastion).expect("insert bastion");
    book.insert(via_jump).expect("insert via-jump");
    book.insert(via_proxy).expect("insert via-proxy");
    store.save(&book).expect("save host book");

    let mut workspace = Workspace::new();
    workspace.set_locale(Locale::Chinese);
    let (view, cx) =
        cx.add_window_view(|_window, cx| ShelluneView::with_store(cx, workspace, store));
    cx.run_until_parked();

    let (zh_jump, zh_proxy) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            view.palette_detail("via-jump").expect("via-jump entry"),
            view.palette_detail("via-proxy").expect("via-proxy entry"),
        )
    });
    assert!(
        zh_jump.contains("1 个跳板") && !zh_jump.contains("jump"),
        "Chinese palette detail must localize jumps: {zh_jump}"
    );
    assert!(
        zh_proxy.contains("代理命令") && !zh_proxy.contains("ProxyCommand"),
        "Chinese palette detail must localize ProxyCommand: {zh_proxy}"
    );

    cx.dispatch_action(ToggleLanguage);
    cx.run_until_parked();
    let (en_jump, en_proxy) = cx.update(|_window, app| {
        let view = view.read(app);
        (
            view.palette_detail("via-jump").expect("via-jump entry"),
            view.palette_detail("via-proxy").expect("via-proxy entry"),
        )
    });
    assert!(
        en_jump.contains("1 jump"),
        "English palette detail must show jump count: {en_jump}"
    );
    assert!(
        en_proxy.contains("ProxyCommand"),
        "English palette detail must show ProxyCommand: {en_proxy}"
    );
}

#[gpui::test]
async fn startup_stage_failures_are_localized_in_chinese(cx: &mut TestAppContext) {
    use crate::app::view::StartupStage;

    let dir = TempDir::new("startup-i18n-zh");
    let root = dir.path().join("data");
    std::fs::write(&root, "not a directory").expect("sentinel file written");
    let mut workspace = Workspace::new();
    workspace.set_locale(Locale::Chinese);
    let (view, cx) = launching_view(cx, workspace, HostStore::at(&root));
    cx.run_until_parked();
    cx.executor()
        .advance_clock(crate::app::view::BRAND_ENTRANCE);
    cx.run_until_parked();

    assert_eq!(startup_stop(&view, cx), Some(StartupStage::Hosts));
    let stage2_reason = startup_failure(&view, cx);
    assert!(
        stage2_reason.contains("hosts.json"),
        "stage 2 failure keeps the file name: {stage2_reason}"
    );
    assert!(
        stage2_reason.contains("无法读取") && !stage2_reason.contains("the saved hosts at"),
        "stage 2 failure must be localized in Chinese: {stage2_reason}"
    );

    // Continue past stage 2; stage 3 also fails and its report must be localized in Chinese.
    click(cx, "startup.continue");
    cx.run_until_parked();
    let stage3_reason = cx.update(|_window, app| {
        view.read(app)
            .startup_reports()
            .into_iter()
            .find(|r| r.stage == StartupStage::Workspace)
            .and_then(|r| r.failure)
            .expect("stage 3 failure recorded")
    });
    assert!(
        stage3_reason.contains("无法读取")
            && !stage3_reason.contains("the forwarding rules at")
            && !stage3_reason.contains("the workspace snapshot at"),
        "stage 3 failure must be localized in Chinese: {stage3_reason}"
    );
}

#[gpui::test]
async fn startup_failure_body_scrolls_with_keyboard_and_shows_scroll_hint(cx: &mut TestAppContext) {
    use crate::app::view::StartupStage;

    let dir = TempDir::new("startup-kbd-scroll");
    let root = dir.path().join(
        "nested-very-long-directory-segment-for-wrapping-startup-error-reason-in-short-window",
    );
    std::fs::create_dir_all(&root).expect("dir created");
    // Corrupt hosts.json with a long invalid payload so the failure body overflows in a short window.
    std::fs::write(root.join("hosts.json"), "{ invalid json").expect("corrupt hosts written");

    let mut workspace = Workspace::new();
    workspace.set_zoom(Zoom::Comfortable);
    let (view, cx) = launching_view(cx, workspace, HostStore::at(&root));
    cx.simulate_resize(size(px(720.0), px(320.0)));
    cx.run_until_parked();
    cx.executor()
        .advance_clock(crate::app::view::BRAND_ENTRANCE);
    cx.run_until_parked();

    assert_eq!(startup_stop(&view, cx), Some(StartupStage::Hosts));
    assert!(
        cx.debug_bounds("startup.body").is_some(),
        "startup.body is mounted"
    );
    let hint = bounds_of(cx, "startup.failure.scroll_hint");
    let cont = bounds_of(cx, "startup.continue");
    assert!(
        hint.bottom() <= cont.top() + px(0.5),
        "scroll hint sits above the action buttons: hint={hint:?}, cont={cont:?}"
    );

    let max_offset = cx.update(|_window, app| view.read(app).startup_scroll().max_offset().height);
    assert!(
        max_offset > px(0.0),
        "startup.body overflows in a very short window so keyboard scroll can be verified"
    );

    // Focus the splash root and press PageDown, then Home.
    cx.update(|window, app| window.focus(view.read(app).root_focus()));
    cx.run_until_parked();
    press_key(cx, "pagedown");
    cx.run_until_parked();
    let after_down = cx.update(|_window, app| view.read(app).startup_scroll().offset().y);
    assert!(
        after_down < px(0.0),
        "PageDown must scroll startup.body downward: offset={after_down:?}"
    );

    press_key(cx, "home");
    cx.run_until_parked();
    let after_home = cx.update(|_window, app| view.read(app).startup_scroll().offset().y);
    assert!(
        after_home.abs() <= px(0.5),
        "Home must return startup.body to top: offset={after_home:?}"
    );
}

#[gpui::test]
async fn short_narrow_single_column_file_view_preserves_list_room(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (files, transfers) = open_transfers(cx, &view, id);
    // Provide a remote directory listing so files.remote.list is rendered.
    let request = match files.requests().last().expect("list request sent") {
        shellune_core::BrowseRequest::Home { request }
        | shellune_core::BrowseRequest::List { request, .. } => *request,
        other => panic!("expected home/list request, got {other:?}"),
    };
    files.reply(
        request,
        "/home/ops",
        &[
            ("file-0.txt", shellune_core::FileKind::File),
            ("file-1.txt", shellune_core::FileKind::File),
            ("file-2.txt", shellune_core::FileKind::File),
            ("file-3.txt", shellune_core::FileKind::File),
            ("file-4.txt", shellune_core::FileKind::File),
            ("file-5.txt", shellune_core::FileKind::File),
        ],
    );
    pump_files(cx, &view);

    // Start a transfer so files.transfers is also visible at the top.
    click(cx, "files.upload");
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.files_question_set_text_for_test("C:/work/report.txt");
            view.submit_files_change_for_test(cx);
        });
    });
    cx.run_until_parked();
    let task = transfers.starts()[0].transfer;
    transfers.push(shellune_core::TransferEvent {
        transfer: task,
        update: shellune_core::TransferUpdate::Failed {
            failure: shellune_core::TransferFailure::NotFound,
            residue: None,
            resume: None,
        },
    });
    pump_files(cx, &view);

    cx.simulate_resize(narrow_window());
    largest_text_size(&view, cx);
    cx.run_until_parked();

    assert!(
        cx.debug_bounds("files.layout.single").is_some(),
        "narrow window uses single-column file layout"
    );
    let viewport = narrow_window();
    let strip = bounds_of(cx, "files.transfers");
    assert_fits_inside(strip, viewport, "files.transfers");
    assert!(
        strip.size.height <= viewport.height * 0.34 + px(1.0),
        "short single-column window caps files.transfers height tighter: {strip:?}"
    );
    let list = bounds_of(cx, "files.list");
    let min_row = Metrics::new(Zoom::Comfortable).list_row_height();
    assert!(
        list.size.height >= min_row,
        "remote file list must retain at least one row of usable height at 720x480 @ 115%: \
         list={list:?}, min_row={min_row:?}"
    );
}

#[gpui::test]
async fn sftp_goto_folder_and_clear_finished_transfers_work_cleanly(cx: &mut TestAppContext) {
    let (view, cx) = remote_view(cx);
    let id = live_remote(cx, &view);
    let (files, transfers) = open_transfers(cx, &view, id);
    let request = match files.requests().last().expect("list request sent") {
        shellune_core::BrowseRequest::Home { request }
        | shellune_core::BrowseRequest::List { request, .. } => *request,
        other => panic!("expected home/list request, got {other:?}"),
    };
    files.reply(
        request,
        "/home/ops",
        &[("notes.txt", shellune_core::FileKind::File)],
    );
    pump_files(cx, &view);

    // Jump directly to a path via toolbar button `files.goto`.
    assert!(cx.debug_bounds("files.goto").is_some());
    assert!(cx.debug_bounds("files.path.copy").is_some());
    click(cx, "files.goto");
    assert!(cx.debug_bounds("files.question").is_some());
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.files_question_set_text_for_test("/var/log/nginx");
            view.submit_files_change_for_test(cx);
        });
    });
    cx.run_until_parked();
    match files.requests().last().expect("goto list request sent") {
        shellune_core::BrowseRequest::List { path, .. } => {
            assert_eq!(path, "/var/log/nginx");
        }
        other => panic!("expected List request for /var/log/nginx, got {other:?}"),
    }

    // Complete a transfer, then verify `transfers.clear_finished` removes finished rows.
    click(cx, "files.upload");
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.files_question_set_text_for_test("C:/work/report.txt");
            view.submit_files_change_for_test(cx);
        });
    });
    cx.run_until_parked();
    let task = transfers.starts()[0].transfer;
    transfers.push(shellune_core::TransferEvent::started(task));
    transfers.push(shellune_core::TransferEvent {
        transfer: task,
        update: shellune_core::TransferUpdate::Completed { bytes: 128 },
    });
    pump_files(cx, &view);
    assert!(cx.debug_bounds("transfers.row.0").is_some());
    assert!(cx.debug_bounds("transfers.clear_finished").is_some());

    click(cx, "transfers.clear_finished");
    assert!(
        !cx.update(|_window, app| view.read(app).transfers_strip_shown(id)),
        "clearing finished transfers empties the session's transfer strip"
    );
}

