/// A desktop connection binds a shared password of the vault, and the binding
/// is one the connection really honours.
///
/// A desktop sign-in is a password, so the RDP and VNC forms offer the vault's
/// shared passwords beside the typed field, and a bound record dials with the
/// record's password at the moment it starts. What still does not exist is a
/// binding that only looks usable: the SSH form's own pickers stay with the
/// SSH form, and clearing the choice returns the form to a typed password
/// (R1).
#[gpui::test]
async fn a_desktop_connection_binds_a_vault_password_and_dials_with_it(cx: &mut TestAppContext) {
    let dir = TempDir::new("security-desktop-bind");
    let (view, cx) = security_view(cx, &dir);

    // One shared password, generated rather than typed.
    click(cx, "security.action.new-password");
    type_into(cx, "security.dialog.name", "Prod login");
    click(cx, "security.dialog.generate.password");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    let (credential, _) = cx
        .update(|_window, app| view.read(app).security_credentials_for_test())
        .first()
        .cloned()
        .expect("the shared password was created");
    let password = cx
        .update(|_window, app| {
            view.read(app)
                .security_credential_password_for_test(credential)
        })
        .expect("the record holds a password");

    // The RDP form offers the vault's shared passwords; the SSH form's own
    // pickers are not drawn on the protocol form.
    click(cx, "nav.hosts");
    click(cx, "hosts.new");
    click(cx, "connection.protocol.rdp");
    assert!(
        cx.update(|_window, app| {
            let view = view.read(app);
            (
                view.hosts_state().is_editing_connection(),
                view.hosts_state().is_editing(),
            )
        }) == (true, false),
        "a desktop record is edited by the protocol form, which has no sign-in section"
    );
    assert!(
        cx.debug_bounds("connection.auth.credential.0").is_some(),
        "a password sign-in offers the vault's shared password"
    );
    assert!(
        cx.debug_bounds("hosts.auth.credential.0").is_none()
            && cx.debug_bounds("hosts.auth.managed.picker").is_none(),
        "the SSH form's pickers stay with the SSH form"
    );

    // Choosing the record takes the typed field away: the vault holds the
    // password, so there is nothing to type and nothing to keep in the system
    // store. The form model is what the render follows, and the clear button
    // is drawn only for a chosen record.
    click(cx, "connection.auth.credential.0");
    assert!(
        cx.debug_bounds("connection.auth.credential.clear")
            .is_some(),
        "a chosen record shows the way back to a typed password"
    );
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .hosts_state()
                .protocol_draft()
                .map(|draft| (draft.credential_id(), draft.needs_secret()))
        }),
        Some((Some(credential), false)),
        "a bound connection has no password of its own to type or keep"
    );
    type_into(cx, "connection.field.address", "127.0.0.1");
    clear_field(cx, "connection.field.port", 4);
    type_into(cx, "connection.field.port", "1");
    click(cx, "connection.save");
    cx.run_until_parked();
    let record = cx
        .update(|_window, app| view.read(app).book().connections().last().cloned())
        .expect("the connection was saved");
    assert_eq!(
        record.credential_id(),
        Some(credential),
        "the record names the one shared password"
    );
    assert!(
        !record.remembers_secret(),
        "the vault holds the password; the system store is not asked to"
    );
    let id = record.id();

    // The start reads the password from the vault: the form had nothing typed
    // and nothing was kept anywhere else.
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.connect_saved_connection(id, cx));
    });
    cx.run_until_parked();
    let session = cx
        .update(|_window, app| view.read(app).open_tabs().last().copied())
        .expect("the connection opened a tab");
    cx.update(|_window, app| {
        let pane = view
            .read(app)
            .desktop_of(session)
            .expect("the desktop surface is mounted")
            .read(app);
        assert_eq!(
            pane.started_password(),
            Some(Some(password.as_str())),
            "the attempt dials with the shared password of the vault"
        );
    });

    // The file names the reference and never the password.
    let file = std::fs::read_to_string(dir.path().join(shellune_storage::FILE_NAME))
        .expect("the connection file was written");
    assert!(file.contains("credential_id"), "{file}");
    assert!(!file.contains(&password), "no secret reaches the file");

    // Clearing the choice returns the form to a typed password.
    click(cx, "nav.hosts");
    click(cx, "hosts.connection.edit.0");
    assert!(
        cx.debug_bounds("connection.auth.credential.clear")
            .is_some(),
        "a bound edit offers the way back to a typed password"
    );
    click(cx, "connection.auth.credential.clear");
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .hosts_state()
                .protocol_draft()
                .map(|draft| (draft.credential_id(), draft.needs_secret()))
        }),
        Some((None, true)),
        "clearing the choice returns the form to a typed password"
    );
    click(cx, "connection.save");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .book()
                .connection(id)
                .and_then(|record| record.credential_id())
        }),
        None,
        "saving the cleared form unbinds the record"
    );
}

/// A shared password reaches every desktop connection that names it, and an
/// independent copy changes on its own from the moment it is made (R1).
#[gpui::test]
async fn a_shared_password_edited_in_one_place_reaches_the_desktop_connections(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("security-desktop-shared");
    let (view, cx) = security_view(cx, &dir);

    click(cx, "security.action.new-password");
    type_into(cx, "security.dialog.name", "Prod login");
    click(cx, "security.dialog.generate.password");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    let (credential, _) = cx
        .update(|_window, app| view.read(app).security_credentials_for_test())
        .first()
        .cloned()
        .expect("the shared password was created");

    // One RDP and one VNC connection, each bound through its own form: two
    // protocols, one shared record.
    for protocol in ["connection.protocol.rdp", "connection.protocol.vnc"] {
        click(cx, "nav.hosts");
        click(cx, "hosts.new");
        click(cx, protocol);
        click(cx, "connection.auth.credential.0");
        type_into(cx, "connection.field.address", "127.0.0.1");
        clear_field(cx, "connection.field.port", 4);
        type_into(cx, "connection.field.port", "1");
        click(cx, "connection.save");
        cx.run_until_parked();
    }
    let bound = cx.update(|_window, app| {
        view.read(app)
            .book()
            .connections()
            .iter()
            .map(|record| (record.id(), record.credential_id()))
            .collect::<Vec<_>>()
    });
    assert_eq!(bound.len(), 2, "both connections were saved");
    for (id, referenced) in &bound {
        assert_eq!(
            *referenced,
            Some(credential),
            "the connection {id} names the one shared record"
        );
    }

    // Editing the shared record is the reality of both connections at once:
    // each next start reads the new value.
    let edit_shared = |cx: &mut VisualTestContext, password: &str| {
        click(cx, "nav.settings");
        click(cx, "settings.item.keys-and-passwords");
        click(cx, "security.credential.0");
        click(cx, "security.detail.action.0");
        clear_field(cx, "security.dialog.secret", 0);
        type_into(cx, "security.dialog.secret", password);
        click(cx, "security.dialog.submit");
        cx.run_until_parked();
    };
    edit_shared(cx, "second-shared-value");
    for (id, _) in &bound {
        cx.update(|_window, cx| {
            view.update(cx, |view, cx| view.connect_saved_connection(*id, cx));
        });
        cx.run_until_parked();
        let session = cx
            .update(|_window, app| view.read(app).open_tabs().last().copied())
            .expect("the connection opened a tab");
        cx.update(|_window, app| {
            let pane = view
                .read(app)
                .desktop_of(session)
                .expect("the desktop surface is mounted")
                .read(app);
            assert_eq!(
                pane.started_password(),
                Some(Some("second-shared-value")),
                "the start of this connection reads the edited shared password"
            );
        });
    }

    // An independent copy keeps its own value: the original's connections move
    // with the original alone.
    click(cx, "nav.settings");
    click(cx, "settings.item.keys-and-passwords");
    click(cx, "security.credential.0");
    click(cx, "security.detail.action.1");
    cx.run_until_parked();
    let copies = cx.update(|_window, app| view.read(app).security_credentials_for_test());
    let copy = copies
        .iter()
        .find(|(id, _)| *id != credential)
        .map(|(id, _)| *id)
        .expect("the copy has its own identity");
    assert_eq!(
        cx.update(|_window, app| { view.read(app).security_credential_password_for_test(copy) }),
        Some("second-shared-value".to_owned()),
        "the copy starts from the value the original had"
    );
    edit_shared(cx, "third-shared-value");
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .security_credential_password_for_test(credential)
        }),
        Some("third-shared-value".to_owned())
    );
    assert_eq!(
        cx.update(|_window, app| { view.read(app).security_credential_password_for_test(copy) }),
        Some("second-shared-value".to_owned()),
        "the independent copy keeps its own value when the original moves on"
    );
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.connect_saved_connection(bound[0].0, cx));
    });
    cx.run_until_parked();
    let session = cx
        .update(|_window, app| view.read(app).open_tabs().last().copied())
        .expect("the connection opened a tab");
    cx.update(|_window, app| {
        let pane = view
            .read(app)
            .desktop_of(session)
            .expect("the desktop surface is mounted")
            .read(app);
        assert_eq!(
            pane.started_password(),
            Some(Some("third-shared-value")),
            "the connection still follows the record it names"
        );
    });
}

/// A desktop connection whose shared password the vault cannot hand over says
/// so, instead of dialling with nothing and letting the server report a
/// refusal that means less (R1).
#[gpui::test]
async fn a_desktop_connection_whose_shared_password_is_unreachable_says_so(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("security-desktop-unreachable");
    // A record that names a credential no vault of this machine holds: the
    // shape a deleted record leaves behind, and what a locked vault reads as.
    let credential = shellune_core::CredentialId::new();
    let mut rdp =
        shellune_core::RdpConfig::new("office", "127.0.0.1", Some("desk")).expect("a valid record");
    rdp.set_port(1).expect("a closed port");
    rdp.set_credential_id(Some(credential));
    seed_connections(
        &dir.store(),
        vec![shellune_core::ConnectionRecord::Rdp(rdp)],
    );
    let (view, cx) = hosts_view(cx, dir.store());

    let id = cx
        .update(|_window, app| {
            view.read(app)
                .book()
                .connections()
                .first()
                .map(shellune_core::ConnectionRecord::id)
        })
        .expect("the record was loaded");
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.connect_saved_connection(id, cx));
    });
    cx.run_until_parked();

    // The session is refused with the localized reason, and no attempt was
    // dialled behind it.
    let session = cx
        .update(|_window, app| view.read(app).open_tabs().last().copied())
        .expect("the attempt was recorded");
    let state = cx.update(|_window, app| {
        view.read(app)
            .workspace()
            .session(session)
            .map(|session| session.state().clone())
    });
    match state {
        Some(shellune_core::SessionState::Failed(
            shellune_core::SessionFailure::ReconnectUnavailable { reason },
        )) => {
            assert!(
                reason.contains("vault cannot hand this password over"),
                "the refusal names the vault, not the server: {reason}"
            );
        }
        other => panic!("the start was refused where the user can read it: {other:?}"),
    }
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_start_count_for_test()),
        0,
        "nothing was dialled with a password the record never chose"
    );
}

/// A desktop record written before desktop connections joined the vault still
/// loads, unbound, and can be bound once it has a place to keep the reference
/// (R1).
#[gpui::test]
async fn a_desktop_record_written_before_vault_binding_still_loads(cx: &mut TestAppContext) {
    let dir = TempDir::new("security-desktop-old-record");

    // Exactly the connection file a build without the reference field wrote:
    // an RDP record with no credential to name.
    let id = shellune_core::HostId::new();
    let book = serde_json::json!({
        "version": 1,
        "hosts": [],
        "connections": [{
            "protocol": "rdp",
            "id": id,
            "name": "office",
            "address": "10.0.0.9",
            "port": 3389,
            "user": "alice"
        }],
        "recents": [],
        "favorites": []
    });
    std::fs::write(
        dir.path().join(shellune_storage::FILE_NAME),
        serde_json::to_string(&book).expect("the old book serializes"),
    )
    .expect("the old book was written");

    let (view, cx) = security_view(cx, &dir);
    let record = cx
        .update(|_window, app| view.read(app).book().connection(id))
        .expect("the old record still loads");
    assert_eq!(record.credential_id(), None, "it loads with nothing bound");

    // A shared password exists, and the edit form of the old record offers it:
    // a record from before the vault is not locked out of it.
    click(cx, "security.action.new-password");
    type_into(cx, "security.dialog.name", "Prod login");
    click(cx, "security.dialog.generate.password");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    let (credential, _) = cx
        .update(|_window, app| view.read(app).security_credentials_for_test())
        .first()
        .cloned()
        .expect("the shared password was created");
    click(cx, "nav.hosts");
    click(cx, "hosts.connection.edit.0");
    assert!(
        cx.debug_bounds("connection.auth.credential.0").is_some(),
        "the old record's form offers the vault's shared password"
    );
    click(cx, "connection.auth.credential.0");
    click(cx, "connection.save");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .book()
                .connection(id)
                .and_then(|record| record.credential_id())
        }),
        Some(credential),
        "the old record can be bound like any other"
    );

    // Deleting the shared record clears the binding, so nothing is left that
    // looks usable and points at a record the vault no longer holds: the next
    // start signs in with no password rather than the deleted one.
    click(cx, "nav.settings");
    click(cx, "settings.item.keys-and-passwords");
    click(cx, "security.credential.0");
    click(cx, "security.detail.action.2");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).security_credentials_for_test())
            .is_empty(),
        "the shared password was deleted"
    );
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .book()
                .connection(id)
                .and_then(|record| record.credential_id())
        }),
        None,
        "the record the deletion unbound names nothing"
    );
    cx.update(|_window, cx| {
        view.update(cx, |view, cx| view.connect_saved_connection(id, cx));
    });
    cx.run_until_parked();
    let session = cx
        .update(|_window, app| view.read(app).open_tabs().last().copied())
        .expect("the connection opened a tab");
    cx.update(|_window, app| {
        let pane = view
            .read(app)
            .desktop_of(session)
            .expect("the desktop surface is mounted")
            .read(app);
        assert_eq!(
            pane.started_password(),
            Some(None),
            "the unbound record starts with no password, not the deleted one"
        );
    });
}

/// An edit made while a vault job runs is kept when the job lands: the job's
/// reference change is replayed on the record as it stands then, and the
/// overlap is named on the page instead of quietly reverting the edit.
#[gpui::test]
async fn an_edit_made_while_a_vault_job_runs_is_kept_when_it_lands(cx: &mut TestAppContext) {
    let dir = TempDir::new("security-drift");
    let (view, cx) = security_view(cx, &dir);
    let (key, _, _) = generate_key_on_page(&view, cx, "Deploy");

    // One host bound to the key, through the host editor's own picker.
    click(cx, "nav.hosts");
    click(cx, "hosts.new");
    type_into(cx, "hosts.field.name", "box");
    type_into(cx, "hosts.field.address", "127.0.0.1");
    clear_field(cx, "hosts.field.port", 2);
    type_into(cx, "hosts.field.port", "1");
    type_into(cx, "hosts.field.user", "ada");
    click(cx, "hosts.auth.remote.method.managed-key");
    click(cx, "hosts.auth.managed.key.0");
    click(cx, "hosts.save");
    cx.run_until_parked();

    // The unbind runs with its finish held, so the window is exactly where a
    // real user would be while the derivation runs.
    click(cx, "nav.settings");
    click(cx, "settings.item.keys-and-passwords");
    click(cx, "security.key.0");
    cx.update(|_window, app| {
        view.update(app, |view, _cx| view.security_hold_finish_for_test(true))
    });
    click(cx, "security.detail.unbind.0");
    assert!(
        cx.update(|_window, app| view.read(app).security_busy_for_test()),
        "the unbind is in flight"
    );

    // Meanwhile the host is renamed - an edit to a record the job also touches.
    click(cx, "nav.hosts");
    click(cx, "hosts.edit.0");
    clear_field(cx, "hosts.field.name", "box".len());
    type_into(cx, "hosts.field.name", "box renamed");
    click(cx, "hosts.save");
    cx.run_until_parked();

    // The job lands: the rename is kept, the unbinding is applied on top of
    // it, and the page names the overlap instead of passing silently.
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.security_release_finish_for_test(cx))
    });
    cx.run_until_parked();
    let host = cx
        .update(|_window, app| view.read(app).book().hosts().first().cloned())
        .expect("the host is still there");
    assert_eq!(
        host.name(),
        "box renamed",
        "the edit made during the job is kept"
    );
    assert_eq!(host.managed_key_id(), None, "the unbinding still applied");
    assert_eq!(host.auth(), None);
    let notice = cx.update(|_window, app| view.read(app).security_notice_for_test());
    let (text, _) = notice.expect("the overlap is named on the page");
    assert!(
        text.contains("box renamed"),
        "the notice names the edited host: {text}"
    );

    // The vault still describes the book it sees: the next write goes through.
    click(cx, "nav.settings");
    click(cx, "settings.item.keys-and-passwords");
    click(cx, "security.action.new-password");
    type_into(cx, "security.dialog.name", "After the overlap");
    click(cx, "security.dialog.generate.password");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    let refused_after = cx.update(|_window, app| {
        view.read(app)
            .security_notice_for_test()
            .is_some_and(|(_, refused)| refused)
    });
    assert!(!refused_after, "a later vault write still succeeds");
    let _ = key;
}
// ---------------------------------------------------------------------------
// The host-trust page, the device's lock, and the vault's travels (T7)
// ---------------------------------------------------------------------------

/// A window on the settings page over stores the test holds, so a vault can be
/// seeded before the window exists and read back after it is gone.
fn vault_window<'a>(
    cx: &'a mut TestAppContext,
    dir: &TempDir,
    secrets: &Arc<shellune_storage::MemorySecrets>,
) -> (Entity<ShelluneView>, &'a mut VisualTestContext) {
    let mut workspace = Workspace::new();
    workspace.select(Destination::Settings);
    let store = dir.store();
    let secrets: Arc<dyn shellune_storage::SecretStore> = secrets.clone();
    let (view, cx) = cx.add_window_view(move |_window, cx| {
        ShelluneView::with_secrets_for_test(cx, workspace, store, secrets)
    });
    cx.simulate_resize(tall_window());
    cx.run_until_parked();
    (view, cx)
}

/// Writes a vault file holding one accepted identity and one shared password,
/// sealed for the machine whose store `secrets` is: what a device that has
/// used its vault for a while starts from.
fn seed_vault(dir: &TempDir, secrets: &Arc<shellune_storage::MemorySecrets>) {
    let mut content = shellune_storage::VaultContent::new();
    let mut trust = shellune_storage::HostTrust::new();
    let key = shellune_storage::HostKey::new(
        "ssh-ed25519".to_owned(),
        "SHA256:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA".to_owned(),
        "AAAAfixture-identity".to_owned(),
    )
    .expect("a fixture identity is well formed");
    trust
        .accept("web.example.com", 22, &key, 1_700_000_000)
        .expect("the identity is accepted");
    content.set_trust(trust);
    content
        .insert_credential(shellune_storage::VaultCredentialRecord::new(
            shellune_core::CredentialMeta::new(
                shellune_core::CredentialId::new(),
                "Prod login".to_owned(),
                Some("deploy".to_owned()),
                shellune_core::VaultRecordVersion::new(1, "seed"),
            ),
            shellune_core::SecretString::new("shared-secret-value"),
        ))
        .expect("the credential is inserted");
    shellune_storage::VaultStore::at(dir.path())
        .save_records(
            &content,
            &[],
            &[shellune_storage::UnsealSource::LocalMachine],
            shellune_storage::KdfParams::new(8, 1, 1).expect("cheap parameters"),
            secrets.as_ref(),
        )
        .expect("the vault is written");
}

/// The host-trust page lists what the vault holds, narrows by the search and
/// removes an identity with a confirmation and no password of any kind - and a
/// restart does not bring the record back (R7).
#[gpui::test]
async fn host_trust_is_searched_and_removed_without_any_passphrase(cx: &mut TestAppContext) {
    let dir = TempDir::new("trust-page");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);

    click(cx, "settings.category.security");
    click(cx, "settings.item.host-trust");
    assert!(
        cx.debug_bounds("security.trust.host.0").is_some(),
        "the accepted identity is listed"
    );
    let rows = cx.update(|_window, app| view.read(app).security_trust_rows_for_test(app));
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].0, "web.example.com");
    assert_eq!(rows[0].1, 22);
    assert_eq!(
        rows[0].3,
        "SHA256:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
    );
    assert!(rows[0].4, "the record comes from the vault, the authority");

    // The search narrows by the fingerprint; a name that matches nothing says
    // so instead of an empty-looking vault.
    type_into(cx, "security.trust.search", "SHA256:AAAA");
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_trust_rows_for_test(app))
            .len(),
        1,
        "the fingerprint finds the record"
    );
    clear_field(cx, "security.trust.search", "SHA256:AAAA".len());
    type_into(cx, "security.trust.search", "nowhere.example");
    assert!(
        cx.debug_bounds("security.trust.empty").is_some(),
        "a search that matches nothing says so"
    );
    clear_field(cx, "security.trust.search", "nowhere.example".len());

    // The removal asks once, needs no passphrase, and takes the record out of
    // the vault and this device's file at once.
    click(cx, "security.trust.delete.0");
    assert!(
        cx.debug_bounds("security.dialog.delete-trust").is_some(),
        "the removal question opens"
    );
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).security_trust_rows_for_test(app))
            .is_empty(),
        "the record is gone from the page"
    );
    assert!(
        cx.update(|_window, app| view.read(app).security_vault_trust_for_test())
            .is_empty(),
        "the record is gone from the vault"
    );

    // A restart reads what is on disk: nothing restores the record.
    drop(view);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    click(cx, "settings.category.security");
    click(cx, "settings.item.host-trust");
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_trust_rows_for_test(app))
            .len(),
        0,
        "the removal survived the restart"
    );
    let _ = view;
}

/// What a connection reads as "known" is the vault first and this device's
/// legacy file under it (ADR-6, T5's handoff): a version 2 sync that clears
/// the plain `known_hosts` never takes the accepted fingerprints with it, and
/// where both hold a record the vault's wins.
#[gpui::test]
async fn a_connection_reads_trust_from_the_vault_beside_the_plain_file(cx: &mut TestAppContext) {
    let dir = TempDir::new("trust-authority");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    // The device's legacy file holds a *different* identity for the same
    // server, the state a not-yet-migrated machine is in.
    let mut plain = shellune_storage::HostTrust::new();
    let stale = shellune_storage::HostKey::new(
        "ssh-ed25519".to_owned(),
        "SHA256:BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB".to_owned(),
        "AAAAstale-identity".to_owned(),
    )
    .expect("a second identity is well formed");
    plain
        .accept("web.example.com", 22, &stale, 1_700_000_050)
        .expect("the plain file accepts its own record");
    shellune_storage::TrustStore::at(dir.path())
        .save(&plain)
        .expect("the plain trust file is written");
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let read = cx.update(|_window, app| {
        let view = view.read(app);
        view.effective_trust()
            .entry("web.example.com", 22)
            .map(|entry| entry.fingerprint().to_owned())
    });
    assert_eq!(
        read.as_deref(),
        Some("SHA256:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"),
        "the vault's fingerprint is the one a connection reads"
    );
}

/// A device with the biometric protection on starts locked, one verification
/// opens the vault, and the idle time locks it again (R3).
#[gpui::test]
async fn the_vault_locks_unlocks_once_and_locks_again_on_idle(cx: &mut TestAppContext) {
    let dir = TempDir::new("lock-idle");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Ok(())]),
    );
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_set_authenticator_for_test(authenticator);
            view.security_enable_lock_for_test(shellune_storage::LockPolicy::UnlockVault, 1, cx);
        })
    });
    assert!(
        cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "the start under the protection is locked"
    );
    assert!(
        cx.update(|_window, app| view.read(app).security_credentials_for_test())
            .is_empty(),
        "a locked vault holds no secret in memory"
    );

    // One verification opens the vault; the answer is used once, for this.
    cx.update(|_window, app| view.update(app, |view, cx| view.security_unlock_for_test(cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "the verification opened the vault"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_credentials_for_test())
            .len(),
        1,
        "the opened vault is the one on disk"
    );

    // The idle minute passes with no sensitive use: the vault locks again.
    cx.executor()
        .advance_clock(std::time::Duration::from_secs(61));
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "the idle time locked the vault again"
    );
}

/// A cancelled verification is never a pass: the vault stays locked and
/// nothing is read (R3, R4).
#[gpui::test]
async fn a_cancelled_verification_keeps_the_vault_locked(cx: &mut TestAppContext) {
    let dir = TempDir::new("lock-cancel");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Err(shellune_storage::BiometricError::Cancelled)]),
    );
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_set_authenticator_for_test(authenticator);
            view.security_enable_lock_for_test(shellune_storage::LockPolicy::UnlockVault, 15, cx);
        })
    });
    cx.update(|_window, app| view.update(app, |view, cx| view.security_unlock_for_test(cx)));
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "a cancelled prompt leaves the vault locked"
    );
}

/// An enrollment change disables this device's biometric protection: the
/// vault stays as it was and the setting says so until the user re-enables it
/// with a fresh verification (R4).
#[gpui::test]
async fn an_enrollment_change_disables_biometric_unlock(cx: &mut TestAppContext) {
    let dir = TempDir::new("lock-enrollment");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Err(shellune_storage::BiometricError::EnrollmentChanged {
            reason: "fingerprints re-enrolled".to_owned(),
        })]),
    );
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_set_authenticator_for_test(authenticator);
            view.security_enable_lock_for_test(shellune_storage::LockPolicy::UnlockVault, 15, cx);
        })
    });
    cx.update(|_window, app| view.update(app, |view, cx| view.security_unlock_for_test(cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_biometric_for_test()),
        "the enrollment change turned the biometric switch off"
    );
    assert!(
        cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "and the vault was not opened by it"
    );
    let saved = shellune_storage::SecurityStore::at(dir.path()).load();
    assert_eq!(saved.biometric_unlock, Some(false));
}

/// The "every sensitive operation" mode verifies each request anew: a pass is
/// never the next request's pass (R3).
#[gpui::test]
async fn every_sensitive_operation_verifies_anew(cx: &mut TestAppContext) {
    let dir = TempDir::new("lock-every");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let credential = cx.update(|_window, app| {
        view.read(app)
            .security_credentials_for_test()
            .first()
            .map(|(id, _)| *id)
            .expect("the seeded credential is in the vault")
    });
    // The protection goes on without locking what is already open: the policy
    // governs what follows, not the past.
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_lock_settings_for_test(
                shellune_storage::LockPolicy::EverySensitiveOperation,
                cx,
            );
        })
    });
    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Ok(()), Ok(())]),
    );
    let counter = authenticator.clone();
    cx.update(|_window, app| {
        view.update(app, |view, _cx| {
            view.security_set_authenticator_for_test(authenticator)
        })
    });

    // First reveal: one verification, then the password is shown.
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_reveal_for_test(credential, cx)
        })
    });
    cx.run_until_parked();
    assert_eq!(counter.verify_calls(), 1, "the first reveal asked once");
    assert!(
        cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "the granted pass showed the password"
    );

    // Hide it again; the second reveal asks again - the first pass is spent.
    cx.update(|_window, app| view.update(app, |view, cx| view.security_hide_password_for_test(cx)));
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_reveal_for_test(credential, cx)
        })
    });
    cx.run_until_parked();
    assert_eq!(counter.verify_calls(), 2, "the second reveal asked again");

    // The script is exhausted: a third request is refused, never guessed at.
    cx.update(|_window, app| view.update(app, |view, cx| view.security_hide_password_for_test(cx)));
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_reveal_for_test(credential, cx)
        })
    });
    cx.run_until_parked();
    assert_eq!(counter.verify_calls(), 3, "the third reveal asked too");
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "an answer the system never gave is not a pass"
    );
}

/// A full backup carries the encrypted vault under the sync passphrase, a
/// wrong passphrase opens nothing, and the restore brings the records and the
/// trust back without duplicates (R9).
#[gpui::test]
async fn a_vault_backup_round_trips_through_the_sync_passphrase(cx: &mut TestAppContext) {
    let source = TempDir::new("vault-backup-a");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&source, &secrets);
    let (view, cx) = vault_window(cx, &source, &secrets);

    // The export: the vault checkbox asks for a sync passphrase when none is
    // saved, and the export cannot start without one.
    click(cx, "settings.category.data");
    click(cx, "settings.backup.export");
    click(cx, "backup.export.vault");
    assert!(
        cx.debug_bounds("backup.export.vault.passphrase").is_some(),
        "a device without a saved passphrase is asked for one"
    );
    click(cx, "backup.export.save");
    assert!(
        !cx.did_prompt_for_new_path(),
        "no file is asked for while the passphrase is missing"
    );
    type_into(
        cx,
        "backup.export.vault.passphrase",
        "correct horse battery",
    );
    type_into(cx, "backup.export.vault.confirm", "correct horse battery");
    click(cx, "backup.export.save");
    assert!(cx.did_prompt_for_new_path());
    let target = source.path().join("vault-backup.json");
    let chosen = target.clone();
    cx.simulate_new_path_selection(move |_directory| Some(chosen));
    cx.run_until_parked();
    let (_, _, vault, _, _) = cx
        .update(|_window, app| view.read(app).export_report_for_test())
        .expect("the export wrote its report");
    assert!(vault, "the backup carries the encrypted vault");
    let text = std::fs::read_to_string(&target).expect("the backup was written");
    assert!(
        !text.contains("shared-secret-value"),
        "no secret in clear text"
    );
    let document = shellune_storage::ShelluneData::read(&target).expect("the backup reads");
    assert_eq!(
        document.version(),
        2,
        "a vault-carrying backup is version 2"
    );
    assert!(document.has_vault());
    assert!(
        !document.has_secrets(),
        "the version 1 password block did not travel with it"
    );
    assert!(
        document.shared().known_hosts().is_empty(),
        "a version 2 document carries no plaintext trust"
    );
    assert!(
        cx.update(|_window, app| view.read(app).saved_sync_passphrase_for_test().is_some()),
        "the passphrase set at the export is the saved sync passphrase"
    );

    // The restore: a version 2 backup asks for the passphrase, the wrong one
    // opens nothing, and the right one brings the vault back whole.
    let restore = TempDir::new("vault-backup-b");
    let restore_secrets = Arc::new(shellune_storage::MemorySecrets::new());
    let (view, cx) = vault_window(cx, &restore, &restore_secrets);
    cx.update(|_window, app| view.update(app, |view, cx| view.read_backup_for_test(&target, cx)));
    cx.run_until_parked();
    assert_eq!(
        backup_stage(&view, cx),
        Some("import.vault-locked"),
        "a version 2 backup asks for the sync passphrase"
    );
    type_into(cx, "backup.import.vault.passphrase", "not the passphrase");
    click(cx, "backup.import.vault.unlock");
    cx.run_until_parked();
    assert_eq!(
        backup_stage(&view, cx),
        Some("import.vault-locked"),
        "a wrong passphrase stays on the question"
    );
    type_into(
        cx,
        "backup.import.vault.passphrase",
        "correct horse battery",
    );
    click(cx, "backup.import.vault.unlock");
    cx.run_until_parked();
    assert_eq!(backup_stage(&view, cx), Some("import.preview"));
    click(cx, "backup.import.apply");
    cx.run_until_parked();
    assert_eq!(backup_stage(&view, cx), Some("import.applied"));
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_vault_trust_for_test()),
        vec![("web.example.com".to_owned(), 22)],
        "the trust came back with the vault"
    );

    // Applying the same backup again creates no duplicates: the records keep
    // their identities, so the second restore lands on the same set (R9).
    drop(view);
    let (view, cx) = vault_window(cx, &restore, &restore_secrets);
    cx.update(|_window, app| view.update(app, |view, cx| view.read_backup_for_test(&target, cx)));
    cx.run_until_parked();
    type_into(
        cx,
        "backup.import.vault.passphrase",
        "correct horse battery",
    );
    click(cx, "backup.import.vault.unlock");
    cx.run_until_parked();
    click(cx, "backup.import.apply");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_vault_trust_for_test())
            .len(),
        1,
        "a repeated restore makes no duplicate records"
    );
    let _ = view;
}

/// Writes a version 2 backup of `hosts` carrying `vault`, sealed under
/// `passphrase`: what a machine that exports its whole vault writes (R9).
fn write_vault_backup(
    path: &std::path::Path,
    hosts: Vec<HostConfig>,
    vault: &shellune_storage::VaultContent,
    passphrase: &str,
) {
    let mut local = shellune_storage::LocalState::default();
    for host in hosts {
        local
            .hosts
            .apply(&HostEdit::create(host))
            .expect("the host is inserted");
    }
    let kdf = shellune_storage::KdfParams::new(8, 1, 1).expect("a cheap cost is accepted");
    let cipher = shellune_storage::VaultCipher::export_copy(
        vault,
        &shellune_core::SecretString::new(passphrase),
        kdf,
    )
    .expect("the vault is sealed");
    let mut options = shellune_storage::ExportOptions::new(shellune_storage::Platform::current());
    options.kdf = kdf;
    options = options.with_vault(cipher);
    shellune_storage::ShelluneData::export_from_vault(&local, &options, None, None)
        .expect("the backup is made")
        .document
        .write_to(path)
        .expect("the backup is written");
}

/// Reads a version 2 backup into the window and opens its vault, leaving the
/// preview on screen.
fn open_vault_backup(
    view: &Entity<ShelluneView>,
    cx: &mut VisualTestContext,
    path: &std::path::Path,
    passphrase: &str,
) {
    read_backup(view, cx, path);
    assert_eq!(backup_stage(view, cx), Some("import.vault-locked"));
    type_into(cx, "backup.import.vault.passphrase", passphrase);
    click(cx, "backup.import.vault.unlock");
    cx.run_until_parked();
    assert_eq!(backup_stage(view, cx), Some("import.preview"));
}

/// Merging a version 2 backup keeps the remembered passwords of hosts only this
/// machine has: the backup says nothing about them, which is no deletion, and
/// their old entries are long gone (R4).
#[gpui::test]
async fn merging_a_vault_backup_keeps_the_passwords_only_this_machine_has(cx: &mut TestAppContext) {
    let dir = TempDir::new("vault-backup-merge");
    let mine = password_host("mine", "10.0.0.1");
    let theirs = password_host("theirs", "10.0.0.2");
    let (mine_id, theirs_id) = (mine.id(), theirs.id());
    seed(&dir.store(), vec![mine]);
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_host_secrets(&dir, secrets.as_ref(), &[(mine_id, "mine-password")]);
    let mut backup_vault = shellune_storage::VaultContent::new();
    backup_vault.set_host_secret(
        theirs_id,
        shellune_core::SecretString::new("theirs-password"),
        "exporter",
    );
    let backup = dir.path().join("merge.json");
    write_vault_backup(&backup, vec![theirs], &backup_vault, "correct horse");
    let (view, cx) = vault_window(cx, &dir, &secrets);

    open_vault_backup(&view, cx, &backup, "correct horse");
    click(cx, "backup.import.apply");
    cx.run_until_parked();
    assert_eq!(backup_stage(&view, cx), Some("import.applied"));
    assert_eq!(host_names(&view, cx), vec!["mine", "theirs"]);
    let vault = open_vault(&dir, &secrets);
    assert_eq!(
        vault
            .host_secret(mine_id)
            .map(shellune_core::SecretString::expose),
        Some("mine-password"),
        "the password only this machine had is kept"
    );
    assert_eq!(
        vault
            .host_secret(theirs_id)
            .map(shellune_core::SecretString::expose),
        Some("theirs-password"),
        "the backup's password arrived"
    );
    assert!(host_entry_accesses(&secrets).is_empty());
}

/// Replacing with a version 2 backup takes the backup's vault, but a host the
/// result still remembers whose password the backup has no record of keeps
/// this machine's password; a host the result drops leaves a tombstone (R4).
#[gpui::test]
async fn replacing_with_a_vault_backup_never_leaves_a_remembered_host_without_its_password(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("vault-backup-replace");
    let shared = password_host("shared", "10.0.0.1");
    let dropped = password_host("dropped", "10.0.0.2");
    let arriving = password_host("arriving", "10.0.0.3");
    let (shared_id, dropped_id, arriving_id) = (shared.id(), dropped.id(), arriving.id());
    seed(&dir.store(), vec![shared.clone(), dropped]);
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_host_secrets(
        &dir,
        secrets.as_ref(),
        &[
            (shared_id, "shared-password"),
            (dropped_id, "dropped-password"),
        ],
    );
    // The exporting machine had not migrated `shared` yet: its vault holds no
    // record of it, while the host still remembers its password.
    let mut backup_vault = shellune_storage::VaultContent::new();
    backup_vault.set_host_secret(
        arriving_id,
        shellune_core::SecretString::new("arriving-password"),
        "exporter",
    );
    let backup = dir.path().join("replace.json");
    write_vault_backup(
        &backup,
        vec![shared, arriving],
        &backup_vault,
        "correct horse",
    );
    let (view, cx) = vault_window(cx, &dir, &secrets);

    open_vault_backup(&view, cx, &backup, "correct horse");
    click(cx, "backup.mode.1");
    click(cx, "backup.import.apply");
    click(cx, "backup.import.apply");
    cx.run_until_parked();
    assert_eq!(backup_stage(&view, cx), Some("import.applied"));
    assert_eq!(host_names(&view, cx), vec!["arriving", "shared"]);
    let vault = open_vault(&dir, &secrets);
    assert_eq!(
        vault
            .host_secret(shared_id)
            .map(shellune_core::SecretString::expose),
        Some("shared-password"),
        "the remembered host keeps the password the backup says nothing about"
    );
    assert_eq!(
        vault
            .host_secret(arriving_id)
            .map(shellune_core::SecretString::expose),
        Some("arriving-password")
    );
    assert_eq!(
        vault.host_secret_state(dropped_id),
        shellune_storage::HostSecretState::Tombstoned,
        "the host the backup replaced away leaves a tombstone, not an absence"
    );
}

/// A version 1 export that seals host passwords reads them from the open vault
/// only: a locked vault asks for its one unlock before the file is chosen, and
/// the passwords are then in the file (R4).
#[gpui::test]
async fn a_password_backup_export_unlocks_a_locked_vault_first(cx: &mut TestAppContext) {
    let dir = TempDir::new("backup-v1-locked");
    let prod = password_host("prod", "10.0.0.1");
    let prod_id = prod.id();
    seed(&dir.store(), vec![prod]);
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_host_secrets(&dir, secrets.as_ref(), &[(prod_id, "hunter2-secret")]);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Ok(())]),
    );
    let verifier = authenticator.clone();
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_set_authenticator_for_test(authenticator);
            view.security_enable_lock_for_test(shellune_storage::LockPolicy::UnlockVault, 15, cx);
        })
    });
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).security_locked_for_test()));

    click(cx, "settings.category.data");
    click(cx, "settings.backup.export");
    click(cx, "backup.export.secrets");
    type_into(cx, "backup.export.passphrase", "pass-one");
    type_into(cx, "backup.export.confirm", "pass-one");
    click(cx, "backup.export.save");
    assert_eq!(verifier.verify_calls(), 1, "the locked vault asked once");
    assert!(
        cx.did_prompt_for_new_path(),
        "the file is chosen after the unlock"
    );
    let target = dir.path().join("v1.json");
    let chosen = target.clone();
    cx.simulate_new_path_selection(move |_directory| Some(chosen));
    cx.run_until_parked();
    let (_, sealed, ..) = cx
        .update(|_window, app| view.read(app).export_report_for_test())
        .expect("the export wrote its report");
    assert_eq!(sealed, Some(1), "prod's password is in the file");
    assert!(host_entry_accesses(&secrets).is_empty());
}

/// A version 1 import that brings host passwords waits for the vault job
/// running now - a migration here - so neither save drops what the other
/// wrote: both passwords are in the vault at the end (R3, R4).
#[gpui::test]
async fn a_password_import_waits_for_the_running_vault_job(cx: &mut TestAppContext) {
    let dir = TempDir::new("backup-v1-waits");
    let hosts = remembered_hosts(1);
    let old_id = hosts[0].id();
    seed(&dir.store(), hosts.clone());
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    secrets.seed_legacy_host(old_id, &shellune_core::SecretString::new("old-password"));
    let arriving = password_host("arriving", "10.0.0.9");
    let arriving_id = arriving.id();
    let backup = dir.path().join("v1-import.json");
    write_backup(
        &backup,
        vec![arriving],
        Some("right horse"),
        &[(arriving_id, "arriving-password")],
    );
    let (view, cx) = vault_window(cx, &dir, &secrets);

    // The migration's job runs; its finish is held, so the job stays running.
    cx.update(|_window, app| {
        view.update(app, |view, _cx| view.security_hold_finish_for_test(true))
    });
    let (dialling, _) = connect_remembered(&view, cx, &hosts[0]);
    assert!(dialling);

    read_backup(&view, cx, &backup);
    type_into(cx, "backup.import.passphrase", "right horse");
    click(cx, "backup.import.unlock");
    cx.run_until_parked();
    assert_eq!(backup_stage(&view, cx), Some("import.preview"));
    click(cx, "backup.import.apply");
    cx.run_until_parked();
    assert_eq!(
        backup_stage(&view, cx),
        Some("import.applying"),
        "the import waits for the running vault job"
    );

    cx.update(|_window, app| {
        view.update(app, |view, cx| view.security_release_finish_for_test(cx))
    });
    cx.run_until_parked();
    assert_eq!(backup_stage(&view, cx), Some("import.applied"));
    let vault = open_vault(&dir, &secrets);
    assert_eq!(
        vault
            .host_secret(old_id)
            .map(shellune_core::SecretString::expose),
        Some("old-password"),
        "the migrated password is kept"
    );
    assert_eq!(
        vault
            .host_secret(arriving_id)
            .map(shellune_core::SecretString::expose),
        Some("arriving-password"),
        "the imported password is there too"
    );
    assert!(!secrets.holds_legacy_host(old_id));
}

/// Machine A: a sync service over `dir` with its own credential store, which
/// the test keeps so it can write A's vault.
fn sync_machine_with_store(
    dir: &TempDir,
    server: &shellune_sync::testing::WebDavServer,
) -> (
    shellune_sync::SyncService,
    Arc<shellune_storage::MemorySecrets>,
) {
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(dir, &secrets, server, true);
    let service = shellune_sync::SyncService::new(
        shellune_storage::LocalData::at(dir.path()),
        shellune_storage::Platform::current(),
        secrets.clone(),
    )
    .with_kdf(shellune_storage::KdfParams::new(8, 1, 1).expect("cheap parameters"));
    (service, secrets)
}

/// Puts these host passwords into the vault of the machine over `dir`, as a
/// migration there would, keeping what the vault already held.
fn add_host_secrets(
    dir: &TempDir,
    secrets: &shellune_storage::MemorySecrets,
    passwords: &[(HostId, String)],
) {
    let store = shellune_storage::VaultStore::at(dir.path());
    let mut content = match store.open(&shellune_storage::UnsealSource::LocalMachine, secrets) {
        Ok(content) => content,
        Err(shellune_storage::VaultStoreError::Missing { .. }) => {
            shellune_storage::VaultContent::new()
        }
        Err(error) => panic!("the vault opens: {error}"),
    };
    for (id, secret) in passwords {
        content.set_host_secret(*id, shellune_core::SecretString::new(secret.clone()), "a");
    }
    let records = dir.store().load().expect("the hosts read").records();
    store
        .save_records(
            &content,
            &records,
            &[shellune_storage::UnsealSource::LocalMachine],
            shellune_storage::KdfParams::new(8, 1, 1).expect("cheap parameters"),
            secrets,
        )
        .expect("the vault is written");
}

/// B's window over the shared hosts, its credential store and A's passwords.
type MigratedCloud<'a> = (
    Entity<ShelluneView>,
    &'a mut VisualTestContext,
    Arc<shellune_storage::MemorySecrets>,
    Vec<(HostId, String)>,
);

/// Two machines share `count` remembered hosts: B took them in from the cloud,
/// then A moved their passwords into its vault and uploaded it. Returns B's
/// window, its store and A's passwords, which B's next sync pulls.
fn machines_with_migrated_cloud<'a>(
    cx: &'a mut TestAppContext,
    server: &shellune_sync::testing::WebDavServer,
    machine_a: &TempDir,
    machine_b: &TempDir,
    count: usize,
) -> MigratedCloud<'a> {
    let hosts = remembered_hosts(count);
    seed(&machine_a.store(), hosts.clone());
    let (a, secrets_a) = sync_machine_with_store(machine_a, server);
    let _ = a.sync().expect("A uploads its hosts");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    configure_sync(machine_b, &secrets, server, true);
    let (view, cx) = sync_window(cx, machine_b, &secrets, Destination::Hosts);
    assert_eq!(host_names(&view, cx).len(), count, "B took A's hosts in");
    let passwords: Vec<(HostId, String)> = hosts
        .iter()
        .map(|host| (host.id(), format!("pw-{}", host.name())))
        .collect();
    add_host_secrets(machine_a, &secrets_a, &passwords);
    let _ = a.sync().expect("A uploads its vault");
    secrets.clear_accesses();
    (view, cx, secrets, passwords)
}

/// A sync that brings the passwords of many hosts this machine never
/// migrated touches none of their old entries (R4): the vault's live record
/// is read first, and each old entry goes only with its host's own deletion
/// or untick. One sync never becomes one system prompt per host.
#[gpui::test]
async fn a_sync_bringing_many_unmigrated_passwords_touches_no_old_entry(cx: &mut TestAppContext) {
    const COUNT: usize = 25;
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("many-live-a"), TempDir::new("many-live-b"));
    // Both machines hold the same remembered hosts. A moved their passwords
    // into its vault and uploaded it; B never connected to them, so each one
    // still has its old entry and B has no vault.
    let hosts = remembered_hosts(COUNT);
    seed(&machine_a.store(), hosts.clone());
    seed(&machine_b.store(), hosts.clone());
    let (a, secrets_a) = sync_machine_with_store(&machine_a, &server);
    let passwords: Vec<(HostId, String)> = hosts
        .iter()
        .map(|host| (host.id(), format!("pw-{}", host.name())))
        .collect();
    add_host_secrets(&machine_a, &secrets_a, &passwords);
    let _ = a.sync().expect("A uploads its hosts and vault");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    for host in &hosts {
        secrets.seed_legacy_host(host.id(), &shellune_core::SecretString::new("old"));
    }
    configure_sync(&machine_b, &secrets, &server, true);
    assert!(!shellune_storage::VaultStore::at(machine_b.path()).exists());

    // B's window starts, and its first sync brings A's vault.
    let (view, cx) = sync_window(cx, &machine_b, &secrets, Destination::Hosts);
    cx.run_until_parked();
    // Neither side has synced before, so the window asks; taking the cloud's
    // side writes A's vault here.
    assert!(sync_conflict_open(&view, cx));
    click(cx, "sync.conflict.remote");
    cx.run_until_parked();
    let vault = open_vault(&machine_b, &secrets);
    for (id, secret) in &passwords {
        assert_eq!(
            vault
                .host_secret(*id)
                .map(shellune_core::SecretString::expose),
            Some(secret.as_str()),
            "the sync brought every password"
        );
    }
    assert_eq!(
        host_entry_accesses(&secrets),
        Vec::new(),
        "no old entry was read or deleted"
    );
    for (id, _) in &passwords {
        assert!(secrets.holds_legacy_host(*id), "the old entries stay");
    }
    // The window reads the synced password, not the old entry.
    let first = passwords[0].0;
    assert_eq!(
        cx.update(|_window, app| view.read(app).saved_secret_for_test(first))
            .as_deref(),
        Some(passwords[0].1.as_str())
    );
    assert_eq!(host_entry_accesses(&secrets), Vec::new());
}

/// A host password saved while a sync runs waits for it (R4): the sync's
/// vault and the window's job never write at once, and the job is written
/// onto what the sync left, so the passwords it pulled are kept.
#[gpui::test]
async fn a_host_password_saved_during_a_sync_is_written_after_it(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("during-sync-a"), TempDir::new("during-sync-b"));
    let (view, cx, secrets, passwords) =
        machines_with_migrated_cloud(cx, &server, &machine_a, &machine_b, 3);

    // The check pulls A's vault; its finish is held, so the sync still runs.
    hold_sync_finish(&view, cx);
    after_poll(cx);
    assert!(sync_finish_held(&view, cx));

    fill_new_host(cx);
    click(cx, "hosts.auth.remote.method.password");
    type_into(cx, "hosts.field.secret", "box-password");
    click(cx, "hosts.save");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).host_form_save_pending()),
        "the save waits for the sync"
    );
    assert!(
        !cx.update(|_window, app| view.read(app).security_job_running()),
        "no vault job runs beside the sync"
    );

    release_sync_finish(&view, cx);
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).host_form_save_pending()));
    let book = machine_b.store().load().expect("B's hosts read");
    let added = book
        .hosts()
        .iter()
        .find(|host| host.name() == "box")
        .map(shellune_core::HostConfig::id)
        .expect("the new host is saved after the sync");
    let vault = open_vault(&machine_b, &secrets);
    assert_eq!(
        vault
            .host_secret(added)
            .map(shellune_core::SecretString::expose),
        Some("box-password")
    );
    for (id, secret) in &passwords {
        assert_eq!(
            vault
                .host_secret(*id)
                .map(shellune_core::SecretString::expose),
            Some(secret.as_str()),
            "the pulled passwords are kept"
        );
    }
    assert_eq!(host_entry_accesses(&secrets), Vec::new());
}

/// An old entry read for a connection while a sync runs is moved into the
/// vault only if the vault the sync left still has no record for the host
/// (R3, R4): a password the sync pulled for it is not overwritten by the old
/// one.
#[gpui::test]
async fn a_migration_queued_during_a_sync_keeps_the_password_the_sync_pulled(
    cx: &mut TestAppContext,
) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (
        TempDir::new("migrate-during-sync-a"),
        TempDir::new("migrate-during-sync-b"),
    );
    // A shares two remembered hosts and a vault that holds the first one's
    // password; B takes both, and the vault, in.
    let hosts = remembered_hosts(2);
    let (first, target) = (hosts[0].id(), hosts[1].clone());
    seed(&machine_a.store(), hosts.clone());
    let (a, secrets_a) = sync_machine_with_store(&machine_a, &server);
    add_host_secrets(&machine_a, &secrets_a, &[(first, "pw-first".to_owned())]);
    let _ = a.sync().expect("A uploads its hosts and vault");
    let (b, secrets) = sync_machine_with_store(&machine_b, &server);
    let _ = b.sync().expect("B takes A's hosts and vault in");
    drop(b);
    assert_eq!(
        open_vault(&machine_b, &secrets).host_secret_state(target.id()),
        shellune_storage::HostSecretState::Absent
    );
    // B remembered the target's password before the vault, in its old entry.
    let mut book = machine_b.store().load().expect("B's hosts read");
    let mut remembered = book.host(target.id()).expect("arrived").clone();
    remembered.set_remember_secret(true);
    book.update(remembered, target.id()).expect("updated");
    machine_b.store().save(&book).expect("B's hosts written");
    secrets.seed_legacy_host(target.id(), &shellune_core::SecretString::new("old"));
    let (view, cx) = sync_window(cx, &machine_b, &secrets, Destination::Hosts);
    assert_eq!(host_names(&view, cx).len(), 2);
    // A then remembers the target's password in the vault and uploads it.
    add_host_secrets(
        &machine_a,
        &secrets_a,
        &[(target.id(), "pw-synced".to_owned())],
    );
    let _ = a.sync().expect("A uploads the new password");

    // B's check pulls it; its finish is held, so the sync still runs while B
    // connects to the host and reads its old entry.
    hold_sync_finish(&view, cx);
    after_poll(cx);
    assert!(sync_finish_held(&view, cx));
    secrets.clear_accesses();
    let (_, password) = connect_remembered(&view, cx, &target);
    assert_eq!(password, "old", "the old entry is used at once");
    assert!(
        host_entry_accesses(&secrets)
            .iter()
            .any(|access| access.op == shellune_storage::SecretOp::Load),
        "the old entry was read: {:?}",
        secrets.accesses()
    );
    assert!(
        !cx.update(|_window, app| view.read(app).security_job_running()),
        "no vault job runs beside the sync"
    );

    release_sync_finish(&view, cx);
    cx.run_until_parked();
    let vault = open_vault(&machine_b, &secrets);
    assert_eq!(
        vault
            .host_secret(target.id())
            .map(shellune_core::SecretString::expose),
        Some("pw-synced"),
        "the pulled password stands"
    );
    assert_eq!(
        vault
            .host_secret(first)
            .map(shellune_core::SecretString::expose),
        Some("pw-first")
    );
}
/// A sync asked for while a vault job runs waits for the job, and starts
/// when it ends.
#[gpui::test]
async fn a_sync_waits_for_the_running_vault_job(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let (machine_a, machine_b) = (TempDir::new("sync-waits-a"), TempDir::new("sync-waits-b"));
    let (view, cx, secrets, passwords) =
        machines_with_migrated_cloud(cx, &server, &machine_a, &machine_b, 2);
    let (before, _, _) = sync_progress(&view, cx);

    // A vault job runs; its finish is held.
    cx.update(|_window, app| {
        view.update(app, |view, _cx| view.security_hold_finish_for_test(true))
    });
    fill_new_host(cx);
    click(cx, "hosts.auth.remote.method.password");
    type_into(cx, "hosts.field.secret", "box-password");
    click(cx, "hosts.save");
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).security_job_running()));

    after_poll(cx);
    let (during, _, _) = sync_progress(&view, cx);
    assert_eq!(during, before, "the sync waits for the vault job");

    cx.update(|_window, app| {
        view.update(app, |view, cx| view.security_release_finish_for_test(cx))
    });
    cx.run_until_parked();
    let (after, _, _) = sync_progress(&view, cx);
    assert!(after > before, "the sync ran once the job ended");
    let vault = open_vault(&machine_b, &secrets);
    for (id, secret) in &passwords {
        assert_eq!(
            vault
                .host_secret(*id)
                .map(shellune_core::SecretString::expose),
            Some(secret.as_str())
        );
    }
    let added = machine_b
        .store()
        .load()
        .expect("B's hosts read")
        .hosts()
        .iter()
        .find(|host| host.name() == "box")
        .map(shellune_core::HostConfig::id)
        .expect("the new host is saved");
    assert_eq!(
        vault
            .host_secret(added)
            .map(shellune_core::SecretString::expose),
        Some("box-password"),
        "the sync kept what the job wrote"
    );
}

/// An automatic sync never starts while this device's vault is locked and the
/// sync would carry it: the job waits for the unlock, and the unlock starts it
/// again (ADR-4). A manual sync is a person's own decision and always runs.
#[gpui::test]
async fn a_locked_vault_defers_automatic_sync_until_the_unlock(cx: &mut TestAppContext) {
    let server = shellune_sync::testing::WebDavServer::start(SYNC_USER, SYNC_PASSWORD);
    let dir = TempDir::new("sync-defer");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    {
        use shellune_storage::SecretStore as _;
        let mut config = shellune_sync::SyncConfig::new(server.url(), SYNC_USER);
        config.auto = true;
        shellune_sync::SyncConfigStore::at(dir.path())
            .save(&config)
            .expect("the sync settings are written");
        secrets
            .save_app(
                shellune_storage::AppSecret::WebDavPassword,
                &shellune_core::SecretString::new(SYNC_PASSWORD),
            )
            .expect("the password is kept");
    }
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    cx.run_until_parked();
    let uploaded = put_count(&server);
    assert!(uploaded >= 1, "the first automatic sync carried the vault");

    // The protection goes on and locks the vault; the next automatic check
    // defers instead of touching the vault behind the user's back.
    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Ok(())]),
    );
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_set_authenticator_for_test(authenticator);
            view.security_enable_lock_for_test(shellune_storage::LockPolicy::UnlockVault, 15, cx);
        })
    });
    after_poll(cx);
    assert!(
        cx.update(|_window, app| view.read(app).sync_deferred_for_test()),
        "the automatic sync said it is waiting for the unlock"
    );
    assert_eq!(
        put_count(&server),
        uploaded,
        "nothing was sent while the vault was locked"
    );

    // A locked vault page hides active creation controls and fake empty lists;
    // a change written directly to the vault file behind the lock is still only
    // synced once the unlock frees the automatic job.
    click(cx, "settings.category.security");
    click(cx, "settings.item.keys-and-passwords");
    assert!(
        cx.debug_bounds("security.locked").is_some()
            && cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "locked vault shows the unlock card"
    );
    {
        let store = shellune_storage::VaultStore::at(dir.path());
        let mut content = store
            .open(
                &shellune_storage::UnsealSource::LocalMachine,
                secrets.as_ref(),
            )
            .expect("the vault opens on disk");
        content
            .insert_credential(shellune_storage::VaultCredentialRecord::new(
                shellune_core::CredentialMeta::new(
                    shellune_core::CredentialId::new(),
                    "Behind the lock".to_owned(),
                    None,
                    shellune_core::VaultRecordVersion::new(1, "seed"),
                ),
                shellune_core::SecretString::new("another-secret-value"),
            ))
            .expect("the second credential is inserted");
        store
            .save_records(
                &content,
                &[],
                &[
                    shellune_storage::UnsealSource::LocalMachine,
                    shellune_storage::UnsealSource::WebDavPassword(
                        shellune_core::SecretString::new(SYNC_PASSWORD),
                    ),
                ],
                shellune_storage::KdfParams::new(8, 1, 1).expect("cheap parameters"),
                secrets.as_ref(),
            )
            .expect("the vault change is saved behind the lock");
    }
    after_poll(cx);
    assert_eq!(
        put_count(&server),
        uploaded,
        "the change made behind the lock was not sent either"
    );

    // The unlock opens the vault and lets the waiting automatic job through:
    // the change really travels now.
    cx.update(|_window, app| view.update(app, |view, cx| view.security_unlock_for_test(cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "the unlock opened the vault"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_credentials_for_test())
            .len(),
        2,
        "the opened vault holds the seeded record and the one made behind the lock"
    );
    assert!(
        put_count(&server) > uploaded,
        "the unlock let the waiting automatic sync really run"
    );
}

/// The vault half of a conflict is decided record by record: each row carries
/// its own choice, the apply stays inert until every one is answered, and a
/// dismissed question keeps the conflict (ADR-5, R8).
#[gpui::test]
async fn vault_conflicts_are_answered_one_by_one(cx: &mut TestAppContext) {
    let dir = TempDir::new("sync-vault-conflict");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.open_sync_vault_conflict_for_test(cx))
    });
    assert!(sync_conflict_open(&view, cx));
    assert!(
        cx.debug_bounds("sync.vault.conflict.row.0").is_some(),
        "the record's row is drawn"
    );
    assert!(
        cx.debug_bounds("sync.vault.conflict.row.1").is_some(),
        "the trusted identity's row is drawn"
    );

    // Half an answer applies nothing: the question stays as it was.
    click(cx, "sync.vault.conflict.local.0");
    click(cx, "sync.vault.conflict.apply");
    cx.run_until_parked();
    assert!(
        sync_conflict_open(&view, cx),
        "a conflict with an open record applies nothing"
    );

    // The trust row names both fingerprints in full, and answering it lets
    // the choices go.
    click(cx, "sync.vault.conflict.remote.1");
    click(cx, "sync.vault.conflict.apply");
    cx.run_until_parked();
    assert!(
        !sync_conflict_open(&view, cx),
        "the answered choices leave the question"
    );
}

/// A backup that carries the whole vault goes through the same always-verify
/// gate a private-key export does: while the vault is locked, or under the
/// every-operation policy, a cancelled or refused verification leaves no file
/// behind (R3, R9, P1-1).
#[gpui::test]
async fn a_vault_backup_export_refuses_to_leave_a_locked_vault(cx: &mut TestAppContext) {
    let dir = TempDir::new("backup-gate");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Err(shellune_storage::BiometricError::Cancelled)]),
    );
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_set_authenticator_for_test(authenticator.clone());
            view.security_enable_lock_for_test(shellune_storage::LockPolicy::UnlockVault, 15, cx);
        })
    });

    // The vault checkbox is ticked and the passphrase typed; the cancelled
    // verification stops everything before a file is ever asked for.
    click(cx, "settings.category.data");
    click(cx, "settings.backup.export");
    click(cx, "backup.export.vault");
    type_into(
        cx,
        "backup.export.vault.passphrase",
        "correct horse battery",
    );
    type_into(cx, "backup.export.vault.confirm", "correct horse battery");
    click(cx, "backup.export.save");
    cx.run_until_parked();
    assert!(
        !cx.did_prompt_for_new_path(),
        "a cancelled verification asks for no file"
    );
    assert!(
        cx.update(|_window, app| view.read(app).export_report_for_test())
            .is_none(),
        "and no export happened"
    );

    // The every-operation policy asks afresh even with the vault open: a
    // cancelled prompt leaves no file there either.
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_lock_settings_for_test(
                shellune_storage::LockPolicy::EverySensitiveOperation,
                cx,
            );
        })
    });
    click(cx, "backup.export.save");
    cx.run_until_parked();
    assert!(
        !cx.did_prompt_for_new_path(),
        "the every-operation policy gates the vault export too"
    );
    let _ = view;
}

/// A machine whose system offers no verification this app can call enables
/// the biometric switch only behind an explicit risk confirmation, never
/// auto-locks, stays reachable after a restart, and can be turned off again -
/// the storage layer's unlocked-session fallback, not a lock-out (R4, P1-2).
#[gpui::test]
async fn a_machine_without_verification_enables_a_session_only_lock(cx: &mut TestAppContext) {
    let dir = TempDir::new("lock-session-only");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    let authenticator = Arc::new(shellune_storage::ScriptedAuthenticator::new(
        shellune_storage::BiometricCapability::Unavailable,
    ));

    // The switch asks the system first; with nothing to call, the question
    // becomes the explicit risk confirmation.
    cx.update(|_window, app| {
        view.update(app, |view, _cx| {
            view.security_set_authenticator_for_test(authenticator.clone())
        })
    });
    click(cx, "settings.category.security");
    click(cx, "settings.item.lock");
    click(cx, "security.lock.biometric");
    assert!(
        cx.debug_bounds("security.dialog.biometric-risk").is_some(),
        "enabling without a verifier asks for the risk confirmation"
    );
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).security_biometric_for_test()),
        "the confirmed risk turns the switch on"
    );
    assert!(
        !cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "the session-only shape never locks the vault"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_credentials_for_test())
            .len(),
        1,
        "the vault stays readable"
    );
    assert_eq!(
        authenticator.verify_calls(),
        0,
        "no verification was ever claimed from a system with none"
    );

    // A relaunch on the same machine keeps the vault reachable: the start-up
    // decision asks the capability too, not only the saved switch.
    drop(view);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.security_set_authenticator_for_test(authenticator.clone());
            view.security_relaunch_for_test(cx);
        })
    });
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_locked_for_test()),
        "a machine with nothing to ask does not start locked"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_credentials_for_test())
            .len(),
        1,
        "the vault opened the plain way"
    );

    // The switch turns off without a prompt nothing could answer.
    click(cx, "settings.category.security");
    click(cx, "settings.item.lock");
    click(cx, "security.lock.biometric");
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_biometric_for_test()),
        "the session-only shape turns off on the unlocked session's own say-so"
    );
    assert_eq!(
        authenticator.verify_calls(),
        0,
        "turning it off demanded no verification either"
    );
    let saved = shellune_storage::SecurityStore::at(dir.path()).load();
    assert_eq!(saved.biometric_unlock, Some(false));
    let _ = view;
}

// ---------------------------------------------------------------------------
// Home Vault workbench, Command Palette, Topbar lock & Connection integration
