/// The measurement R4 asks for: twenty 512 x 512 images scrolled through the
/// viewport, timed per frame. Printed, and held to a bound a debug build meets.
#[gpui::test]
async fn twenty_large_images_scroll_within_a_frame_budget(cx: &mut TestAppContext) {
    let (pane, cx) = pane_with("", cx);
    let image = sixel_image(512, 512);
    cx.update(|_window, app| {
        pane.update(app, |pane, cx| {
            for index in 0..20 {
                pane.feed_for_test(format!("image {index}\r\n").as_bytes(), cx);
                pane.feed_for_test(&image, cx);
            }
        });
    });
    cx.run_until_parked();
    redraw(cx);
    let mut frames = Vec::new();
    for _ in 0..30 {
        cx.update(|_window, app| pane.update(app, |pane, cx| pane.scroll_for_test(5, cx)));
        let started = std::time::Instant::now();
        redraw(cx);
        frames.push(started.elapsed());
    }
    frames.sort();
    let median = frames[frames.len() / 2];
    let worst = frames[frames.len() - 1];
    eprintln!(
        "R4 image scroll: median {median:?}, worst {worst:?}, cached {} images",
        cx.update(|_window, app| pane.read(app).cached_images_for_test())
    );
    assert!(
        median < std::time::Duration::from_millis(250),
        "median frame {median:?}"
    );
}

#[gpui::test]
async fn osc8_links_show_their_target_on_hover_and_open_only_when_allowed(cx: &mut TestAppContext) {
    let content = "\x1b]8;;https://example.com/docs\x1b\\docs here\x1b]8;;\x1b\\  \
                   \x1b]8;;javascript:alert(1)\x1b\\evil\x1b]8;;\x1b\\";
    let (pane, cx) = pane_with(content, cx);
    let refused = std::rc::Rc::new(std::cell::RefCell::new(
        Vec::<shellune_terminal::LinkRefusal>::new(),
    ));
    let seen = refused.clone();
    let _subscription = cx.update(|_window, app| {
        app.subscribe(
            &pane,
            move |_pane, request: &crate::app::terminal::PaneRequest, _app| {
                if let crate::app::terminal::PaneRequest::LinkRefused(scheme) = request {
                    seen.borrow_mut().push(scheme.clone());
                }
            },
        )
    });
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    let vp = bounds_of(cx, "terminal.viewport");
    let at = |column: f32| {
        point(
            vp.origin.x + px(cell.width * (column + 0.5)),
            vp.origin.y + px(cell.height * 0.5),
        )
    };
    let secondary = if cfg!(target_os = "macos") {
        Modifiers {
            platform: true,
            ..Modifiers::default()
        }
    } else {
        Modifiers {
            control: true,
            ..Modifiers::default()
        }
    };
    let hovered = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| pane.read(app).hovered_link_for_test().map(str::to_owned))
    };
    let opened = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| pane.read(app).opened_urls_for_test().to_vec())
    };

    // A plain hover over an OSC 8 link shows where it goes, without opening it.
    cx.simulate_mouse_move(at(2.0), None, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(hovered(cx), Some("https://example.com/docs".to_owned()));
    assert!(
        cx.debug_bounds("terminal.link_target").is_some(),
        "the target is shown while the link is hovered"
    );

    // A plain click is still a click on text: nothing opens.
    cx.simulate_click(at(2.0), Modifiers::default());
    cx.run_until_parked();
    assert!(opened(cx).is_empty());

    // A plain drag across the link still selects.
    let from = grid_point_at(cx, &pane, 0.5, 0.1);
    assert_eq!(
        drag_in_grid(cx, &pane, from, at(6.0), Modifiers::default()),
        Some("docs he".to_owned()),
        "dragging over a link selects its text"
    );
    assert!(opened(cx).is_empty());

    // Ctrl/Cmd+click opens the stated target.
    cx.simulate_mouse_move(at(2.0), None, secondary);
    cx.simulate_click(at(2.0), secondary);
    cx.run_until_parked();
    assert_eq!(opened(cx), vec!["https://example.com/docs".to_owned()]);

    // Moving off the link hides the target. (GPUI keeps a selector's last debug
    // bounds across frames, so the hover state is what is checked here.)
    cx.simulate_mouse_move(at(30.0), None, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(hovered(cx), None);

    // A javascript: target is refused and named, never opened.
    cx.simulate_mouse_move(at(12.0), None, secondary);
    cx.simulate_click(at(12.0), secondary);
    cx.run_until_parked();
    assert_eq!(opened(cx).len(), 1, "javascript: must not open");
    assert_eq!(
        refused.borrow().as_slice(),
        &[shellune_terminal::LinkRefusal::Scheme(
            "javascript".to_owned()
        )]
    );
    assert!(
        cx.update(|_window, app| pane.read(app).sent().is_empty()),
        "no link interaction reached the shell"
    );
}

/// A pointer resting on a link stays still while the grid moves under it: new
/// output, the wheel and a resize each re-check what it is over, so the underline
/// and target never stay on cells that now hold other text (R1).
#[gpui::test]
async fn a_hovered_osc8_link_follows_the_text_when_the_grid_moves_under_a_still_pointer(
    cx: &mut TestAppContext,
) {
    let mut content = String::new();
    for i in 0..200 {
        content.push_str(&format!("older {i}\r\n"));
    }
    content.push_str("\x1b]8;;https://example.com/a\x1b\\link-a\x1b]8;;\x1b\\");
    let (pane, cx) = pane_with(&content, cx);
    let row = cx.update(|_window, app| {
        pane.read(app)
            .visible_text()
            .iter()
            .position(|line| line.contains("link-a"))
            .expect("the link is on screen")
    });
    let resting = grid_point_at(cx, &pane, row as f32 + 0.5, 2.5);
    let hovered = |cx: &mut VisualTestContext| {
        cx.update(|_window, app| pane.read(app).hovered_link_for_test().map(str::to_owned))
    };
    cx.simulate_mouse_move(resting, None, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(hovered(cx), Some("https://example.com/a".to_owned()));

    // Output scrolls the link up a row; the pointer now rests on plain text.
    cx.update(|_window, app| {
        pane.update(app, |pane, cx| {
            pane.feed_for_test(b"\r\nplain text here", cx)
        });
    });
    cx.run_until_parked();
    redraw(cx);
    assert_eq!(
        hovered(cx),
        None,
        "output moved the link away from the pointer"
    );

    // The wheel brings it back under the pointer: the hover follows the text again.
    cx.simulate_mouse_move(resting, None, Modifiers::default());
    cx.simulate_event(ScrollWheelEvent {
        position: resting,
        delta: ScrollDelta::Lines(point(0.0, 1.0)),
        modifiers: Modifiers::default(),
        touch_phase: Default::default(),
    });
    cx.run_until_parked();
    redraw(cx);
    let visible = cx.update(|_window, app| pane.read(app).visible_text());
    let under = visible.get(row).cloned().unwrap_or_default();
    assert_eq!(
        hovered(cx).is_some(),
        under.contains("link-a"),
        "the hover matches the text under the pointer after the wheel: {under:?}"
    );
}

#[gpui::test]
async fn a_program_that_took_the_mouse_still_gets_plain_clicks_on_an_osc8_link(
    cx: &mut TestAppContext,
) {
    let content = "\x1b[?1000h\x1b]8;;https://example.com\x1b\\link\x1b]8;;\x1b\\";
    let (pane, cx) = pane_with(content, cx);
    let cell = cx.update(|_window, app| pane.read(app).cell_size());
    let vp = bounds_of(cx, "terminal.viewport");
    let on_link = point(
        vp.origin.x + px(cell.width * 1.5),
        vp.origin.y + px(cell.height * 0.5),
    );
    cx.simulate_click(on_link, Modifiers::default());
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| pane.read(app).sent().is_empty()),
        "the click was reported to the program"
    );
    assert!(cx.update(|_window, app| pane.read(app).opened_urls_for_test().is_empty()));
}

#[gpui::test]
async fn terminal_links_context_menu_and_shell_key_passthrough_invariants(cx: &mut TestAppContext) {
    let mut content = String::new();
    for i in 0..60 {
        content.push_str(&format!("older {i}\r\n"));
    }
    content.push_str("Visit https://example.com/guide or ssh://root@10.0.0.1");
    let (pane, cx) = pane_with(&content, cx);
    cx.simulate_resize(design_window());
    cx.run_until_parked();

    let (cell, row_idx) = cx.update(|_window, app| {
        let p = pane.read(app);
        let row_idx = p
            .visible_text()
            .iter()
            .position(|line| line.contains("https://example.com/guide"))
            .expect("url row on screen");
        (p.cell_size(), row_idx)
    });
    let vp_bounds = bounds_of(cx, "terminal.viewport");
    let http_point = point(
        vp_bounds.origin.x + px(cell.width * 10.0),
        vp_bounds.origin.y + px(cell.height * (row_idx as f32 + 0.5)),
    );
    let ssh_point = point(
        vp_bounds.origin.x + px(cell.width * 40.0),
        vp_bounds.origin.y + px(cell.height * (row_idx as f32 + 0.5)),
    );
    let secondary_mods = if cfg!(target_os = "macos") {
        Modifiers {
            platform: true,
            ..Modifiers::default()
        }
    } else {
        Modifiers {
            control: true,
            ..Modifiers::default()
        }
    };

    // Plain hover & plain click over http URL neither underline nor open it.
    cx.simulate_mouse_move(http_point, None, Modifiers::default());
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).hovered_link_for_test().map(str::to_owned)),
        None
    );
    cx.simulate_click(http_point, Modifiers::default());
    cx.run_until_parked();
    assert!(cx.update(|_window, app| pane.read(app).opened_urls_for_test().is_empty()));

    // Ctrl/Cmd + hover underlines http(s) URL; Ctrl/Cmd + click opens it.
    cx.simulate_mouse_move(http_point, None, secondary_mods);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).hovered_link_for_test().map(str::to_owned)),
        Some("https://example.com/guide".to_owned()),
    );
    cx.simulate_click(http_point, secondary_mods);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).opened_urls_for_test().to_vec()),
        vec!["https://example.com/guide".to_owned()],
    );

    // Non-http(s) scheme (ssh://) is rejected by allowlist on both hover and click.
    cx.simulate_mouse_move(ssh_point, None, secondary_mods);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).hovered_link_for_test().map(str::to_owned)),
        None,
    );
    cx.simulate_click(ssh_point, secondary_mods);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).opened_urls_for_test().len()),
        1,
        "ssh:// scheme must never open via Ctrl/Cmd+click"
    );

    // Alternate screen disables URL hover & click.
    cx.update(|_window, app| {
        pane.update(app, |p, cx| {
            p.feed_for_test(b"\x1b[?1049h\x1b[HVisit https://example.com/alt", cx);
        });
    });
    cx.run_until_parked();
    let alt_point = point(
        vp_bounds.origin.x + px(cell.width * 10.0),
        vp_bounds.origin.y + px(cell.height * 0.5),
    );
    cx.simulate_mouse_move(alt_point, None, secondary_mods);
    cx.simulate_click(alt_point, secondary_mods);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).opened_urls_for_test().len()),
        1,
        "alternate screen must never intercept Ctrl/Cmd+click for URLs"
    );
    cx.update(|_window, app| {
        pane.update(app, |p, cx| p.feed_for_test(b"\x1b[?1049l", cx));
    });
    cx.run_until_parked();

    // Right-click over http(s) URL shows Open link & Copy link, plus snippets/split/clear.
    cx.simulate_mouse_down(http_point, MouseButton::Right, Modifiers::default());
    cx.simulate_mouse_up(http_point, MouseButton::Right, Modifiers::default());
    cx.run_until_parked();
    for selector in [
        "terminal.menu.open_link",
        "terminal.menu.copy_link",
        "terminal.menu.clear",
        "terminal.menu.snippets",
        "terminal.menu.split_right",
        "terminal.menu.split_down",
    ] {
        assert!(
            cx.debug_bounds(selector).is_some(),
            "terminal right-click menu over URL must offer {selector}"
        );
    }
    click(cx, "terminal.menu.copy_link");
    assert_eq!(
        cx.update(|_window, app| pane.read(app).last_copy().map(str::to_owned)),
        Some("https://example.com/guide".to_owned())
    );

    // Clear terminal & scrollback wipes both screen and history without seizing Ctrl+L.
    assert!(cx.update(|_window, app| pane.read(app).history_len()) > 0);
    right_click(cx, "terminal.viewport");
    click(cx, "terminal.menu.clear");
    assert_eq!(cx.update(|_window, app| pane.read(app).history_len()), 0);
    assert!(
        cx.update(|_window, app| {
            pane.read(app)
                .visible_text()
                .iter()
                .all(|line| line.trim().is_empty())
        }),
        "clear_terminal_and_scrollback wipes the visible primary screen too"
    );

    // Strict passthrough invariant: Esc (0x1b), Ctrl+C without selection (0x03), Ctrl+L (0x0c).
    cx.update(|window, app| window.focus(pane.read(app).focus_handle()));
    cx.simulate_keystrokes("escape ctrl-c ctrl-l");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| pane.read(app).sent().to_vec()),
        vec![0x1b, 0x03, 0x0c],
        "Esc, unselected Ctrl+C and Ctrl+L must pass straight through to the shell"
    );
}

#[gpui::test]
async fn snippets_drawer_keyboard_flow_formatted_hint_and_global_tool_entrypoints(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("snippets-and-global-tools");
    seed(
        &dir.store(),
        vec![stored_host("web", "10.0.0.5", 22, "deploy", None)],
    );
    let mut book = shellune_core::SnippetBook::new();
    book.create("check disk", "df -h").expect("snippet 1");
    book.create("check mem", "free -m").expect("snippet 2");
    book.create("multi step", "echo step1\necho step2")
        .expect("snippet 3");
    shellune_storage::SnippetStore::at(dir.path())
        .save(&book)
        .expect("save snippets");

    let (view, cx) = snippet_view(app_cx, &dir);
    let session = live_remote(cx, &view);
    show_remote_terminal(cx, &view, session);

    // Right-click terminal -> Snippets… opens Tool::Snippets directly with search focused.
    right_click(cx, "terminal.viewport");
    click(cx, "terminal.menu.snippets");
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Snippets)
    );
    assert!(
        cx.debug_bounds("snippets.keys.hint").is_some(),
        "snippet keyboard hint is shown"
    );
    // Verify {run_key} placeholder is properly substituted in both locales.
    for locale in [Locale::English, Locale::Chinese] {
        let ux = copy::ux_for(locale);
        let filled = copy::fill(ux.snippet_keys_hint, &[("run_key", "Ctrl+Enter")]);
        assert!(
            !filled.contains("{run_key}"),
            "{locale:?} snippet_keys_hint left {{run_key}} unformatted: {filled}"
        );
    }

    // Immediate typing filters to "check mem", and Ctrl/Cmd+Enter executes & closes & returns focus!
    cx.simulate_input("mem");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .snippet_panel()
                .filtered_indices(view.read(app).snippets().snippets())
                .len()
        }),
        1
    );
    let run_stroke = format!("{}-enter", Platform::current().keystroke_modifier());
    cx.simulate_keystrokes(&run_stroke);
    cx.run_until_parked();
    assert_eq!(
        String::from_utf8_lossy(&snippet_sent(cx, &view, session)),
        "free -m\r",
        "Ctrl/Cmd+Enter runs the filtered snippet once"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        None,
        "running a snippet auto-closes the snippet drawer"
    );
    assert!(
        cx.update(|window, app| {
            view.read(app)
                .pane_of(session)
                .is_some_and(|p| p.read(app).focus_handle().is_focused(window))
        }),
        "auto-closing the snippet drawer returns focus to the active terminal"
    );

    // Multiline snippet closes drawer and routes through paste confirmation before sending.
    let before_multi = snippet_sent(cx, &view, session).len();
    cx.update(|_window, app| view.update(app, |v, cx| v.open_snippets(false, cx)));
    cx.run_until_parked();
    cx.simulate_input("multi");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        None
    );
    assert!(
        cx.update(|_window, app| view.read(app).paste_prompt_open_for_test(app)),
        "multiline snippet still opens the paste confirmation dialog"
    );
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        before_multi,
        "nothing is written before paste confirmation"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();

    // Global tool entry points: 1) Command Palette ("snippets", "transfers", "forwards", "batch")
    for (query, expected_tool) in [
        ("snippets", Some(crate::app::view::Tool::Snippets)),
        ("transfers", Some(crate::app::view::Tool::Transfers)),
        ("forwards", Some(crate::app::view::Tool::Forwards)),
    ] {
        go(cx, crate::app::actions::OpenPalette);
        cx.simulate_input(query);
        cx.run_until_parked();
        assert!(
            !cx.update(|_window, app| view.read(app).palette_titles().is_empty()),
            "palette query {query:?} finds a global entry"
        );
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(
            cx.update(|_window, app| view.read(app).tool_for_test()),
            expected_tool,
            "palette query {query:?} opens {expected_tool:?}"
        );
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
    }
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input("batch");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("batch.dialog").is_some(),
        "palette query 'batch' opens the Batch Tasks center"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();

    // Global tool entry points: 2) Terminal session.more menu
    click(cx, "session.more");
    for selector in [
        "session.more.snippets",
        "session.more.transfers",
        "session.more.global_forwards",
        "session.more.batch",
    ] {
        assert!(
            cx.debug_bounds(selector).is_some(),
            "session.more menu offers {selector}"
        );
    }
    click(cx, "session.more.transfers");
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Transfers)
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();

    // Global tool entry points: 3) Home hosts.more menu
    click(cx, "nav.hosts");
    click(cx, "hosts.more");
    for selector in [
        "hosts.more.snippets",
        "hosts.more.transfers",
        "hosts.more.forwards",
        "hosts.batch.open.list",
    ] {
        assert!(
            cx.debug_bounds(selector).is_some(),
            "hosts.more menu offers {selector}"
        );
    }
    click(cx, "hosts.more.forwards");
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Forwards)
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();

    // Closing Tool::Snippets via Escape or close button restores prior non-terminal field focus
    // (hosts.search and vault security.search) instead of losing it to snippet_panel.search_field.
    let hosts_search_focused = |cx: &mut VisualTestContext| {
        let handle = cx.update(|_window, app| view.read(app).hosts_search_focus_for_test(app));
        cx.update(|window, _app| handle.is_focused(window))
    };
    click(cx, "hosts.search");
    assert!(
        hosts_search_focused(cx),
        "hosts.search holds focus before opening snippets"
    );
    click(cx, "hosts.more");
    click(cx, "hosts.more.snippets");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Snippets)
    );
    cx.simulate_input("mem");
    cx.run_until_parked();
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(
        hosts_search_focused(cx),
        "closing Tool::Snippets with Escape restores focus to hosts.search"
    );

    // Also via Command Palette -> ManageSnippets -> close button (`snippets.dialog.close`).
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input("snippets");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    cx.simulate_input("mem");
    cx.run_until_parked();
    click(cx, "snippets.dialog.close");
    cx.run_until_parked();
    assert!(
        hosts_search_focused(cx),
        "closing Tool::Snippets with close button restores focus to hosts.search"
    );

    // Vault search (`security.search`) focus is likewise preserved across Tool::Snippets.
    let vdir = TempDir::new("snippets-vault-focus");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&vdir, &secrets);
    shellune_storage::SnippetStore::at(vdir.path())
        .save(&book)
        .expect("save snippets");
    let (vview, vcx) = vault_window(app_cx, &vdir, &secrets);
    vcx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    vcx.simulate_resize(design_window());
    click(vcx, "nav.hosts");
    click(vcx, "hosts.view.vault");
    vcx.run_until_parked();
    click(vcx, "security.search");
    let vault_search_focused = |vcx: &mut VisualTestContext| {
        let handle = vcx.update(|_window, app| vview.read(app).security_search_focus(app));
        vcx.update(|window, _app| handle.is_focused(window))
    };
    assert!(
        vault_search_focused(vcx),
        "security.search holds focus before opening snippets"
    );
    go(vcx, crate::app::actions::OpenPalette);
    vcx.simulate_input("snippets");
    vcx.run_until_parked();
    vcx.simulate_keystrokes("enter");
    vcx.run_until_parked();
    vcx.simulate_input("disk");
    vcx.run_until_parked();
    vcx.simulate_keystrokes("escape");
    vcx.run_until_parked();
    assert!(
        vault_search_focused(vcx),
        "closing Tool::Snippets restores focus to Vault security.search"
    );
}

#[gpui::test]
async fn pending_tab_menu_ssh_duplicate_menu_alignment_split_zoom_and_background_banner(
    cx: &mut TestAppContext,
) {
    // 1. Restored pending tabs answer right-click with tab.menu (connect, duplicate, rename, accents, move, close).
    let dir = TempDir::new("pending-tab-and-ssh-dup");
    seed(
        &dir.store(),
        vec![stored_host("prod-ssh", "10.0.0.42", 22, "ops", None)],
    );
    let host_id = dir.store().load().expect("hosts").hosts()[0].id();
    let pending_tabs = vec![
        WorkspaceTab::new(
            "pending-one",
            PaneNode::leaf(PaneTarget::remote(host_id), TerminalMode::Classic),
        )
        .expect("tab 1"),
        WorkspaceTab::new(
            "pending-two",
            PaneNode::leaf(PaneTarget::remote(host_id), TerminalMode::Classic),
        )
        .expect("tab 2"),
    ];
    let first_tab_id = pending_tabs[0].id();
    let snapshot = WorkspaceSnapshot::new(pending_tabs, PanelConfig::default()).expect("snapshot");
    WorkspaceStore::at(dir.path())
        .save(&snapshot)
        .expect("save workspace");

    let (view, vcx) = cx.add_window_view(|_window, cx| {
        ShelluneView::with_store_and_trust(
            cx,
            Workspace::new(),
            HostStore::at(dir.path()),
            TrustStore::at(dir.path()),
        )
    });
    vcx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    vcx.simulate_resize(design_window());
    vcx.run_until_parked();

    right_click(vcx, "session.tab.0");
    assert!(
        vcx.debug_bounds("tab.menu").is_some(),
        "right-clicking a restored pending tab opens tab.menu"
    );
    for selector in [
        "tab.menu.connect",
        "tab.menu.duplicate",
        "tab.menu.rename",
        "tab.menu.forwards",
        "tab.menu.accents",
        "tab.menu.move_right",
        "tab.menu.close",
        "tab.menu.close_others",
        "tab.menu.close_right",
    ] {
        assert!(
            vcx.debug_bounds(selector).is_some(),
            "pending tab right-click menu offers {selector}"
        );
    }
    click(vcx, "tab.menu.move_right");
    assert_eq!(
        vcx.update(|_window, app| view.read(app).workspace().layout().tabs()[1].id()),
        first_tab_id,
        "Move Right reorders a pending tab cleanly"
    );

    // 2. SSH duplicate_session stays in Destination::LocalShells and opens/switches to a new tab
    //    instead of jumping back to Destination::Hosts; tab.menu & session.more align on core items.
    let (ssh_view, ssh_cx) = remote_view(cx);
    ssh_cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    ssh_cx.simulate_resize(design_window());
    let ssh_one = live_remote(ssh_cx, &ssh_view);
    show_remote_terminal(ssh_cx, &ssh_view, ssh_one);

    // Check alignment between tab.menu and session.more when >1 tabs exist after duplicating.
    right_click(ssh_cx, "session.tab.0");
    for selector in [
        "tab.menu.duplicate",
        "tab.menu.rename",
        "tab.menu.forwards",
        "tab.menu.accents",
        "tab.menu.close",
    ] {
        assert!(
            ssh_cx.debug_bounds(selector).is_some(),
            "tab.menu missing {selector}"
        );
    }
    click(ssh_cx, "tab.menu.duplicate");
    ssh_cx.run_until_parked();
    assert_eq!(
        ssh_cx.update(|_window, app| ssh_view.read(app).workspace().destination()),
        Destination::LocalShells,
        "duplicating an SSH tab must stay in the terminal workspace instead of jumping to Hosts"
    );
    assert_eq!(
        ssh_cx.update(|_window, app| ssh_view.read(app).workspace().layout().tabs().len()),
        2,
        "duplicating an SSH tab immediately creates a second session tab"
    );
    let duplicated_active = ssh_cx.update(|_window, app| ssh_view.read(app).active_session());
    assert!(
        duplicated_active.is_some() && duplicated_active != Some(ssh_one),
        "duplicated SSH tab becomes the active session immediately"
    );
    assert!(
        ssh_cx.update(|_window, app| ssh_view.read(app).connection_inline_for_test()),
        "duplicated interactive-auth SSH tab renders its inline connection form"
    );
    assert!(
        ssh_cx.debug_bounds("remote.hide").is_none(),
        "idle pre-dial duplicated SSH form must not offer remote.hide"
    );

    // Type a password in the duplicated tab's form, switch back to live ssh_one tab,
    // then switch back to the duplicated tab via click, select_tab, and Command Palette:
    // the inline password form, its typed secret, and password field focus all survive.
    type_into(ssh_cx, "remote.password", "dup-secret-pw");
    assert_eq!(
        ssh_cx.update(|_window, app| ssh_view.read(app).remote_password_text_for_test(app)),
        "dup-secret-pw"
    );
    click(ssh_cx, "session.tab.0");
    assert!(
        !ssh_cx.update(|_window, app| ssh_view.read(app).connection_inline_for_test()),
        "switching to live tab hides the inline connection form"
    );
    click(ssh_cx, "session.tab.1");
    assert!(
        ssh_cx.update(|_window, app| ssh_view.read(app).connection_inline_for_test()),
        "clicking back to duplicated SSH tab restores its inline password form instead of a stuck spinner"
    );
    assert_eq!(
        ssh_cx.update(|_window, app| ssh_view.read(app).remote_password_text_for_test(app)),
        "dup-secret-pw",
        "typed password survives switching tabs away and back"
    );
    assert!(
        ssh_cx.update(|window, app| {
            ssh_view
                .read(app)
                .remote_password_focus_for_test(app)
                .is_focused(window)
        }),
        "clicking back to duplicated SSH tab focuses its password input"
    );

    // Also verify select_tab(0) -> select_tab(1) preserves the inline form.
    ssh_cx.update(|window, app| ssh_view.update(app, |v, cx| v.select_tab(0, window, cx)));
    ssh_cx.run_until_parked();
    ssh_cx.update(|window, app| ssh_view.update(app, |v, cx| v.select_tab(1, window, cx)));
    ssh_cx.run_until_parked();
    assert!(
        ssh_cx.update(|_window, app| ssh_view.read(app).connection_inline_for_test()),
        "select_tab(1) restores the duplicated SSH tab's inline password form"
    );

    // Once the duplicated SSH tab actually starts dialling (in_flight), remote.hide appears
    // and clicking it steps back to the live terminal tab inside LocalShells rather than Hosts.
    ssh_cx.update(|_window, app| {
        ssh_view.update(app, |v, cx| v.script_remote_attempt(Vec::new(), cx));
    });
    wait_for_loading_card(ssh_cx);
    assert!(
        ssh_cx.debug_bounds("remote.hide").is_some(),
        "once in_flight, remote.hide is offered"
    );
    click(ssh_cx, "remote.hide");
    assert_eq!(
        ssh_cx.update(|_window, app| ssh_view.read(app).workspace().destination()),
        Destination::LocalShells,
        "hiding an in-flight duplicated SSH connection in a multi-tab workspace stays in LocalShells"
    );
    assert_eq!(
        ssh_cx.update(|_window, app| ssh_view.read(app).active_session()),
        Some(ssh_one),
        "hiding the duplicated attempt activates the live terminal tab"
    );

    // Switch back to live ssh_one tab and verify session.more aligns on rename, accents, forwards, close_others, close_right.
    click(ssh_cx, "session.tab.0");
    click(ssh_cx, "session.more");
    for selector in [
        "session.more.duplicate",
        "session.more.rename",
        "session.more.accents",
        "session.more.forwards",
        "session.more.close",
        "session.more.close_others",
        "session.more.close_right",
    ] {
        assert!(
            ssh_cx.debug_bounds(selector).is_some(),
            "session.more missing aligned item {selector}"
        );
    }
    ssh_cx.simulate_keystrokes("escape");
    ssh_cx.run_until_parked();

    // Narrow/short window layout guard across 720x480, 520x480, 440x480 and Dark/Light themes.
    for appearance in [theme::Appearance::Dark, theme::Appearance::Light] {
        theme::set_appearance(appearance);
        for win_size in [
            size(px(720.0), px(480.0)),
            size(px(520.0), px(480.0)),
            size(px(440.0), px(480.0)),
        ] {
            ssh_cx.simulate_resize(win_size);
            ssh_cx.run_until_parked();
            let vp = ssh_cx.update(|w, _| w.viewport_size());
            assert_fits_inside(bounds_of(ssh_cx, "terminal.bar"), vp, "terminal.bar");
            ssh_cx.dispatch_action(crate::app::keymap::ToggleFocusMode);
            ssh_cx.run_until_parked();
            assert_fits_inside(bounds_of(ssh_cx, "focus.mode.exit"), vp, "focus.mode.exit");
            ssh_cx.dispatch_action(crate::app::keymap::ToggleFocusMode);
            ssh_cx.run_until_parked();
        }
    }
    theme::set_appearance(theme::Appearance::Dark);

    // 3. Split divider keyboard focus, inactive pane 1-click zoom + header double-click zoom,
    //    and background inactive split pane disconnect banner + 1-click reconnect.
    let Some((split_view, split_cx, left_id, right_id)) = split_tab(cx) else {
        return;
    };
    let (left_pane_id, _right_pane_id) = split_cx.update(|_window, app| {
        let leaves = split_view.read(app).workspace().layout().leaves();
        (leaves[0].id(), leaves[1].id())
    });

    // Keyboard-focusing the split divider reveals nudge buttons and nudges with arrow keys.
    assert!(split_cx.debug_bounds("pane.resize.more").is_none());
    split_cx.update(|window, app| {
        split_view.update(app, |v, cx| {
            v.focus_first_split_divider_for_test(window, cx)
        });
    });
    split_cx.run_until_parked();
    assert!(
        split_cx.debug_bounds("pane.resize.less").is_some()
            && split_cx.debug_bounds("pane.resize.more").is_some(),
        "focusing the split divider reveals the 24x24 nudge buttons"
    );
    let ratio_before =
        split_cx.update(|_window, app| split_view.read(app).layout_ratios_for_test()[0].1);
    split_cx.simulate_keystrokes("right escape");
    split_cx.run_until_parked();
    let ratio_after =
        split_cx.update(|_window, app| split_view.read(app).layout_ratios_for_test()[0].1);
    assert!(
        ratio_after > ratio_before,
        "Right arrow nudges focused LeftRight divider"
    );

    // Inactive pane (left_pane_id) offers 1-click Zoom button without pre-activating.
    let inactive_zoom_sel: &'static str =
        Box::leak(format!("pane.zoom.{left_pane_id}").into_boxed_str());
    let zbounds = split_cx
        .debug_bounds(inactive_zoom_sel)
        .expect("inactive split pane header exposes one-click zoom button");
    assert!(zbounds.size.width >= px(24.0) && zbounds.size.height >= px(24.0));
    split_cx.simulate_click(zbounds.center(), Modifiers::default());
    split_cx.run_until_parked();
    assert_eq!(
        split_cx.update(|_window, app| split_view.read(app).active_session()),
        Some(left_id),
        "clicking zoom on an inactive pane focuses it"
    );
    assert!(
        split_cx.update(|_window, app| {
            split_view
                .read(app)
                .workspace()
                .layout()
                .active_tab()
                .and_then(|t| t.zoomed())
                == Some(left_pane_id)
        }),
        "clicking zoom on an inactive pane zooms it in one click"
    );

    // Double-clicking the pane header toggles zoom back off, and focus returns cleanly.
    let head_sel: &'static str = Box::leak(format!("pane.head.{left_pane_id}").into_boxed_str());
    let head_bounds = split_cx.debug_bounds(head_sel).expect("pane header");
    let head_point = point(head_bounds.origin.x + px(24.0), head_bounds.center().y);
    split_cx.simulate_event(gpui::MouseDownEvent {
        position: head_point,
        button: MouseButton::Left,
        modifiers: Modifiers::default(),
        click_count: 2,
        first_mouse: false,
    });
    split_cx.simulate_event(gpui::MouseUpEvent {
        position: head_point,
        button: MouseButton::Left,
        modifiers: Modifiers::default(),
        click_count: 2,
    });
    split_cx.run_until_parked();
    assert!(
        split_cx.update(|_window, app| {
            split_view
                .read(app)
                .workspace()
                .layout()
                .active_tab()
                .and_then(|t| t.zoomed())
                .is_none()
        }),
        "double-clicking a split pane header toggles zoom"
    );

    // Focus right_id again so left_id is an INACTIVE background split pane, then drop left_id's connection:
    // top disconnect banner + Reconnect button must appear on left_id immediately BEFORE activation!
    let right_bounds = bounds_of(split_cx, "pane.idle");
    split_cx.simulate_click(right_bounds.center(), Modifiers::default());
    split_cx.run_until_parked();
    assert_eq!(
        split_cx.update(|_window, app| split_view.read(app).active_session()),
        Some(right_id)
    );
    split_cx.update(|_window, app| {
        if let Some(left_pane) = split_view.read(app).pane_of(left_id).cloned() {
            let tag = left_pane.read(app).tag();
            left_pane.update(app, |p, cx| {
                p.adopt_events(
                    tag,
                    vec![crate::app::terminal::SourceEvent::Lost(
                        "background channel dropped".to_owned(),
                    )],
                    cx,
                );
            });
        }
        split_view.update(app, |v, cx| {
            let _ = v
                .workspace_mut_for_test()
                .session_failed(left_id, shellune_core::SessionFailure::ConnectionLost);
            cx.notify();
        });
    });
    split_cx.run_until_parked();
    assert_eq!(
        split_cx.update(|_window, app| split_view.read(app).active_session()),
        Some(right_id),
        "right pane is still the active pane"
    );
    assert!(
        split_cx.debug_bounds("terminal.failure").is_some()
            && split_cx.debug_bounds("terminal.failure.next").is_some(),
        "inactive background split pane immediately displays its top disconnect banner and Reconnect button"
    );
}

#[gpui::test]
async fn vault_gate_never_leaks_operation_granted_and_resume_chain_tracks_parked_and_switched_sessions(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("vault-gate-no-grant-leak-and-parked-chain");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());

    // Seed one vault managed key + one vault shared credential + one RDP connection + two SSH hosts.
    let generated = shellune_ssh::keys::generate(shellune_ssh::keys::ManagedKeyKind::Ed25519)
        .expect("generate ed25519 key");
    let public = shellune_ssh::keys::public_data(&generated).expect("public key data");
    let pem = shellune_ssh::keys::export_private_key(&generated, None).expect("export key");
    let key_id = shellune_core::KeyId::new();
    let cred_id = shellune_core::CredentialId::new();
    let mut content = shellune_storage::VaultContent::new();
    content
        .insert_key(shellune_storage::VaultKeyRecord::new(
            shellune_core::ManagedKeyMeta::new(
                key_id,
                "Vault SSH key".to_owned(),
                public.algorithm,
                public.authorized_key,
                public.fingerprint,
                None,
                shellune_core::VaultRecordVersion::new(1, "seed"),
            ),
            pem,
        ))
        .expect("insert key");
    content
        .insert_credential(shellune_storage::VaultCredentialRecord::new(
            shellune_core::CredentialMeta::new(
                cred_id,
                "Vault shared pass".to_owned(),
                Some("ops".to_owned()),
                shellune_core::VaultRecordVersion::new(1, "seed"),
            ),
            shellune_core::SecretString::new("super-secret-pass"),
        ))
        .expect("insert credential");
    shellune_storage::VaultStore::at(dir.path())
        .save_records(
            &content,
            &[],
            &[shellune_storage::UnsealSource::LocalMachine],
            shellune_storage::KdfParams::new(8, 1, 1).expect("cheap kdf"),
            secrets.as_ref(),
        )
        .expect("save vault");

    let mut book = shellune_storage::HostBook::new();
    let mut rdp_cfg =
        shellune_core::RdpConfig::new("Vault RDP", "127.0.0.1", Some("ops")).expect("rdp config");
    rdp_cfg.set_port(1).expect("closed port");
    rdp_cfg.set_credential_id(Some(cred_id));
    let rdp_record = shellune_core::ConnectionRecord::Rdp(rdp_cfg);
    let rdp_id = rdp_record.id();
    book.insert_connection(rdp_record).expect("insert rdp");

    let mut ssh_vault =
        shellune_core::HostConfig::new("vault-ssh", "127.0.0.1", 1, "ops").expect("ssh_vault");
    ssh_vault.set_auth(Some(shellune_core::AuthMethodKind::ManagedKey));
    ssh_vault.set_managed_key_id(Some(key_id));
    book.insert(ssh_vault.clone()).expect("insert ssh_vault");

    let mut ssh_plain =
        shellune_core::HostConfig::new("plain-ssh", "127.0.0.1", 1, "guest").expect("ssh_plain");
    ssh_plain.set_auth(Some(shellune_core::AuthMethodKind::Password));
    let ssh_plain_id = ssh_plain.id();
    book.insert(ssh_plain).expect("insert ssh_plain");
    dir.store().save(&book).expect("save hosts");

    // Scripted answers:
    // 1) Ok(()) -> initial unlock
    // 2) Ok(()) -> ExportKey verification held while dialog closes on Esc
    // 3) Err(Cancelled) -> proves subsequent sensitive op STILL verifies instead of consuming leaked grant
    // 4) Ok(()) -> Desktop verification held while target session closes
    // 5) Err(Cancelled) -> proves subsequent sensitive op STILL verifies after closed desktop session
    // 6) Ok(()) -> initial `open_remote(&ssh_vault)` to mount the live SSH tab
    // 7) Err(Cancelled) -> parked duplicate SSH chain verification cancelled -> writes form_error on parked attempt
    // 8) Ok(()) -> parked duplicate SSH chain verification approved while plain-ssh form is open -> dials parked tab only
    let auth = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([
            Ok(()),
            Ok(()),
            Err(shellune_storage::BiometricError::Cancelled),
            Ok(()),
            Err(shellune_storage::BiometricError::Cancelled),
            Ok(()),
            Err(shellune_storage::BiometricError::Cancelled),
            Ok(()),
        ]),
    );
    let mut ws = Workspace::new();
    ws.select(Destination::Hosts);
    let store = dir.store();
    let secrets_dyn: Arc<dyn shellune_storage::SecretStore> = secrets.clone();
    let (view, cx) = app_cx.add_window_view(move |_window, cx| {
        let mut v = ShelluneView::with_secrets_for_test(cx, ws, store, secrets_dyn);
        v.security_set_authenticator_for_test(auth);
        v.security_enable_lock_for_test(
            shellune_storage::LockPolicy::EverySensitiveOperation,
            15,
            cx,
        );
        v.security_unlock_for_test(cx);
        v
    });
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(size(px(1280.0), px(860.0)));
    cx.run_until_parked();

    // 1A. Start ExportKey verification, close dialog with Esc BEFORE verification resolves, then release Ok(()).
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    click(cx, "security.key.0");
    click(cx, "security.detail.action.2");
    cx.run_until_parked();
    click(cx, "security.dialog.export.plain");
    click(cx, "security.dialog.export.risk");
    cx.update(|_window, app| view.update(app, |v, _cx| v.security_hold_verify_for_test(true)));
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    // Dismiss the export dialog while system verification is still waiting.
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_dialog_open()),
        "export dialog closed while verification was pending"
    );
    cx.update(|_window, app| view.update(app, |v, cx| v.security_release_verify_for_test(cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_operation_granted_for_test()),
        "operation_granted must be cleared even when ExportKey returned early after dialog dismissal"
    );
    // Subsequent sensitive operation (reveal credential) MUST ask the verifier (consuming answer #3 Cancelled).
    click(cx, "security.credential.0");
    click(cx, "security.detail.reveal");
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "subsequent sensitive operation was NOT bypassed by a leaked operation_granted flag"
    );

    // 1B. Start RDP connection under EverySensitiveOperation, close its tab while verification is held,
    //     release Ok(()) (#4), and prove the next RDP connection (#5 Cancelled) still hits the gate!
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.security_hold_verify_for_test(true);
            v.connect_saved_connection(rdp_id, cx);
        });
    });
    cx.run_until_parked();
    let waiting_rdp = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("waiting rdp session");
    cx.update(|_window, app| view.update(app, |v, cx| v.close_session(waiting_rdp, cx)));
    cx.run_until_parked();
    cx.update(|_window, app| view.update(app, |v, cx| v.security_release_verify_for_test(cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_operation_granted_for_test()),
        "operation_granted must be false after target desktop tab closed mid-verification"
    );
    cx.update(|_window, app| view.update(app, |v, cx| v.connect_saved_connection(rdp_id, cx)));
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_start_count_for_test()),
        0,
        "next desktop connection still goes through verification instead of bypassing via stale grant"
    );
    let cancelled_rdp = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("cancelled rdp session");
    cx.update(|_window, app| view.update(app, |v, cx| v.close_session(cancelled_rdp, cx)));
    cx.run_until_parked();

    // 1C. Mount a live SSH tab for `ssh_vault` (#6 Ok), duplicate it while verification is held,
    //     switch back to the original tab (parking the duplicate), and release Cancelled (#7).
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.open_remote(&ssh_vault, cx);
        });
    });
    cx.run_until_parked();
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.script_remote_attempt(
                vec![
                    shellune_ssh::RemoteEvent::Connected,
                    shellune_ssh::RemoteEvent::Data(b"vault ready\r\n$ ".to_vec()),
                ],
                cx,
            );
        });
    });
    cx.run_until_parked();
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.pump_remote_once(cx);
        });
    });
    cx.run_until_parked();
    let live_ssh_id = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("live ssh session");
    cx.update(|window, app| {
        view.update(app, |v, cx| {
            v.security_hold_verify_for_test(true);
            v.duplicate_session(live_ssh_id, window, cx);
        });
    });
    cx.run_until_parked();
    let dup_id = cx
        .update(|_window, app| view.read(app).active_session())
        .expect("duplicated ssh session");
    assert_ne!(dup_id, live_ssh_id);
    assert!(
        cx.debug_bounds("remote.verifying").is_some(),
        "duplicated vault SSH session shows verifying state"
    );

    // Switch back to `live_ssh_id`, parking `dup_id`'s connection form into `self.attempts`.
    cx.update(|_window, app| view.update(app, |v, cx| v.activate(live_ssh_id, cx)));
    cx.run_until_parked();
    cx.update(|_window, app| view.update(app, |v, cx| v.security_release_verify_for_test(cx)));
    cx.run_until_parked();

    // Switching back to `dup_id` reveals the cancellation banner written onto the parked attempt!
    cx.update(|_window, app| view.update(app, |v, cx| v.activate(dup_id, cx)));
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("remote.form.error").is_some(),
        "cancelled verification writes cancellation reason onto the parked duplicate attempt"
    );

    // 1D. Retry `dup_id` with verification held, then open plain-password `ssh_plain`:
    //     `ssh_plain` must NOT be shown as verifying, and releasing Ok(()) (#7) must dial
    //     ONLY parked `dup_id` in the background while keeping `ssh_plain` on screen!
    cx.update(|_window, app| view.update(app, |v, _cx| v.security_hold_verify_for_test(true)));
    click(cx, "remote.connect");
    cx.run_until_parked();
    assert!(cx.debug_bounds("remote.verifying").is_some());

    cx.update(|_window, app| {
        let plain = view.read(app).book().host(ssh_plain_id).cloned().unwrap();
        view.update(app, |v, cx| v.open_remote(&plain, cx));
    });
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !cx.update(|_window, app| view.read(app).security_verifying_for_chain()),
        "opening another plain-password host while dup_id awaits verification never marks host B as verifying"
    );
    // In `verifying_vault` mode `remote.connect` has no click handler (`ControlState::Loading`);
    // on `plain-ssh` clicking `remote.connect` with empty password immediately runs `connect_remote`!
    click(cx, "remote.connect");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| {
            view.read(app)
                .remote_state()
                .and_then(|panel| panel.form_error())
                .is_some()
        }),
        "plain-ssh Connect button remains interactive while dup_id awaits vault verification"
    );

    cx.update(|_window, app| view.update(app, |v, cx| v.security_release_verify_for_test(cx)));
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).attempt_generation_for_test(dup_id).is_some()),
        "verification approval dials the parked duplicate SSH attempt in the background"
    );
    assert_eq!(
        cx.update(|_window, app| { view.read(app).remote_state().map(|panel| panel.host().id()) }),
        Some(ssh_plain_id),
        "foreground plain-password host form remains undisturbed when parked SSH verification completes"
    );
}

#[gpui::test]
async fn vault_revealed_password_resets_across_all_workspace_and_launcher_transitions(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("vault-reveal-navigation-reset");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);

    let mut book = shellune_storage::HostBook::new();
    let mut ssh_host =
        shellune_core::HostConfig::new("ask-pass-ssh", "127.0.0.1", 1, "root").expect("ssh");
    ssh_host.set_auth(Some(shellune_core::AuthMethodKind::Password));
    book.insert(ssh_host.clone()).expect("insert ssh");
    dir.store().save(&book).expect("save hosts");

    let (view, cx) = vault_window(app_cx, &dir, &secrets);
    cx.simulate_resize(size(px(1280.0), px(840.0)));
    cx.run_until_parked();

    // Mount one live terminal session tab so we can click/activate tabs from Vault.
    let live_tab = live_remote(cx, &view);
    cx.run_until_parked();

    // 1. Reveal password on Home -> Vault, then activate an existing session tab: must hide immediately!
    click(cx, "nav.hosts");
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    click(cx, "security.credential.0");
    click(cx, "security.detail.reveal");
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).security_password_shown_for_test()));

    cx.update(|_window, app| view.update(app, |v, cx| v.activate(live_tab, cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "activating a session tab from Home -> Vault must immediately reset revealed password"
    );

    // 2. Return to Home -> Vault, reveal again, open connection card and click Continue in background (`hide_connection`):
    //    must reset revealed password so returning to Home -> Vault never shows plaintext!
    click(cx, "nav.hosts");
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "returning to Home -> Vault keeps password masked"
    );
    click(cx, "security.detail.reveal");
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).security_password_shown_for_test()));

    cx.update(|_window, app| view.update(app, |v, cx| v.open_remote(&ssh_host, cx)));
    cx.run_until_parked();
    cx.update(|_window, app| view.update(app, |v, cx| v.hide_connection_for_test(cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "hide_connection returning to Home -> Vault must reset revealed password"
    );

    // 3. Reveal on Settings -> Security -> Keys & Passwords, then start a new local shell via topbar:
    //    must reset revealed password immediately!
    click(cx, "nav.settings");
    click(cx, "settings.category.security");
    cx.run_until_parked();
    click(cx, "security.credential.0");
    click(cx, "security.detail.reveal");
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).security_password_shown_for_test()));

    cx.update(|_window, app| view.update(app, |v, cx| v.activate(live_tab, cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "leaving Settings -> Security -> Keys via tab activation immediately hides revealed password"
    );
}

#[gpui::test]
async fn vault_revealed_password_resets_from_default_local_shells_home_and_restored_pending_tabs(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("vault-reveal-default-local-shells-home");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);

    let mut book = shellune_storage::HostBook::new();
    let mut ssh_host =
        shellune_core::HostConfig::new("agent-ssh", "127.0.0.1", 1, "root").expect("ssh");
    ssh_host.set_auth(Some(shellune_core::AuthMethodKind::Agent));
    let ssh_id = ssh_host.id();
    book.insert(ssh_host.clone()).expect("insert ssh");

    let rdp_cfg =
        shellune_core::RdpConfig::new("plain-rdp", "127.0.0.1:3389", Some("alice")).expect("rdp");
    let rdp_id = rdp_cfg.id();
    book.insert_connection(shellune_core::ConnectionRecord::Rdp(rdp_cfg))
        .expect("insert rdp");

    let serial_cfg = shellune_core::SerialConfig::new("console-serial", "COM254").expect("serial");
    let serial_id = serial_cfg.id();
    book.insert_connection(shellune_core::ConnectionRecord::Serial(serial_cfg))
        .expect("insert serial");

    dir.store().save(&book).expect("save book");

    // Open in Workspace::new() default state (`Destination::LocalShells`, 0 open tabs -> `home_shown() == true`).
    let store = dir.store();
    let secret_store: Arc<dyn shellune_storage::SecretStore> = secrets.clone();
    let (view, cx) = app_cx.add_window_view(move |_window, cx| {
        ShelluneView::with_secrets_for_test(cx, Workspace::new(), store, secret_store)
    });
    cx.simulate_resize(size(px(1280.0), px(840.0)));
    cx.run_until_parked();

    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().destination()),
        Destination::LocalShells,
        "cold-start default destination is Destination::LocalShells"
    );
    assert!(
        cx.update(|_window, app| view.read(app).home_shown()),
        "with 0 open tabs, Destination::LocalShells renders the home page"
    );

    let authenticator = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Ok(()), Ok(()), Ok(()), Ok(())]),
    );
    let verify_counter = authenticator.clone();
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.security_lock_settings_for_test(
                shellune_storage::LockPolicy::EverySensitiveOperation,
                cx,
            );
            v.security_set_authenticator_for_test(authenticator);
        });
    });

    // Directly click `hosts.view.vault` WITHOUT clicking `nav.hosts` first!
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().destination()),
        Destination::LocalShells,
        "clicking hosts.view.vault from initial home keeps destination == LocalShells"
    );
    assert!(
        cx.update(|_window, app| view.read(app).is_security_keys_surface_visible()),
        "HomeSection::Vault under LocalShells home_shown() must be recognized as visible"
    );

    // 1. Reveal password (#1 verify), connect SSH host, assert `revealed == false`,
    //    then `close_session` back to LocalShells Home -> Vault: password stays masked and requires re-verify!
    click(cx, "security.credential.0");
    click(cx, "security.detail.reveal");
    cx.run_until_parked();
    assert_eq!(verify_counter.verify_calls(), 1);
    assert!(cx.update(|_window, app| view.read(app).security_password_shown_for_test()));

    cx.update(|_window, app| view.update(app, |v, cx| v.connect_saved_connection(ssh_id, cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "dialling SSH from LocalShells Home -> Vault must immediately reset revealed password"
    );
    let ssh_session = cx.update(|_window, app| {
        view.read(app)
            .active_session()
            .expect("SSH session tab opened")
    });
    cx.update(|_window, app| view.update(app, |v, cx| v.close_session(ssh_session, cx)));
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).home_shown()));
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "closing last SSH tab back to LocalShells Home -> Vault must NOT re-expose plaintext password"
    );

    // 2. Re-revealing requires a fresh system verification (#2 verify), then non-vault RDP resets it!
    click(cx, "security.detail.reveal");
    cx.run_until_parked();
    assert_eq!(
        verify_counter.verify_calls(),
        2,
        "returning to Home -> Vault requires fresh verification under EverySensitiveOperation"
    );
    assert!(cx.update(|_window, app| view.read(app).security_password_shown_for_test()));

    cx.update(|_window, app| view.update(app, |v, cx| v.open_desktop_connection(rdp_id, cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "connecting non-vault RDP from LocalShells Home -> Vault must reset revealed password"
    );
    let rdp_session = cx.update(|_window, app| {
        view.read(app)
            .active_session()
            .expect("RDP session tab opened")
    });
    cx.update(|_window, app| view.update(app, |v, cx| v.close_session(rdp_session, cx)));
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).home_shown()));
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "closing last RDP tab back to LocalShells Home -> Vault keeps password masked"
    );

    // 3. Re-reveal (#3 verify), then Serial connection resets it and closing serial tab keeps it masked!
    click(cx, "security.detail.reveal");
    cx.run_until_parked();
    assert_eq!(verify_counter.verify_calls(), 3);
    assert!(cx.update(|_window, app| view.read(app).security_password_shown_for_test()));

    cx.update(|_window, app| view.update(app, |v, cx| v.open_serial_connection(serial_id, cx)));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "connecting Serial from LocalShells Home -> Vault must reset revealed password"
    );
    let serial_session = cx.update(|_window, app| {
        view.read(app)
            .active_session()
            .expect("Serial session tab opened")
    });
    cx.update(|_window, app| view.update(app, |v, cx| v.close_session(serial_session, cx)));
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).home_shown()));
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "closing last Serial tab back to LocalShells Home -> Vault keeps password masked"
    );

    // 4. Restored pending tab: clicking `session.tab.0` (`select_tab`) from Home -> Vault immediately resets revealed!
    let pending_dir = TempDir::new("vault-reveal-restored-pending-tab");
    let pending_secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&pending_dir, &pending_secrets);
    pending_dir.store().save(&book).expect("save pending book");
    let pending_tabs = vec![
        WorkspaceTab::new(
            "restored-pending",
            PaneNode::leaf(PaneTarget::remote(ssh_id), TerminalMode::Classic),
        )
        .expect("pending tab"),
    ];
    let snapshot =
        WorkspaceSnapshot::new(pending_tabs, PanelConfig::default()).expect("pending snapshot");
    WorkspaceStore::at(pending_dir.path())
        .save(&snapshot)
        .expect("save pending workspace");

    let pending_store = pending_dir.store();
    let pending_secret_store: Arc<dyn shellune_storage::SecretStore> = pending_secrets.clone();
    let (pending_view, pending_cx) = app_cx.add_window_view(move |_window, cx| {
        ShelluneView::with_secrets_for_test(
            cx,
            Workspace::new(),
            pending_store,
            pending_secret_store,
        )
    });
    pending_cx.simulate_resize(size(px(1280.0), px(840.0)));
    pending_cx.run_until_parked();

    click(pending_cx, "nav.hosts");
    click(pending_cx, "hosts.view.vault");
    pending_cx.run_until_parked();
    click(pending_cx, "security.credential.0");
    click(pending_cx, "security.detail.reveal");
    pending_cx.run_until_parked();
    assert!(
        pending_cx.update(|_window, app| pending_view.read(app).security_password_shown_for_test())
    );

    click(pending_cx, "session.tab.0");
    pending_cx.run_until_parked();
    assert!(
        !pending_cx
            .update(|_window, app| pending_view.read(app).security_password_shown_for_test()),
        "selecting a restored pending tab from Home -> Vault must immediately reset revealed password"
    );
}

#[gpui::test]
async fn desktop_unremembered_password_is_strictly_one_shot_on_save_and_connect_only(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("desktop-ephemeral-secret-lifecycle");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let cred_id = shellune_storage::VaultStore::at(dir.path())
        .open(
            &shellune_storage::UnsealSource::LocalMachine,
            secrets.as_ref(),
        )
        .expect("load vault")
        .credentials()
        .next()
        .expect("cred")
        .meta()
        .id();

    // Seed one vault-backed RDP record so we can also exercise the busy desktop verification gate.
    let mut book = shellune_storage::HostBook::new();
    let mut gated_cfg =
        shellune_core::RdpConfig::new("Gated RDP", "127.0.0.1", Some("ops")).expect("rdp");
    gated_cfg.set_port(1).expect("closed port");
    gated_cfg.set_credential_id(Some(cred_id));
    let gated_rdp = shellune_core::ConnectionRecord::Rdp(gated_cfg);
    let gated_rdp_id = gated_rdp.id();
    book.insert_connection(gated_rdp).expect("insert gated rdp");
    dir.store().save(&book).expect("save hosts");

    let auth = Arc::new(
        shellune_storage::ScriptedAuthenticator::new(
            shellune_storage::BiometricCapability::Biometrics,
        )
        .script([Ok(()), Err(shellune_storage::BiometricError::Cancelled)]),
    );
    let mut ws = Workspace::new();
    ws.select(Destination::Hosts);
    let store = dir.store();
    let secrets_dyn: Arc<dyn shellune_storage::SecretStore> = secrets.clone();
    let (view, cx) = app_cx.add_window_view(move |_window, cx| {
        let mut v = ShelluneView::with_secrets_for_test(cx, ws, store, secrets_dyn);
        v.security_set_authenticator_for_test(auth);
        v.security_enable_lock_for_test(
            shellune_storage::LockPolicy::EverySensitiveOperation,
            15,
            cx,
        );
        v.security_unlock_for_test(cx);
        v
    });
    cx.simulate_resize(size(px(1280.0), px(900.0)));
    cx.run_until_parked();

    // 1. "Save" alone (`connection.save`) with Remember unticked MUST NOT store in `desktop_secrets`.
    let temp_rdp_id = save_desktop_password_form(
        cx,
        &view,
        "connection.protocol.rdp",
        "temp-only-save-secret",
        false,
    );
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_secret_count_for_test()),
        0,
        "clicking Save alone with Remember unticked must leave zero secrets in desktop_secrets"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).saved_secret_for_test(temp_rdp_id)),
        None,
        "unremembered password is never written to SecretStore"
    );

    // 2. While `gated_rdp` occupies desktop verification, clicking "Save & Connect" on `temp_rdp_id`
    //    hits the busy early-return in `open_desktop_connection_with_ephemeral` and MUST NOT leak `desktop_secrets`!
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.security_hold_verify_for_test(true);
            v.connect_saved_connection(gated_rdp_id, cx);
        });
    });
    cx.run_until_parked();
    click(cx, "nav.hosts");
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.edit_connection_for_test(temp_rdp_id, cx);
        });
    });
    cx.run_until_parked();
    type_into(cx, "connection.field.secret", "busy-aborted-secret");
    click(cx, "connection.save_connect");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_secret_count_for_test()),
        0,
        "Save & Connect aborted by busy desktop verification must not leave any secret in desktop_secrets"
    );

    // Release the held verification, return to Hosts, and run normal "Save & Connect":
    // consumes the one-shot password immediately and leaves `desktop_secrets` empty afterwards!
    cx.update(|_window, app| view.update(app, |v, cx| v.security_release_verify_for_test(cx)));
    cx.run_until_parked();
    click(cx, "nav.hosts");
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.edit_connection_for_test(temp_rdp_id, cx);
        });
    });
    cx.run_until_parked();
    type_into(cx, "connection.field.secret", "one-shot-rdp-secret");
    click(cx, "connection.save_connect");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_start_count_for_test()),
        1,
        "Save & Connect started the desktop session"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).desktop_secret_count_for_test()),
        0,
        "one-shot password was consumed immediately and leaves desktop_secrets empty for future sessions"
    );
}

#[gpui::test]
async fn vault_and_connection_modals_preserve_outer_focus_return_across_typing_validation_and_inline_creation(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("modal-focus-return-preservation");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(app_cx, &dir, &secrets);
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(size(px(1280.0), px(860.0)));
    cx.run_until_parked();

    let vault_search_focused = |cx: &mut VisualTestContext| {
        let handle = cx.update(|_window, app| view.read(app).security_search_focus(app));
        cx.update(|window, _app| handle.is_focused(window))
    };
    let vault_list_focused = |cx: &mut VisualTestContext| {
        cx.update(|window, app| view.read(app).security_list_focused(window))
    };
    let hosts_search_focused = |cx: &mut VisualTestContext| {
        let handle = cx.update(|_window, app| view.read(app).hosts_search_focus_for_test(app));
        cx.update(|window, _app| handle.is_focused(window))
    };

    // 1. Vault page: focus `security.search`, open NewCredential modal, trigger refusal refocus,
    //    type into fields, then press Escape -> focus must return to `security.search`!
    click(cx, "nav.hosts");
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    click(cx, "security.search");
    assert!(vault_search_focused(cx));

    click(cx, "security.action.new-password");
    cx.run_until_parked();
    // Submit empty to trigger `security_focus_refused_field`, then type text (triggering redraws).
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    cx.simulate_input("Typing inside modal");
    cx.run_until_parked();
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        vault_search_focused(cx),
        "closing vault dialog after typing & refusal refocus restores focus to security.search"
    );

    // 2. Vault page: focus `security.list_focus`, open GenerateKey modal, type & save ->
    //    focus must return to `security.list_focus`!
    click(cx, "security.credential.0");
    cx.run_until_parked();
    assert!(vault_list_focused(cx));
    click(cx, "security.action.generate");
    cx.run_until_parked();
    cx.simulate_input("Focus-return key");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        vault_list_focused(cx),
        "saving vault dialog restores focus to security.list_focus"
    );

    // 3. Home page: focus `hosts.search`, open SSH dialog, trigger validation failure refocus AND
    //    stacked inline `PendingVaultBind` credential dialog, then close SSH dialog ->
    //    focus must return to `hosts.search`!
    click(cx, "hosts.view.all");
    cx.run_until_parked();
    click(cx, "hosts.search");
    assert!(hosts_search_focused(cx));

    click(cx, "hosts.new");
    cx.run_until_parked();
    // Validation failure sets `field_focus_pending` while `host_fields` is already open.
    click(cx, "hosts.save");
    cx.run_until_parked();
    // Open stacked inline shared-credential dialog (`PendingVaultBind::SshSharedCredential`).
    click(cx, "hosts.auth.remote.method.password");
    cx.run_until_parked();
    click(cx, "hosts.auth.credential.new");
    cx.run_until_parked();
    type_into(cx, "security.dialog.name", "Stacked SSH cred");
    click(cx, "security.dialog.generate.password");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().draft().is_some()),
        "SSH dialog remains open after inline credential creation"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        hosts_search_focused(cx),
        "closing SSH dialog after validation refocus and inline vault dialog restores focus to hosts.search"
    );

    // 4. Home page: focus `hosts.search`, open New -> switch to RDP, trigger validation failure +
    //    close RDP dialog ->
    //    focus must return to `hosts.search`!
    click(cx, "hosts.search");
    assert!(hosts_search_focused(cx));
    click(cx, "hosts.new");
    click(cx, "connection.protocol.rdp");
    cx.run_until_parked();
    click(cx, "connection.save");
    cx.run_until_parked();
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        hosts_search_focused(cx),
        "closing RDP dialog after protocol switch and validation refocus restores hosts.search"
    );
}

#[gpui::test]
async fn cold_start_local_shells_home_keyboard_loop_group_launcher_focus_and_inline_validation_clear(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("cold-start-home-keyboard-and-inline-validation");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());

    let mut book = shellune_storage::HostBook::new();
    let ssh_host = stored_host("prod-api", "10.10.0.5", 22, "deploy", Some("Ops"));
    let ssh_id = ssh_host.id();
    book.insert(ssh_host).expect("insert ssh");
    let rdp_cfg =
        shellune_core::RdpConfig::new("ops-desk", "10.10.0.9:3389", Some("alice")).expect("rdp");
    let rdp_id = rdp_cfg.id();
    book.insert_connection(shellune_core::ConnectionRecord::Rdp(rdp_cfg))
        .expect("insert rdp");
    dir.store().save(&book).expect("save book");

    let store = dir.store();
    let secret_store: Arc<dyn shellune_storage::SecretStore> = secrets.clone();
    let (view, cx) = app_cx.add_window_view(move |_window, cx| {
        ShelluneView::with_secrets_for_test(cx, Workspace::new(), store, secret_store)
    });
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(size(px(1280.0), px(840.0)));
    cx.run_until_parked();

    // Without ever clicking `nav.hosts`, destination starts as `LocalShells` showing the home page.
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().destination()),
        Destination::LocalShells
    );
    assert!(cx.update(|_window, app| view.read(app).home_shown()));

    let hosts_search_focused = |cx: &mut gpui::VisualTestContext| {
        cx.update(|window, app| {
            view.read(app)
                .hosts_search_focus_for_test(app)
                .is_focused(window)
        })
    };

    // 1. From cold-start Home page (`Destination::LocalShells`), `/` focuses `hosts.search`,
    //    `Tab` moves focus to the active home page and sets cursor on row 0, `*` toggles favorite,
    //    `F2` opens edit dialog and `Escape` returns focus to the list, `Shift+F10` -> `Move to group…`
    //    preserves focus return when opened from `hosts.search`.
    cx.simulate_keystrokes("/");
    cx.run_until_parked();
    assert!(
        hosts_search_focused(cx),
        "pressing '/' on cold-start LocalShells home page focuses hosts.search"
    );
    cx.simulate_input("ops");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        crate::app::view::home::home_highlights::ranges_of("ops-desk").is_some(),
        "typing in hosts.search on cold-start home highlights matching connection name"
    );

    // Tab from `hosts.search` into the list under `Destination::LocalShells`.
    cx.simulate_keystrokes("tab");
    cx.run_until_parked();
    assert!(
        !hosts_search_focused(cx),
        "Tab moves focus out of hosts.search to the home list"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).hosts_cursor()),
        Some(ssh_id),
        "Tab selects the first visible record"
    );

    // Move down to `ops-desk` (RDP) and toggle favorite via `*`.
    cx.simulate_keystrokes("down");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).hosts_cursor()),
        Some(rdp_id)
    );
    cx.simulate_keystrokes("*");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).book().is_favorite(rdp_id)),
        "'*' on cold-start LocalShells home list toggles favorite on RDP row"
    );

    // Press F2 to open RDP editor and Escape to return to the list.
    cx.simulate_keystrokes("f2");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().protocol_draft().is_some()),
        "F2 opens the protocol connection dialog"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);

    // Focus `hosts.search`, open row menu via `Shift+F10`, pick `Move to group…`, confirm move,
    // and verify focus returns cleanly to `hosts.search`!
    click(cx, "hosts.search");
    assert!(hosts_search_focused(cx));
    cx.simulate_keystrokes("shift-f10");
    cx.run_until_parked();
    assert!(cx.debug_bounds("host.menu.move_group").is_some());
    click(cx, "host.menu.move_group");
    cx.run_until_parked();
    cx.simulate_input("Infra");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    redraw(cx);
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .book()
                .connection(rdp_id)
                .and_then(|r| r.group_text())
        }),
        Some("Infra".to_owned()),
        "MoveSingle updates RDP record's group"
    );
    assert!(
        hosts_search_focused(cx),
        "confirming Move to group restores focus back to hosts.search"
    );

    // 2. Topbar `+` launcher (`header.primary`) opened while `hosts.search` is focused:
    //    typing in launcher search and pressing Escape restores focus to `hosts.search`.
    click(cx, "header.primary");
    cx.run_until_parked();
    assert!(cx.debug_bounds("shell.picker").is_some());
    cx.simulate_input("ops");
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("launcher.host.0").is_some(),
        "launcher lists matching saved records across protocols"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        hosts_search_focused(cx),
        "closing topbar '+' launcher with Escape restores focus to hosts.search"
    );

    // 3. Global tool modal (`Tool::Forwards`) opened over the Home page blocks host shortcuts behind it.
    cx.simulate_keystrokes("escape"); // clear non-empty `hosts.search`
    cx.run_until_parked();
    cx.simulate_keystrokes("escape"); // empty `hosts.search` -> focus home list
    cx.run_until_parked();
    assert!(!hosts_search_focused(cx));
    click(cx, "hosts.more");
    cx.run_until_parked();
    click(cx, "hosts.more.forwards");
    cx.run_until_parked();
    cx.simulate_keystrokes("delete");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().pending_delete().is_none()),
        "Delete key while global Forwards modal is open must not trigger host deletion behind the modal"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();

    // 4. Subgroup refusal banner clears on edit (`GroupEditor::set_name`), and switching SSH auth
    //    from Password (with unticked remember + typed secret) to an inline-generated ManagedKey
    //    never stashes a leftover ephemeral secret on Save & Connect.
    right_click(cx, "hosts.tree.0");
    cx.run_until_parked();
    click(cx, "hosts.group.create_sub.open");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| {
            view.read(app)
                .hosts_state()
                .group_editor()
                .map(|e| e.name().to_owned())
        }),
        Some("Infra/".to_owned())
    );
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| {
            view.read(app)
                .hosts_state()
                .group_editor()
                .and_then(|e| e.error())
                .is_some()
        }),
        "submitting trailing slash 'Infra/' shows group refusal"
    );
    cx.simulate_input("Core");
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| {
            view.read(app)
                .hosts_state()
                .group_editor()
                .and_then(|e| e.error())
                .is_none()
        }),
        "typing subgroup suffix immediately clears stale group dialog refusal"
    );
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();

    click(cx, "hosts.new");
    cx.run_until_parked();
    type_into(cx, "hosts.field.address", "127.0.0.1");
    clear_field(cx, "hosts.field.port", 2);
    type_into(cx, "hosts.field.port", "1");
    type_into(cx, "hosts.field.user", "ubuntu");
    click(cx, "hosts.auth.remote.method.password");
    type_into(cx, "hosts.field.secret", "leftover-password-not-used");
    click(cx, "hosts.remember");
    click(cx, "hosts.auth.remote.method.managed-key");
    cx.run_until_parked();
    click(cx, "hosts.auth.managed.generate");
    cx.run_until_parked();
    type_into(cx, "security.dialog.name", "inline-ed25519");
    click(cx, "security.dialog.submit");
    cx.run_until_parked();
    redraw(cx);
    click(cx, "hosts.save_connect");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.update(app, |v, _cx| v.ephemeral_ssh_secret_count_for_test())),
        0,
        "switching away from Password to ManagedKey before Save & Connect never stashes an ephemeral secret"
    );
    assert!(
        cx.update(|_window, app| view.read(app).hosts_state().draft().is_none()),
        "SSH host with inline-generated managed key saves and connects cleanly"
    );
}

#[gpui::test]
async fn global_tools_batch_focus_isolation_home_snippet_guard_and_context_split_reconnect(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("global-tools-focus-isolation-and-split-reconnect");
    seed(
        &dir.store(),
        vec![stored_host("web", "10.0.0.5", 22, "deploy", None)],
    );
    let mut book = shellune_core::SnippetBook::new();
    book.create("echo safe", "echo safe").expect("snippet");
    shellune_storage::SnippetStore::at(dir.path())
        .save(&book)
        .expect("save snippets");

    let (view, cx) = snippet_view(app_cx, &dir);
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(design_window());
    let session = live_remote(cx, &view);
    show_remote_terminal(cx, &view, session);

    let terminal_focused = |cx: &mut VisualTestContext| {
        cx.update(|window, app| {
            view.read(app)
                .pane_of(session)
                .is_some_and(|p| p.read(app).focus_handle().is_focused(window))
        })
    };
    assert!(
        terminal_focused(cx),
        "live SSH terminal initially holds focus"
    );

    // 1. Opening Transfers, Forwards (with editor), or Batch over a live terminal isolates
    //    keystrokes from leaking into the hidden PTY and restores terminal focus on Escape.
    let sent_before = snippet_sent(cx, &view, session).len();
    click(cx, "session.more");
    click(cx, "session.more.transfers");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Transfers)
    );
    cx.simulate_input("echo leaked");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing while Transfers modal is open must never leak into the terminal PTY behind the scrim"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(
        terminal_focused(cx),
        "closing Transfers modal with Escape restores focus to the active terminal"
    );

    click(cx, "session.more");
    click(cx, "session.more.global_forwards");
    cx.run_until_parked();
    click(cx, "forwards.new");
    cx.run_until_parked();
    assert!(cx.debug_bounds("forwards.form").is_some());
    cx.simulate_keystrokes("escape"); // close forward editor
    cx.run_until_parked();
    assert!(cx.debug_bounds("forwards.form").is_none());
    cx.simulate_keystrokes("escape"); // close Forwards tool modal
    cx.run_until_parked();
    assert!(
        terminal_focused(cx),
        "closing Forwards editor and modal with Escape restores focus to the active terminal"
    );

    click(cx, "session.more");
    click(cx, "session.more.batch");
    cx.run_until_parked();
    assert!(cx.debug_bounds("batch.dialog").is_some());
    type_into(cx, "batch.step.field.0", "uptime");
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        terminal_focused(cx),
        "closing Batch preview after typing in step field restores focus to the active terminal"
    );

    // 2. Navigating to Home (`Destination::Hosts`) while `session` stays open in the background:
    //    - Opening Snippets from `hosts.more.snippets` and pressing Enter refuses with
    //      `snippet_no_terminal` instead of injecting into the hidden background terminal!
    //    - Opening Batch from `hosts.more` or Command Palette and typing inside Batch preserves
    //      `hosts.search` focus return on Escape!
    click(cx, "nav.hosts");
    cx.run_until_parked();
    let hosts_search_focused = |cx: &mut VisualTestContext| {
        let handle = cx.update(|_window, app| view.read(app).hosts_search_focus_for_test(app));
        cx.update(|window, _app| handle.is_focused(window))
    };
    click(cx, "hosts.search");
    assert!(hosts_search_focused(cx));

    let sent_before_home_snippet = snippet_sent(cx, &view, session).len();
    click(cx, "hosts.more");
    click(cx, "hosts.more.snippets");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before_home_snippet,
        "pressing Enter in Snippets on Home page must never inject into a hidden background terminal"
    );
    assert!(
        cx.update(|_window, app| view.read(app).toast_titles())
            .iter()
            .any(|t| t == copy::ENGLISH_UX.snippet_no_terminal),
        "Snippets on Home page explains that a terminal must be on screen first"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        hosts_search_focused(cx),
        "closing Snippets on Home page restores focus to hosts.search"
    );

    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input("batch");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert!(cx.debug_bounds("batch.dialog").is_some());
    type_into(cx, "batch.step.field.0", "whoami");
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        hosts_search_focused(cx),
        "closing Batch opened via Command Palette restores focus to hosts.search"
    );

    // 3. Return to live SSH terminal, right-click -> `terminal.menu.split_right`:
    //    the newly created pending pane becomes active (`active_session() == None`), and typing
    //    must NOT leak into the now-idle left SSH pane.
    cx.update(|_window, app| view.update(app, |v, cx| v.activate(session, cx)));
    cx.run_until_parked();
    show_remote_terminal(cx, &view, session);
    let sent_before_split = snippet_sent(cx, &view, session).len();
    right_click(cx, "terminal.viewport");
    click(cx, "terminal.menu.split_right");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).workspace().layout().leaves().len()),
        2
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        None,
        "pending right pane becomes active after context-menu split"
    );
    assert!(
        !terminal_focused(cx),
        "idle left SSH pane must not keep keyboard focus when right pending pane is active"
    );
    cx.simulate_input("nope");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before_split,
        "typing while pending split pane is active sends nothing to the idle SSH pane"
    );

    // 4. One-click Reconnect (`terminal.failure.next`) on an inactive background split pane
    //    focuses that split pane and opens its reconnect flow in place.
    let Some((split_view, split_cx, left_id, right_id)) = split_tab(app_cx) else {
        return;
    };
    assert_eq!(
        split_cx.update(|_window, app| split_view.read(app).active_session()),
        Some(right_id),
        "split_tab starts with right_id active and left_id idle in the background"
    );
    split_cx.update(|_window, app| {
        if let Some(left_pane) = split_view.read(app).pane_of(left_id).cloned() {
            let tag = left_pane.read(app).tag();
            left_pane.update(app, |p, cx| {
                p.adopt_events(
                    tag,
                    vec![crate::app::terminal::SourceEvent::Lost(
                        "background channel dropped".to_owned(),
                    )],
                    cx,
                );
            });
        }
        split_view.update(app, |v, cx| {
            let _ = v
                .workspace_mut_for_test()
                .session_failed(left_id, shellune_core::SessionFailure::ConnectionLost);
            cx.notify();
        });
    });
    split_cx.run_until_parked();
    click(split_cx, "terminal.failure.next");
    split_cx.run_until_parked();
    assert_eq!(
        split_cx.update(|_window, app| split_view.read(app).active_session()),
        Some(left_id),
        "clicking Reconnect on an inactive background split pane activates that pane"
    );
    assert_eq!(
        split_cx
            .update(|_window, app| { split_view.read(app).workspace().layout().active_session() }),
        Some(left_id),
        "layout active_session synchronizes with the reconnecting split pane"
    );
}

#[gpui::test]
async fn modal_palette_cancel_batch_switch_and_pending_split_overlay_focus_isolation(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("modal-palette-cancel-batch-switch-and-pending-split");
    seed(
        &dir.store(),
        vec![stored_host("web", "10.0.0.5", 22, "deploy", None)],
    );
    let mut book = shellune_core::SnippetBook::new();
    book.create("echo safe", "echo safe").expect("snippet");
    shellune_storage::SnippetStore::at(dir.path())
        .save(&book)
        .expect("save snippets");

    let (view, cx) = snippet_view(app_cx, &dir);
    cx.update(|_window, app| app.bind_keys(key_bindings(Platform::current())));
    cx.simulate_resize(design_window());
    let session = live_remote(cx, &view);
    show_remote_terminal(cx, &view, session);

    let terminal_focused = |cx: &mut VisualTestContext| {
        cx.update(|window, app| {
            view.read(app)
                .pane_of(session)
                .is_some_and(|p| p.read(app).focus_handle().is_focused(window))
        })
    };
    assert!(terminal_focused(cx));

    // 1. Opening Transfers, Forwards (after Escape from editor), or Batch over a live terminal,
    //    then opening Command Palette (Ctrl/Cmd+K) and cancelling it with Escape (or toggle)
    //    must keep keyboard focus isolated from the underlying terminal PTY while the modal
    //    stays open, and still restore terminal focus once the modal itself closes.
    let sent_before = snippet_sent(cx, &view, session).len();

    click(cx, "session.more");
    click(cx, "session.more.transfers");
    cx.run_until_parked();
    go(cx, crate::app::actions::OpenPalette);
    assert!(cx.update(|_window, app| view.read(app).palette_open()));
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).palette_open()));
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Transfers),
        "Transfers stays open after cancelling Command Palette"
    );
    assert!(
        !terminal_focused(cx),
        "cancelling Command Palette over Transfers must not focus the hidden terminal PTY"
    );
    cx.simulate_input("echo leaked-transfers");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing after cancelling palette over Transfers never reaches the hidden terminal PTY"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        terminal_focused(cx),
        "closing Transfers after palette cancel restores terminal focus"
    );

    click(cx, "session.more");
    click(cx, "session.more.global_forwards");
    cx.run_until_parked();
    click(cx, "forwards.new");
    cx.run_until_parked();
    cx.simulate_keystrokes("escape"); // close forwards.form back to Forwards list
    cx.run_until_parked();
    assert!(cx.debug_bounds("forwards.form").is_none());
    go(cx, crate::app::actions::OpenPalette);
    go(cx, crate::app::actions::OpenPalette); // cancel via second Ctrl/Cmd+K toggle
    cx.run_until_parked();
    assert!(!cx.update(|_window, app| view.read(app).palette_open()));
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Forwards),
    );
    assert!(
        !terminal_focused(cx),
        "toggling Command Palette closed over Forwards must not focus the hidden terminal PTY"
    );
    cx.simulate_input("echo leaked-forwards");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing after toggling palette closed over Forwards never reaches the hidden terminal PTY"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(terminal_focused(cx));

    click(cx, "session.more");
    click(cx, "session.more.batch");
    cx.run_until_parked();
    assert!(cx.debug_bounds("batch.dialog").is_some());
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    assert!(cx.debug_bounds("batch.dialog").is_some());
    assert!(
        !terminal_focused(cx),
        "cancelling Command Palette over unfocused Batch modal must not focus the hidden terminal PTY"
    );
    cx.simulate_input("echo leaked-batch");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing after cancelling palette over Batch never reaches the hidden terminal PTY"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(terminal_focused(cx));

    // 2. Home multi-select bar `hosts.batch.open` isolates `hosts.search`, and switching from a
    //    focused `batch.step.field.0` via Command Palette to Snippets, Transfers, Forwards,
    //    New Host, or Import preserves `hosts.search` as the outer focus return target on Escape.
    click(cx, "nav.hosts");
    cx.run_until_parked();
    let hosts_search_focused = |cx: &mut VisualTestContext| {
        let handle = cx.update(|_window, app| view.read(app).hosts_search_focus_for_test(app));
        cx.update(|window, _app| handle.is_focused(window))
    };
    click(cx, "hosts.select.0");
    cx.run_until_parked();
    click(cx, "hosts.search");
    assert!(hosts_search_focused(cx));

    click(cx, "hosts.batch.open");
    cx.run_until_parked();
    assert!(cx.debug_bounds("batch.dialog").is_some());
    assert!(
        !hosts_search_focused(cx),
        "hosts.batch.open must move keyboard focus off hosts.search"
    );
    cx.simulate_input("leaked");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).hosts_state().search().to_owned()),
        "",
        "typing over Batch opened from hosts.batch.open must not mutate hosts.search"
    );
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    cx.simulate_input("still-isolated");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).hosts_state().search().to_owned()),
        "",
        "cancelling Command Palette over Batch must not leak keys into hosts.search"
    );

    let v_replacement_open = |v: &ShelluneView, label: &str| match label {
        "Snippets" => v.tool_for_test() == Some(crate::app::view::Tool::Snippets),
        "Transfers" => v.tool_for_test() == Some(crate::app::view::Tool::Transfers),
        "Forwards" => v.tool_for_test() == Some(crate::app::view::Tool::Forwards),
        "New Host" => v.hosts_state().draft().is_some(),
        "Import" => v.import_open_for_test(),
        _ => false,
    };
    for (palette_query, label) in [
        (copy::ENGLISH_UX.snippet_manage_action, "Snippets"),
        (ENGLISH.nav_transfers, "Transfers"),
        (ENGLISH.nav_forwards, "Forwards"),
        (ENGLISH.primary_hosts, "New Host"),
        (ENGLISH.import_open, "Import"),
    ] {
        if !cx.update(|_window, app| view.read(app).batch_panel().view().is_open()) {
            click(cx, "hosts.batch.open");
            cx.run_until_parked();
        }
        assert!(
            cx.update(|_window, app| view.read(app).batch_panel().view().is_open()),
            "Batch is open before switching to {label}"
        );
        type_into(cx, "batch.step.field.0", "uptime");
        go(cx, crate::app::actions::OpenPalette);
        cx.simulate_input(palette_query);
        cx.run_until_parked();
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        redraw(cx);
        assert!(
            !cx.update(|_window, app| view.read(app).batch_panel().view().is_open()),
            "switching from Batch via palette query {palette_query:?} ({label}) closes Batch"
        );
        assert!(
            cx.update(|_window, app| v_replacement_open(view.read(app), label)),
            "palette query {palette_query:?} opens {label}"
        );
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        redraw(cx);
        assert!(
            hosts_search_focused(cx),
            "closing {label} after switching from focused Batch field restores hosts.search"
        );
    }

    // 3. Splitting an SSH session via keyboard shortcut (`SplitPaneRight` -> `split_active` ->
    //    `present_active_pane`) or moving pane/tab focus to a pending waiting pane (`active_session() == None`)
    //    clears `focus_return` so opening and closing overlays never leaks keys to the inactive SSH pane.
    cx.update(|_window, app| view.update(app, |v, cx| v.activate(session, cx)));
    cx.run_until_parked();
    show_remote_terminal(cx, &view, session);
    assert!(terminal_focused(cx));

    let sent_before_shortcut_split = snippet_sent(cx, &view, session).len();
    go(cx, crate::app::actions::SplitPaneRight);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        None,
        "SplitPaneRight on SSH session activates the new pending split pane"
    );
    assert!(
        !terminal_focused(cx),
        "inactive left SSH pane does not hold focus when right pending split pane is active"
    );

    // Open and close Command Palette, Snippets, Transfers, and Tab List while pending pane is active.
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !terminal_focused(cx),
        "closing Command Palette on pending split pane must not focus inactive SSH pane"
    );

    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input(copy::ENGLISH_UX.snippet_manage_action);
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert!(cx.debug_bounds("snippets.dialog").is_some());
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !terminal_focused(cx),
        "closing Snippets on pending split pane must not focus inactive SSH pane"
    );

    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input("transfers");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !terminal_focused(cx),
        "closing Transfers on pending split pane must not focus inactive SSH pane"
    );

    cx.update(|window, app| view.update(app, |v, cx| v.toggle_tab_list(window, cx)));
    cx.run_until_parked();
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !terminal_focused(cx),
        "closing Tab List on pending split pane must not focus inactive SSH pane"
    );

    // Move focus to left live SSH pane, then back to right pending pane via FocusPaneRight,
    // open/close Transfers, and verify typing still sends nothing to the inactive SSH pane.
    go(cx, crate::app::actions::FocusPaneLeft);
    cx.run_until_parked();
    assert!(terminal_focused(cx));
    go(cx, crate::app::actions::FocusPaneRight);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        None
    );
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input("transfers");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !terminal_focused(cx),
        "closing Transfers after FocusPaneRight to pending pane must not focus inactive SSH pane"
    );
    cx.simulate_input("echo blind-type");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before_shortcut_split,
        "typing on pending split pane after opening/closing overlays sends zero bytes to inactive SSH pane"
    );

    // Also open a second live shell tab, then switch back to Tab 0 via `select_tab(0)` (whose
    // active pane is the pending split pane, so `show_layout_tab` takes the `active_session() == None`
    // branch), then open and close Command Palette + Snippets and verify zero focus leakage to
    // either the second tab's shell or Tab 0's inactive SSH pane.
    go(cx, crate::app::actions::NewLocalShell);
    cx.run_until_parked();
    let second_tab_session =
        cx.update(|_window, app| view.read(app).active_session().expect("new local shell"));
    let second_shell_focused = |cx: &mut VisualTestContext| {
        cx.update(|window, app| {
            view.read(app)
                .pane_of(second_tab_session)
                .is_some_and(|p| p.read(app).focus_handle().is_focused(window))
        })
    };
    assert!(second_shell_focused(cx));
    cx.update(|window, app| view.update(app, |v, cx| v.select_tab(0, window, cx)));
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).active_session()),
        None,
        "switching via select_tab(0) back to tab with active pending split pane sets active_session to None"
    );
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input(copy::ENGLISH_UX.snippet_manage_action);
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert!(cx.debug_bounds("snippets.dialog").is_some());
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !terminal_focused(cx) && !second_shell_focused(cx),
        "closing Snippets after select_tab to pending pane must not focus background shell or inactive SSH pane"
    );
    cx.simulate_input("echo tab-leak");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before_shortcut_split,
        "typing after select_tab to pending pane and closing overlay sends zero bytes to SSH pane"
    );
}

#[gpui::test]
async fn modal_field_unmount_reclaim_focus_and_async_pane_focus_isolation(
    app_cx: &mut TestAppContext,
) {
    let dir = TempDir::new("modal-field-unmount-and-async-pane-focus");
    seed(
        &dir.store(),
        vec![
            stored_host("web", "10.0.0.5", 22, "deploy", None),
            stored_host("db", "10.0.0.6", 22, "deploy", None),
        ],
    );

    let (view, cx) = snippet_view(app_cx, &dir);
    let session = live_remote(cx, &view);
    show_remote_terminal(cx, &view, session);

    let session_focused = |cx: &mut VisualTestContext, target: SessionId| {
        cx.update(|window, app| {
            view.read(app)
                .pane_of(target)
                .is_some_and(|p| p.read(app).focus_handle().is_focused(window))
        })
    };
    assert!(session_focused(cx, session));
    let sent_before = snippet_sent(cx, &view, session).len();

    // 1. Port Forwarding modal (`Tool::Forwards`) over a live terminal:
    //    (a) Focus listen port field -> click `forwards.form.close` (unmounts `forwards.form`).
    //    (b) Focus target host field -> click `forwards.kind.2` (`Dynamic`, unmounts `forwards.target`).
    //    (c) Fill valid rule with target port focused -> click `forwards.save` (unmounts `forwards.form`).
    //    None of these `on_focus_lost` -> `reclaim_focus` transitions may leak focus to the terminal,
    //    and pressing `Escape` afterwards restores terminal focus.
    click(cx, "session.more");
    click(cx, "session.more.global_forwards");
    cx.run_until_parked();
    click(cx, "forwards.new");
    cx.run_until_parked();

    let listen_port_handle =
        cx.update(|_window, app| view.read(app).forward_listen_port_focus_for_test(app));
    cx.update(|window, _app| window.focus(&listen_port_handle));
    cx.simulate_input("8080");
    cx.run_until_parked();
    redraw(cx);
    assert!(cx.update(|window, _app| listen_port_handle.is_focused(window)));

    click(cx, "forwards.form.close");
    redraw(cx);
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).forward_editor_open_for_test()),
        "clicking forwards.form.close closes the tunnel editor"
    );
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Forwards)
    );
    assert!(
        !session_focused(cx, session),
        "clicking forwards.form.close while listen port was focused must not focus hidden terminal"
    );
    cx.simulate_input("echo leaked-fwd-cancel");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing after forwards.form.close sends zero bytes to hidden terminal PTY"
    );

    click(cx, "forwards.new");
    cx.run_until_parked();
    let target_host_handle =
        cx.update(|_window, app| view.read(app).forward_target_host_focus_for_test(app));
    cx.update(|window, _app| window.focus(&target_host_handle));
    cx.simulate_input("db.internal");
    cx.run_until_parked();
    redraw(cx);
    assert!(cx.update(|window, _app| target_host_handle.is_focused(window)));

    click(cx, "forwards.kind.2"); // Dynamic unmounts target host/port fields while form stays open
    redraw(cx);
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).forward_editor_kind_for_test()),
        Some(shellune_core::ForwardKind::Dynamic)
    );
    assert!(
        !session_focused(cx, session),
        "switching tunnel kind to Dynamic while target host was focused must not focus hidden terminal"
    );
    cx.simulate_input("echo leaked-fwd-dynamic");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing after Dynamic switch sends zero bytes to hidden terminal PTY"
    );

    click(cx, "forwards.kind.0"); // Back to Local
    cx.run_until_parked();
    cx.update(|window, _app| window.focus(&listen_port_handle));
    cx.simulate_input("18080");
    cx.update(|window, _app| window.focus(&target_host_handle));
    cx.simulate_input("db.internal");
    let target_port_handle =
        cx.update(|_window, app| view.read(app).forward_target_port_focus_for_test(app));
    cx.update(|window, _app| window.focus(&target_port_handle));
    cx.simulate_input("5432");
    cx.run_until_parked();
    redraw(cx);
    assert!(cx.update(|window, _app| target_port_handle.is_focused(window)));

    click(cx, "forwards.save");
    redraw(cx);
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).forward_editor_open_for_test()),
        "clicking forwards.save closes the tunnel editor after adopting the rule"
    );
    assert!(cx.debug_bounds("forwards.row.0").is_some());
    assert!(
        !session_focused(cx, session),
        "clicking forwards.save while target port was focused must not focus hidden terminal"
    );
    cx.simulate_input("echo leaked-fwd-save");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing after forwards.save sends zero bytes to hidden terminal PTY"
    );

    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        session_focused(cx, session),
        "pressing Escape to close Forwards restores terminal focus"
    );

    // 2. Batch modal (`Batch`) over a live terminal:
    //    Focus `batch.step.field.0` -> click `batch.switch.library`, then back to `batch.switch.editor`,
    //    focus `batch.step.field.0` -> click `batch.switch.history`, then press `Escape` to close Batch.
    click(cx, "session.more");
    click(cx, "session.more.batch");
    cx.run_until_parked();
    type_into(cx, "batch.step.field.0", "uptime");
    click(cx, "batch.switch.library");
    redraw(cx);
    assert!(cx.debug_bounds("batch.dialog").is_some());
    assert!(
        !session_focused(cx, session),
        "switching Batch to Library after focusing step field must not focus hidden terminal"
    );
    cx.simulate_input("echo leaked-batch-lib");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing on Batch Library tab sends zero bytes to hidden terminal PTY"
    );

    click(cx, "batch.switch.editor");
    cx.run_until_parked();
    type_into(cx, "batch.step.field.0", " -p");
    click(cx, "batch.switch.history");
    redraw(cx);
    assert!(
        !session_focused(cx, session),
        "switching Batch to History after focusing step field must not focus hidden terminal"
    );
    cx.simulate_input("echo leaked-batch-hist");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing on Batch History tab sends zero bytes to hidden terminal PTY"
    );

    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        session_focused(cx, session),
        "pressing Escape to close Batch restores terminal focus"
    );

    // 3. Quick Connect modal (`quick_open`) over a live terminal:
    //    Focus `quick.password`, then switch auth method to `quick.method.agent` (unmounts password field).
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input(ENGLISH.quick_connect);
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    click(cx, "quick.method.password");
    type_into(cx, "quick.password", "s3cr3t");
    click(cx, "quick.method.agent");
    redraw(cx);
    assert!(
        !session_focused(cx, session),
        "switching Quick Connect auth method away from focused password field must not focus hidden terminal"
    );
    cx.simulate_input("echo leaked-quick");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing after Quick Connect auth switch sends zero bytes to hidden terminal PTY"
    );
    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(session_focused(cx, session));

    // 4. Async remote connection completion (`on_remote_ready` -> `attach_pane` -> `focus_pane` +
    //    `pane_focus_pending`) while a blocking modal (`Tool::Forwards`) is open must NOT steal
    //    keyboard focus through the modal backdrop, and closing the modal afterwards hands focus
    //    to the newly connected active terminal.
    let second_host = cx.update(|_window, app| view.read(app).book().hosts()[1].clone());
    cx.update(|_window, app| {
        view.update(app, |v, cx| {
            v.open_remote(&second_host, cx);
            v.script_remote_attempt(
                vec![
                    shellune_ssh::RemoteEvent::Connected,
                    shellune_ssh::RemoteEvent::Data(b"db ready\r\n$ ".to_vec()),
                ],
                cx,
            );
        });
    });
    cx.run_until_parked();

    // Open Forwards modal BEFORE the async connection finishes.
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input(ENGLISH.nav_forwards);
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Forwards)
    );

    // Now complete the async SSH handshake while Forwards stays open.
    cx.update(|_window, app| {
        view.update(app, |v, cx| v.pump_remote_once(cx));
    });
    cx.run_until_parked();
    redraw(cx);

    let second_session = cx.update(|_window, app| {
        view.read(app)
            .workspace()
            .sessions()
            .items()
            .iter()
            .map(shellune_core::Session::id)
            .find(|id| *id != session && view.read(app).pane_of(*id).is_some())
            .expect("second remote session attached")
    });
    let second_sent_before = snippet_sent(cx, &view, second_session).len();
    assert!(
        !session_focused(cx, session) && !session_focused(cx, second_session),
        "async remote readiness while Forwards modal is open must not focus either terminal behind the backdrop"
    );
    cx.simulate_input("echo leaked-async-ready");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, session).len(),
        sent_before,
        "typing during open Forwards after async connect sends zero bytes to first terminal"
    );
    assert_eq!(
        snippet_sent(cx, &view, second_session).len(),
        second_sent_before,
        "typing during open Forwards after async connect sends zero bytes to newly connected terminal"
    );

    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        session_focused(cx, second_session),
        "closing Forwards after async connect hands focus cleanly to the newly active terminal"
    );

    // 5. Stacked modal (`Rename Tab` via Command Palette) cancelled over `Tool::Transfers`, and
    //    active session closed (`request_close_session` -> `drop_pane` -> `focus_pane`) while
    //    `Tool::Transfers` stays open: neither may leak focus to the underlying terminal PTY,
    //    and closing `Tool::Transfers` afterwards focuses the remaining active terminal.
    click(cx, "session.more");
    click(cx, "session.more.transfers");
    cx.run_until_parked();
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Transfers)
    );
    go(cx, crate::app::actions::OpenPalette);
    cx.simulate_input(ENGLISH.tab_menu_rename);
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    cx.simulate_keystrokes("escape"); // cancel Rename Tab while Transfers stays open
    cx.run_until_parked();
    redraw(cx);
    assert_eq!(
        cx.update(|_window, app| view.read(app).tool_for_test()),
        Some(crate::app::view::Tool::Transfers)
    );
    assert!(
        !session_focused(cx, session) && !session_focused(cx, second_session),
        "cancelling stacked Rename Tab over Transfers must not focus hidden terminal PTY"
    );
    cx.simulate_input("echo leaked-stacked-rename");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(
        snippet_sent(cx, &view, second_session).len(),
        second_sent_before
    );

    // Close the active `second_session` while `Transfers` remains open (`drop_pane` -> `focus_pane`).
    cx.update(|_window, app| {
        view.update(app, |v, cx| v.request_close_session(second_session, cx));
    });
    cx.run_until_parked();
    redraw(cx);
    assert!(
        !session_focused(cx, session),
        "closing active session behind open Transfers must not steal focus to remaining terminal"
    );
    cx.simulate_input("echo leaked-after-drop-pane");
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert_eq!(snippet_sent(cx, &view, session).len(), sent_before);

    cx.simulate_keystrokes("escape");
    cx.run_until_parked();
    redraw(cx);
    assert!(
        session_focused(cx, session),
        "closing Transfers focuses the remaining active terminal"
    );
}

#[gpui::test]
async fn a_copied_password_leaves_the_clipboard_and_a_shown_one_hides_by_itself(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("vault-clipboard-clear");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    click(cx, "nav.hosts");
    cx.simulate_resize(size(px(1280.0), px(840.0)));
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    let clipboard =
        |cx: &mut VisualTestContext| cx.read_from_clipboard().and_then(|item| item.text());

    // A copied password is on the clipboard, and gone again after the wait.
    click(cx, "security.credential.copy-password.0");
    assert_eq!(clipboard(cx), Some("shared-secret-value".to_owned()));
    cx.executor()
        .advance_clock(std::time::Duration::from_secs(29));
    cx.run_until_parked();
    assert_eq!(
        clipboard(cx),
        Some("shared-secret-value".to_owned()),
        "the password stays for the whole wait"
    );
    cx.executor()
        .advance_clock(std::time::Duration::from_secs(2));
    cx.run_until_parked();
    assert_ne!(
        clipboard(cx),
        Some("shared-secret-value".to_owned()),
        "the clipboard forgets the password once the wait is over"
    );

    // Something the user copied since is never cleared.
    click(cx, "security.credential.copy-password.0");
    cx.write_to_clipboard(gpui::ClipboardItem::new_string("mine".to_owned()));
    cx.executor()
        .advance_clock(std::time::Duration::from_secs(31));
    cx.run_until_parked();
    assert_eq!(clipboard(cx), Some("mine".to_owned()));

    // A shown password hides itself; a second reveal restarts the wait.
    click(cx, "security.credential.0");
    click(cx, "security.detail.reveal");
    assert!(cx.update(|_window, app| view.read(app).security_password_shown_for_test()));
    cx.executor()
        .advance_clock(std::time::Duration::from_secs(20));
    cx.run_until_parked();
    click(cx, "security.detail.reveal");
    click(cx, "security.detail.reveal");
    cx.executor()
        .advance_clock(std::time::Duration::from_secs(20));
    cx.run_until_parked();
    assert!(
        cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "the first reveal's timer does not hide the second reveal"
    );
    cx.executor()
        .advance_clock(std::time::Duration::from_secs(11));
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).security_password_shown_for_test()),
        "a shown password hides by itself"
    );
}

#[gpui::test]
async fn a_weak_password_is_measured_flagged_and_kept_by_the_attention_filter(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("vault-weak-password");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    click(cx, "nav.hosts");
    cx.simulate_resize(size(px(1280.0), px(840.0)));
    click(cx, "hosts.view.vault");
    cx.run_until_parked();

    // Nothing in the seeded vault needs attention.
    click(cx, "security.filter.attention");
    assert!(cx.debug_bounds("security.attention.empty").is_some());
    click(cx, "security.filter.all");

    click(cx, "security.action.new-password");
    cx.simulate_input("Old router");
    assert!(
        cx.debug_bounds("security.dialog.strength").is_none(),
        "an empty password has no meter"
    );
    type_into(cx, "security.dialog.secret", "password1");
    assert!(cx.debug_bounds("security.dialog.strength").is_some());
    click(cx, "security.dialog.submit");
    cx.run_until_parked();

    let weak = cx
        .update(|_window, app| view.read(app).security_credentials_for_test())
        .into_iter()
        .find(|(_, name)| name == "Old router")
        .expect("the weak password was saved")
        .0;
    click(cx, "security.filter.attention");
    assert_eq!(
        cx.update(|_window, app| view.read(app).security_visible_records(app)),
        vec![crate::app::view::security::SecurityRecord::Credential(weak)],
        "only the weak password needs attention"
    );
    click(cx, "security.credential.0");
    assert!(
        cx.debug_bounds("security.detail.weak").is_some(),
        "its detail card says why"
    );
}

/// A data conflict names every place both sides changed differently - the kind
/// of record, its name, the field and both values - and each is answered on its
/// own; "all from …" answers the rest at once, and nothing applies until every
/// place has an answer.
#[gpui::test]
async fn sync_record_conflicts_name_each_place_and_are_answered_one_by_one(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("sync-record-conflict");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let (view, cx) = vault_window(cx, &dir, &secrets);
    cx.update(|_window, app| {
        view.update(app, |view, cx| view.open_sync_record_conflict_for_test(cx))
    });
    assert!(sync_conflict_open(&view, cx));
    for selector in [
        "sync.records.row.0",
        "sync.records.row.1",
        "sync.records.local.value.0",
        "sync.records.remote.value.0",
    ] {
        assert!(cx.debug_bounds(selector).is_some(), "{selector} is drawn");
    }

    // One answer is not enough.
    click(cx, "sync.records.local.0");
    click(cx, "sync.vault.conflict.apply");
    cx.run_until_parked();
    assert!(
        sync_conflict_open(&view, cx),
        "an open place applies nothing"
    );
    let choices = cx.update(|_window, app| view.read(app).sync_document_choices_for_test());
    assert_eq!(choices[0].1, Some(shellune_storage::MergeSide::Local));
    assert_eq!(choices[1].1, None);

    // "All from the cloud" answers every place, the first one included.
    click(cx, "sync.records.all.remote");
    let choices = cx.update(|_window, app| view.read(app).sync_document_choices_for_test());
    assert!(
        choices
            .iter()
            .all(|(_, side)| *side == Some(shellune_storage::MergeSide::Remote)),
        "{choices:?}"
    );
    click(cx, "sync.records.local.1");
    click(cx, "sync.vault.conflict.apply");
    cx.run_until_parked();
    assert!(
        !sync_conflict_open(&view, cx),
        "every place answered lets the choices go"
    );
}

/// A key file only this device has is moved into the vault in one step: the
/// vault holds the key, its connections sign in with it on every device, and
/// a file that cannot be read is named and keeps its connection as it was.
#[gpui::test]
async fn key_files_move_into_the_vault_and_their_connections_follow(cx: &mut TestAppContext) {
    let dir = TempDir::new("vault-key-files");
    let secrets = Arc::new(shellune_storage::MemorySecrets::new());
    seed_vault(&dir, &secrets);
    let key = shellune_ssh::keys::generate(shellune_ssh::ManagedKeyKind::Ed25519)
        .expect("a key generates");
    let fingerprint = shellune_ssh::keys::public_data(&key)
        .expect("public material")
        .fingerprint;
    let pem = shellune_ssh::keys::export_private_key(&key, None).expect("a plain export");
    let key_path = dir.path().join("id_test");
    std::fs::write(&key_path, pem.expose()).expect("the key file is written");
    let mut web = shellune_core::HostConfig::new("web", "10.0.0.5", 22, "deploy").expect("valid");
    web.set_auth(Some(shellune_core::AuthMethodKind::KeyFile));
    web.set_identity_file(Some(key_path.display().to_string()));
    let mut gone = shellune_core::HostConfig::new("gone", "10.0.0.6", 22, "deploy").expect("valid");
    gone.set_auth(Some(shellune_core::AuthMethodKind::KeyFile));
    gone.set_identity_file(Some(dir.path().join("missing").display().to_string()));
    let (web_id, gone_id) = (web.id(), gone.id());
    {
        let mut book = HostBook::new();
        book.insert(web).expect("insert");
        book.insert(gone).expect("insert");
        dir.store().save(&book).expect("save hosts");
    }
    let (view, cx) = vault_window(cx, &dir, &secrets);
    click(cx, "nav.hosts");
    cx.simulate_resize(size(px(1280.0), px(840.0)));
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    assert!(
        cx.debug_bounds("security.key-files").is_some(),
        "the banner says so"
    );

    click(cx, "security.key-files.move");
    cx.run_until_parked();

    let keys = cx.update(|_window, app| view.read(app).security_keys_for_test());
    let (key_id, _, _) = keys
        .iter()
        .find(|(_, _, print)| *print == fingerprint)
        .cloned()
        .expect("the vault holds the key");
    let (moved, kept) = cx.update(|_window, app| {
        let book = view.read(app).book();
        let find = |id| {
            book.hosts()
                .iter()
                .find(|host| host.id() == id)
                .cloned()
                .expect("host")
        };
        (find(web_id), find(gone_id))
    });
    assert_eq!(
        moved.auth(),
        Some(shellune_core::AuthMethodKind::ManagedKey)
    );
    assert_eq!(moved.managed_key_id(), Some(key_id));
    assert_eq!(moved.identity_file(), None, "no path is left to travel");
    assert_eq!(
        kept.auth(),
        Some(shellune_core::AuthMethodKind::KeyFile),
        "a file that cannot be read keeps its connection as it was"
    );
    let (notice, warns) = cx
        .update(|_window, app| view.read(app).security_notice_for_test())
        .expect("a notice");
    assert!(warns, "a skipped file is a warning: {notice}");
    assert!(
        notice.contains("missing"),
        "the skipped file is named: {notice}"
    );
}

#[gpui::test]
async fn t2_sidebar_fold_unifies_toolbar_palette_shortcut_and_persists_with_text_size(
    cx: &mut TestAppContext,
) {
    let dir = TempDir::new("t2-sidebar-prefs");
    let mut book = HostBook::new();
    let mut host = HostConfig::new("prod-web", "10.0.0.10", 22, "deploy").expect("valid");
    host.set_group_path(Some(GroupPath::parse("Prod").expect("valid")));
    book.insert(host).expect("insert");
    dir.store().save(&book).expect("save");

    let (view, cx) = hosts_view_with_trust(cx, &dir);
    cx.simulate_resize(size(px(1280.0), px(820.0)));
    cx.update(|_window, app| {
        view.update(app, |view, cx| {
            view.use_saved_preferences_for_test(&shellune_storage::Preferences::default(), cx);
        });
    });
    cx.run_until_parked();

    assert!(!cx.update(|_window, app| view.read(app).home_sidebar_folded()));

    // 1. Toolbar toggle folds the sidebar and persists `sidebar_collapsed = Some(true)`.
    click(cx, "home.sidebar.toggle");
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).home_sidebar_folded()));
    let saved = shellune_storage::PreferencesStore::at(dir.path()).load();
    assert_eq!(saved.sidebar_collapsed, Some(true));

    // 2. Folded Groups button is keyboard-reachable from Vault via Arrow Down and expands on Enter.
    click(cx, "hosts.view.vault");
    cx.run_until_parked();
    cx.simulate_keystrokes("down");
    cx.run_until_parked();
    cx.simulate_keystrokes("enter");
    cx.run_until_parked();
    assert!(
        !cx.update(|_window, app| view.read(app).home_sidebar_folded()),
        "Enter on folded Groups expands the sidebar"
    );
    let saved = shellune_storage::PreferencesStore::at(dir.path()).load();
    assert_eq!(saved.sidebar_collapsed, Some(false));

    // 3. Shortcut (`ToggleSidebar`) and palette share the exact same state.
    cx.dispatch_action(crate::app::actions::ToggleSidebar);
    cx.run_until_parked();
    assert!(cx.update(|_window, app| view.read(app).home_sidebar_folded()));
    let saved = shellune_storage::PreferencesStore::at(dir.path()).load();
    assert_eq!(saved.sidebar_collapsed, Some(true));

    // 4. `CycleTextSize` persists `text_size`.
    let before_size = saved.text_size;
    cx.dispatch_action(CycleTextSize);
    cx.run_until_parked();
    let after = shellune_storage::PreferencesStore::at(dir.path()).load();
    assert_ne!(after.text_size, before_size, "CycleTextSize persists zoom");
}

#[gpui::test]
async fn t2_host_row_selected_and_search_match_do_not_occlude_meta(cx: &mut TestAppContext) {
    let dir = TempDir::new("t2-host-row-meta");
    let mut book = HostBook::new();
    let mut host = HostConfig::new("prod-api", "10.0.0.21", 22, "deploy").expect("valid");
    host.set_group_path(Some(GroupPath::parse("Prod").expect("valid")));
    let host_id = host.id();
    book.insert(host).expect("insert");
    let mut other = HostConfig::new("staging-db", "10.0.0.22", 22, "ops").expect("valid");
    other.set_group_path(Some(GroupPath::parse("Staging").expect("valid")));
    book.insert(other).expect("insert");
    book.record_connection(host_id, 1_700_000_000)
        .expect("record connection");
    dir.store().save(&book).expect("save");

    let (_view, cx) = hosts_view_with_trust(cx, &dir);
    cx.simulate_resize(size(px(1280.0), px(820.0)));
    cx.run_until_parked();

    // Select the first row via keyboard cursor.
    click(cx, "hosts.row.0");
    cx.run_until_parked();
    let tag = bounds_of(cx, "hosts.tag.0");
    let last = bounds_of(cx, "hosts.last.0");
    let connect = bounds_of(cx, "hosts.connect.0");
    assert!(
        tag.right() <= connect.left(),
        "selected row group tag must not be covered by connect button: {tag:?} vs {connect:?}"
    );
    assert!(
        last.right() <= connect.left(),
        "selected row last-connected time must not be covered by connect button: {last:?} vs {connect:?}"
    );

    // Search so row 0 is the Enter match (`host.enter == true`).
    click(cx, "hosts.search");
    cx.simulate_input("prod-api");
    cx.run_until_parked();
    let tag = bounds_of(cx, "hosts.tag.0");
    let last = bounds_of(cx, "hosts.last.0");
    let connect = bounds_of(cx, "hosts.connect.0");
    assert!(
        tag.right() <= connect.left(),
        "search match group tag must not be covered: {tag:?} vs {connect:?}"
    );
    assert!(
        last.right() <= connect.left(),
        "search match last time must not be covered: {last:?} vs {connect:?}"
    );
}

